INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撕碎", "is_correct": true, "explanation": "正确。“干树叶或撕碎的纸”，撕碎的纸是可以铺进箱里的材料。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：点燃的纸会燃烧，不能铺进堆肥箱，与句意不符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸的纸会变成纸浆，不是可以撕碎后铺进箱里的材料，句意不通。"}, {"text": "熨平", "is_correct": false, "explanation": "搭配：“熨平”用于衣物、布料，不用来描述铺在箱里的纸。"}], "explanations": {"撕碎": "正确。“干树叶或撕碎的纸”，撕碎的纸是可以铺进箱里的材料。", "点燃": "语义：点燃的纸会燃烧，不能铺进堆肥箱，与句意不符。", "煮沸": "语义：煮沸的纸会变成纸浆，不是可以撕碎后铺进箱里的材料，句意不通。", "熨平": "搭配：“熨平”用于衣物、布料，不用来描述铺在箱里的纸。"}, "sentence_index": 0, "correct_answer": "撕碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈不小心把碗撕碎了。", "explanation": "这里应该用〈打碎〉。碗是硬物，应说打碎；“撕碎”用于纸、布等软的东西。"}, {"text": "工人用锤子把石头撕碎了。", "explanation": "这里应该用〈砸碎〉。用锤子敲击石头应说砸碎，石头不能撕。"}, {"text": "杯子从桌上掉下来，撕碎了。", "explanation": "这里应该用〈摔碎〉。杯子落地应说摔碎，不说撕碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撕碎", "is_correct": true, "explanation": "正确。“他撕碎了那张没用的车票”，撕碎是把车票弄成碎片。"}, {"text": "蒸掉", "is_correct": false, "explanation": "语义：蒸是加热处理，不能用于车票，“蒸掉那张车票”句意不通。"}, {"text": "兑换", "is_correct": false, "explanation": "搭配：“兑换”用于有效的票据，“没用的车票”不能兑换。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销需要有效凭证，与“没用的”车票不符。"}], "explanations": {"撕碎": "正确。“他撕碎了那张没用的车票”，撕碎是把车票弄成碎片。", "蒸掉": "语义：蒸是加热处理，不能用于车票，“蒸掉那张车票”句意不通。", "兑换": "搭配：“兑换”用于有效的票据，“没用的车票”不能兑换。", "报销": "语义：报销需要有效凭证，与“没用的”车票不符。"}, "sentence_index": 6, "correct_answer": "撕碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车轮把空瓶子撕碎了。", "explanation": "这里应该用〈压碎〉。压的结果是压碎，撕碎用于纸、布等可撕的材料。"}, {"text": "斧子把木板撕碎了。", "explanation": "这里应该用〈劈碎〉。用斧子劈硬木应说劈碎，撕碎不能用于硬木。"}, {"text": "汽车把路灯撕碎了。", "explanation": "这里应该用〈撞碎〉。路灯是玻璃材质，被撞后应说撞碎，不说撕碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他旧报纸撕碎了。", "corrected_sentence": "他把旧报纸撕碎了。", "error_description": "漏用“把”：“撕碎”的宾语“旧报纸”前要加“把”，应为“他把旧报纸撕碎了”，不能说“他旧报纸撕碎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把那张车票撕碎了。", "corrected_sentence": "他没把那张车票撕碎。", "error_description": "体貌错误：“没”表示否定，与“了”不能同用，应为“他没把那张车票撕碎”，不能说“他没把那张车票撕碎了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物体含有较多水分，与“干”相对。", "primary_collocate": null, "pronunciation": "shī", "ipa": "ʂʅ˥", "syllable_count": 1, "sentences": [{"text": "每次加完湿垃圾，就盖一层干材料，这样可以减少臭味，也能帮助分解。", "target_word": "湿", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "雨很大，我的鞋全湿了。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上还是湿的，小心滑倒。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿衣服不要放在包里。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛巾太湿了，再拧一拧。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布是湿的，擦桌子正好。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服没干，摸起来有点湿。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，路上的树叶都是湿的。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发湿着，快去吹干。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把湿手擦干再碰插座。", "target_word": "湿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "湿透", "label": "复合"}, {"form": "潮湿", "label": "复合"}, {"form": "湿漉漉", "label": "叠词"}], "register": "中性", "sense_fingerprint": "物体含水多，与干相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿（shī），意思是物体含水多，与“干”相对。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与 shī 声调不同（第二声），意思是数字十。"}, {"text": "时", "is_correct": false, "explanation": "时（shí）与 shī 声调不同（第二声），意思是时间。"}, {"text": "事", "is_correct": false, "explanation": "事（shì）与 shī 声调不同（第四声），意思是事情。"}, {"text": "书", "is_correct": false, "explanation": "书（shū）与 shī 的韵母不同（u 与 i），意思是书籍。"}, {"text": "思", "is_correct": false, "explanation": "思（sī）与 shī 声母不同（s 与 sh），意思是思考。"}], "explanations": {"湿": "正确答案：湿（shī），意思是物体含水多，与“干”相对。", "十": "十（shí）与 shī 声调不同（第二声），意思是数字十。", "时": "时（shí）与 shī 声调不同（第二声），意思是时间。", "事": "事（shì）与 shī 声调不同（第四声），意思是事情。", "书": "书（shū）与 shī 的韵母不同（u 与 i），意思是书籍。", "思": "思（sī）与 shī 声母不同（s 与 sh），意思是思考。"}, "sentence_index": null, "correct_answer": "湿"}, "level_3": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿。“湿垃圾”是固定类别，与“干材料”形成对比。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空垃圾”与“加完……垃圾”的动作矛盾，句子不通。"}, {"text": "热", "is_correct": false, "explanation": "语义：热描述温度，不是垃圾的分类，与句中的分类语境不符。"}, {"text": "大", "is_correct": false, "explanation": "搭配：“大件”是固定说法，不说“大垃圾”作分类。"}], "explanations": {"湿": "正确答案：湿。“湿垃圾”是固定类别，与“干材料”形成对比。", "空": "语义：“空垃圾”与“加完……垃圾”的动作矛盾，句子不通。", "热": "语义：热描述温度，不是垃圾的分类，与句中的分类语境不符。", "大": "搭配：“大件”是固定说法，不说“大垃圾”作分类。"}, "sentence_index": 0, "correct_answer": "湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护肤后，她的皮肤很湿。", "explanation": "这里应该用〈滋润〉。湿指物体含水多，皮肤保湿、柔润要说滋润；皮肤湿通常指出汗或沾水。"}, {"text": "今天心情很湿。", "explanation": "这里应该用〈好〉。湿只形容物体含水多，不能形容心情；说心情好要用好。"}, {"text": "这个箱子很湿，我一个人就能搬。", "explanation": "这里应该用〈轻〉。湿只形容物体含水多，不能表示分量；说箱子轻要用轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿（shī），意思是物体含水多，与“干”相对。"}, {"text": "是", "is_correct": false, "explanation": "是（shì）与 shī 声调不同（第四声），意思是“是的”或判断。"}, {"text": "石", "is_correct": false, "explanation": "石（shí）与 shī 声调不同（第二声），意思是石头。"}, {"text": "史", "is_correct": false, "explanation": "史（shǐ）与 shī 声调不同（第三声），意思是历史。"}, {"text": "食", "is_correct": false, "explanation": "食（shí）与 shī 声调不同（第二声），意思是食物。"}], "explanations": {"湿": "正确答案：湿（shī），意思是物体含水多，与“干”相对。", "是": "是（shì）与 shī 声调不同（第四声），意思是“是的”或判断。", "石": "石（shí）与 shī 声调不同（第二声），意思是石头。", "史": "史（shǐ）与 shī 声调不同（第三声），意思是历史。", "食": "食（shí）与 shī 声调不同（第二声），意思是食物。"}, "sentence_index": null, "correct_answer": "湿"}, "level_3": {"options": [{"text": "湿", "is_correct": true, "explanation": "正确答案：湿。前一句说衣服“没干”，后一句“有点湿”与之呼应。"}, {"text": "脆", "is_correct": false, "explanation": "语义：脆形容容易断裂，衣服没干却摸起来脆，与句意不符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：硬多形容质地挺直，不说衣服摸起来有点硬来表示未干透。"}, {"text": "烫", "is_correct": false, "explanation": "语义：烫指温度高，衣服没干却摸起来烫，与句中的状态不符。"}], "explanations": {"湿": "正确答案：湿。前一句说衣服“没干”，后一句“有点湿”与之呼应。", "脆": "语义：脆形容容易断裂，衣服没干却摸起来脆，与句意不符。", "硬": "搭配：硬多形容质地挺直，不说衣服摸起来有点硬来表示未干透。", "烫": "语义：烫指温度高，衣服没干却摸起来烫，与句中的状态不符。"}, "sentence_index": 6, "correct_answer": "湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车跑得很湿。", "explanation": "这里应该用〈快〉。湿只形容物体含水多，不能形容速度；说车跑得快要用快。"}, {"text": "这个问题很湿，大家都讨论了很久。", "explanation": "这里应该用〈难〉。湿只形容物体含水多，不能形容问题的难易；说问题难要用难。"}, {"text": "这个灯泡很湿，屋里一下子就亮了。", "explanation": "这里应该用〈亮〉。湿只形容含水多，不能形容光线明暗；说灯泡亮要用亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水把我的衣服淋了湿。", "corrected_sentence": "雨水把我的衣服淋湿了。", "error_description": "错误形式：淋了湿；正确形式：淋湿了。“湿”作结果补语，应紧跟在动词“淋”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的袖子湿了着，先脱下来吧。", "corrected_sentence": "他的袖子湿着，先脱下来吧。", "error_description": "错误形式：湿了着；正确形式：湿着。“湿”是形容词，表示状态持续只用“着”，不能与“了”同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
