INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指覆盖在物体上方的部分，或用于遮盖、封闭的器具。", "primary_collocate": null, "pronunciation": "gài", "ipa": "kai˥˩", "syllable_count": 1, "sentences": [{"text": "首先，准备一个有盖的塑料箱，放在阳台或院子角落。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "堆肥箱的盖要关紧，这样才能减少臭味。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "然后，把每天的厨余放进去，最后再把箱子的盖合上。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子有盖，很干净。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅的盖不见了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子没有盖，东西会掉出来。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桶的盖是蓝色的。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盖放在桌子上。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子的盖很紧。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到壶的盖了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盖", "label": "量词"}, {"form": "盖子", "label": "复合"}, {"form": "蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "盖：容器上方用来遮盖、封闭的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11419, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指器具上方的盖子或覆盖。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 gài 声母不同（m 与 g），意思是出售。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。"}], "explanations": {"盖": "正确：盖 gài，指器具上方的盖子或覆盖。", "改": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。", "卖": "mài（第四声）与 gài 声母不同（m 与 g），意思是出售。", "害": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“盖”指箱子的盖子，“有盖的塑料箱”即带盖子的箱子。"}, {"text": "手", "is_correct": false, "explanation": "语义：塑料箱上没有“手”这一部件，“有手的塑料箱”不成立。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是人或动物的器官，不能用来说物品有脸。"}, {"text": "人", "is_correct": false, "explanation": "语义：“有人的塑料箱”指箱子里有人，与准备堆肥的语境不符。"}], "explanations": {"盖": "正确：“盖”指箱子的盖子，“有盖的塑料箱”即带盖子的箱子。", "手": "语义：塑料箱上没有“手”这一部件，“有手的塑料箱”不成立。", "脸": "体貌：“脸”是人或动物的器官，不能用来说物品有脸。", "人": "语义：“有人的塑料箱”指箱子里有人，与准备堆肥的语境不符。"}, "sentence_index": 0, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个杯子有一根盖，很干净。", "explanation": "量词错误：盖子应用量词“个”，“根”用于细长的东西，不能用来数盖子。"}, {"text": "那个杯子有一座盖，很干净。", "explanation": "量词错误：盖子应用量词“个”，“座”用于房屋、山等大型的东西，不能用来数杯盖。"}, {"text": "这个杯子有一条盖，很干净。", "explanation": "量词错误：盖子应用量词“个”，“条”用于细长的东西，不能用来数盖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11419, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指器具上方的盖子或覆盖。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gài 声调不同，意思是应该。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。"}, {"text": "干", "is_correct": false, "explanation": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}], "explanations": {"盖": "正确：盖 gài，指器具上方的盖子或覆盖。", "该": "gāi（第一声）与 gài 声调不同，意思是应该。", "带": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。", "告": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。", "干": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“桶的盖”指桶的盖子，是蓝色的，符合语境。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是人或动物的器官，桶没有眼睛，不能说“眼睛是蓝色的”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能有颜色，“声音是蓝色的”不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是嗅觉感受，不能用颜色来描述。"}], "explanations": {"盖": "正确：“桶的盖”指桶的盖子，是蓝色的，符合语境。", "眼睛": "体貌：“眼睛”是人或动物的器官，桶没有眼睛，不能说“眼睛是蓝色的”。", "声音": "语义：声音不能有颜色，“声音是蓝色的”不成立。", "味道": "语义：味道是嗅觉感受，不能用颜色来描述。"}, "sentence_index": 6, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把水壶有一颗盖，很小。", "explanation": "量词错误：盖子应用量词“个”，“颗”用于小而圆的颗粒状东西，不能用来数壶盖。"}, {"text": "那个篮子有一棵盖，很大。", "explanation": "量词错误：盖子应用量词“个”，“棵”用于树木、植物，不能用来数盖子。"}, {"text": "我找不到壶的一扇盖了。", "explanation": "量词错误：盖子应用量词“个”，“扇”用于门、窗，不能用来数壶盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的锅有两只盖。", "corrected_sentence": "我家的锅有两个盖。", "error_description": "量词错误：“盖”应用量词“个”，说“两个盖”；“只”不是盖子的常用量词，不能用来数盖子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子有一块盖，是蓝色的。", "corrected_sentence": "这个盒子有一个盖，是蓝色的。", "error_description": "量词错误：“盖”应用量词“个”，说“一个盖”；“块”用于块状的东西，不能用来数盖子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
