INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指食物或物品变质后散发的不好闻的气味。", "primary_collocate": null, "pronunciation": "chòu wèi", "ipa": "ʈʂʰou˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "每次加完湿垃圾，就盖一层干材料，这样可以减少臭味，也能帮助分解。", "target_word": "臭味", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这样做可以让桶里保持干燥，也能减少虫子和臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "垃圾桶里有一股臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面有很大的臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，臭味就慢慢没了。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼放了三天，已经有臭味了。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一进门就闻到了臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种垃圾袋可以挡住臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋里的臭味很重。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的袜子有臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股臭味", "label": "量词"}], "register": "中性", "sense_fingerprint": "臭味：食物、垃圾等变质后发出的难闻气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臭味", "is_correct": true, "explanation": "正确：“臭味”指难闻的气味，与“减少”搭配，符合语境。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“减少收入”与垃圾处理、分解无关，前后语义不通。"}, {"text": "知识", "is_correct": false, "explanation": "搭配：“减少”一般用于数量、程度，“减少知识”不是常见搭配。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“减少工资”与堆肥的语境无关，句子不通。"}], "explanations": {"臭味": "正确：“臭味”指难闻的气味，与“减少”搭配，符合语境。", "收入": "语义：“减少收入”与垃圾处理、分解无关，前后语义不通。", "知识": "搭配：“减少”一般用于数量、程度，“减少知识”不是常见搭配。", "工资": "语义：“减少工资”与堆肥的语境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "臭味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶香水的臭味很好闻。", "explanation": "这里应该用〈气味〉。臭味专指难闻的气味，不能用来形容好闻的香水。"}, {"text": "这道菜的臭味很鲜美。", "explanation": "这里应该用〈味道〉。臭味只指难闻的气味，不能用来形容鲜美的菜。"}, {"text": "垃圾桶里有一块臭味。", "explanation": "量词错误：臭味应用量词“股”，“块”用于成块的东西，不能用来数气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臭味", "is_correct": true, "explanation": "正确：“闻到了臭味”即闻到难闻的气味，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是用眼睛看的，不能用“闻”来感知，“闻到了颜色”不成立。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步一般是听到的，不能用“闻”来感知。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是人体器官，不能作为“闻”的对象。"}], "explanations": {"臭味": "正确：“闻到了臭味”即闻到难闻的气味，符合语境。", "颜色": "语义：颜色是用眼睛看的，不能用“闻”来感知，“闻到了颜色”不成立。", "脚步": "语义：脚步一般是听到的，不能用“闻”来感知。", "眼睛": "体貌：“眼睛”是人体器官，不能作为“闻”的对象。"}, "sentence_index": 6, "correct_answer": "臭味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕有浓浓的臭味，很诱人。", "explanation": "这里应该用〈香气〉。臭味指难闻的气味，不能与“诱人”搭配。"}, {"text": "早晨的山林里有清新的臭味。", "explanation": "这里应该用〈气息〉。臭味只指难闻的气味，不能与“清新”搭配。"}, {"text": "厨房里有一根臭味。", "explanation": "量词错误：臭味应用量词“股”，“根”用于细长的东西，不能用来数气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "垃圾箱里有一个臭味，要尽快清理。", "corrected_sentence": "垃圾箱里有一股臭味，要尽快清理。", "error_description": "量词错误：“臭味”应用量词“股”，说“一股臭味”；“个”不能用来数气味。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鞋柜里飘出一条臭味，很快就散了。", "corrected_sentence": "鞋柜里飘出一股臭味，很快就散了。", "error_description": "量词错误：“臭味”应用量词“股”，“条”用于细长的东西，不能用来数气味。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
