INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肉类指可供食用的动物肌肉组织，如猪肉、牛肉、羊肉等。", "primary_collocate": null, "pronunciation": "ròu lèi", "ipa": "ʐoʊ˥˩ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "不要把肉类、油和乳制品放进堆肥箱，它们容易引来虫子，也难分解。", "target_word": "肉类", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "猪肉、牛肉和羊肉都属于肉类。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议老人减少肉类的摄入，多吃青菜。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "yī shēng jiàn yì lǎo rén jiǎn shǎo ròu lèi de shè rù, duō chī qīng cài.", "sentence_source": "generated"}, {"text": "这家超市的肉类区在二楼。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "素食者不吃任何肉类。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉类放在冰箱里可以保存很久。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉类和蔬菜要分开存放，以免串味。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "ròu lèi hé shū cài yào fēn kāi cún fàng, yǐ miǎn chuàn wèi.", "sentence_source": "generated"}, {"text": "这家饭店的肉类菜品很受欢迎。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "zhè jiā fàndiàn de ròu lèi càipǐn hěn shòu huānyíng.", "sentence_source": "generated"}, {"text": "肉类里的蛋白质很多，对身体好。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对肉类过敏，所以从来不吃牛肉。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "肉類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "肉类：可供食用的动物肌肉组织的总称，如猪肉、牛肉、羊肉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉类", "is_correct": true, "explanation": "正确。“肉类”与“油”“乳制品”并列，都是不宜放入堆肥箱的食物，符合“容易引来虫子，也难分解”的描述。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜易分解，与“也难分解”的描述相反。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“引来虫子”需要有机食物作主语，玻璃不能与之搭配。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果本身易腐、易分解，与“也难分解”的描述相反。"}], "explanations": {"肉类": "正确。“肉类”与“油”“乳制品”并列，都是不宜放入堆肥箱的食物，符合“容易引来虫子，也难分解”的描述。", "蔬菜": "语义：蔬菜易分解，与“也难分解”的描述相反。", "玻璃": "搭配：“引来虫子”需要有机食物作主语，玻璃不能与之搭配。", "水果": "语义：水果本身易腐、易分解，与“也难分解”的描述相反。"}, "sentence_index": 0, "correct_answer": "肉类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只肉类，准备今晚做饭。", "explanation": "这里不能用〈只〉。〈只〉用于动物，“肉类”是食物的类别，应说“一种肉类”。"}, {"text": "他一口气吃了半斤肉类。", "explanation": "这里应该用〈肉〉。“肉”指一份具体的食物，可以说“半斤肉”；“肉类”指一大类食物，吃下去的是具体的肉，不说“半斤肉类”。"}, {"text": "他去肉类买了排骨。", "explanation": "这里应该用〈肉铺〉。“肉铺”是卖肉的店，“肉类”是食物类别，不能当作购物的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉类", "is_correct": true, "explanation": "正确。“肉类”与“蔬菜”并列，都是需要分开存放、以免串味的食物。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍没有气味，不会“串味”，与后句“以免串味”的语境不符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是食品，谈不上与蔬菜“串味”。"}, {"text": "电器", "is_correct": false, "explanation": "搭配：“串味”多用于食物之间，“电器”不能与“蔬菜”构成这样的搭配。"}], "explanations": {"肉类": "正确。“肉类”与“蔬菜”并列，都是需要分开存放、以免串味的食物。", "书籍": "语义：书籍没有气味，不会“串味”，与后句“以免串味”的语境不符。", "玩具": "语义：玩具不是食品，谈不上与蔬菜“串味”。", "电器": "搭配：“串味”多用于食物之间，“电器”不能与“蔬菜”构成这样的搭配。"}, "sentence_index": 6, "correct_answer": "肉类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老虎是一种肉类动物。", "explanation": "这里应该用〈肉食〉。“肉食动物”指以肉为食的动物，“肉类”是食物统称，不能用来修饰“动物”。"}, {"text": "我冰箱里放着一个肉类。", "explanation": "这里不能用〈个〉。〈个〉是通用量词，但“肉类”是一类食物，应说“一种肉类”。"}, {"text": "她今天穿了一条肉类的裙子。", "explanation": "这里应该用〈肉色〉。“肉色”表示颜色，“肉类”是食品类别，不能用来形容衣服的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店卖三块肉类。", "corrected_sentence": "这家店卖三种肉类。", "error_description": "量词错误：“肉类”指一类食物，应用〈种〉；〈块〉用于一块具体的肉，不能用于类别。正确说法是“三种肉类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "超市里有好几个肉类。", "corrected_sentence": "超市里有好几种肉类。", "error_description": "量词错误：“肉类”是一类食物，应用〈种〉，不能用通用量词〈个〉。正确说法是“好几种肉类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
