INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "油是从动物或植物中提取的脂肪，常用于烹饪，也可指石油等矿物油。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "jou˧˥", "syllable_count": 1, "sentences": [{"text": "不要把肉类、油和乳制品放进堆肥箱，它们容易引来虫子，也难分解。", "target_word": "油", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "妈妈用热油炒菜，厨房里很香。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这瓶油放在厨房的桌子上。", "target_word": "油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种油是用花生做的，闻起来很香。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车没有油了，开不走了。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油和水不能混在一起，油总是浮在上面。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把油倒进锅里，等油热了再放肉。", "target_word": "油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他少吃油，多吃青菜。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服上有一块油，用水洗不干净。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锅里的油太多了，菜吃起来很腻。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "桶", "label": "量词"}, {"form": "滴", "label": "量词"}, {"form": "食用油", "label": "复合词"}, {"form": "石油", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动植物脂肪或矿物油，可用于烹饪或作燃料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11423, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。油 yóu（第二声），指动植物脂肪或矿物油。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有。"}, {"text": "又", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是又、再。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是朋友。"}, {"text": "右", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是右边。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀。"}], "explanations": {"油": "正确。油 yóu（第二声），指动植物脂肪或矿物油。", "有": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有。", "又": "yòu（第四声）与 yóu（第二声）声调不同，意思是又、再。", "友": "yǒu（第三声）与 yóu（第二声）声调不同，意思是朋友。", "右": "yòu（第四声）与 yóu（第二声）声调不同，意思是右边。", "优": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀。"}, "sentence_index": null, "correct_answer": "油"}, "level_3": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。这里的油指可以放进堆肥箱的食物类油脂，与肉类、乳制品并列。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会引来虫子，与“它们容易引来虫子”的理由相矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“肉类”“乳制品”都是食物，玻璃不能与它们并列。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池不会引来虫子，也不能分解成堆肥，与整句的理由都不合。"}], "explanations": {"油": "正确。这里的油指可以放进堆肥箱的食物类油脂，与肉类、乳制品并列。", "石头": "语义：石头不会引来虫子，与“它们容易引来虫子”的理由相矛盾。", "玻璃": "搭配：“肉类”“乳制品”都是食物，玻璃不能与它们并列。", "电池": "语义：电池不会引来虫子，也不能分解成堆肥，与整句的理由都不合。"}, "sentence_index": 0, "correct_answer": "油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只油，放在厨房里。", "explanation": "这里应该用〈瓶〉。油是液体，一般用“瓶”“桶”计量，不能用“只”。"}, {"text": "做凉拌菜时，他多放了一点油，结果菜很甜。", "explanation": "这里应该用〈糖〉。油不能让菜变甜，甜味要用〈糖〉。"}, {"text": "炒菜时多放一点油，结果菜咸得吃不下。", "explanation": "这里应该用〈盐〉。油不能调出咸味，咸味要用〈盐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11423, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。油 yóu（第二声），指动植物脂肪或矿物油。"}, {"text": "幼", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是年纪小。"}, {"text": "柚", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是柚子。"}, {"text": "悠", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是悠闲。"}, {"text": "幽", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是幽静。"}, {"text": "诱", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是诱惑。"}], "explanations": {"油": "正确。油 yóu（第二声），指动植物脂肪或矿物油。", "幼": "yòu（第四声）与 yóu（第二声）声调不同，意思是年纪小。", "柚": "yòu（第四声）与 yóu（第二声）声调不同，意思是柚子。", "悠": "yōu（第一声）与 yóu（第二声）声调不同，意思是悠闲。", "幽": "yōu（第一声）与 yóu（第二声）声调不同，意思是幽静。", "诱": "yòu（第四声）与 yóu（第二声）声调不同，意思是诱惑。"}, "sentence_index": null, "correct_answer": "油"}, "level_3": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。“把油倒进锅里”指下油，后句“等油热了”也要求这里是食用油。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是固体，倒不进锅里，也不能用来炒菜。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰不能用来炒菜，“等冰热了再放肉”也不合理。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能用来炒菜，与“等油热了再放肉”的炒菜过程不符。"}], "explanations": {"油": "正确。“把油倒进锅里”指下油，后句“等油热了”也要求这里是食用油。", "木头": "语义：木头是固体，倒不进锅里，也不能用来炒菜。", "冰": "语义：冰不能用来炒菜，“等冰热了再放肉”也不合理。", "纸": "语义：纸不能用来炒菜，与“等油热了再放肉”的炒菜过程不符。"}, "sentence_index": 6, "correct_answer": "油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一根油回家。", "explanation": "这里应该用〈瓶〉。油是液体，用“根”不对，“根”用于细长的东西。"}, {"text": "我在超市买了一颗油。", "explanation": "这里应该用〈瓶〉。“颗”用于颗粒状的东西，液体的油不能用“颗”计量。"}, {"text": "桌子上放着一张油。", "explanation": "这里应该用〈瓶〉。“张”用于纸、桌子等平面的东西，油不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种油得热很快，要小火慢炒。", "corrected_sentence": "这种油热得很快，要小火慢炒。", "error_description": "补语位置错误：“热”是“油”的谓语，应说“油热得很快”，不说“油得热很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一只油倒进锅里，然后开火。", "corrected_sentence": "他把一瓶油倒进锅里，然后开火。", "error_description": "量词错误：油是液体，应用“瓶”计量，不能用“只”，应说“一瓶油”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
