INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乳制品是指以哺乳动物乳汁为主要原料加工制成的各种食品。", "primary_collocate": null, "pronunciation": "rǔ zhì pǐn", "ipa": "ʐu˨˩˦ ʈʂɨ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "不要把肉类、油和乳制品放进堆肥箱，它们容易引来虫子，也难分解。", "target_word": "乳制品", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "须特别注意，动物性残余如肉类、油脂及乳制品应严格排除，因其易引致厌氧发酵，滋生异味与害虫。", "target_word": "乳制品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "牛奶、奶酪和酸奶都是乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对乳制品过敏，不能喝牛奶。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的乳制品放在冷柜里。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乳制品要放进冰箱，不然很快会坏。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子每天应该吃一些乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶酪和黄油都是常见的乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人不吃肉，但会吃乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "乳製品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乳制品：以哺乳动物乳汁为原料加工制成的食品，如奶酪、酸奶、黄油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乳制品", "is_correct": true, "explanation": "正确。“乳制品”与“肉类”“油”并列，都是不宜放入堆肥箱的食物，符合“容易引来虫子，也难分解”的描述。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜易分解，与“也难分解”的描述相反。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“引来虫子”需要有机食物作主语，玻璃不能与之搭配。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料不会引来虫子，与“容易引来虫子”的描述矛盾。"}], "explanations": {"乳制品": "正确。“乳制品”与“肉类”“油”并列，都是不宜放入堆肥箱的食物，符合“容易引来虫子，也难分解”的描述。", "蔬菜": "语义：蔬菜易分解，与“也难分解”的描述相反。", "玻璃": "搭配：“引来虫子”需要有机食物作主语，玻璃不能与之搭配。", "塑料": "语义：塑料不会引来虫子，与“容易引来虫子”的描述矛盾。"}, "sentence_index": 0, "correct_answer": "乳制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我冰箱里有一根乳制品。", "explanation": "这里不能用〈根〉。〈根〉用于细长的东西，“乳制品”是食品类别，应说“一种乳制品”。"}, {"text": "小宝宝每天都吃母亲的乳制品。", "explanation": "这里应该用〈乳汁〉。“乳汁”指母亲分泌的奶，“乳制品”是加工食品，不能指母乳。"}, {"text": "豆腐和豆干都是乳制品。", "explanation": "这里应该用〈豆制品〉。“豆制品”以大豆为原料，“乳制品”以乳汁为原料，豆腐不属于乳制品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乳制品", "is_correct": true, "explanation": "正确。乳制品是可以食用的食品，符合“吃一些”的搭配。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料不能食用，与“孩子每天应该吃一些”的常识相悖。"}, {"text": "文具", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“文具”不能与“吃”搭配。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，与“应该吃”的语境矛盾。"}], "explanations": {"乳制品": "正确。乳制品是可以食用的食品，符合“吃一些”的搭配。", "颜料": "语义：颜料不能食用，与“孩子每天应该吃一些”的常识相悖。", "文具": "搭配：“吃”的宾语应是食物，“文具”不能与“吃”搭配。", "玩具": "语义：玩具不能吃，与“应该吃”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "乳制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我冰箱里放着一把乳制品。", "explanation": "这里不能用〈把〉。〈把〉用于有柄的器具，“乳制品”是食品类别，不能用“把”来计量。"}, {"text": "我们超市进了一座乳制品。", "explanation": "这里不能用〈座〉。〈座〉用于山、楼房等大型固定物，“乳制品”是食品，不能用“座”来计量。"}, {"text": "桌上放着一张乳制品。", "explanation": "这里不能用〈张〉。〈张〉用于平面的东西，“乳制品”是食品类别，不能用“张”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们超市卖很多块乳制品。", "corrected_sentence": "我们超市卖很多种乳制品。", "error_description": "量词错误：“乳制品”是一类食品，应用〈种〉；〈块〉用于一块具体的东西，不能用于类别。正确说法是“很多种乳制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天买好几个乳制品。", "corrected_sentence": "妈妈每天买好几种乳制品。", "error_description": "量词错误：“乳制品”是一类食品，应用〈种〉，不能用通用量词〈个〉。正确说法是“好几种乳制品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
