INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11425, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招来、使过来，通常指吸引人或事物到自己所在的方向。", "primary_collocate": null, "pronunciation": "yǐn lái", "ipa": "in˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "不要把肉类、油和乳制品放进堆肥箱，它们容易引来虫子，也难分解。", "target_word": "引来", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "花香引来了很多蝴蝶。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的歌声引来了很多路人。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话引来了一阵笑声。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边的灯光引来了很多小飞虫。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾放在外面，会引来老鼠。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他乱说话，给自己引来了不少麻烦。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的饭菜很好吃，引来了很多客人。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的饭店引来了很多人排队。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的新书引来了很多读者的关注。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "引来了", "label": "完成体"}, {"form": "引来过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "吸引、招来人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引来", "is_correct": true, "explanation": "正确。“容易引来虫子”指吸引虫子过来，是句子的理由。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：如果说“容易驱散虫子”，就与“不要放进堆肥箱”的警告相矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，虫子不能被修理。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能用于虫子。"}], "explanations": {"引来": "正确。“容易引来虫子”指吸引虫子过来，是句子的理由。", "驱散": "语义：如果说“容易驱散虫子”，就与“不要放进堆肥箱”的警告相矛盾。", "修理": "搭配：“修理”的对象是器物，虫子不能被修理。", "翻译": "搭配：“翻译”的对象是语言或文字，不能用于虫子。"}, "sentence_index": 0, "correct_answer": "引来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈从菜市场引来了一把青菜。", "explanation": "这里应该用〈带来〉。引来指吸引或招致，不用于拿着东西过来。"}, {"text": "我昨天在超市引来了一瓶牛奶。", "explanation": "这里应该用〈买〉。引来指吸引或招致，不能表示购买东西，买东西要用〈买〉。"}, {"text": "他小时候引来了很多邮票，现在还留着。", "explanation": "这里应该用〈收集〉。引来指吸引或招致，不能表示搜集物品，搜集要用〈收集〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引来", "is_correct": true, "explanation": "正确。“引来”表示招致，与“乱说话”的因果一致。"}, {"text": "消除", "is_correct": false, "explanation": "语义：“乱说话”是造成麻烦的原因，“消除麻烦”与之相反，句子不通。"}, {"text": "摆脱", "is_correct": false, "explanation": "语义：“摆脱麻烦”表示避开了麻烦，与“乱说话”的因果矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接“苦”“亏”等，不接“麻烦”，句子不自然。"}], "explanations": {"引来": "正确。“引来”表示招致，与“乱说话”的因果一致。", "消除": "语义：“乱说话”是造成麻烦的原因，“消除麻烦”与之相反，句子不通。", "摆脱": "语义：“摆脱麻烦”表示避开了麻烦，与“乱说话”的因果矛盾。", "吃": "搭配：“吃”一般接“苦”“亏”等，不接“麻烦”，句子不自然。"}, "sentence_index": 6, "correct_answer": "引来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他努力练习，终于引来了一块奖牌。", "explanation": "这里应该用〈获得〉。引来表示吸引或招致，不能用于获得奖牌。"}, {"text": "这种化学反应会引来大量热量。", "explanation": "这里应该用〈产生〉。引来指吸引或招致，不能用于化学反应产生热量。"}, {"text": "这台机器自动引来了一份报告。", "explanation": "这里应该用〈生成〉。引来不能表示机器生成报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲的笑话引来去了一阵掌声。", "corrected_sentence": "他讲的笑话引来了一阵掌声。", "error_description": "趋向补语用错：掌声是朝说话人一方传来的，「引来」后不应再接「去」，应说「引来了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在阳台放了一盘水果，想把蝴蝶引来了。", "corrected_sentence": "我在阳台放了一盘水果，想把蝴蝶引来。", "error_description": "“了”用错：“想”表示目的，句子不应在“引来”后加“了”，应说“想把蝴蝶引来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
