INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "虫子，通常指昆虫或类似的小型爬行、蠕动动物。", "primary_collocate": null, "pronunciation": "chóng zi", "ipa": "ʈʂʰʊŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "不要把肉类、油和乳制品放进堆肥箱，它们容易引来虫子，也难分解。", "target_word": "虫子", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "在堆肥桶里铺上干草，可以保持干燥，也能减少虫子和臭味。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一只小虫子在爬。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天晚上，虫子特别多。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕虫子，看见就叫。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户没关，几只虫子飞进了房间。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟在树上找虫子吃。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜叶上有虫子，要洗干净再吃。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可以杀死花园里的虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在泥土里找到一条虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "蟲子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "虫子：昆虫或类似的小型爬行、蠕动动物的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。食物的气味容易引来虫子，符合“容易引来”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会被食物引来，与“引来”的意思冲突。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“引来”的宾语多是会移动的生物或气味，不说“引来玻璃”。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不会被食物吸引，这句话的意思不通。"}], "explanations": {"虫子": "正确答案。食物的气味容易引来虫子，符合“容易引来”的语境。", "石头": "语义：石头不会被食物引来，与“引来”的意思冲突。", "玻璃": "搭配：“引来”的宾语多是会移动的生物或气味，不说“引来玻璃”。", "窗帘": "语义：窗帘不会被食物吸引，这句话的意思不通。"}, "sentence_index": 0, "correct_answer": "虫子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的虫子学家，专门研究蝴蝶。", "explanation": "这里应该用〈昆虫〉。“昆虫学家”是固定的书面词，口语中的“虫子”不能组成这个词。"}, {"text": "地上有一棵虫子在爬。", "explanation": "这里应该用〈只〉或〈条〉。“棵”用于树木和植物，不用于小虫子。"}, {"text": "我家养了一只虫子，每天早上都会叫我起床。", "explanation": "这里应该用〈狗〉。虫子指小型爬行或蠕动的虫类，不指会叫、会叫醒人的狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。鸟在树上找虫子吃是常见的觅食场景。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：树上一般不会有鱼，与句中的“树上”冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“吃”的对象必须是食物，不说吃汽车。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“吃”的对象必须是食物，不说吃铅笔。"}], "explanations": {"虫子": "正确答案。鸟在树上找虫子吃是常见的觅食场景。", "鱼": "语义：树上一般不会有鱼，与句中的“树上”冲突。", "汽车": "搭配：“吃”的对象必须是食物，不说吃汽车。", "铅笔": "搭配：“吃”的对象必须是食物，不说吃铅笔。"}, "sentence_index": 6, "correct_answer": "虫子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在泥土里找到一朵虫子。", "explanation": "这里应该用〈只〉或〈条〉。“朵”用于花朵，不用于虫子。"}, {"text": "桌子上放着一颗虫子。", "explanation": "这里应该用〈只〉或〈条〉。“颗”用于颗粒、果实等小而圆的东西，不用于虫子。"}, {"text": "花园的墙上有一块虫子。", "explanation": "这里应该用〈只〉或〈条〉。“块”用于块状的东西，不用于会爬的小虫子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的垃圾桶里爬着几本小虫子。", "corrected_sentence": "厨房的垃圾桶里爬着几只小虫子。", "error_description": "量词错误：“本”用于书籍等物品，虫子是小动物，应该说“几只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花盆里爬着几张虫子。", "corrected_sentence": "花盆里爬着几只虫子。", "error_description": "量词错误：“张”用于纸张、桌子等平面物，虫子是小动物，应该说“几只”。正确说法是“几只虫子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
