INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11427, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示时间或数量上按照一定的间隔重复出现。", "primary_collocate": null, "pronunciation": "měi gé", "ipa": "mei˨˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "每隔一两周用铲子翻一次堆肥，让空气进去，这样垃圾会分解得更快。", "target_word": "每隔", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "每隔三天，我就给花浇一次水。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每隔一个小时就休息一会儿。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车每隔十分钟来一辆。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每隔两周，我们开一次会。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让我每隔八小时吃一次药。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每隔几天就给妈妈打个电话。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师每隔一段时间就换一次座位。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每隔一年回一次老家。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每隔五分钟，他都看一下手机。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每过一段相同的时间就重复一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11427, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每隔", "is_correct": true, "explanation": "正确。每隔读 měi gé，表示每过一段相同的时间重复一次。"}, {"text": "每个", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，意思是每一个。"}, {"text": "美国", "is_correct": false, "explanation": "guó 与 gé 韵母不同（uo 与 e），意思是美国。"}, {"text": "没个", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是没有一个。"}, {"text": "每科", "is_correct": false, "explanation": "kē（第一声）与 gé（第二声）声母和声调都不同，意思是每门学科。"}], "explanations": {"每隔": "正确。每隔读 měi gé，表示每过一段相同的时间重复一次。", "每个": "gè（第四声）与 gé（第二声）声调不同，意思是每一个。", "美国": "guó 与 gé 韵母不同（uo 与 e），意思是美国。", "没个": "méi（第二声）与 měi（第三声）声调不同，意思是没有一个。", "每科": "kē（第一声）与 gé（第二声）声母和声调都不同，意思是每门学科。"}, "sentence_index": null, "correct_answer": "每隔"}, "level_3": {"options": [{"text": "每隔", "is_correct": true, "explanation": "正确：“每隔”表示按固定间隔重复，与“一两周用一次”相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情忽然发生一次，与按固定间隔反复翻堆肥不符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不能用于说明反复出现的习惯。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与隔一两周才做一次的间隔不符。"}], "explanations": {"每隔": "正确：“每隔”表示按固定间隔重复，与“一两周用一次”相符。", "突然": "语义：“突然”指事情忽然发生一次，与按固定间隔反复翻堆肥不符。", "已经": "体貌：“已经”表示动作已经完成，不能用于说明反复出现的习惯。", "立刻": "语义：“立刻”表示马上发生，与隔一两周才做一次的间隔不符。"}, "sentence_index": 0, "correct_answer": "每隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每隔一个月就毕业了。", "explanation": "“毕业”是一次性事件，不能按固定间隔反复发生，与“每隔”搭配不通。"}, {"text": "每隔春节，家家都贴春联。", "explanation": "这里应该用〈每逢〉。每隔要接表示间隔的时段或数量，如“每隔一年”，不能直接接节日。"}, {"text": "我每隔去北京都住在这家酒店。", "explanation": "这里应该用〈每次〉。每隔要接表示间隔的时段或数量，不能直接修饰动词“去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每隔", "is_correct": true, "explanation": "正确：“每隔”表示按固定间隔重复，与“几天就打一次电话”相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生的一次，与有规律地隔几天重复不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：“刚刚”表示刚发生，不能用于说明隔几天的规律习惯。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”指持续不断，与“隔几天”的间隔矛盾。"}], "explanations": {"每隔": "正确：“每隔”表示按固定间隔重复，与“几天就打一次电话”相符。", "忽然": "语义：“忽然”指突然发生的一次，与有规律地隔几天重复不符。", "刚刚": "体貌：“刚刚”表示刚发生，不能用于说明隔几天的规律习惯。", "一直": "语义：“一直”指持续不断，与“隔几天”的间隔矛盾。"}, "sentence_index": 6, "correct_answer": "每隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每隔不定的时间来一次。", "explanation": "这里把“每隔”误用成“随意、不固定间隔”的意思；“每隔”指间隔固定，不能用于随机的时间。"}, {"text": "学校每隔组织体检。", "explanation": "这里应该用〈定期〉。每隔要接明确的间隔，如“每隔一年”，不能单独修饰动词。"}, {"text": "他每隔十年就去世了。", "explanation": "“去世”是一次性事件，不能按固定间隔反复发生，与“每隔”搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每隔了两天去一次超市。", "corrected_sentence": "我每隔两天去一次超市。", "error_description": "错误：“每隔了两天”；正确：“每隔两天”。“每隔”表示按间隔反复，后面直接接时段，中间不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每隔的半年回一次老家。", "corrected_sentence": "我每隔半年回一次老家。", "error_description": "错误：“每隔的”；正确：“每隔”。“每隔”是副词，后面不加结构助词“的”，直接接时段即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
