INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "铲子是一种带有长柄和扁平或略弯金属头的工具，主要用于挖掘、铲取或移动松散物质如泥土、雪或谷物。", "primary_collocate": null, "pronunciation": "chǎn zi", "ipa": "tʂʰan˨˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "每隔一两周用铲子翻一次堆肥，让空气进去，这样垃圾会分解得更快。", "target_word": "铲子", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "堆肥的过程中，需要每周用铲子或长勺搅拌一次。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爸爸用铲子在院子里挖了一个坑。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，他拿着铲子去门口铲雪。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在沙滩上用小铲子挖沙。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花以前，先用铲子把土翻一翻。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把铲子很旧，但是还很好用。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用铲子把谷物铲进袋子里。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在花园里找不到那把铲子了。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一把新铲子，我们去种树。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "鏟子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带长柄和扁平金属头、用来挖土铲雪或翻动松散物质的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11428, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。铲子 chǎn zi，指带长柄、用来挖土或铲东西的工具。"}, {"text": "杆子", "is_correct": false, "explanation": "gǎn（第三声）与 chǎn 仅声母不同（g 与 ch），声调相同，意思是杆子。"}, {"text": "板子", "is_correct": false, "explanation": "bǎn（第三声）与 chǎn 仅声母不同（b 与 ch），声调相同，意思是板子。"}, {"text": "毯子", "is_correct": false, "explanation": "tǎn（第三声）与 chǎn 仅声母不同（t 与 ch），声调相同，意思是毯子。"}, {"text": "厂子", "is_correct": false, "explanation": "chǎng 与 chǎn 韵母不同（ang 与 an），声调相同，意思是工厂。"}], "explanations": {"铲子": "正确答案。铲子 chǎn zi，指带长柄、用来挖土或铲东西的工具。", "杆子": "gǎn（第三声）与 chǎn 仅声母不同（g 与 ch），声调相同，意思是杆子。", "板子": "bǎn（第三声）与 chǎn 仅声母不同（b 与 ch），声调相同，意思是板子。", "毯子": "tǎn（第三声）与 chǎn 仅声母不同（t 与 ch），声调相同，意思是毯子。", "厂子": "chǎng 与 chǎn 韵母不同（ang 与 an），声调相同，意思是工厂。"}, "sentence_index": null, "correct_answer": "铲子"}, "level_3": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。用铲子翻堆肥可以让空气进去，符合句意。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷太小，不能用来翻动堆肥。"}, {"text": "扫帚", "is_correct": false, "explanation": "搭配：“翻”的工具要能插入并翻动松散物质，扫帚不搭配这个动作。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能用来翻堆肥，这句话的意思不通。"}], "explanations": {"铲子": "正确答案。用铲子翻堆肥可以让空气进去，符合句意。", "牙刷": "语义：牙刷太小，不能用来翻动堆肥。", "扫帚": "搭配：“翻”的工具要能插入并翻动松散物质，扫帚不搭配这个动作。", "钥匙": "语义：钥匙不能用来翻堆肥，这句话的意思不通。"}, "sentence_index": 0, "correct_answer": "铲子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿着铲子去厨房切苹果。", "explanation": "这里应该用〈刀〉。铲子是用来挖或铲的工具，不用于切东西，切苹果要用刀。"}, {"text": "下雪了，他拿着一条铲子去门口铲雪。", "explanation": "这里应该用〈把〉。铲子是有柄的工具，“条”用于细长的东西。"}, {"text": "院子里有一支铲子靠在墙边。", "explanation": "这里应该用〈把〉。“支”用于笔、枪等细长的东西，铲子应该说“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11428, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。铲子 chǎn zi，指带长柄、用来挖土或铲东西的工具。"}, {"text": "碾子", "is_correct": false, "explanation": "碾子 niǎn zi，指碾压谷物的石滚，与 chǎn 仅声母不同（n 与 ch），声调相同。"}, {"text": "剪子", "is_correct": false, "explanation": "剪子 jiǎn zi，指剪东西的工具，与 chǎn 仅声母不同（j 与 ch），声调相同。"}, {"text": "胆子", "is_correct": false, "explanation": "d 与 ch 声母不同，声调相同，意思是胆子，即胆量。"}, {"text": "茧子", "is_correct": false, "explanation": "茧子 jiǎn zi，指手上磨出的硬皮，与 chǎn 仅声母不同（j 与 ch），声调相同。"}], "explanations": {"铲子": "正确答案。铲子 chǎn zi，指带长柄、用来挖土或铲东西的工具。", "碾子": "碾子 niǎn zi，指碾压谷物的石滚，与 chǎn 仅声母不同（n 与 ch），声调相同。", "剪子": "剪子 jiǎn zi，指剪东西的工具，与 chǎn 仅声母不同（j 与 ch），声调相同。", "胆子": "d 与 ch 声母不同，声调相同，意思是胆子，即胆量。", "茧子": "茧子 jiǎn zi，指手上磨出的硬皮，与 chǎn 仅声母不同（j 与 ch），声调相同。"}, "sentence_index": null, "correct_answer": "铲子"}, "level_3": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。“这把铲子”指一件有柄的工具，符合“很旧，但还很好用”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“把”不用于房子，房子应该说“座”或“栋”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能说“好用”，这句话的意思不通。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不能说“好用”，这句话的意思不通。"}], "explanations": {"铲子": "正确答案。“这把铲子”指一件有柄的工具，符合“很旧，但还很好用”。", "房子": "搭配：量词“把”不用于房子，房子应该说“座”或“栋”。", "河流": "语义：河流不能说“好用”，这句话的意思不通。", "老鼠": "语义：老鼠不能说“好用”，这句话的意思不通。"}, "sentence_index": 6, "correct_answer": "铲子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一朵新铲子，我们去种树。", "explanation": "这里应该用〈把〉。“朵”用于花朵，铲子应该说“一把”。"}, {"text": "妈妈给我买了一棵新铲子，我们去种树。", "explanation": "这里应该用〈把〉。“棵”用于树木和植物，铲子应该说“一把”。"}, {"text": "妈妈给我买了一颗新铲子，我们去种树。", "explanation": "这里应该用〈把〉。“颗”用于颗粒、果实等小而圆的东西，铲子应该说“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一根铲子翻了一遍菜地。", "corrected_sentence": "我用一把铲子翻了一遍菜地。", "error_description": "量词错误：“根”用于细长的东西，铲子是有柄的工具，应该说“一把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园丁用一支铲子把土堆平整了。", "corrected_sentence": "园丁用一把铲子把土堆平整了。", "error_description": "量词错误：“支”用于笔、枪等细长的东西，铲子是有柄的工具，应该说“一把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
