INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11429, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变物体的方向或位置，使另一面朝上。", "primary_collocate": null, "pronunciation": "fān", "ipa": "fan˥", "syllable_count": 1, "sentences": [{"text": "每隔一两周用铲子翻一次堆肥，让空气进去，这样垃圾会分解得更快。", "target_word": "翻", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "妈妈把锅里的鱼翻了一下。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煎蛋的一面熟了，要翻过来再煎。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天农民先用犁把地翻一遍。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤肉的时候，每面都要翻几次。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳很大，把床垫翻过来晒一晒。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煎鱼的时候别总翻，不然鱼会碎。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗好的鱼干要放在太阳下，每天翻一次。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饼一面煎黄了，快用铲子翻一下。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的土太硬，爸爸用铁锹翻了半天。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻了", "label": "体标"}, {"form": "翻过", "label": "体标"}, {"form": "翻翻", "label": "重叠"}, {"form": "翻动", "label": "复合"}], "register": "中性", "sense_fingerprint": "把物体翻转，使另一面朝上，如翻鱼、翻土、翻床垫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确。fān（第一声）是翻，意思是翻转、翻动。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是米饭。"}, {"text": "方", "is_correct": false, "explanation": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反。"}], "explanations": {"翻": "正确。fān（第一声）是翻，意思是翻转、翻动。", "饭": "fàn（第四声）与 fān（第一声）声调不同，意思是米饭。", "方": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。", "分": "fēn 与 fān 韵母不同（en 与 an），意思是分开。", "反": "fǎn（第三声）与 fān（第一声）声调不同，意思是相反。"}, "sentence_index": null, "correct_answer": "翻"}, "level_3": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确：“翻”指翻动堆肥，使空气进入，与“用铲子”搭配。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”用于水等液体，不能说用铲子浇堆肥。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去表面的污物，与让空气进入堆肥的意思不符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指整体移动，不是翻动堆肥使空气进入。"}], "explanations": {"翻": "正确：“翻”指翻动堆肥，使空气进入，与“用铲子”搭配。", "浇": "搭配：“浇”用于水等液体，不能说用铲子浇堆肥。", "擦": "语义：“擦”指抹去表面的污物，与让空气进入堆肥的意思不符。", "搬": "语义：“搬”指整体移动，不是翻动堆肥使空气进入。"}, "sentence_index": 0, "correct_answer": "翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民用锄头翻了一个坑。", "explanation": "这里应该用〈挖〉。翻是使物体另一面朝上，挖是向下取出土，不能说“翻一个坑”。"}, {"text": "妈妈把窗户翻开，让风进来。", "explanation": "这里应该用〈推〉。翻开多用于书本、纸张，窗户要推开。"}, {"text": "他把水翻进杯子里。", "explanation": "这里应该用〈倒〉。翻指使物体翻转，不表示液体流出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11429, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确。fān（第一声）是翻，意思是翻转、翻动。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。"}, {"text": "返", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}, {"text": "繁", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是繁多。"}], "explanations": {"翻": "正确。fān（第一声）是翻，意思是翻转、翻动。", "烦": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。", "犯": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错。", "返": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。", "繁": "fán（第二声）与 fān（第一声）声调不同，意思是繁多。"}, "sentence_index": null, "correct_answer": "翻"}, "level_3": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确：“翻”指使鱼的另一面朝上，与煎鱼的动作相符。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”指使液体流出，与煎鱼时翻动鱼的动作不符。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒”多用于盐、糖等，不能与煎鱼的动作搭配。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指用手轻击，不能描述煎鱼时的翻动。"}], "explanations": {"翻": "正确：“翻”指使鱼的另一面朝上，与煎鱼的动作相符。", "倒": "语义：“倒”指使液体流出，与煎鱼时翻动鱼的动作不符。", "撒": "搭配：“撒”多用于盐、糖等，不能与煎鱼的动作搭配。", "拍": "语义：“拍”指用手轻击，不能描述煎鱼时的翻动。"}, "sentence_index": 6, "correct_answer": "翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱翻进了口袋。", "explanation": "这里应该用〈放〉。翻指使物体翻转，不表示把东西放进某处。"}, {"text": "他翻住了小偷的手。", "explanation": "这里应该用〈抓〉。翻表示使物体翻转，不表示用手握住。"}, {"text": "她把衣服翻干净了。", "explanation": "这里应该用〈洗〉。翻只能改变方向，不能表示把衣服弄干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气很好，把被子翻过晒一晒。", "corrected_sentence": "天气很好，把被子翻过来晒一晒。", "error_description": "错误：“翻过”；正确：“翻过来”。“把”字句中动词后须带结果补语表示翻转后的方向，只说“翻过”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把锅里的饼翻了只面。", "corrected_sentence": "妈妈把锅里的饼翻了个面。", "error_description": "错误：“翻了只面”；正确：“翻了个面”。“面”的量词用“个”，“只”用于动物或成对物品中的一个，不能用于“面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "与“进去”构成反义，表示从里面到外面。"}, {"text": "起来", "is_correct": false, "explanation": "语义：“起来”表示向上或开始，与“进去”不构成反义。"}, {"text": "过来", "is_correct": false, "explanation": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "下来", "is_correct": false, "explanation": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}], "correct_answer": "出去", "explanations": {"出去": "与“进去”构成反义，表示从里面到外面。", "起来": "语义：“起来”表示向上或开始，与“进去”不构成反义。", "过来": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。", "下来": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出来", "is_correct": true, "explanation": "与“进去”构成反义，表示从里面到外面。"}, {"text": "上来", "is_correct": false, "explanation": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "回来", "is_correct": false, "explanation": "语义：“回来”表示返回原处，不是“进去”的反义词。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”表示离去，与“进去”不构成反义。"}], "correct_answer": "出来", "explanations": {"出来": "与“进去”构成反义，表示从里面到外面。", "上来": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。", "回来": "语义：“回来”表示返回原处，不是“进去”的反义词。", "走开": "语义：“走开”表示离去，与“进去”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示从外面移动到里面。", "primary_collocate": null, "pronunciation": "jìn qù", "ipa": "tɕin˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "每隔一两周用铲子翻一次堆肥，让空气进去，这样垃圾会分解得更快。", "target_word": "进去", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "门开着，你直接进去吧。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷了，我们快进去吧。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在办公室里，你敲门再进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都进去了，只有我还在外面。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影马上开始，快点进去找座位。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕黑，不敢一个人进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有人看着，没有票不能进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞很黑，我们带上灯再进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先在这儿等，我进去问一下。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进去了", "label": "体标"}, {"form": "进去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或物从外面移动到里面，如进屋、进门、空气进入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：进去（jìn qù）表示从外面移动到里面。"}, {"text": "进取", "is_correct": false, "explanation": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上、积极争取。"}, {"text": "禁区", "is_correct": false, "explanation": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。"}, {"text": "进气", "is_correct": false, "explanation": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。"}, {"text": "金曲", "is_correct": false, "explanation": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}], "explanations": {"进去": "正确：进去（jìn qù）表示从外面移动到里面。", "进取": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上、积极争取。", "禁区": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。", "进气": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。", "金曲": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}, "sentence_index": null, "correct_answer": "进去"}, "level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：空气从外面进入堆肥内部，应用“进去”。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后要接动作宾语，不能说空气进行。"}, {"text": "进步", "is_correct": false, "explanation": "语义：“进步”指进展、提高，空气不会进步。"}, {"text": "进门", "is_correct": false, "explanation": "搭配：“进门”说人或物从门口进入房间，不说让空气进门。"}], "explanations": {"进去": "正确：空气从外面进入堆肥内部，应用“进去”。", "进行": "搭配：“进行”后要接动作宾语，不能说空气进行。", "进步": "语义：“进步”指进展、提高，空气不会进步。", "进门": "搭配：“进门”说人或物从门口进入房间，不说让空气进门。"}, "sentence_index": 0, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一年进去了，他还是没有找到工作。", "explanation": "这里应该用〈过去〉。说时间流逝要用“过去”，“进去”只表示从外面移动到里面，不能用于时间。"}, {"text": "他顺利进去了决赛。", "explanation": "这里应该用〈进入〉。“进去”多用于具体空间的移动，决赛是抽象的阶段，应说“进入决赛”。"}, {"text": "他的成绩进去了全班前十名。", "explanation": "这里应该用〈进入〉。“进去”多用于具体空间的移动，名次是抽象的，应说“进入前十名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：“进去”表示从外面走到黑暗的里面，句意通顺。"}, {"text": "进化", "is_correct": false, "explanation": "语义：“进化”指生物或事物逐步发展，与孩子怕黑、不敢走进去的句意不符。"}, {"text": "进修", "is_correct": false, "explanation": "语义：“进修”指在职深造，与孩子不敢一个人走进某处的句意不符。"}, {"text": "进货", "is_correct": false, "explanation": "语义：“进货”指商店购入商品，与孩子怕黑无关。"}], "explanations": {"进去": "正确：“进去”表示从外面走到黑暗的里面，句意通顺。", "进化": "语义：“进化”指生物或事物逐步发展，与孩子怕黑、不敢走进去的句意不符。", "进修": "语义：“进修”指在职深造，与孩子不敢一个人走进某处的句意不符。", "进货": "语义：“进货”指商店购入商品，与孩子怕黑无关。"}, "sentence_index": 6, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在屋里，你快进去吧。", "explanation": "这里应该用“进来”。说话人在屋里，叫对方向自己这边进入时用“进来”，不用“进去”。"}, {"text": "他从屋里进去了外面。", "explanation": "这里应该用〈出去〉。从屋里到屋外要用“出去”，“进去”表示从外面到里面，方向相反。"}, {"text": "他爬进去了楼顶。", "explanation": "这里应该用〈上去〉。到楼顶是向上移动，要用“上去”；“进去”表示进入某个空间，楼顶不是可以进入的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外面下雨了，你快进去了躲一躲吧。", "corrected_sentence": "外面下雨了，你快进去躲一躲吧。", "error_description": "错误：“进去了躲”；正确：“进去躲”。祈使句中“进去”后不加“了”，应直接接动词“躲一躲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门没锁，你可以进去的看看。", "corrected_sentence": "门没锁，你可以进去看看。", "error_description": "错误：“进去的看看”；正确：“进去看看”。“进去”后直接接动词，不加结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泥土即土壤，是地球表面由岩石风化形成的含有矿物质和有机物的疏松物质，是植物生长的基础。", "primary_collocate": null, "pronunciation": "ní tǔ", "ipa": "ni˧˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "大约两个月后，原来的垃圾会变成深褐色、像泥土一样的东西，这就是堆肥了。", "target_word": "泥土", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他用手挖开泥土，把种子放进去。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨，泥土里有一股香味。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在泥土上玩得很开心。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花需要松软的泥土才能长好。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天都和泥土打交道。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋上沾满了泥土。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把泥土装进了花盆里。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的泥土有一种特别的味道。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓住在潮湿的泥土里。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块泥土", "label": "量词"}, {"form": "一层泥土", "label": "量词"}], "register": "中性", "sense_fingerprint": "泥土：土壤，含矿物质和有机物的疏松物质，植物生长的基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃透明坚硬，与句中由垃圾转化而来、深褐色的松软物质不符。"}, {"text": "泥土", "is_correct": true, "explanation": "这里指堆肥那样深褐色、松软的土状物质，符合句意。"}, {"text": "牛奶", "is_correct": false, "explanation": "体貌：牛奶是白色液体，与句中的深褐色不符。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料是人工合成材料，而堆肥由有机物分解而来，不会变成塑料。"}], "explanations": {"玻璃": "语义：玻璃透明坚硬，与句中由垃圾转化而来、深褐色的松软物质不符。", "泥土": "这里指堆肥那样深褐色、松软的土状物质，符合句意。", "牛奶": "体貌：牛奶是白色液体，与句中的深褐色不符。", "塑料": "语义：塑料是人工合成材料，而堆肥由有机物分解而来，不会变成塑料。"}, "sentence_index": 0, "correct_answer": "泥土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承包了那块泥土，准备种果树。", "explanation": "这里应该用〈土地〉。承包的是可以耕种的一块地，泥土指地表的土质，不能承包。"}, {"text": "他在图书馆读完了一本泥土。", "explanation": "这里应该用〈书〉。泥土是土壤，不能用来阅读；读完的应是“一本书”。"}, {"text": "他每天早上吃一块泥土当早饭。", "explanation": "这里应该用〈面包〉。泥土是土壤，不能当食物；早饭吃的应是“一块面包”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不可能沾在鞋子上。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“沾满”用于附着在物体表面的脏东西，笑容不能沾在鞋上。"}, {"text": "泥土", "is_correct": true, "explanation": "这里指沾在鞋上的土，与“沾满”搭配，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是大气层，不是可以沾在鞋上的东西。"}], "explanations": {"星星": "语义：星星在天上，不可能沾在鞋子上。", "笑容": "搭配：“沾满”用于附着在物体表面的脏东西，笑容不能沾在鞋上。", "泥土": "这里指沾在鞋上的土，与“沾满”搭配，符合句意。", "天空": "语义：天空是大气层，不是可以沾在鞋上的东西。"}, "sentence_index": 6, "correct_answer": "泥土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在窗台上发现了一张泥土。", "explanation": "这里应该用〈一块〉。“张”用于纸、桌子等平面的东西，泥土不能用“张”计量。"}, {"text": "妈妈买回一只泥土装进花盆。", "explanation": "这里应该用〈一袋〉。“只”用于动物，泥土不能用“只”计量。"}, {"text": "工地上堆着一个泥土。", "explanation": "这里应该用〈一堆〉。“个”不能用来计量成堆的泥土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候在河边玩过泥土过。", "corrected_sentence": "我小时候在河边玩过泥土。", "error_description": "“过”重复：经历标记“过”只说一次，应紧跟动词，应说“玩过泥土”，不能在宾语后再加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人运来了一位泥土。", "corrected_sentence": "工人运来了一车泥土。", "error_description": "量词错误：泥土应用“车”计量，“位”只用于人，不能说“一位泥土”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
