INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "混进指混杂在人群中或某个群体中，偷偷地进入。", "primary_collocate": null, "pronunciation": "hùn jìn", "ipa": "xuən˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他穿上工作服，混进了工地。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小偷扮成送货员，混进了银行的后台。", "target_word": "混进", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "小偷混进了参观的人群里。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有票，想混进电影院里看电影。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个记者混进了会场，想听他们说什么。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个陌生人混进了我们的班级。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着校服，混进学校里玩。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察混进坏人中间，收集了很多证据。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想混进大人的队伍里去看比赛。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有邀请，他怎么混进晚会的？", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混进了", "label": "体标"}, {"form": "混进去", "label": "方向补语"}], "register": "中性", "sense_fingerprint": "混杂在人群或群体中偷偷进入某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入，与“穿上工作服”的伪装情境相合。"}, {"text": "吃进", "is_correct": false, "explanation": "语义：“吃进”指把食物咽下去，不能用来指人进入工地，与句意不合。"}, {"text": "写进", "is_correct": false, "explanation": "语义：“写进”指把文字写到某处，与人进入工地的意思不合。"}, {"text": "掉进", "is_correct": false, "explanation": "语义：“掉进”指不慎落入，与有意伪装后进入的语境不符。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入，与“穿上工作服”的伪装情境相合。", "吃进": "语义：“吃进”指把食物咽下去，不能用来指人进入工地，与句意不合。", "写进": "语义：“写进”指把文字写到某处，与人进入工地的意思不合。", "掉进": "语义：“掉进”指不慎落入，与有意伪装后进入的语境不符。"}, "sentence_index": 0, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他光明正大地混进了会场，大家都欢迎他。", "explanation": "这里应该用〈进入〉。混进含有偷偷进入、不被察觉的意思，与“光明正大”矛盾。"}, {"text": "他作为嘉宾混进了晚会，坐在主席台上。", "explanation": "这里应该用〈出席〉。受邀的嘉宾是正式到场的，应说“出席”；“混进”只用于没有资格而偷偷进入的人。"}, {"text": "他报了名，正式混进了比赛，裁判还给他打了分。", "explanation": "这里应该用〈参加〉。报名的选手是合法参赛的，应说“参加”；“混进”指没有资格而偷偷进入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入，与“穿着校服”的伪装情境相合。"}, {"text": "关进", "is_correct": false, "explanation": "语义：“关进”指被强制关在里面，与“穿着校服”去学校里玩的意思不合。"}, {"text": "搬进", "is_correct": false, "explanation": "语义：“搬进”指搬家或搬东西进入某处，不能用来指人去学校里玩。"}, {"text": "陷进", "is_correct": false, "explanation": "搭配：“陷进”多用于陷入泥坑或困境，不能与“学校里玩”搭配。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入，与“穿着校服”的伪装情境相合。", "关进": "语义：“关进”指被强制关在里面，与“穿着校服”去学校里玩的意思不合。", "搬进": "语义：“搬进”指搬家或搬东西进入某处，不能用来指人去学校里玩。", "陷进": "搭配：“陷进”多用于陷入泥坑或困境，不能与“学校里玩”搭配。"}, "sentence_index": 6, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一脚踹开门，混进了办公室。", "explanation": "这里应该用〈闯进〉。混进表示悄悄进入、不被发现，“一脚踹开门”是强行、公开地进入，应说“闯进”。"}, {"text": "他大摇大摆地混进了房间。", "explanation": "这里应该用〈走进〉。混进表示悄悄进入，“大摇大摆”是旁若无人、公开进入，应说“走进”。"}, {"text": "消防员混进了火场，救出了被困的人。", "explanation": "这里应该用〈冲进〉。消防员是为救人而正式进入火场，应说“冲进”；“混进”表示偷偷进入，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小孩趁乱混进在了人群。", "corrected_sentence": "那个小孩趁乱混进了人群。", "error_description": "位置错误：“混进”与“了”之间不能插入“在”，应说“混进了人群”，不能说“混进在了人群”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他趁着人多，悄悄混进着会场。", "corrected_sentence": "他趁着人多，悄悄混进了会场。", "error_description": "体标错误：“混进”表示已完成的动作，应用“了”，不能用“着”（“着”表示持续的状态）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
