INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于栽种花卉的容器，通常由陶瓷、塑料等材料制成。", "primary_collocate": null, "pronunciation": "huā pén", "ipa": "xua˥ pʰən˧˥", "syllable_count": 2, "sentences": [{"text": "把它混进花盆或菜园的土里，植物会长得更好。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "把做好的堆肥混进花盆的土里，植物会长得更好。", "target_word": "花盆", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "阳台上有三个花盆，里面都种着花。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花盆太小，花长大了会放不下。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给花盆里的土浇了水。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心碰倒了花盆，土洒了一地。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去商店买了一个新花盆。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆底下有小洞，水可以流出来。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把花盆搬到窗户旁边，那里太阳大。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花盆是陶瓷做的，很漂亮。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个花盆", "label": "量词"}, {"form": "花盆架", "label": "复合"}], "register": "中性", "sense_fingerprint": "陶瓷或塑料制成、用来栽花种花的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11439, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”（huā pén）指装土种花的容器，即本词。"}, {"text": "花纹", "is_correct": false, "explanation": "wén 与 pén 声母不同（w 与 p），声调相同，意思是花纹。"}, {"text": "花盘", "is_correct": false, "explanation": "pán 与 pén 元音不同（a 与 e），意思是花盘。"}, {"text": "花棚", "is_correct": false, "explanation": "péng 与 pén 韵母不同（-ng 与 -n），意思是花棚。"}], "explanations": {"花盆": "正确：“花盆”（huā pén）指装土种花的容器，即本词。", "花纹": "wén 与 pén 声母不同（w 与 p），声调相同，意思是花纹。", "花盘": "pán 与 pén 元音不同（a 与 e），意思是花盘。", "花棚": "péng 与 pén 韵母不同（-ng 与 -n），意思是花棚。"}, "sentence_index": null, "correct_answer": "花盆"}, "level_3": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”是装土种花的容器，与“混进……土里”的语境相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”用来装书，不能用来装土，与“混进……土里”的意思不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”用来冷藏食物，不能把土混进去，与句中的“植物”也不搭。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“饮料”是喝的东西，不能与“菜园的土”并列作为混入的地点。"}], "explanations": {"花盆": "正确：“花盆”是装土种花的容器，与“混进……土里”的语境相合。", "书包": "语义：“书包”用来装书，不能用来装土，与“混进……土里”的意思不合。", "冰箱": "语义：“冰箱”用来冷藏食物，不能把土混进去，与句中的“植物”也不搭。", "饮料": "搭配：“饮料”是喝的东西，不能与“菜园的土”并列作为混入的地点。"}, "sentence_index": 0, "correct_answer": "花盆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一条花盆，放在阳台上。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，花盆不能用“条”。"}, {"text": "园丁在院子里砌了一个花盆，种满了月季。", "explanation": "这里应该用〈花坛〉。花盆是可以搬动的容器，不用砌；用砖砌起来、固定在地面上的是花坛。"}, {"text": "花盆里养着几条金鱼。", "explanation": "这里应该用〈鱼缸〉。花盆用来栽花，不能用来养鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”是可以在商店买到的种花容器，与“买了一个新”相合。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”不能用“买”来获得，与“买了一个新”的意思不合。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”是养成的行为模式，不能去商店买，与“买”冲突。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“买”一般不跟“工作”搭配，得到工作要说“找”或“得到”。"}], "explanations": {"花盆": "正确：“花盆”是可以在商店买到的种花容器，与“买了一个新”相合。", "问题": "语义：“问题”不能用“买”来获得，与“买了一个新”的意思不合。", "习惯": "语义：“习惯”是养成的行为模式，不能去商店买，与“买”冲突。", "工作": "搭配：“买”一般不跟“工作”搭配，得到工作要说“找”或“得到”。"}, "sentence_index": 6, "correct_answer": "花盆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用花盆洗了脸。", "explanation": "这里应该用〈脸盆〉。花盆用来栽花，洗脸要用脸盆。"}, {"text": "妈妈用花盆盛饭，招待客人。", "explanation": "这里应该用〈碗〉。花盆用来栽花，不能用来盛饭。"}, {"text": "他把鸡蛋放进了花盆里，准备煮着吃。", "explanation": "这里应该用〈锅〉。煮东西要用锅，花盆是用来栽花的，不能用来煮鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在窗边摆了一条花盆。", "corrected_sentence": "我们在窗边摆了一个花盆。", "error_description": "量词错误：“花盆”应用量词“个”，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在阳台上放了一条新花盆。", "corrected_sentence": "妈妈在阳台上放了一个新花盆。", "error_description": "量词错误：“花盆”应用量词“个”，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
