INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植蔬菜的园子。", "primary_collocate": null, "pronunciation": "cài yuán", "ipa": "tsʰaɪ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "把它混进花盆或菜园的土里，植物会长得更好。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷的菜园在房子后面。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的菜园里种着白菜和西红柿。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，奶奶都去菜园浇水。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜园里的黄瓜已经长大了。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在菜园旁边修了一道小篱笆。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我帮爸爸在菜园里拔草。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜园不大，但是蔬菜很新鲜。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，菜园里都是水。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跑进菜园，摘了几个西红柿。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个菜园", "label": "量词"}, {"form": "一片菜园", "label": "量词"}, {"form": "菜園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "菜园：种植蔬菜的园子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是种植的场所，“混进教室的土里”不合理。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里没有可以种植的土，“混进厨房的土里”不成立。"}, {"text": "菜园", "is_correct": true, "explanation": "这里指种蔬菜的园子，与“花盆”并列，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱的土”不成立，冰箱是电器，里面没有土。"}], "explanations": {"教室": "语义：教室是上课的地方，不是种植的场所，“混进教室的土里”不合理。", "厨房": "语义：厨房里没有可以种植的土，“混进厨房的土里”不成立。", "菜园": "这里指种蔬菜的园子，与“花盆”并列，符合句意。", "冰箱": "搭配：“冰箱的土”不成立，冰箱是电器，里面没有土。"}, "sentence_index": 0, "correct_answer": "菜园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在菜园里欣赏牡丹。", "explanation": "这里应该用〈花园〉。花园用于观赏花草，菜园是种蔬菜的园子，不用来欣赏牡丹。"}, {"text": "孩子们在菜园里玩滑梯。", "explanation": "这里应该用〈公园〉。公园有游乐设施和开阔场地，菜园是种菜的地方，不能用来玩滑梯。"}, {"text": "秋天，菜园里挂满了红苹果。", "explanation": "这里应该用〈果园〉。果园种果树，苹果长在树上；菜园种蔬菜，不种苹果树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书房", "is_correct": false, "explanation": "语义：书房是看书学习的地方，不能在里面拔草。"}, {"text": "菜园", "is_correct": true, "explanation": "这里指种着蔬菜、会长草的园子，与“拔草”相符。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：“拔草”一般在田地或园子里进行，“仓库里拔草”不搭配。"}, {"text": "浴室", "is_correct": false, "explanation": "语义：浴室里没有可以长草的土地，不能在里面拔草。"}], "explanations": {"书房": "语义：书房是看书学习的地方，不能在里面拔草。", "菜园": "这里指种着蔬菜、会长草的园子，与“拔草”相符。", "仓库": "搭配：“拔草”一般在田地或园子里进行，“仓库里拔草”不搭配。", "浴室": "语义：浴室里没有可以长草的土地，不能在里面拔草。"}, "sentence_index": 6, "correct_answer": "菜园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家门前有一间菜园。", "explanation": "这里应该用〈一片〉。“间”用于房屋，菜园不能用“间”计量。"}, {"text": "院子里有一棵菜园。", "explanation": "这里应该用〈一片〉。“棵”用于树木和植物个体，菜园不能用“棵”计量。"}, {"text": "我家后院有一本菜园。", "explanation": "这里应该用〈一片〉。“本”用于书册，菜园不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口有一朵菜园。", "corrected_sentence": "我家门口有一片菜园。", "error_description": "量词错误：“朵”用于花朵，菜园应用“片”计量，不能说“一朵菜园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子的角落有一台菜园。", "corrected_sentence": "院子的角落有一片菜园。", "error_description": "量词错误：菜园应用“片”计量，“台”用于机器，不能说“一台菜园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
