INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11451, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使抽象的概念或思想变得具体、形象，容易被人理解或感知。", "primary_collocate": null, "pronunciation": "jù xiàng huà", "ipa": "tɕy˥˩ ɕjɑŋ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "回望历史，从木质风车到纳米级光伏材料，能源技术的演化本质是人类对自然规律认知深度的具象化。", "target_word": "具象化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代环境伦理的实践维度中，家庭堆肥系统已成为都市可持续理念具象化的微观载体，不仅体现个体对生态责任的主动承担，更构成城市减废战略中不可或缺的分布式节点。", "target_word": "具象化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "画家用颜色把抽象的情绪具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用生活中的例子，把抽象的道理具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告能把品牌的理念具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人常用比喻让抽象的思想具象化。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建筑师做了一个模型，让设计想法具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写日记，是为了让模糊的感受具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影把战争的残酷具象化，观众看了很难过。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座雕像是和平理念的具象化。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "具象化了", "label": "体标"}, {"form": "具象化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把抽象的概念、思想、情感转化为具体可感的形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具象化", "is_correct": true, "explanation": "正确。“认知深度的具象化”是名词用法，指认知的具体体现，与句意一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观色彩，与“认知深度”无关。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指时令，与能源技术对自然规律的认识不相干。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“认知深度”不说“年龄”，“认知深度的年龄”不成立。"}], "explanations": {"具象化": "正确。“认知深度的具象化”是名词用法，指认知的具体体现，与句意一致。", "颜色": "语义：“颜色”指外观色彩，与“认知深度”无关。", "季节": "语义：“季节”指时令，与能源技术对自然规律的认识不相干。", "年龄": "搭配：“认知深度”不说“年龄”，“认知深度的年龄”不成立。"}, "sentence_index": 0, "correct_answer": "具象化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器把体积具象化了。", "explanation": "这里应该用〈缩小〉。“具象化”指使抽象的概念变得具体可感，体积变小不是这个意思，要说“缩小”。"}, {"text": "学者把具体的经验具象化，形成了理论。", "explanation": "这里应该用〈抽象化〉。“具象化”是使抽象变具体，此处是把具体经验变成理论，方向相反。"}, {"text": "这份报告把零散的数据具象化成几个结论。", "explanation": "这里应该用〈概括〉。“具象化”是使抽象变具体，此处是把具体数据归纳为结论，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具象化", "is_correct": true, "explanation": "正确。“让设计想法具象化”指让抽象的想法变得具体可见，与句意一致。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”指食物或物体变质，与做模型让想法变得具体的意思相反。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多用于资金、账户，不说“冻结想法”。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体变成液体，与句中让想法变得具体无关。"}], "explanations": {"具象化": "正确。“让设计想法具象化”指让抽象的想法变得具体可见，与句意一致。", "腐烂": "语义：“腐烂”指食物或物体变质，与做模型让想法变得具体的意思相反。", "冻结": "搭配：“冻结”多用于资金、账户，不说“冻结想法”。", "融化": "语义：“融化”指固体变成液体，与句中让想法变得具体无关。"}, "sentence_index": 6, "correct_answer": "具象化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师把具体的图纸具象化，写成了一篇论文。", "explanation": "这里应该用〈抽象化〉。“具象化”是使抽象变具体，此处是把具体图纸变成论文里的理论，方向相反。"}, {"text": "编辑把生动的故事具象化，提炼成了一句格言。", "explanation": "这里应该用〈提炼〉。“具象化”是使抽象变具体，此处是把具体故事压缩成抽象的格言，方向相反。"}, {"text": "会计把具体的账目具象化，归纳成了一个结论。", "explanation": "这里应该用〈归纳〉。“具象化”是使抽象变具体，此处是把具体账目归为结论，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者用一个故事，把抽象的爱具象化着。", "corrected_sentence": "作者用一个故事，把抽象的爱具象化了。", "error_description": "体标错误：“具象化”表示完成时应用“了”，不能用“着”，应说“具象化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画把抽象的孤独具象化了很动人。", "corrected_sentence": "这幅画把抽象的孤独具象化得很动人。", "error_description": "错误形式：“具象化了很动人”；正确形式：“具象化得很动人”。这里需要程度补语“得”引出评价，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
