INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "减少废物产生，保护环境。", "primary_collocate": null, "pronunciation": "jiǎn fèi", "ipa": "tɕjɛn²¹⁴ fei⁵¹", "syllable_count": 2, "sentences": [{"text": "在当代环境伦理的实践维度中，家庭堆肥系统已成为都市可持续性（sustainability）理念具象化的微观载体，不仅体现个体对生态责任的主动承担，更构成城市减废（waste reduction）战略中不可或缺的分布式节点。", "target_word": "减废", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们家今年开始认真减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少用塑料袋是减废的好办法。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请同学们一起减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用旧瓶子做花盆，既省钱又减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减废，妈妈每周只买需要的东西。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅去年开始减废，剩菜少多了。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区正在推动减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减废从自己带水杯开始。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坚持减废一个月，感觉不难。", "target_word": "减废", "complexity_tier": "T3", "furigana": "jiǎn fèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "减废了", "label": "体标"}, {"form": "减废过", "label": "体标"}], "register": "中性", "sense_fingerprint": "减少废物的产生以保护环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减废", "is_correct": true, "explanation": "正确。“城市减废战略”指以减少废物为目标的城市战略，与句中强调的生态责任相符。"}, {"text": "扩张", "is_correct": false, "explanation": "语义：“扩张”指扩大规模，与句中强调的生态责任相反，不能修饰这一战略。"}, {"text": "上市", "is_correct": false, "explanation": "语义：“上市”指产品或股票进入市场，与环境伦理的语境无关，句意不通。"}, {"text": "吐槽", "is_correct": false, "explanation": "语域：“吐槽”是口语网络用语，不适合用于这样的学术化长句。"}], "explanations": {"减废": "正确。“城市减废战略”指以减少废物为目标的城市战略，与句中强调的生态责任相符。", "扩张": "语义：“扩张”指扩大规模，与句中强调的生态责任相反，不能修饰这一战略。", "上市": "语义：“上市”指产品或股票进入市场，与环境伦理的语境无关，句意不通。", "吐槽": "语域：“吐槽”是口语网络用语，不适合用于这样的学术化长句。"}, "sentence_index": 0, "correct_answer": "减废"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把废纸拿去减废。", "explanation": "这里应该用〈回收〉。减废指减少废物的产生，不能用来表示把废纸拿去处理掉。"}, {"text": "我们要减废用电。", "explanation": "这里应该用〈节约〉。减废针对废物，不能用来搭配“用电”这类资源的使用。"}, {"text": "这些旧电池不能随便减废。", "explanation": "这里应该用〈废弃〉。减废指减少废物的产生，不能用来表示随意丢弃废物这一行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减废", "is_correct": true, "explanation": "正确。“去年开始减废”指餐厅开始减少废物，剩菜随之变少，前后逻辑相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：餐厅不能开始游泳，“游泳”也与剩菜减少没有关系。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”指人的体型变胖，不能用于餐厅，也不会使剩菜变少。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”需要带认识的对象，句中没有宾语，也与“剩菜少多了”没有因果关系。"}], "explanations": {"减废": "正确。“去年开始减废”指餐厅开始减少废物，剩菜随之变少，前后逻辑相符。", "游泳": "语义：餐厅不能开始游泳，“游泳”也与剩菜减少没有关系。", "发胖": "体貌：“发胖”指人的体型变胖，不能用于餐厅，也不会使剩菜变少。", "认识": "配价：“认识”需要带认识的对象，句中没有宾语，也与“剩菜少多了”没有因果关系。"}, "sentence_index": 6, "correct_answer": "减废"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天跑步，想减废十斤。", "explanation": "这里应该用〈减肥〉。减废指减少废物的产生，不能用来表示减轻体重，应说“减肥”。"}, {"text": "这台旧电脑需要减废。", "explanation": "这里应该用〈修理〉。减废指减少废物，不能用来表示使器物恢复正常。"}, {"text": "她很会减废压力。", "explanation": "这里应该用〈减压〉。减废指减少废物，不能用来表示缓解精神压力，应说“减压”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在认真减废过。", "corrected_sentence": "我们正在认真减废。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用。应删去“过”，改为“我们正在认真减废。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店今年减废了过。", "corrected_sentence": "这家店今年减废了。", "error_description": "“了”和“过”不能同时用在动词“减废”后，表示完成或经历只用其一。应删去“过”，改为“这家店今年减废了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
