INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指人或事物非常重要，缺少了就不行。", "primary_collocate": null, "pronunciation": "bù kě huò quē", "ipa": "pu˥˩ kʰɤ˨˩˦ xuo˥˩ tɕʰyɛ˥", "syllable_count": 4, "sentences": [{"text": "这种深植于文化土壤中的生态理性，正在成为跨学科研究的焦点，为气候适应政策提供不可或缺的参照系。", "target_word": "不可或缺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代环境伦理的实践维度中，家庭堆肥系统已成为都市可持续理念具象化的微观载体，不仅体现个体对生态责任的主动承担，更构成城市减废战略中不可或缺的分布式节点。", "target_word": "不可或缺", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "水是生命中不可或缺的东西。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的帮助对我来说不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机已经成了现代生活中不可或缺的工具。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气和阳光对植物不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个团队里，他的作用不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭是我们每天不可或缺的食物。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时，盐是不可或缺的。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的睡眠是健康不可或缺的一部分。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可或缺的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "非常重要，缺少就不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模糊不清", "is_correct": false, "explanation": "语义：参照系要为政策提供依据，“模糊不清”与“焦点”“提供参照”的语境相矛盾。"}, {"text": "不可或缺", "is_correct": true, "explanation": "“不可或缺”说明参照系缺了就不行，与前文“成为跨学科研究的焦点”“为政策提供”的语境一致。"}, {"text": "可有可无", "is_correct": false, "explanation": "语义：“可有可无”说明不重要，与前文说它是研究焦点、为政策提供参照相矛盾。"}, {"text": "五彩斑斓", "is_correct": false, "explanation": "体貌：“五彩斑斓”形容颜色鲜艳，只能描述外观，不能修饰参照系。"}], "explanations": {"模糊不清": "语义：参照系要为政策提供依据，“模糊不清”与“焦点”“提供参照”的语境相矛盾。", "不可或缺": "“不可或缺”说明参照系缺了就不行，与前文“成为跨学科研究的焦点”“为政策提供”的语境一致。", "可有可无": "语义：“可有可无”说明不重要，与前文说它是研究焦点、为政策提供参照相矛盾。", "五彩斑斓": "体貌：“五彩斑斓”形容颜色鲜艳，只能描述外观，不能修饰参照系。"}, "sentence_index": 0, "correct_answer": "不可或缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨之后地面会变湿，这是不可或缺的。", "explanation": "这里应该用〈必然〉。不可或缺说事物缺了就不行，强调重要；说下雨后地面变湿是必然的结果，要用〈必然〉。"}, {"text": "每个人最终都会变老，这是不可或缺的。", "explanation": "这里应该用〈不可避免〉。不可或缺说缺了就不行，强调重要；说变老无法避免，要用〈不可避免〉。"}, {"text": "今天的天气很不可或缺，大家都想出去玩。", "explanation": "这里应该用〈晴朗〉。不可或缺指事物缺了就不行，不能用来形容天气；说天气好要用〈晴朗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聪明伶俐", "is_correct": false, "explanation": "搭配：“聪明伶俐”形容人的机灵，不能用来说“作用”。"}, {"text": "饥肠辘辘", "is_correct": false, "explanation": "语义：“饥肠辘辘”指人饿了，与他在团队里的作用无关。"}, {"text": "英俊挺拔", "is_correct": false, "explanation": "体貌：“英俊挺拔”形容人的外貌和身材，不能用来形容作用。"}, {"text": "不可或缺", "is_correct": true, "explanation": "“不可或缺”说明他在团队中的作用缺了就不行，符合句子的语境。"}], "explanations": {"聪明伶俐": "搭配：“聪明伶俐”形容人的机灵，不能用来说“作用”。", "饥肠辘辘": "语义：“饥肠辘辘”指人饿了，与他在团队里的作用无关。", "英俊挺拔": "体貌：“英俊挺拔”形容人的外貌和身材，不能用来形容作用。", "不可或缺": "“不可或缺”说明他在团队中的作用缺了就不行，符合句子的语境。"}, "sentence_index": 6, "correct_answer": "不可或缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛会输，这是不可或缺的。", "explanation": "这里应该用〈注定〉。不可或缺说缺了就不行，强调重要；说比赛输定了，要用〈注定〉。"}, {"text": "天黑以后天色会暗，这是不可或缺的。", "explanation": "这里应该用〈理所当然〉。不可或缺强调缺了就不行；说天黑后天色变暗是自然之理，要用〈理所当然〉。"}, {"text": "明天太阳会升起，这是不可或缺的。", "explanation": "这里应该用〈必定〉。不可或缺强调缺了就不行；说太阳明天一定升起，要用〈必定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经成为团队里不可或缺人。", "corrected_sentence": "他已经成为团队里不可或缺的人。", "error_description": "“不可或缺”修饰名词时要加“的”，应说“不可或缺的人”；漏掉“的”，“不可或缺人”不成词组。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师是班里不可或缺了的支柱。", "corrected_sentence": "这位老师是班里不可或缺的支柱。", "error_description": "“不可或缺”修饰名词时只用“的”，不能加“了”；“了”表示动作完成，不能放在修饰名词的形容词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
