INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对生活和生产过程中产生的固体废弃物进行收集、运输、分类、处理、再利用或最终处置的过程。", "primary_collocate": null, "pronunciation": "lā jī chǔ lǐ", "ipa": "la˥ tɕi˥ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "通过有机（organic）废弃物的本地化循环转化，家庭层面的资源再利用机制有效缩短了传统垃圾处理链条，从而降低碳足迹并增强社区层面的生态韧性。", "target_word": "垃圾处理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市正在改进垃圾处理的方法。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理需要居民先把垃圾分类。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的垃圾处理费用越来越高。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的垃圾处理能减少对环境的污染。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府投入大量资金做好垃圾处理工作。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的垃圾处理一直是个难题。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理的最后一步是填埋或者焚烧。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着人口增加，垃圾处理的压力变大了。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家建议社区加强垃圾处理的宣传。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾处理厂", "label": "复合"}, {"form": "垃圾处理站", "label": "复合"}, {"form": "垃圾处理系统", "label": "复合"}, {"form": "垃圾處理", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "固体废弃物从收集到最终处置的整个过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：指从收集、运输到最终处置的整个过程，可以修饰“链条”，与“缩短了传统……链条”的语义相合。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“链条”指相互衔接的环节或工序，“人口”不能组成这样的链条，“传统人口链条”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能组成“链条”，句子无法表达“缩短链条”的意思。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”不是工序或环节，与“缩短链条”无关，句意不通。"}], "explanations": {"垃圾处理": "正确：指从收集、运输到最终处置的整个过程，可以修饰“链条”，与“缩短了传统……链条”的语义相合。", "人口": "搭配：“链条”指相互衔接的环节或工序，“人口”不能组成这样的链条，“传统人口链条”说不通。", "天气": "搭配：“天气”不能组成“链条”，句子无法表达“缩短链条”的意思。", "感情": "语义：“感情”不是工序或环节，与“缩短链条”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河被垃圾处理污染了。", "explanation": "这里应该用〈废弃物〉。垃圾处理指收集、处置废物的整个过程，不是污染物本身；河流被污染的是被丢弃的废弃物，而非处理过程。"}, {"text": "政府新建了一条垃圾处理。", "explanation": "这里应该用〈座〉或〈套〉。垃圾处理是一个过程，建设的是工厂或系统，应说“一座垃圾处理厂”或“一套垃圾处理系统”，“条”不用于此。"}, {"text": "他是我们家的垃圾处理。", "explanation": "这里是把过程误当成人。垃圾处理指处理的过程，不指做这项工作的人；指人应说〈垃圾处理员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：作主语，指从收集到最终处置的整个过程，与“难题”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“农村的颜色”不成立，“颜色”不能与“难题”构成这样的主谓关系。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是庆祝的日子，不是需要解决的问题，“农村的节日一直是个难题”句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是需要解决的问题，与“是个难题”的语义矛盾。"}], "explanations": {"垃圾处理": "正确：作主语，指从收集到最终处置的整个过程，与“难题”相合。", "颜色": "搭配：“农村的颜色”不成立，“颜色”不能与“难题”构成这样的主谓关系。", "节日": "语义：“节日”是庆祝的日子，不是需要解决的问题，“农村的节日一直是个难题”句意不通。", "天空": "语义：“天空”不是需要解决的问题，与“是个难题”的语义矛盾。"}, "sentence_index": 6, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的垃圾处理该倒了。", "explanation": "这里是把过程误当成容器。垃圾处理指处理的过程，不是盛放废物的东西；该倒的应是〈垃圾桶〉。"}, {"text": "我们小区新买了一台垃圾处理。", "explanation": "这里是把过程误当成设备。垃圾处理指处理的过程，不是机器；指设备应说〈垃圾处理器〉，“台”只计量机器，不能直接计量过程。"}, {"text": "这座城市的垃圾处理很害羞，不敢见人。", "explanation": "这里是把过程误当成人。垃圾处理指处理的过程，不会害羞；做这项工作的应是〈环卫工人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市完善了一套垃圾处理了体系。", "corrected_sentence": "这座城市完善了一套垃圾处理体系。", "error_description": "动态助词“了”误加在名词性的“垃圾处理”之后；“了”应紧接动词“完善”，全句只有这一处错误。错误形式：完善了一套垃圾处理了体系；正确形式：完善了一套垃圾处理体系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把垃圾处理很重视。", "corrected_sentence": "政府对垃圾处理很重视。", "error_description": "“重视”的对象应由介词“对”引出，应说“对垃圾处理很重视”；“把”字句要求对宾语作处置，且“很重视”不能用于把字句。错误形式：把垃圾处理很重视；正确形式：对垃圾处理很重视。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
