INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指性格、态度、言语等不严厉、不粗暴，使人感到亲切。", "primary_collocate": null, "pronunciation": "wēn hé", "ipa": "wən˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老师说话的语气很温和，学生们都不紧张。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格温和，从来不大声说话。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用温和的态度安慰着病人。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她温和地对孩子说：“没关系，慢慢来。”", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的笑容很温和，让人觉得亲切。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对客人的抱怨，经理的回答非常温和。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位校长待人温和，同事们都喜欢他。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话虽然温和，但是意思很清楚。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢温和的老师，不喜欢太严厉的。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和脾气急的哥哥比，弟弟温和多了。", "target_word": "温和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温和派", "label": "复合"}, {"form": "溫和", "label": "繁体"}], "register": "中性", "sense_fingerprint": "性格、态度、言语不严厉不粗暴，让人觉得亲切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温和", "is_correct": true, "explanation": "正确：修饰“语气”，指说话不严厉、不粗暴，与“学生们都不紧张”相合。"}, {"text": "严厉", "is_correct": false, "explanation": "语义：“严厉”让人紧张，与后半句“学生们都不紧张”相矛盾。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”会让学生感到紧张，与“学生们都不紧张”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材，不能用来形容“语气”。"}], "explanations": {"温和": "正确：修饰“语气”，指说话不严厉、不粗暴，与“学生们都不紧张”相合。", "严厉": "语义：“严厉”让人紧张，与后半句“学生们都不紧张”相矛盾。", "粗暴": "语义：“粗暴”会让学生感到紧张，与“学生们都不紧张”矛盾。", "高大": "搭配：“高大”形容身材，不能用来形容“语气”。"}, "sentence_index": 0, "correct_answer": "温和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的拳头很温和，一拳就把对手打倒了。", "explanation": "这里是把形容性格的“温和”误用到力量上。温和指性格、态度不粗暴，不形容拳头；且“一拳打倒”与“温和”矛盾，应说〈有力〉。"}, {"text": "这次考试的题目很温和，他全部答错了。", "explanation": "这里应该用〈简单〉。温和形容人的性格、态度，不用来形容题目难度；题目容易应说“简单”，且“全部答错”也与“温和”矛盾。"}, {"text": "湖面很温和，没有一丝风。", "explanation": "这里应该用〈平静〉。平静形容水面或心情没有波动；温和形容人的性格或态度，不用来形容湖面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温和", "is_correct": true, "explanation": "正确：指待人不严厉、不粗暴，与“同事们都喜欢他”相合。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示不关心别人，同事不会“都喜欢他”，句意矛盾。"}, {"text": "刻薄", "is_correct": false, "explanation": "语义：“刻薄”指说话尖酸，与“同事们都喜欢他”相矛盾。"}, {"text": "笨拙", "is_correct": false, "explanation": "搭配：“笨拙”形容动作不灵活，不用来描述“待人”的态度。"}], "explanations": {"温和": "正确：指待人不严厉、不粗暴，与“同事们都喜欢他”相合。", "冷漠": "语义：“冷漠”表示不关心别人，同事不会“都喜欢他”，句意矛盾。", "刻薄": "语义：“刻薄”指说话尖酸，与“同事们都喜欢他”相矛盾。", "笨拙": "搭配：“笨拙”形容动作不灵活，不用来描述“待人”的态度。"}, "sentence_index": 6, "correct_answer": "温和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆辣子鸡很温和地叫我起床。", "explanation": "这里是把形容人态度的“温和”用到了菜上。温和指性格、态度不粗暴，菜不能“温和地”做动作。"}, {"text": "面对小偷，他温和地拔出了手枪。", "explanation": "这里是把形容性格的“温和”误用到动作上。温和指性格、态度不粗暴，不形容拔枪；应说〈迅速〉或〈果断〉。"}, {"text": "这杯牛奶的性格很温和，可以直接喝。", "explanation": "这里是把形容人性格的“温和”用到了牛奶上。温和形容人的性格、态度，不用来说牛奶的状态；说牛奶不烫应说〈温热〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老奶奶温和的劝我先休息。", "corrected_sentence": "这位老奶奶温和地劝我先休息。", "error_description": "“温和”修饰动词“劝”时作状语，要用“地”，不能用“的”。错误形式：温和的劝；正确形式：温和地劝。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶讲故事讲很温和，孩子们都爱听。", "corrected_sentence": "奶奶讲故事讲得很温和，孩子们都爱听。", "error_description": "表示程度的补语要用结构助词“得”引出，应说“讲得很温和”；缺少“得”，说“讲很温和”不成立。错误形式：讲很温和；正确形式：讲得很温和。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显露", "is_correct": true, "explanation": "反义：“潜藏着”指暗中存在、不被察觉，“显露”指表现出来让人看见，二者相对。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”指把坏了的东西修好，与隐与显无关。"}, {"text": "搬运", "is_correct": false, "explanation": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被发现。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}], "correct_answer": "显露", "explanations": {"显露": "反义：“潜藏着”指暗中存在、不被察觉，“显露”指表现出来让人看见，二者相对。", "修理": "无反义关系：“修理”指把坏了的东西修好，与隐与显无关。", "搬运": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被发现。", "讨论": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：“潜藏着”指不被察觉地存在，“暴露”指藏着的东西被人知道，二者相对。"}, {"text": "翻译", "is_correct": false, "explanation": "无反义关系：“翻译”指把一种语言转成另一种语言，与隐现无关。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指到外地游览，与是否被发现无关。"}, {"text": "播种", "is_correct": false, "explanation": "无反义关系：“播种”指把种子撒进土里，与隐与显无关。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：“潜藏着”指不被察觉地存在，“暴露”指藏着的东西被人知道，二者相对。", "翻译": "无反义关系：“翻译”指把一种语言转成另一种语言，与隐现无关。", "旅行": "无反义关系：“旅行”指到外地游览，与是否被发现无关。", "播种": "无反义关系：“播种”指把种子撒进土里，与隐与显无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "隐藏着，不让人发现或注意到。", "primary_collocate": null, "pronunciation": "qián cáng zhe", "ipa": "tɕʰjɛn˧˥ tsʰɑŋ˧˥ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "这一自己动手（DIY）型生态干预，本质上是对工业化消费模式的温和重构，其背后潜藏着深层的园艺（horticulture）哲学——即人与土地之间应建立一种非掠夺性的共生关系。", "target_word": "潜藏着", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "平静的生活下面潜藏着不少危险。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容里潜藏着深深的悲伤。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同看起来简单，其实潜藏着风险。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的错误背后可能潜藏着大问题。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这座安静的城市里，潜藏着许多机会。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里潜藏着一个没人知道的秘密。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次成功的背后潜藏着许多人的努力。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看似普通的数据中潜藏着重要的信息。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话里潜藏着对我们的不满。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜藏", "label": "体标"}, {"form": "潜藏了", "label": "体标"}, {"form": "潜藏过", "label": "体标"}, {"form": "潛藏著", "label": "繁体"}], "register": "中性", "sense_fingerprint": "危险、问题、情感等抽象的东西暗中存在，不易被发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示深层哲学暗中存在、不易被察觉，与句意相合。"}, {"text": "停放着", "is_correct": false, "explanation": "语义：“停放”指车辆或物品停留放置，抽象的哲学不能被停放。"}, {"text": "挂着", "is_correct": false, "explanation": "搭配：“挂着”多接具体物件或画像，不说“背后挂着哲学”。"}, {"text": "堆着", "is_correct": false, "explanation": "语义：“堆着”指许多实物堆放在一起，与抽象的哲学不相容。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示深层哲学暗中存在、不易被察觉，与句意相合。", "停放着": "语义：“停放”指车辆或物品停留放置，抽象的哲学不能被停放。", "挂着": "搭配：“挂着”多接具体物件或画像，不说“背后挂着哲学”。", "堆着": "语义：“堆着”指许多实物堆放在一起，与抽象的哲学不相容。"}, "sentence_index": 0, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白板的角落里潜藏着一行大字：欢迎光临。", "explanation": "这里应该用〈写着〉。潜藏着指东西隐藏起来、不被看见，而白板上的大字醒目可见，应说“白板的角落里写着一行大字”。"}, {"text": "夜空中潜藏着许多星星，亮得很。", "explanation": "这里应该用〈闪烁〉。潜藏着强调不被察觉，而星星明亮可见，应说“夜空中闪烁着许多星星”。"}, {"text": "他潜藏着病情，没有告诉家人。", "explanation": "这里应该用〈隐瞒〉。潜藏着说的是事物自己暗中存在，不用来形容人主动瞒着别人，应说“他隐瞒了病情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示秘密藏在心里、没人知道，与句意相合。"}, {"text": "陈列着", "is_correct": false, "explanation": "语义：“陈列”是摆出来供人观看，与“没人知道的秘密”相矛盾。"}, {"text": "写着", "is_correct": false, "explanation": "搭配：“写着”要写在纸或墙上，不说心里写着一个秘密。"}, {"text": "唱着", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱秘密。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示秘密藏在心里、没人知道，与句意相合。", "陈列着": "语义：“陈列”是摆出来供人观看，与“没人知道的秘密”相矛盾。", "写着": "搭配：“写着”要写在纸或墙上，不说心里写着一个秘密。", "唱着": "搭配：“唱”的对象是歌曲，不能说唱秘密。"}, "sentence_index": 6, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息在报纸头版潜藏着，每个读者一翻开报纸就看见了。", "explanation": "这里应该用〈刊登〉。潜藏着指不被发现，而头版消息人人可见，应说“报纸头版刊登了这个消息”。"}, {"text": "公园的入口处潜藏着一块大招牌，远远地就能看见。", "explanation": "这里应该用〈竖立〉。潜藏着指不被注意，而大招牌远远可见，应说“公园入口处竖立着一块大招牌”。"}, {"text": "路牌上潜藏着几个大字，过往的行人一抬头就能读到。", "explanation": "这里应该用〈标着〉。潜藏着指不被看见，而路牌上的大字醒目，行人一抬头就能读到，应说“路牌上标着几个大字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们的笑声里潜藏在一丝不安。", "corrected_sentence": "孩子们的笑声里潜藏着一丝不安。", "error_description": "错误在于“潜藏”后的“在”。应为“潜藏着”，“着”表示持续存在的状态；“潜藏在”后面要接处所，不能直接接“一丝不安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子角落里潜藏起来一股怪味。", "corrected_sentence": "屋子角落里潜藏着一股怪味。", "error_description": "错误在于“潜藏”后的“起来”。应为“潜藏着”，“着”表示怪味持续存在的状态；“潜藏起来”是不及物的，后面不能直接接宾语“一股怪味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
