INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容通过强力或威胁的方式夺取他人财物或资源的行为。", "primary_collocate": null, "pronunciation": "lüè duó xìng", "ipa": "lɥe˥˩ two˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这一自己动手（DIY）型生态干预，本质上是对工业化消费模式的温和重构，其背后潜藏着深层的园艺（horticulture）哲学——即人与土地之间应建立一种非掠夺性的共生关系。", "target_word": "掠夺性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种掠夺性开发会毁掉森林。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过度捕鱼是一种掠夺性的做法。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们对矿产的掠夺性开采很严重。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府禁止掠夺性经营。", "target_word": "掠夺性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的掠夺性行为让村民很生气。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "掠夺性捕捞让海里的鱼越来越少。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要停止对土地的掠夺性使用。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种掠夺性的方式不能长久。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家批评这种掠夺性的开发计划。", "target_word": "掠夺性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掠奪性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "以强力或威胁夺取他人财物资源的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掠夺性", "is_correct": true, "explanation": "正确。“非掠夺性”表示不以强力夺取他人资源，与“共生关系”的句意相合。"}, {"text": "暴躁性", "is_correct": false, "explanation": "语义：“暴躁”形容人的脾气，共生关系不能暴躁。"}, {"text": "易燃性", "is_correct": false, "explanation": "语义：“易燃”说的是物质的性质，与共生关系不相干。"}, {"text": "高温性", "is_correct": false, "explanation": "搭配：“高温”多用于天气或物体，不说“共生关系的高温性”。"}], "explanations": {"掠夺性": "正确。“非掠夺性”表示不以强力夺取他人资源，与“共生关系”的句意相合。", "暴躁性": "语义：“暴躁”形容人的脾气，共生关系不能暴躁。", "易燃性": "语义：“易燃”说的是物质的性质，与共生关系不相干。", "高温性": "搭配：“高温”多用于天气或物体，不说“共生关系的高温性”。"}, "sentence_index": 0, "correct_answer": "掠夺性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种液体有很强的掠夺性，接触皮肤会受伤。", "explanation": "这里应该用〈腐蚀性〉。掠夺性指以强力夺取财物资源，液体伤皮肤是腐蚀，应说“有很强的腐蚀性”。"}, {"text": "这种病的掠夺性很强，要注意隔离。", "explanation": "这里应该用〈传染性〉。掠夺性指夺取财物资源，疾病是传播，应说“传染性很强”。"}, {"text": "这场地震的掠夺性很大，房子倒了很多。", "explanation": "这里应该用〈破坏性〉。掠夺性强调夺取财物资源，地震造成的是毁坏，应说“破坏性很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掠夺性", "is_correct": true, "explanation": "正确。“掠夺性捕捞”指过度猎取，与“鱼越来越少”的句意相合。"}, {"text": "节约性", "is_correct": false, "explanation": "语义：“节约”意味着少消耗，与“鱼越来越少”的结果相矛盾。"}, {"text": "装饰性", "is_correct": false, "explanation": "搭配：捕捞的目的不是装饰，不说“装饰性捕捞”。"}, {"text": "欢乐性", "is_correct": false, "explanation": "语义：“欢乐”形容愉快的气氛，与捕捞导致鱼减少的情况不相符。"}], "explanations": {"掠夺性": "正确。“掠夺性捕捞”指过度猎取，与“鱼越来越少”的句意相合。", "节约性": "语义：“节约”意味着少消耗，与“鱼越来越少”的结果相矛盾。", "装饰性": "搭配：捕捞的目的不是装饰，不说“装饰性捕捞”。", "欢乐性": "语义：“欢乐”形容愉快的气氛，与捕捞导致鱼减少的情况不相符。"}, "sentence_index": 6, "correct_answer": "掠夺性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学成绩很有掠夺性，班里没人能超过他。", "explanation": "这里应该用〈突出〉。掠夺性指以强力夺取他人财物或资源，形容成绩应说“很突出”，与此处的义项不符。"}, {"text": "这幅画的颜色很有掠夺性，看一眼就忘不掉。", "explanation": "这里应该用〈鲜明〉。掠夺性指以强力夺取他人财物或资源，形容颜色应说“很鲜明”。"}, {"text": "妈妈做饭很有掠夺性，每次都把厨房收拾得干干净净。", "explanation": "这里应该用〈利落〉。掠夺性指以强力夺取他人财物或资源，形容做事干净利索应说“利落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种开采方式具有很强的很掠夺性。", "corrected_sentence": "这种开采方式具有很强的掠夺性。", "error_description": "程度副词“很”重复修饰：“很强的”已为“掠夺性”加上程度修饰，不能再在“掠夺性”前加“很”。错误形式：具有很强的很掠夺性；正确形式：具有很强的掠夺性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种很掠夺性开发十分普遍。", "corrected_sentence": "这种掠夺性开发十分普遍。", "error_description": "错误在于在定语“掠夺性”前加了程度副词“很”。“掠夺性”修饰“开发”时直接作定语，应说“这种掠夺性开发”，不能说“很掠夺性开发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "脏：与“卫生”意思相反，指不干净、可能有细菌，与厕所不卫生的说法相对。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜：形容价格低，与“卫生”没有反义关系，不能描述清洁状况。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明：形容人的智力或反应快，与“卫生”的清洁义无关。"}, {"text": "锋利", "is_correct": false, "explanation": "锋利：形容刀刃等尖利，与“卫生”的清洁义没有对应关系。"}], "correct_answer": "脏", "explanations": {"脏": "脏：与“卫生”意思相反，指不干净、可能有细菌，与厕所不卫生的说法相对。", "便宜": "便宜：形容价格低，与“卫生”没有反义关系，不能描述清洁状况。", "聪明": "聪明：形容人的智力或反应快，与“卫生”的清洁义无关。", "锋利": "锋利：形容刀刃等尖利，与“卫生”的清洁义没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "脏：与“卫生”意思相反，指不干净、可能有细菌，与检查教室卫生的内容相对。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨：形容待人大方，与“卫生”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝：形容反应慢，与“卫生”的清洁义无关。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重：形容分量大或心情压抑，与“卫生”的清洁义没有对应关系。"}], "correct_answer": "脏", "explanations": {"脏": "脏：与“卫生”意思相反，指不干净、可能有细菌，与检查教室卫生的内容相对。", "慷慨": "慷慨：形容待人大方，与“卫生”没有反义关系。", "迟钝": "迟钝：形容反应慢，与“卫生”的清洁义无关。", "沉重": "沉重：形容分量大或心情压抑，与“卫生”的清洁义没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "卫生指保持身体、环境清洁健康的行为或状态，如个人卫生、公共卫生。", "primary_collocate": null, "pronunciation": "wèi shēng", "ipa": "wei˥˩ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "要实现高效且卫生的家庭堆肥运作，首要在于理解“绿色材料”与“棕色材料”的生化平衡。", "target_word": "卫生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家餐馆很注意厨房卫生。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭前洗手是个好的卫生习惯。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共厕所不太卫生，我不想去。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请注意个人卫生。", "target_word": "卫生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水果要洗干净才卫生。", "target_word": "卫生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "街道上的卫生状况越来越好。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用脏手拿食物，很不卫生。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说生吃海鲜不卫生。", "target_word": "卫生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校每周检查教室的卫生。", "target_word": "卫生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "衛生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体与环境清洁健康的状态或行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卫生", "is_correct": true, "explanation": "卫生：修饰“运作”，指清洁、无病菌，与“高效”并列，句意通顺。"}, {"text": "迟缓", "is_correct": false, "explanation": "语义：“迟缓”与前面的“高效”意思相反，前后矛盾。"}, {"text": "繁琐", "is_correct": false, "explanation": "语义：“繁琐”与“高效”相矛盾，高效的运作不会繁琐。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“混乱”与“高效”相矛盾，高效的运作不会混乱。"}], "explanations": {"卫生": "卫生：修饰“运作”，指清洁、无病菌，与“高效”并列，句意通顺。", "迟缓": "语义：“迟缓”与前面的“高效”意思相反，前后矛盾。", "繁琐": "语义：“繁琐”与“高效”相矛盾，高效的运作不会繁琐。", "混乱": "语义：“混乱”与“高效”相矛盾，高效的运作不会混乱。"}, "sentence_index": 0, "correct_answer": "卫生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多吃蔬菜很卫生。", "explanation": "这里应该用〈健康〉。卫生指清洁、无病菌，说饮食对身体有益要用健康。"}, {"text": "这首歌很卫生。", "explanation": "这里应该用〈好听〉。“好听”指声音动听，“卫生”指清洁、无病菌，不能用来评价歌曲。"}, {"text": "这个花坛修得很卫生。", "explanation": "这里应该用〈美观〉。“美观”指外形好看，“卫生”指清洁、无病菌，形容花坛的样子要用美观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卫生", "is_correct": true, "explanation": "卫生：修饰“状况”，指清洁、无病菌的状况，与“越来越好”相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外貌或景物，不能修饰“状况”。"}, {"text": "危险", "is_correct": false, "explanation": "语义：“危险”与“越来越好”矛盾，状况不能既危险又在变好。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”指声音吵闹，与“街道状况越来越好”的评价不协调。"}], "explanations": {"卫生": "卫生：修饰“状况”，指清洁、无病菌的状况，与“越来越好”相符。", "漂亮": "搭配：“漂亮”多形容外貌或景物，不能修饰“状况”。", "危险": "语义：“危险”与“越来越好”矛盾，状况不能既危险又在变好。", "嘈杂": "语义：“嘈杂”指声音吵闹，与“街道状况越来越好”的评价不协调。"}, "sentence_index": 6, "correct_answer": "卫生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书摆得很卫生。", "explanation": "这里应该用〈整齐〉。“整齐”指摆放有序，“卫生”指清洁、无病菌，不能用来形容摆放。"}, {"text": "她画的画很卫生。", "explanation": "这里应该用〈漂亮〉。“漂亮”指好看，“卫生”指清洁、无病菌，不能用来评价画的好坏。"}, {"text": "他对客人很卫生。", "explanation": "这里应该用〈热情〉。“热情”指待人友好，“卫生”只指清洁，不能形容待人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅没卫生，我不想去。", "corrected_sentence": "这家餐厅不卫生，我不想去。", "error_description": "“卫生”作形容词表示否定要用“不”，应说“不卫生”，不能说“没卫生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新开的这家店比老店很卫生。", "corrected_sentence": "新开的这家店比老店卫生。", "error_description": "比字句中不能再用程度副词“很”修饰形容词，“很”应删去。错误形式：比老店很卫生；正确形式：比老店卫生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
