INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "棕色是由红色和黄色混合而成的颜色，像巧克力的颜色。", "primary_collocate": null, "pronunciation": "zōng sè", "ipa": "tsʊŋ˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这棵老树的树皮是棕色的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗有一身棕色的毛。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的树叶变成了棕色。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢穿棕色的皮鞋。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力是棕色的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一个棕色的皮包。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有一只棕色的大熊。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色和黄色混在一起，会变成棕色。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼睛是漂亮的棕色。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子是用棕色的木头做的。", "target_word": "棕色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深棕色", "label": "复合"}, {"form": "浅棕色", "label": "复合"}], "register": "中性", "sense_fingerprint": "棕色:名词:红黄混合而成、像巧克力的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棕色", "is_correct": true, "explanation": "正确：“树皮是棕色的”是描述树皮颜色的常用说法，与句中的老树语境相符。"}, {"text": "液体", "is_correct": false, "explanation": "语义：树皮是固体，“液体的树皮”与事实不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：树皮是植物组织，不是石头，“石头的树皮”句意不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：树皮不是玻璃，“玻璃的树皮”与事实不符。"}], "explanations": {"棕色": "正确：“树皮是棕色的”是描述树皮颜色的常用说法，与句中的老树语境相符。", "液体": "语义：树皮是固体，“液体的树皮”与事实不符。", "石头": "语义：树皮是植物组织，不是石头，“石头的树皮”句意不通。", "玻璃": "语义：树皮不是玻璃，“玻璃的树皮”与事实不符。"}, "sentence_index": 0, "correct_answer": "棕色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上喝了一杯棕色。", "explanation": "这里应该用〈咖啡〉。棕色是颜色，不能当作饮料的名称。"}, {"text": "他有一个棕色的主意。", "explanation": "这里应该用〈好〉。评价主意的好坏要说“好”，棕色只表示颜色，不能用来评价主意。"}, {"text": "我最喜欢吃棕色。", "explanation": "这里应该用〈巧克力〉。棕色是颜色，不能当作食物来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棕色", "is_correct": true, "explanation": "正确：“森林里有一只棕色的大熊”，棕色修饰大熊的颜色，这里应填“棕色”。"}, {"text": "液体", "is_correct": false, "explanation": "语义：大熊不可能由液体构成，“液体的大熊”句意不通。"}, {"text": "金属", "is_correct": false, "explanation": "语义：森林里的大熊不是金属制品，“金属的大熊”与句中的自然场景不符。"}, {"text": "电子", "is_correct": false, "explanation": "搭配：“电子”一般不用来修饰动物，“电子的大熊”搭配不当。"}], "explanations": {"棕色": "正确：“森林里有一只棕色的大熊”，棕色修饰大熊的颜色，这里应填“棕色”。", "液体": "语义：大熊不可能由液体构成，“液体的大熊”句意不通。", "金属": "语义：森林里的大熊不是金属制品，“金属的大熊”与句中的自然场景不符。", "电子": "搭配：“电子”一般不用来修饰动物，“电子的大熊”搭配不当。"}, "sentence_index": 6, "correct_answer": "棕色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子是用棕色做的。", "explanation": "这里应该用〈木头〉。棕色是颜色，不能说明桌子是用什么材料做成的。"}, {"text": "他用棕色唱了一首歌。", "explanation": "这里应该用〈嗓子〉。唱歌要靠嗓子发声，棕色是颜色，不能当作唱歌的工具。"}, {"text": "他在比赛中得了棕色。", "explanation": "这里应该用〈铜牌〉。比赛中获得的奖牌要说“铜牌”，棕色是颜色，不能指奖牌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选了一只棕色。", "corrected_sentence": "他选了一种棕色。", "error_description": "量词错误：“棕色”作颜色名词时用量词“种”，“只”只用于动物等单个个体，不能用来计量颜色。正确应为“一种棕色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了两个棕色色的皮包。", "corrected_sentence": "妈妈昨天买了两个棕色的皮包。", "error_description": "错误：“棕色”本身已含“色”字，后面不应再加“色”，应改为“棕色的毛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
