INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物化学的简称，研究生物体内化学过程和物质的科学。", "primary_collocate": null, "pronunciation": "shēng huà", "ipa": "ʂɤŋ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "要实现高效且卫生的家庭堆肥运作，首要在于理解“绿色材料”与“棕色材料”的生化平衡。", "target_word": "生化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在大学读生化，想研究新药。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生化课上，老师讲了细胞里的反应。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的生化考试得了第一名。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生化实验室里不能吃东西。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生在大学学过生化，所以能看懂血液检查的结果。", "target_word": "生化", "complexity_tier": "T3", "furigana": "yī shēng zài dà xué xué guò shēng huà, suǒ yǐ néng kàn dǒng xuè yè jiǎn chá de jié guǒ", "sentence_source": "generated"}, {"text": "生化研究帮助人们了解身体里的变化。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥学的是生化，毕业后进了药厂。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要了解食物怎么变成能量，先要学一点生化。", "target_word": "生化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生化是一门很有用的科学。", "target_word": "生化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生化反应", "label": "复合"}, {"form": "生化实验", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物化学的简称，一门学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生化", "is_correct": true, "explanation": "正确：生化 shēnghuà，指生物化学，研究生物体内化学过程的学科。"}, {"text": "神话", "is_correct": false, "explanation": "shén（第二声）与 shēng（第一声）声调不同，韵母 en 与 eng 也不同，意思是神话。"}, {"text": "升华", "is_correct": false, "explanation": "shēnghuá（第二声）与 shēnghuà（第四声）声调不同，意思是升华。"}, {"text": "深化", "is_correct": false, "explanation": "shēnhuà 与 shēnghuà 的韵母不同（en 与 eng），声调相同，意思是深化。"}, {"text": "生花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，意思是生出花朵，常见于“妙笔生花”。"}], "explanations": {"生化": "正确：生化 shēnghuà，指生物化学，研究生物体内化学过程的学科。", "神话": "shén（第二声）与 shēng（第一声）声调不同，韵母 en 与 eng 也不同，意思是神话。", "升华": "shēnghuá（第二声）与 shēnghuà（第四声）声调不同，意思是升华。", "深化": "shēnhuà 与 shēnghuà 的韵母不同（en 与 eng），声调相同，意思是深化。", "生花": "huā（第一声）与 huà（第四声）声调不同，意思是生出花朵，常见于“妙笔生花”。"}, "sentence_index": null, "correct_answer": "生化"}, "level_3": {"options": [{"text": "生化", "is_correct": true, "explanation": "正确：“生化平衡”指堆肥中有机物分解的生化关系，与句意一致。"}, {"text": "文化", "is_correct": false, "explanation": "语义：堆肥材料的比例是化学过程，“文化”与堆肥运作无关。"}, {"text": "艺术", "is_correct": false, "explanation": "语义：堆肥材料的分解过程与“艺术”无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“平衡”多用于系统、关系，不说“体重平衡”。"}], "explanations": {"生化": "正确：“生化平衡”指堆肥中有机物分解的生化关系，与句意一致。", "文化": "语义：堆肥材料的比例是化学过程，“文化”与堆肥运作无关。", "艺术": "语义：堆肥材料的分解过程与“艺术”无关，句意不通。", "体重": "搭配：“平衡”多用于系统、关系，不说“体重平衡”。"}, "sentence_index": 0, "correct_answer": "生化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天早上七点起床，生化很规律。", "explanation": "这里应该用〈生活〉。“生活很规律”说日常起居，“生化”不能描述日常起居。"}, {"text": "他每天早上吃一碗生化当早饭。", "explanation": "这里应该用〈面条〉。生化是学科名称，不能当作食物。"}, {"text": "我的生化很重，搬不动。", "explanation": "这里应该用〈行李〉。生化是学科名称，不是有重量的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生化", "is_correct": true, "explanation": "正确：“生化研究”指研究生物化学的学科，与句意一致。"}, {"text": "社会", "is_correct": false, "explanation": "语义：社会研究与身体里的变化无关，句意不通。"}, {"text": "天文", "is_correct": false, "explanation": "语义：天文研究与人体内部的变化无关，句意不通。"}, {"text": "文具", "is_correct": false, "explanation": "搭配：“研究”后接的通常是学科或领域，“文具”不是研究领域。"}], "explanations": {"生化": "正确：“生化研究”指研究生物化学的学科，与句意一致。", "社会": "语义：社会研究与身体里的变化无关，句意不通。", "天文": "语义：天文研究与人体内部的变化无关，句意不通。", "文具": "搭配：“研究”后接的通常是学科或领域，“文具”不是研究领域。"}, "sentence_index": 6, "correct_answer": "生化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树在夏天生化得很快。", "explanation": "这里应该用〈生长〉。树长高用生长；生化不是这个意思。"}, {"text": "厨房的橱柜里放着一瓶生化。", "explanation": "这里应该用〈酱油〉。生化是学科名称，不能装在瓶子里。"}, {"text": "他每天傍晚在生化上跑步。", "explanation": "这里应该用〈操场〉。生化是学科名称，不是跑步的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表妹在大学里学了了生化，现在做研究。", "corrected_sentence": "表妹在大学里学了生化，现在做研究。", "error_description": "错误形式：“学了了生化”；正确形式：“学了生化”。动词后只需一个“了”，重复的“了”是常见的学习者错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今年选了一个生化。", "corrected_sentence": "他今年选了一门生化。", "error_description": "错误形式：“一个生化”；正确形式：“一门生化”。学科要用量词“门”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
