INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指某样东西里含有大量的某种成分或物质。", "primary_collocate": null, "pronunciation": "fù hán", "ipa": "fu˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "富含", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "橙子富含维生素。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶富含钙，对骨头很好。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼富含蛋白质。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海藻富含碘，对身体有好处。", "target_word": "富含", "complexity_tier": "T3", "furigana": "hǎi zǎo fù hán diǎn, duì shēn tǐ yǒu hǎo chù.", "sentence_source": "generated"}, {"text": "这片土地富含铁，所以是红色的。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚果富含油脂，不要吃太多。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的水富含盐，不能喝。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉富含钾，运动后可以吃一根。", "target_word": "富含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米富含淀粉，能给身体提供能量。", "target_word": "富含", "complexity_tier": "T3", "furigana": "yù mǐ fù hán diàn fěn, néng gěi shēn tǐ tí gòng néng liàng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "富含着", "label": "体标"}], "register": "书面", "sense_fingerprint": "富含:动词:某物中含有大量某种成分或物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富含", "is_correct": true, "explanation": "正确：“富含”表示有机肥里含有大量腐殖质，与句意一致。"}, {"text": "缺少", "is_correct": false, "explanation": "语义：“缺少腐殖质”与“转化为……稳定有机肥”的目的相悖，句意不通。"}, {"text": "排除", "is_correct": false, "explanation": "搭配：“排除”针对干扰因素，不能与腐殖质这类成分搭配。"}, {"text": "排出", "is_correct": false, "explanation": "语义：“排出腐殖质”是把腐殖质排走，与“富含腐殖质”的意思相反，句意不符。"}], "explanations": {"富含": "正确：“富含”表示有机肥里含有大量腐殖质，与句意一致。", "缺少": "语义：“缺少腐殖质”与“转化为……稳定有机肥”的目的相悖，句意不通。", "排除": "搭配：“排除”针对干扰因素，不能与腐殖质这类成分搭配。", "排出": "语义：“排出腐殖质”是把腐殖质排走，与“富含腐殖质”的意思相反，句意不符。"}, "sentence_index": 0, "correct_answer": "富含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学富含一万名学生。", "explanation": "这里应该用〈包括〉。富含只说某物里含有大量成分或物质，学校里有多少学生不能用“富含”。"}, {"text": "这个箱子富含三本书。", "explanation": "这里应该用〈含有〉。富含讲的是物质成分，箱子里的书不是成分，应说“含有”或“装着”。"}, {"text": "他富含一辆汽车。", "explanation": "这里应该用〈拥有〉。富含不用于人拥有物品，人拥有东西要说“拥有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富含", "is_correct": true, "explanation": "正确：“富含”说坚果里油脂多，与“不要吃太多”的提醒相符。"}, {"text": "凝固", "is_correct": false, "explanation": "配价：“凝固”是不及物动词，不能带“油脂”作宾语。"}, {"text": "蒸发", "is_correct": false, "explanation": "搭配：“蒸发”一般用于水分等液体，不说“蒸发油脂”。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：“驱散”是赶走的意思，与“坚果富含油脂”的句意不合。"}], "explanations": {"富含": "正确：“富含”说坚果里油脂多，与“不要吃太多”的提醒相符。", "凝固": "配价：“凝固”是不及物动词，不能带“油脂”作宾语。", "蒸发": "搭配：“蒸发”一般用于水分等液体，不说“蒸发油脂”。", "驱散": "语义：“驱散”是赶走的意思，与“坚果富含油脂”的句意不合。"}, "sentence_index": 6, "correct_answer": "富含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师富含很强的责任心。", "explanation": "这里应该用〈具备〉。责任心是人的品质，不是物质成分，应说“具备”。"}, {"text": "这间教室富含欢快的笑声。", "explanation": "这里应该用〈充满〉。富含讲物质成分，教室里弥漫的笑声要说“充满”。"}, {"text": "她的脸上富含幸福。", "explanation": "这里应该用〈洋溢〉。幸福从脸上流露要说“洋溢”，“富含”只用于物质成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "燕麦富含过膳食纤维，早上吃很健康。", "corrected_sentence": "燕麦富含膳食纤维，早上吃很健康。", "error_description": "错误：“富含”是状态动词，不能加表示经历的助词“过”，应删去“过”，说“燕麦富含膳食纤维”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "芝麻富含了钙，经常吃有益健康。", "corrected_sentence": "芝麻富含钙，经常吃有益健康。", "error_description": "错误：“富含”是状态动词，不能加表示完成的助词“了”，应删去“了”，说“芝麻富含钙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
