INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氮，化学元素，符号N，原子序数7，通常状态下为无色、无臭、无味的气体，是空气中含量最多的成分。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "空气里有很多氮。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "氮是一种没有颜色的气体。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物长大需要氮。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "氮的符号是N。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种肥料里有氮，也有磷。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤里缺少氮，叶子就会变黄。", "target_word": "氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中氮最多，氧排第二。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学课上，老师给我们介绍了氮。", "target_word": "氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氮没有气味，也没有味道。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮的原子序数是七。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "氮气", "label": "复合词"}, {"form": "氮肥", "label": "复合词"}], "register": "科技", "sense_fingerprint": "化学元素氮，空气中含量最多的无色无味气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11481, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确答案：氮（dàn），化学元素，空气中含量最多的无色无味气体。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn（第四声）声调不同，意思是胆囊或勇气。"}, {"text": "丹", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是红色或丹药。"}, {"text": "炭", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是木炭。"}], "explanations": {"氮": "正确答案：氮（dàn），化学元素，空气中含量最多的无色无味气体。", "胆": "dǎn（第三声）与 dàn（第四声）声调不同，意思是胆囊或勇气。", "丹": "dān（第一声）与 dàn（第四声）声调不同，意思是红色或丹药。", "炭": "tàn 与 dàn 声母不同（t 与 d），意思是木炭。"}, "sentence_index": null, "correct_answer": "氮"}, "level_3": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确：“氮”是空气中的成分，与“空气里有很多”的句意一致。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁是固态金属，空气里不会大量存在。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是固体材料，不会大量漂浮在空气里，“空气里有很多木板”与事实不符。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“空气里”一般搭配气体，不说“空气里有很多糖”。"}], "explanations": {"氮": "正确：“氮”是空气中的成分，与“空气里有很多”的句意一致。", "铁": "语义：铁是固态金属，空气里不会大量存在。", "木板": "语义：木板是固体材料，不会大量漂浮在空气里，“空气里有很多木板”与事实不符。", "糖": "搭配：“空气里”一般搭配气体，不说“空气里有很多糖”。"}, "sentence_index": 0, "correct_answer": "氮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院里常用氮来帮助病人呼吸。", "explanation": "这里应该用〈氧〉。帮助病人呼吸要用氧气，氮不能供给呼吸，不能用“氮”。"}, {"text": "烧烤的时候要用氮来生火。", "explanation": "这里应该用〈木炭〉。烧烤燃料是木炭（碳），氮不能燃烧，不能用来生火。"}, {"text": "游泳池里要加氮来消毒。", "explanation": "这里应该用〈氯〉。游泳池消毒用氯，氮没有消毒作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11481, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确答案：氮（dàn），化学元素，空气中含量最多的无色无味气体。"}, {"text": "单", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是单独、单位。"}, {"text": "荡", "is_correct": false, "explanation": "dàng 与 dàn 韵母不同（ang 与 an），意思是摇动。"}, {"text": "叹", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是叹气。"}], "explanations": {"氮": "正确答案：氮（dàn），化学元素，空气中含量最多的无色无味气体。", "单": "dān（第一声）与 dàn（第四声）声调不同，意思是单独、单位。", "荡": "dàng 与 dàn 韵母不同（ang 与 an），意思是摇动。", "叹": "tàn 与 dàn 声母不同（t 与 d），意思是叹气。"}, "sentence_index": null, "correct_answer": "氮"}, "level_3": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确：“氮”是空气中含量最多的气体，与前后句相符。"}, {"text": "氧", "is_correct": false, "explanation": "语义：前半句说“最多”的是氧，与后半句“氧排第二”矛盾。"}, {"text": "碳", "is_correct": false, "explanation": "语义：碳在空气中的含量远低于氮，不会是最多的成分。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“空气中……最多”说的是气体成分，固态石头不能这样说。"}], "explanations": {"氮": "正确：“氮”是空气中含量最多的气体，与前后句相符。", "氧": "语义：前半句说“最多”的是氧，与后半句“氧排第二”矛盾。", "碳": "语义：碳在空气中的含量远低于氮，不会是最多的成分。", "石头": "搭配：“空气中……最多”说的是气体成分，固态石头不能这样说。"}, "sentence_index": 6, "correct_answer": "氮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室里有一只氮。", "explanation": "这里应该用〈瓶〉。氮是气体，装在容器里计量要用“瓶”“罐”，“只”不用于气体。"}, {"text": "燃料电池用氮发电，很环保。", "explanation": "这里应该用〈氢〉。氢能燃烧、可作燃料电池的原料；氮不能燃烧，不能这样用。"}, {"text": "医生用氮给伤口消毒。", "explanation": "这里应该用〈碘〉。碘有消毒作用，常用来给伤口消毒；氮没有这种用途。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每天生产一只氮。", "corrected_sentence": "这家工厂每天生产一吨氮。", "error_description": "错误：量词“只”用于动物等，不能用于氮这种气体。应用“吨”（或“瓶”“罐”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气氮约占空气的四分之三，无色无味。", "corrected_sentence": "氮气约占空气的四分之三，无色无味。", "error_description": "错误：“氮气”是复合词，语素顺序不能颠倒，“气氮”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
