INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草屑指草被切割或折断后产生的细小碎片或粉末，常见于修剪草坪或收割干草时。", "primary_collocate": null, "pronunciation": "cǎo xiè", "ipa": "tsʰau˨˩˦ ɕie˥˩", "syllable_count": 2, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "草屑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "割完草后，地上全是草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把草屑倒进了堆肥箱。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，草屑飞到了衣服上。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鞋底沾着草屑。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堆草屑可以做肥料。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "修剪草坪后要扫掉草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草屑落进了他的头发里。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "割草机把草屑喷到路上。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里到处是绿色的草屑。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "把", "label": "量词"}], "register": "中性", "sense_fingerprint": "割草或折断草后产生的细小碎片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：指新鲜的细碎草片，属于湿性有机物，与“新鲜”搭配，句意通顺。"}, {"text": "碎纸", "is_correct": false, "explanation": "语义：碎纸属于干燥的棕色材料，与“湿性有机物”不符。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料不是有机物，不能归入“湿性有机物”。"}, {"text": "石子", "is_correct": false, "explanation": "搭配：“新鲜”修饰石子不通顺，石子也不属于有机物。"}], "explanations": {"草屑": "草屑：指新鲜的细碎草片，属于湿性有机物，与“新鲜”搭配，句意通顺。", "碎纸": "语义：碎纸属于干燥的棕色材料，与“湿性有机物”不符。", "塑料": "语义：塑料不是有机物，不能归入“湿性有机物”。", "石子": "搭配：“新鲜”修饰石子不通顺，石子也不属于有机物。"}, "sentence_index": 0, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在草地上采了一把草屑。", "explanation": "这里应该用〈草叶〉。草屑是细碎的碎片，采摘的是完整的草叶，不能说采草屑。"}, {"text": "我们每周修剪草屑。", "explanation": "这里应该用〈草坪〉。修剪的是长着的草坪，草屑已是碎片，不能修剪。"}, {"text": "他把草屑编成了小篮子。", "explanation": "这里应该用〈稻草〉。编织需要完整的长条草，草屑是碎片，不能用来编织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：修剪后扫走的是碎草，与“扫掉”搭配，句意通顺。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是被修剪的对象，不能被扫掉。"}, {"text": "花盆", "is_correct": false, "explanation": "搭配：“扫掉”用于碎屑，不能说扫掉花盆。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是固定的建筑，不会被“扫掉”。"}], "explanations": {"草屑": "草屑：修剪后扫走的是碎草，与“扫掉”搭配，句意通顺。", "草坪": "语义：草坪是被修剪的对象，不能被扫掉。", "花盆": "搭配：“扫掉”用于碎屑，不能说扫掉花盆。", "围墙": "语义：围墙是固定的建筑，不会被“扫掉”。"}, "sentence_index": 6, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "园丁把草屑挖了出来，重新种草。", "explanation": "这里应该用〈草根〉。草根埋在土里可以挖出，草屑是碎片，不能挖。"}, {"text": "她把草屑夹进书里做标本。", "explanation": "这里应该用〈花瓣〉。花瓣薄而完整，可以压成标本，草屑只是碎片，不能这样用。"}, {"text": "院子里开满了草屑。", "explanation": "这里应该用〈花〉。“开满”用于花朵，草屑不会开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里扫出了一只草屑。", "corrected_sentence": "院子里扫出了一堆草屑。", "error_description": "“草屑”的量词应用“堆”或“把”，不能用“只”，“只”一般用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把草屑扫了掉。", "corrected_sentence": "他把草屑扫掉了。", "error_description": "“扫掉”是动词加结果补语的固定结构，“掉”要紧跟动词，应说“扫掉了”，不能说“扫了掉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干性", "is_correct": true, "explanation": "干性与湿性相对，指不含水分、干燥的性质，如“干性材料”。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬描述质地的硬度，与湿性所指的含水性质没有反义关系。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重描述重量，与湿性所指的含水性质不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮描述光线，与湿性所指的含水性质不构成反义。"}], "correct_answer": "干性", "explanations": {"干性": "干性与湿性相对，指不含水分、干燥的性质，如“干性材料”。", "坚硬": "坚硬描述质地的硬度，与湿性所指的含水性质没有反义关系。", "沉重": "沉重描述重量，与湿性所指的含水性质不构成反义。", "明亮": "明亮描述光线，与湿性所指的含水性质不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "柔软", "is_correct": false, "explanation": "柔软描述质地，与湿性所指的含水性质没有反义关系。"}, {"text": "干性", "is_correct": true, "explanation": "干性与湿性相对，指不含水分、干燥的性质，如句中“干草是干性材料”。"}, {"text": "轻便", "is_correct": false, "explanation": "轻便描述使用时的便利程度，与湿性所指的含水性质不构成反义。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈描述液体的透明程度，与湿性所指的含水性质不构成反义。"}], "correct_answer": "干性", "explanations": {"柔软": "柔软描述质地，与湿性所指的含水性质没有反义关系。", "干性": "干性与湿性相对，指不含水分、干燥的性质，如句中“干草是干性材料”。", "轻便": "轻便描述使用时的便利程度，与湿性所指的含水性质不构成反义。", "清澈": "清澈描述液体的透明程度，与湿性所指的含水性质不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容含有水分或潮湿的性质。", "primary_collocate": null, "pronunciation": "shī xìng", "ipa": "ʂɨ˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "湿性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "湿性材料含水多，放在桶里容易发臭。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性原料要放进冰箱，干性原料放柜子里。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性饲料含水量高，夏天不能放太久。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥时湿性材料太多，要加些干树叶。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种湿性敷料能让伤口保持潮湿。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性废料运输时要防止渗漏，避免污染路面。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "shī xìng fèi liào yùn shū shí yào fáng zhǐ shèn lòu, bì miǎn wū rǎn lù miàn.", "sentence_source": "generated"}, {"text": "菜叶和果皮属于湿性材料，木屑属于干性材料。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性废料比较重，因为里面有很多水。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鲜草屑是湿性材料，干草是干性材料。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濕性", "label": "繁体"}, {"form": "湿性材料", "label": "复合"}], "register": "书面", "sense_fingerprint": "湿性：含有水分、潮湿的性质（多作定语，如湿性材料）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿性", "is_correct": true, "explanation": "湿性：东西含水、潮湿的性质，多作定语，如“湿性材料”。"}, {"text": "失信", "is_correct": false, "explanation": "shī xìn 与湿性 shī xìng 的第一个音节相同，第二个音节韵尾不同（xìn 为 -n，xìng 为 -ng），意思是失去信用。"}, {"text": "施行", "is_correct": false, "explanation": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是实施、施行。"}, {"text": "食性", "is_correct": false, "explanation": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是动物的食物种类和摄食习性。"}, {"text": "实行", "is_correct": false, "explanation": "shí xíng 与 shī xìng 两个音节的声调都不同，意思是执行、实施。"}], "explanations": {"湿性": "湿性：东西含水、潮湿的性质，多作定语，如“湿性材料”。", "失信": "shī xìn 与湿性 shī xìng 的第一个音节相同，第二个音节韵尾不同（xìn 为 -n，xìng 为 -ng），意思是失去信用。", "施行": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是实施、施行。", "食性": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是动物的食物种类和摄食习性。", "实行": "shí xíng 与 shī xìng 两个音节的声调都不同，意思是执行、实施。"}, "sentence_index": null, "correct_answer": "湿性"}, "level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "语义：干燥指不含水分，与前文“厨余果皮、咖啡渣、新鲜草屑”等含水材料矛盾。"}, {"text": "湿性", "is_correct": true, "explanation": "正确：“湿性”修饰“有机物”，说明这类物质含水分，与前文列举的含水材料相符。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：“新鲜”多用于食物、草叶，不能直接修饰“有机物”这类物质的总称，搭配不当。"}, {"text": "干性", "is_correct": false, "explanation": "语义：干性指不含水分的性质，与前文列举的含水绿色材料相反。"}], "explanations": {"干燥": "语义：干燥指不含水分，与前文“厨余果皮、咖啡渣、新鲜草屑”等含水材料矛盾。", "湿性": "正确：“湿性”修饰“有机物”，说明这类物质含水分，与前文列举的含水材料相符。", "新鲜": "搭配：“新鲜”多用于食物、草叶，不能直接修饰“有机物”这类物质的总称，搭配不当。", "干性": "语义：干性指不含水分的性质，与前文列举的含水绿色材料相反。"}, "sentence_index": 0, "correct_answer": "湿性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨后的湿性空气让人觉得很舒服。", "explanation": "这里应该用〈湿润〉。湿性指东西含水的性质，多用于材料、废料；形容空气、土地潮湿的舒适感要用湿润。"}, {"text": "他是个湿性很强的人。", "explanation": "这里用错了对象。湿性只说东西、材料带水的性质，不能用来形容人；形容人的性情要用〈阴沉〉。"}, {"text": "地下室的湿性很大，墙上长满了霉。", "explanation": "这里应该用〈湿度〉。湿性是形容词，不作名词；说地下室潮湿的程度要用湿度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湿性", "is_correct": true, "explanation": "湿性：东西含水、潮湿的性质，多作定语，如“湿性废料”。"}, {"text": "时兴", "is_correct": false, "explanation": "shí xīng 与 shī xìng 两个音节的声调都不同，意思是一时流行、时髦。"}, {"text": "施刑", "is_correct": false, "explanation": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是对人施加刑罚。"}, {"text": "实性", "is_correct": false, "explanation": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是真实、实体的性质，多见于医学描述。"}, {"text": "室性", "is_correct": false, "explanation": "shì xìng 的第一个音节声调不同（shì 为第四声，shī 为第一声），是医学用语，指心室的。"}], "explanations": {"湿性": "湿性：东西含水、潮湿的性质，多作定语，如“湿性废料”。", "时兴": "shí xīng 与 shī xìng 两个音节的声调都不同，意思是一时流行、时髦。", "施刑": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是对人施加刑罚。", "实性": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是真实、实体的性质，多见于医学描述。", "室性": "shì xìng 的第一个音节声调不同（shì 为第四声，shī 为第一声），是医学用语，指心室的。"}, "sentence_index": null, "correct_answer": "湿性"}, "level_3": {"options": [{"text": "干性", "is_correct": false, "explanation": "语义：干性废料不含水，一般不会渗漏，与“防止渗漏”的要求不符。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”描述物体能否透光，一般不用来修饰“废料”。"}, {"text": "湿性", "is_correct": true, "explanation": "正确：“湿性废料”指含水的废料，运输时才需要防止渗漏。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：清洁的废料不会污染路面，与后文“避免污染路面”的语境矛盾。"}], "explanations": {"干性": "语义：干性废料不含水，一般不会渗漏，与“防止渗漏”的要求不符。", "透明": "搭配：“透明”描述物体能否透光，一般不用来修饰“废料”。", "湿性": "正确：“湿性废料”指含水的废料，运输时才需要防止渗漏。", "清洁": "语义：清洁的废料不会污染路面，与后文“避免污染路面”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "湿性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的湿性很大，衣服很难干。", "explanation": "这里应该用〈湿度〉。湿度指空气中水汽的多少，用来描述天气潮湿的程度；湿性只说东西本身含水的性质，不用来形容天气。"}, {"text": "这台机器的湿性很强，运转起来很顺。", "explanation": "这里用错了对象。湿性只说东西含水的性质，不能用来描述机器的运转；说机器运转平稳，要用〈平稳〉。"}, {"text": "这批草屑的湿性很多，堆放时要通风。", "explanation": "这里应该用〈水分〉。湿性是形容词，说草屑里水的多少要用“水分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堆湿性地材料要先晾干再装袋。", "corrected_sentence": "这堆湿性材料要先晾干再装袋。", "error_description": "“湿性”作定语时直接放在名词前，中间不能加“地”（“地”用于修饰动词、形容词作状语）。应说“湿性材料”，不能说“湿性地材料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批很湿性的草屑要盖上布，防止风干。", "corrected_sentence": "这批湿性的草屑要盖上布，防止风干。", "error_description": "“湿性”作定语时前面不能加程度副词“很”，应说“湿性的草屑”，不能说“很湿性的草屑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
