INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通常指含有碳元素的化合物，是生命物质的基础。", "primary_collocate": null, "pronunciation": "yǒu jī wù", "ipa": "joʊ˨˩˦ tɕi˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "有机物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "有机物里一般都含有碳元素。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐不是有机物，因为它不含碳元素。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物用阳光把水和二氧化碳变成有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋白质是生命物质，也是一种有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里，老师让我们分辨有机物和无机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机物燃烧时会产生二氧化碳。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精是一种常见的有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤里的有机物越多，植物长得越好。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄糖和脂肪都属于有机物，是常见的能量来源。", "target_word": "有机物", "complexity_tier": "T3", "furigana": "pú táo táng hé zhī fáng dōu shǔ yú yǒu jī wù, shì cháng jiàn de néng liàng lái yuán.", "sentence_source": "generated"}], "morphological_forms": [{"form": "有機物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有机物：含碳的化合物，生命物质的基础（化学术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无机物", "is_correct": false, "explanation": "语义：无机物不含碳元素，与前文“厨余果皮、咖啡渣、新鲜草屑”等有机材料矛盾。"}, {"text": "矿物质", "is_correct": false, "explanation": "语义：矿物质多为无机成分，与前文列举的有机材料性质不合。"}, {"text": "有机物", "is_correct": true, "explanation": "正确：“湿性有机物”指含水的有机物，与前文列举的厨余果皮、咖啡渣等相符。"}, {"text": "水分", "is_correct": false, "explanation": "搭配：“水分”是量的概念，“湿性水分”搭配不当，不能作为材料种类的名称。"}], "explanations": {"无机物": "语义：无机物不含碳元素，与前文“厨余果皮、咖啡渣、新鲜草屑”等有机材料矛盾。", "矿物质": "语义：矿物质多为无机成分，与前文列举的有机材料性质不合。", "有机物": "正确：“湿性有机物”指含水的有机物，与前文列举的厨余果皮、咖啡渣等相符。", "水分": "搭配：“水分”是量的概念，“湿性水分”搭配不当，不能作为材料种类的名称。"}, "sentence_index": 0, "correct_answer": "有机物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水是一种有机物，能帮助身体散热。", "explanation": "这里应该用〈无机物〉。有机物指含碳的化合物，水由氢和氧组成，不含碳，属于无机物。"}, {"text": "食盐属于有机物，里面不含碳元素。", "explanation": "这里应该用〈无机物〉。有机物含碳，食盐不含碳，应说“食盐属于无机物”。"}, {"text": "铁是一种有机物，很容易生锈。", "explanation": "这里应该用〈金属〉。有机物指含碳的化合物，铁是金属元素，不属于有机物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属", "is_correct": false, "explanation": "语义：金属在普通条件下不会燃烧生成二氧化碳，与句中的说法矛盾。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“水”不能燃烧，“水燃烧时”搭配不当。"}, {"text": "有机物", "is_correct": true, "explanation": "正确：有机物含碳，燃烧时会产生二氧化碳，与句意相符。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石多为无机物，不会燃烧产生二氧化碳。"}], "explanations": {"金属": "语义：金属在普通条件下不会燃烧生成二氧化碳，与句中的说法矛盾。", "水": "搭配：“水”不能燃烧，“水燃烧时”搭配不当。", "有机物": "正确：有机物含碳，燃烧时会产生二氧化碳，与句意相符。", "矿石": "语义：矿石多为无机物，不会燃烧产生二氧化碳。"}, "sentence_index": 6, "correct_answer": "有机物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店卖的都是有机物，比如铜勺和玻璃杯。", "explanation": "这里应该用〈无机物〉。铜和玻璃都属于无机物，不是含碳的有机化合物。"}, {"text": "我把这只有机物放进了试管里。", "explanation": "这里应该用〈种〉或〈类〉。“只”用于动物和器物，有机物是物质，应说“这种有机物”。"}, {"text": "氢和氧都属于有机物，是化学元素。", "explanation": "这里应该用〈无机物〉或〈元素〉。氢和氧是不含碳的化学元素，不属于有机物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "甲烷是最简单的一座有机物，只含碳和氢。", "corrected_sentence": "甲烷是最简单的一种有机物，只含碳和氢。", "error_description": "量词错误：“有机物”是一类化合物，应说“一种有机物”，不能用“座”（“座”用于山、楼等大型固定物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些有机物们燃烧后会变成水和二氧化碳。", "corrected_sentence": "这些有机物燃烧后会变成水和二氧化碳。", "error_description": "“有机物”是物质名称，不能加“们”表示复数，应去掉“们”，说“这些有机物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指生物生长或活动所需要的碳的来源，比如植物通过光合作用利用二氧化碳，动物通过吃食物获得碳。", "primary_collocate": null, "pronunciation": "tàn yuán", "ipa": "tʰan˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "碳源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "碳源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "植物用二氧化碳当碳源。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物吃食物，食物就是它的碳源。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌长大需要碳源。", "target_word": "碳源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "糖是细菌很好的碳源。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验里，我们用葡萄糖做碳源。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有碳源，微生物就不能生长。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干树叶可以给堆肥提供碳源。", "target_word": "碳源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种培养液里缺少碳源。", "target_word": "碳源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "生物生长所需碳的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：前句说绿色材料富含氮元素，棕色材料则提供碳源，二者形成对比。"}, {"text": "氮源", "is_correct": false, "explanation": "语义：前句已说绿色材料富含氮元素，棕色材料不应提供氮源。"}, {"text": "光照", "is_correct": false, "explanation": "搭配：“提供”后接的是养分类物料，干燥残余物不能说提供光照。"}, {"text": "水分", "is_correct": false, "explanation": "语义：句中的“干燥残余物”与“水分”相矛盾。"}], "explanations": {"碳源": "正确：前句说绿色材料富含氮元素，棕色材料则提供碳源，二者形成对比。", "氮源": "语义：前句已说绿色材料富含氮元素，棕色材料不应提供氮源。", "光照": "搭配：“提供”后接的是养分类物料，干燥残余物不能说提供光照。", "水分": "语义：句中的“干燥残余物”与“水分”相矛盾。"}, "sentence_index": 0, "correct_answer": "碳源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用碳源喂养小狗。", "explanation": "这里应该用〈食物〉。碳源指生物获得碳的来源，不是可以直接拿来喂养宠物的东西。"}, {"text": "我用碳源来擦桌子。", "explanation": "这里应该用〈抹布〉。碳源指生物获得碳的物质，不能用来擦桌子。"}, {"text": "这批货的碳源很可靠。", "explanation": "这里应该用〈来源〉。碳源专指生物获得碳的物质，不能泛指货物的出处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碳源", "is_correct": true, "explanation": "正确：葡萄糖是细菌可以利用的碳源。"}, {"text": "食盐", "is_correct": false, "explanation": "语义：葡萄糖是糖类，不能用来做食盐。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：葡萄糖不能用来做玩具。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“做”的对象应是实验用的物料，不说用葡萄糖做钢铁。"}], "explanations": {"碳源": "正确：葡萄糖是细菌可以利用的碳源。", "食盐": "语义：葡萄糖是糖类，不能用来做食盐。", "玩具": "语义：葡萄糖不能用来做玩具。", "钢铁": "搭配：“做”的对象应是实验用的物料，不说用葡萄糖做钢铁。"}, "sentence_index": 6, "correct_answer": "碳源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家大力发展碳源，减少对煤的依赖。", "explanation": "这里应该用〈能源〉。碳源指生物获得碳的来源，不是指国家发展的能源。"}, {"text": "这辆车的碳源用完了，要加油。", "explanation": "这里应该用〈燃料〉。碳源指生物获得碳的来源，不能指汽车使用的燃料。"}, {"text": "这封信的碳源很清楚。", "explanation": "这里应该用〈出处〉。碳源特指生物获得碳的来源，不能泛指信件的出处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里买了一只碳源。", "corrected_sentence": "实验室里买了一种碳源。", "error_description": "“碳源”是物质，量词应用“种”，不能用“只”（“只”多用于动物或单个物体）。把“一只”改为“一种”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这组培养皿里缺少碳源们。", "corrected_sentence": "这组培养皿里缺少碳源。", "error_description": "错误：“们”只用于指人或有生命的群体，不能加在“碳源”后面，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完整", "is_correct": true, "explanation": "正确：完整与“碎”相对，指东西没有破裂成块。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指清楚分明，与“碎”不是反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地软，与“碎”的破裂状态没有对应的反义关系。"}, {"text": "光滑", "is_correct": false, "explanation": "光滑描述表面质地，与“碎”不构成反义关系。"}], "correct_answer": "完整", "explanations": {"完整": "正确：完整与“碎”相对，指东西没有破裂成块。", "清晰": "清晰指清楚分明，与“碎”不是反义关系。", "柔软": "柔软指质地软，与“碎”的破裂状态没有对应的反义关系。", "光滑": "光滑描述表面质地，与“碎”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完整", "is_correct": true, "explanation": "正确：完整与“碎”相对，指纸张没有撕裂成块。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足、颜色鲜亮，与“碎”不是反义关系。"}, {"text": "平滑", "is_correct": false, "explanation": "平滑描述表面质地，与“碎”不是反义关系。"}, {"text": "香甜", "is_correct": false, "explanation": "香甜形容味道甜美，与“碎”不是反义关系。"}], "correct_answer": "完整", "explanations": {"完整": "正确：完整与“碎”相对，指纸张没有撕裂成块。", "明亮": "明亮指光线充足、颜色鲜亮，与“碎”不是反义关系。", "平滑": "平滑描述表面质地，与“碎”不是反义关系。", "香甜": "香甜形容味道甜美，与“碎”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体因外力作用而分裂成小块或碎片。", "primary_collocate": null, "pronunciation": "suì", "ipa": "suei˥˩", "syllable_count": 1, "sentences": [{"text": "杯子掉在地上，碎了。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有很多碎玻璃。", "target_word": "碎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小心，这个碗很容易碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，窗户的玻璃都碎了。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饼干掉在地上，全碎了。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕碎了，要去修。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块石头很硬，不容易碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把纸撕得很碎，扔进了垃圾桶。", "target_word": "碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓶从桌子上摔下来，碎成了几块。", "target_word": "碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们捡起地上的碎纸，放进袋子里。", "target_word": "碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碎了", "label": "体标"}, {"form": "打碎", "label": "复合词"}, {"form": "碎片", "label": "复合词"}], "register": "中性", "sense_fingerprint": "物体受力裂成小块、碎片的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：碎（suì），指物体受外力裂成小块。"}, {"text": "随", "is_correct": false, "explanation": "suí 与 suì 声调不同，意思是跟随。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z / s），声调相同，意思是最。"}, {"text": "睡", "is_correct": false, "explanation": "shuì 与 suì 声母不同（sh / s），声调相同，意思是睡觉。"}], "explanations": {"碎": "正确：碎（suì），指物体受外力裂成小块。", "随": "suí 与 suì 声调不同，意思是跟随。", "最": "zuì 与 suì 声母不同（z / s），声调相同，意思是最。", "睡": "shuì 与 suì 声母不同（sh / s），声调相同，意思是睡觉。"}, "sentence_index": null, "correct_answer": "碎"}, "level_3": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：杯子摔落后裂成小块，用“碎”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：杯子摔落在地上不会因此变亮。"}, {"text": "凉", "is_correct": false, "explanation": "语义：杯子掉在地上不会因此变凉。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”不描述摔落后的结果，与“掉在地上”的变化不相关。"}], "explanations": {"碎": "正确：杯子摔落后裂成小块，用“碎”。", "亮": "语义：杯子摔落在地上不会因此变亮。", "凉": "语义：杯子掉在地上不会因此变凉。", "干净": "搭配：“干净”不描述摔落后的结果，与“掉在地上”的变化不相关。"}, "sentence_index": 0, "correct_answer": "碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的封面碎了。", "explanation": "这里应该用〈破〉。碎指东西裂成小块，封面只是破损，应说“破了”。"}, {"text": "这根绳子碎了。", "explanation": "这里应该用〈断〉。碎指东西摔成小块，绳子被拉断应说“断”。"}, {"text": "这碗汤碎了。", "explanation": "这里应该用〈凉〉。碎指物体受外力摔成小块，汤变冷应说“凉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：碎（suì），指物体受外力裂成小块。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 suì 声母不同（d / s），声调相同，意思是对。"}, {"text": "醉", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z / s），声调相同，意思是醉酒。"}, {"text": "翠", "is_correct": false, "explanation": "cuì 与 suì 声母不同（c / s），声调相同，意思是翠绿。"}], "explanations": {"碎": "正确：碎（suì），指物体受外力裂成小块。", "对": "duì 与 suì 声母不同（d / s），声调相同，意思是对。", "醉": "zuì 与 suì 声母不同（z / s），声调相同，意思是醉酒。", "翠": "cuì 与 suì 声母不同（c / s），声调相同，意思是翠绿。"}, "sentence_index": null, "correct_answer": "碎"}, "level_3": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：石头很硬，不容易裂成小块，用“碎”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：石头不会因此有甜味，句意不通。"}, {"text": "响", "is_correct": false, "explanation": "语义：“响”与石头是否容易被破坏无关，句意不通。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”不能用来描述石头的性质。"}], "explanations": {"碎": "正确：石头很硬，不容易裂成小块，用“碎”。", "甜": "语义：石头不会因此有甜味，句意不通。", "响": "语义：“响”与石头是否容易被破坏无关，句意不通。", "香": "搭配：“香”不能用来描述石头的性质。"}, "sentence_index": 6, "correct_answer": "碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上碎了一道缝。", "explanation": "这里应该用〈裂〉。碎指东西摔成小块，墙缝只是裂开，应说“裂”。"}, {"text": "这杯水很碎。", "explanation": "这里应该用〈热〉。碎指物体摔成小块，形容水的温度应说“热”。"}, {"text": "天气碎了。", "explanation": "这里应该用〈变〉。碎指物体受外力摔成小块，天气的变化应说“变”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把纸碎了。", "corrected_sentence": "他把纸撕碎了。", "error_description": "“碎”作结果补语，前面需要动作动词，“把纸碎了”缺少动词，应补上“撕”，说“撕碎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块玻璃很硬，不容易碎了。", "corrected_sentence": "这块玻璃很硬，不容易碎。", "error_description": "“不容易碎”表示一般性的性质，不能加“了”；应删去句末的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
