INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸板是由纸浆制成的一种较厚、较硬的纸张，常用于制作包装盒或模型。", "primary_collocate": null, "pronunciation": "zhǐ bǎn", "ipa": "ʈʂʐ̩˨˩˦ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "纸板", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "纸板", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我用纸板做了一个小房子模型。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递盒是用纸板做的，很轻。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸板剪成了三块。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用纸板做手工。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块纸板太薄，做不了盒子。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在纸板上画了一只大熊猫。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，我们找了很多纸板来包东西。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用完的纸板放进回收箱。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张纸板", "label": "量词"}, {"form": "一块纸板", "label": "量词"}, {"form": "硬纸板", "label": "复合"}, {"form": "瓦楞纸板", "label": "复合"}, {"form": "紙板", "label": "繁体"}], "register": "中性", "sense_fingerprint": "纸浆制成的较厚较硬的纸，用于包装盒、模型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11489, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纸板", "is_correct": true, "explanation": "纸板 zhǐ bǎn：纸浆制成的较厚较硬的纸，正确答案。"}, {"text": "直板", "is_correct": false, "explanation": "直板 zhí bǎn：zhí（第二声）与 zhǐ（第三声）声调不同，意思是直的板子。"}, {"text": "制版", "is_correct": false, "explanation": "制版 zhì bǎn：zhì（第四声）与 zhǐ（第三声）声调不同，意思是印刷或制作的版。"}, {"text": "纸本", "is_correct": false, "explanation": "纸本 zhǐ běn：běn 与 bǎn 韵母不同（en 与 an），意思是纸质的版本。"}], "explanations": {"纸板": "纸板 zhǐ bǎn：纸浆制成的较厚较硬的纸，正确答案。", "直板": "直板 zhí bǎn：zhí（第二声）与 zhǐ（第三声）声调不同，意思是直的板子。", "制版": "制版 zhì bǎn：zhì（第四声）与 zhǐ（第三声）声调不同，意思是印刷或制作的版。", "纸本": "纸本 zhǐ běn：běn 与 bǎn 韵母不同（en 与 an），意思是纸质的版本。"}, "sentence_index": null, "correct_answer": "纸板"}, "level_3": {"options": [{"text": "纸板", "is_correct": true, "explanation": "“碎纸板”指干燥的纸板碎片，属于棕色碳源材料，与“干树叶、木屑”并列。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”属于前文的绿色湿性材料，与此处“干燥残余物”的棕色材料相矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是有机物，无法为堆肥提供碳源。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“碎”用于形容块状或片状的固体，不能说“碎水”。"}], "explanations": {"纸板": "“碎纸板”指干燥的纸板碎片，属于棕色碳源材料，与“干树叶、木屑”并列。", "蔬菜": "语义：“蔬菜”属于前文的绿色湿性材料，与此处“干燥残余物”的棕色材料相矛盾。", "玻璃": "语义：玻璃不是有机物，无法为堆肥提供碳源。", "水": "搭配：“碎”用于形容块状或片状的固体，不能说“碎水”。"}, "sentence_index": 0, "correct_answer": "纸板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个快递是装在纸板里寄来的。", "explanation": "这里应该用〈纸箱〉。纸板是片状的硬纸材料，装东西的立体容器要用纸箱，不说“装在纸板里”。"}, {"text": "这条新闻登在纸板上。", "explanation": "这里应该用〈报纸〉。纸板厚而硬，不用于印刷刊登新闻，新闻应登在报纸上。"}, {"text": "超市把东西装进纸板里。", "explanation": "这里应该用〈纸袋〉。纸板是片状材料，装东西要用纸袋或纸箱，不说“装进纸板里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸板", "is_correct": true, "explanation": "“这块纸板”指一片纸板，太薄，所以做不了盒子，只有“纸板”符合语境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能用来做盒子，“这块面包太薄，做不了盒子”的语境说不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，与“做不了盒子”的说法无关，句子无法成立。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能用来做盒子，“做不了盒子”的说法对食品没有意义。"}], "explanations": {"纸板": "“这块纸板”指一片纸板，太薄，所以做不了盒子，只有“纸板”符合语境。", "面包": "语义：面包不能用来做盒子，“这块面包太薄，做不了盒子”的语境说不通。", "蛋糕": "语义：蛋糕是食品，与“做不了盒子”的说法无关，句子无法成立。", "饼干": "语义：饼干是食品，不能用来做盒子，“做不了盒子”的说法对食品没有意义。"}, "sentence_index": 6, "correct_answer": "纸板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只纸板做手工。", "explanation": "这里应该用〈张〉或〈块〉。“只”多用于动物或成对器物中的一个，平面的纸板说“一只”很不自然。"}, {"text": "他撕了一根纸板。", "explanation": "这里应该用〈张〉或〈块〉。“根”用于细长的东西，纸板是平面的，不用“根”。"}, {"text": "我买了一把纸板。", "explanation": "这里应该用〈张〉或〈块〉。“把”用于有柄或可以握住的器具，纸板没有这些特征。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一个纸板。", "corrected_sentence": "他买了一块纸板。", "error_description": "量词错误：“纸板”是平面的薄片，应用量词“块”或“张”，说“一个纸板”是错误的，应为“一块纸板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹纸板折成了一个小盒子。", "corrected_sentence": "妹妹把纸板折成了一个小盒子。", "error_description": "“把”缺失：处置式要用“把”引出宾语“纸板”，应为“妹妹把纸板折成了一个小盒子”，省去“把”写成“妹妹纸板折成”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
