INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木屑是指锯木头时掉下来的细碎粉末或小颗粒。", "primary_collocate": null, "pronunciation": "mù xiè", "ipa": "mu˥˩ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "木屑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人锯木头时，地上掉了很多木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把木屑扫进桶里吧。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木屑很轻，风一吹就飞起来了。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木匠锯完木头，头发上都是木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟笼的底下铺着一层木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边锯木头，一边用嘴吹掉木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木屑是很细小的颗粒，别吸进鼻子里。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完家具，工人要清理地上的木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在木屑堆里跑来跑去。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "层", "label": "量词"}], "register": "中性", "sense_fingerprint": "木屑：锯木头时掉下的细碎粉末或小颗粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：锯木头时掉下的细碎粉末或小颗粒。"}, {"text": "不屑", "is_correct": false, "explanation": "bù（第四声）与 mù（第四声）声母不同（b 与 m），意思是轻视、看不起。"}, {"text": "木楔", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是木头做的楔子。"}, {"text": "木鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是木头做的鞋。"}], "explanations": {"木屑": "木屑：锯木头时掉下的细碎粉末或小颗粒。", "不屑": "bù（第四声）与 mù（第四声）声母不同（b 与 m），意思是轻视、看不起。", "木楔": "xiē（第一声）与 xiè（第四声）声调不同，意思是木头做的楔子。", "木鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是木头做的鞋。"}, "sentence_index": null, "correct_answer": "木屑"}, "level_3": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：干燥的锯末颗粒，属于棕色碳源材料。"}, {"text": "厨余果皮", "is_correct": false, "explanation": "语义：前文已说厨余果皮是湿性有机物，与“干燥”矛盾。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“干燥”不能修饰饭菜，“干燥残余物”也不指饭菜。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是有机物，不能作为堆肥中的碳源。"}], "explanations": {"木屑": "木屑：干燥的锯末颗粒，属于棕色碳源材料。", "厨余果皮": "语义：前文已说厨余果皮是湿性有机物，与“干燥”矛盾。", "饭菜": "搭配：“干燥”不能修饰饭菜，“干燥残余物”也不指饭菜。", "玻璃": "语义：玻璃不是有机物，不能作为堆肥中的碳源。"}, "sentence_index": 0, "correct_answer": "木屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只木屑。", "explanation": "这里应该用〈堆〉。木屑是成堆的细碎颗粒，量词不能用〈只〉，那是用于动物或单件物品的。"}, {"text": "这堆完整的木屑可以拿来当柴烧。", "explanation": "这里应该用〈木块〉。木屑是细碎的颗粒，不能说“完整”；完整的木料要用木块。"}, {"text": "爷爷用木屑雕刻了一只小鸟。", "explanation": "这里应该用〈木头〉。木屑是细碎的颗粒，无法雕刻成型；雕刻要用整块的木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：锯木头时掉下的细碎颗粒，可以用嘴吹掉。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“吹掉”只能搭配细碎的东西，不能说“吹掉木头”。"}, {"text": "锯子", "is_correct": false, "explanation": "语义：锯子是锯木头用的工具，不是锯下来的东西，无法被吹掉。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是完整的板材，不是锯下的碎末，与“锯木头”的结果不符。"}], "explanations": {"木屑": "木屑：锯木头时掉下的细碎颗粒，可以用嘴吹掉。", "木头": "搭配：“吹掉”只能搭配细碎的东西，不能说“吹掉木头”。", "锯子": "语义：锯子是锯木头用的工具，不是锯下来的东西，无法被吹掉。", "木板": "语义：木板是完整的板材，不是锯下的碎末，与“锯木头”的结果不符。"}, "sentence_index": 6, "correct_answer": "木屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这堆木屑都是长长的木条。", "explanation": "这里应该用〈木条〉。木屑是细碎的颗粒，不能说是“长长的”；长条形的木料要用木条。"}, {"text": "这些木屑又粗又壮。", "explanation": "这里应该用〈木棒〉。木屑是细碎的颗粒，说不上“又粗又壮”；粗长结实的木料要用木棒。"}, {"text": "这些木屑很高大。", "explanation": "这里应该用〈木头〉。木屑是细碎的颗粒，说不上高大；说木材高大要用木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙角有一只木屑，要记得打扫。", "corrected_sentence": "墙角有一堆木屑，要记得打扫。", "error_description": "量词错误：“木屑”是成堆的细碎颗粒，应说“一堆木屑”，不能说“一只木屑”（“只”用于动物或单件物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风把木屑吹了地上。", "corrected_sentence": "风把木屑吹到了地上。", "error_description": "补语缺失：“吹”后要用补语“到”表示落点，应说“风把木屑吹到了地上”，不能说“风把木屑吹了地上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "湿润", "is_correct": true, "explanation": "正确答案。“湿润”与“干燥”相对，指水分充足。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线，与“干燥”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“干燥”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音小，与“干燥”没有反义关系，其反义词是吵闹。"}], "correct_answer": "湿润", "explanations": {"湿润": "正确答案。“湿润”与“干燥”相对，指水分充足。", "明亮": "“明亮”形容光线，与“干燥”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“干燥”没有反义关系。", "安静": "“安静”形容声音小，与“干燥”没有反义关系，其反义词是吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "湿润", "is_correct": true, "explanation": "正确答案。“湿润”与“干燥”相对，指水分充足。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”形容水或眼睛干净透明，与“干燥”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧哗，与“干燥”没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”形容质地硬，与“干燥”没有反义关系，其反义词是柔软。"}], "correct_answer": "湿润", "explanations": {"湿润": "正确答案。“湿润”与“干燥”相对，指水分充足。", "清澈": "“清澈”形容水或眼睛干净透明，与“干燥”没有反义关系。", "热闹": "“热闹”形容场面喧哗，与“干燥”没有反义关系。", "坚硬": "“坚硬”形容质地硬，与“干燥”没有反义关系，其反义词是柔软。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "缺乏水分的状态，与湿润相对。", "primary_collocate": null, "pronunciation": "gān zào", "ipa": "kan˥˥ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这样做可以让桶里保持干燥，也能减少虫子和臭味。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "南方夏天很潮湿，北方的秋天却很干燥。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天空气干燥，最好在房间里放一盆水。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的皮肤很干燥，每天洗完脸都要擦护肤霜。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子要放在干燥阴凉的地方，不然会发霉。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的气候干燥，一年很少下雨。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间太干燥了，我的喉咙很不舒服。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书要放在干燥的柜子里，别让它受潮。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气干燥的时候，很容易着火，大家要小心。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天又冷又干燥，很少下雨下雪。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "干燥剂", "label": "复合"}, {"form": "干燥器", "label": "复合"}, {"form": "乾燥", "label": "繁体"}], "register": "通用", "sense_fingerprint": "空气、气候、皮肤等缺少水分，与潮湿、湿润相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“干燥”读作 gān zào，指缺少水分。"}, {"text": "干枣", "is_correct": false, "explanation": "干枣 gān zǎo 与“干燥”的第一个音节相同，第二个音节只有声调不同（第三声与第四声），意思是干枣。"}, {"text": "干草", "is_correct": false, "explanation": "干草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是干草。"}, {"text": "干扰", "is_correct": false, "explanation": "干扰 gān rǎo 的第二个音节声母 r 与 z 不同，声调也不同，意思是妨碍。"}], "explanations": {"干燥": "正确答案。“干燥”读作 gān zào，指缺少水分。", "干枣": "干枣 gān zǎo 与“干燥”的第一个音节相同，第二个音节只有声调不同（第三声与第四声），意思是干枣。", "干草": "干草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是干草。", "干扰": "干扰 gān rǎo 的第二个音节声母 r 与 z 不同，声调也不同，意思是妨碍。"}, "sentence_index": null, "correct_answer": "干燥"}, "level_3": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“保持干燥”指桶里不潮湿，与“减少虫子和臭味”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容人多声杂，不能形容桶里的状态。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，不能用来形容桶里的干湿。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”说光线充足，与“减少虫子和臭味”无关。"}], "explanations": {"干燥": "正确答案。“保持干燥”指桶里不潮湿，与“减少虫子和臭味”相符。", "热闹": "语义：“热闹”形容人多声杂，不能形容桶里的状态。", "高大": "体貌：“高大”形容人或物的形体，不能用来形容桶里的干湿。", "明亮": "语义：“明亮”说光线充足，与“减少虫子和臭味”无关。"}, "sentence_index": 0, "correct_answer": "干燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把厨房打扫得很干燥，地板都亮了。", "explanation": "这里应该用〈干净〉。“干燥”指缺少水分，形容打扫后的整洁要用“干净”。"}, {"text": "他回答问题很干燥，三句话就把问题说清楚了。", "explanation": "这里应该用〈干脆〉。“干脆”形容说话直截了当，“干燥”不用来形容说话。"}, {"text": "这家店到了晚上就很干燥，几乎没有客人。", "explanation": "这里应该用〈冷清〉。“干燥”指缺少水分，形容地方没有人气、生意清淡要用“冷清”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“干燥”读作 gān zào，指缺少水分。"}, {"text": "赶早", "is_correct": false, "explanation": "赶早 gǎn zǎo 两个音节的声调都与“干燥”不同，意思是尽早。"}, {"text": "甘草", "is_correct": false, "explanation": "甘草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是一种中药。"}, {"text": "干烧", "is_correct": false, "explanation": "干烧 gān shāo 的第二个音节声母 sh 与 z 不同，声调也不同，是一种烹饪方法。"}], "explanations": {"干燥": "正确答案。“干燥”读作 gān zào，指缺少水分。", "赶早": "赶早 gǎn zǎo 两个音节的声调都与“干燥”不同，意思是尽早。", "甘草": "甘草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是一种中药。", "干烧": "干烧 gān shāo 的第二个音节声母 sh 与 z 不同，声调也不同，是一种烹饪方法。"}, "sentence_index": null, "correct_answer": "干燥"}, "level_3": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“太干燥了”形容房间缺少水分，与“喉咙很不舒服”相符。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不能用来形容房间。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人或事物的年龄，不能用来形容房间的状态。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，不能用来形容房间。"}], "explanations": {"干燥": "正确答案。“太干燥了”形容房间缺少水分，与“喉咙很不舒服”相符。", "苗条": "体貌：“苗条”形容人的身材，不能用来形容房间。", "年轻": "语义：“年轻”形容人或事物的年龄，不能用来形容房间的状态。", "嘹亮": "语义：“嘹亮”形容声音，不能用来形容房间。"}, "sentence_index": 6, "correct_answer": "干燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她做事很干燥，三两下就把任务完成了。", "explanation": "这里应该用〈干练〉。“干燥”指缺少水分，形容做事利落要用“干练”。"}, {"text": "这只鸟的叫声很干燥，听着很舒服。", "explanation": "这里应该用〈清脆〉。“干燥”不用来形容声音，形容声音悦耳要用“清脆”。"}, {"text": "他在这个行业的经验很干燥，很多人都向他请教。", "explanation": "这里应该用〈丰富〉。“干燥”指缺少水分，形容经验多要用“丰富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仓库的空气很干燥地，适合存放粮食。", "corrected_sentence": "这个仓库的空气很干燥，适合存放粮食。", "error_description": "“干燥”作谓语时后面不能加结构助词“地”，“地”用于修饰动词，应说“很干燥”，不能说“很干燥地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天天气干燥地很，嘴唇都裂了。", "corrected_sentence": "这几天天气干燥得很，嘴唇都裂了。", "error_description": "“干燥”后面接程度补语要用“得”，不能用“地”；“地”用于修饰动词。应说“干燥得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
