INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体或物质被使用、消耗或处理后所余下的部分。", "primary_collocate": null, "pronunciation": "cán yú wù", "ipa": "tsʰan³⁵ y³⁵ u⁵¹", "syllable_count": 3, "sentences": [{"text": "绿色材料富含氮元素，包括厨余果皮、咖啡渣、新鲜草屑等湿性有机物；棕色材料则提供碳源，如干树叶、碎纸板、木屑等干燥残余物。", "target_word": "残余物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "洗完锅以后，锅底还有一些残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用水冲掉了杯子里的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烧完木头后，炉子里留下了黑色的残余物。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天都要清理机器上的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把咖啡的残余物放进花盆里，花会长得更好。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器经过清洗，内部已经没有残余物。", "target_word": "残余物", "complexity_tier": "T3", "furigana": "zhè tái jīqì jīngguò qīngxǐ, nèibù yǐjīng méiyǒu cányúwù", "sentence_source": "generated"}, {"text": "实验结束后，瓶底留着白色的残余物。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过滤以后，纸上剩下的就是残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要把食物残余物倒进水池。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆残余物", "label": "量词"}, {"form": "一层残余物", "label": "量词"}, {"form": "殘餘物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "残余物|物质被使用或处理后余下的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残余物", "is_correct": true, "explanation": "残余物：物料使用或处理后剩下的部分，此处指堆肥中干燥的剩余物。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“干燥”不能修饰“水”，“干燥水”说不通。"}, {"text": "汤汁", "is_correct": false, "explanation": "语义：汤汁是液体，与“干燥”矛盾。"}, {"text": "石子", "is_correct": false, "explanation": "语义：石子不是有机物，不属于堆肥中的棕色碳源。"}], "explanations": {"残余物": "残余物：物料使用或处理后剩下的部分，此处指堆肥中干燥的剩余物。", "水": "搭配：“干燥”不能修饰“水”，“干燥水”说不通。", "汤汁": "语义：汤汁是液体，与“干燥”矛盾。", "石子": "语义：石子不是有机物，不属于堆肥中的棕色碳源。"}, "sentence_index": 0, "correct_answer": "残余物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "炉子里留下了一只残余物。", "explanation": "这里应该用〈堆〉或〈层〉。残余物是零散铺开的剩余物，不能用〈只〉，那是用于动物或单件物品的。"}, {"text": "考古队挖出了一具古人的残余物。", "explanation": "这里应该用〈遗骸〉。残余物指物质使用或处理后剩下的部分，不指人的遗体。"}, {"text": "他给儿子留下了一笔残余物。", "explanation": "这里应该用〈遗产〉。残余物是用剩的东西，不是可以留给子女的财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残余物", "is_correct": true, "explanation": "残余物：清洗后内部已经没有的剩余物质。"}, {"text": "手指", "is_correct": false, "explanation": "语义：机器内部不可能有手指，句子说不通。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“没有”后接的是物质，“故事”不能用来指机器内部的残留。"}, {"text": "灵魂", "is_correct": false, "explanation": "语义：机器内部说不上有没有灵魂，与清洗的语境不符。"}], "explanations": {"残余物": "残余物：清洗后内部已经没有的剩余物质。", "手指": "语义：机器内部不可能有手指，句子说不通。", "故事": "搭配：“没有”后接的是物质，“故事”不能用来指机器内部的残留。", "灵魂": "语义：机器内部说不上有没有灵魂，与清洗的语境不符。"}, "sentence_index": 6, "correct_answer": "残余物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些残余物是爷爷留下的纪念品。", "explanation": "这里应该用〈纪念品〉。残余物是用剩的东西，不能说是留作纪念的物品。"}, {"text": "他拿到了一笔残余物。", "explanation": "这里应该用〈奖学金〉。残余物是用剩的东西，不能用“拿到一笔”来说；拿到的一笔钱要说奖学金。"}, {"text": "他口袋里有一叠残余物。", "explanation": "这里应该用〈钞票〉。残余物是废弃的剩余物，不能指钞票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "锅底留下了一根残余物，要用水冲掉。", "corrected_sentence": "锅底留下了一层残余物，要用水冲掉。", "error_description": "量词错误：“残余物”是铺开的剩余物，应说“一层残余物”，不能说“一根残余物”（“根”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上留着一层白色地残余物。", "corrected_sentence": "桌子上留着一层白色的残余物。", "error_description": "结构助词错误：颜色词作定语修饰名词时用“的”，应说“白色的残余物”，不能用“地”（“地”用于修饰动词、形容词作状语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不同成分在整体中所占的比例或组合关系。", "primary_collocate": null, "pronunciation": "pèi bǐ", "ipa": "pʰei⁵¹ pi²¹⁴", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "配比", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "做蛋糕时，面粉和糖的配比很重要。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种水泥的配比是一份水泥三份沙子。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这杯咖啡的牛奶配比太高了。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以试试不同的配比，找出最好的口味。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肥料的配比不对，花长得不好。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的茶叶和水的配比很特别。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生告诉我这种药的配比不能改。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红色和蓝色的配比不同，颜色也不同。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人按照新的配比做出了更好的材料。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种配比", "label": "量词"}, {"form": "混合配比", "label": "复合"}], "register": "中性", "sense_fingerprint": "配比|不同成分所占的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配比", "is_correct": true, "explanation": "正确：“配比”指成分之间的比例关系，与“约为1:2（体积比）”相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热程度，不能用“1:2（体积比）”这样的比值来表示。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，与句中“体积比”的说法冲突。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“理想体重”不说“约为1:2（体积比）”，体重不是体积之比。"}], "explanations": {"配比": "正确：“配比”指成分之间的比例关系，与“约为1:2（体积比）”相符。", "温度": "语义：“温度”是冷热程度，不能用“1:2（体积比）”这样的比值来表示。", "面积": "语义：“面积”指平面的大小，与句中“体积比”的说法冲突。", "体重": "搭配：“理想体重”不说“约为1:2（体积比）”，体重不是体积之比。"}, "sentence_index": 0, "correct_answer": "配比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图的配比是一比一万。", "explanation": "这里应该用〈比例〉。配比指混合时各成分的搭配比例，地图的缩放比例不能说配比。"}, {"text": "我们班有一把新的配比。", "explanation": "这里应该用〈种〉。配比是抽象的搭配关系，不用“把”，“把”用于有柄的器具。"}, {"text": "这台电脑的配比很高。", "explanation": "这里应该用〈配置〉。配比指各成分的搭配比例，电脑的硬件规格要说配置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配比", "is_correct": true, "explanation": "正确：“配比”指茶叶和水的搭配比例，与“很特别”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只用于人或动物，茶叶和水没有年龄。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”用于人或直立之物，不与“茶叶和水”搭配。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：句中说的是两种材料的搭配关系，“寿命”指存在或使用的年限，意思不通。"}], "explanations": {"配比": "正确：“配比”指茶叶和水的搭配比例，与“很特别”相符。", "年龄": "语义：“年龄”只用于人或动物，茶叶和水没有年龄。", "身高": "搭配：“身高”用于人或直立之物，不与“茶叶和水”搭配。", "寿命": "语义：句中说的是两种材料的搭配关系，“寿命”指存在或使用的年限，意思不通。"}, "sentence_index": 6, "correct_answer": "配比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁的配比比铝大。", "explanation": "这里应该用〈比重〉。配比指各成分的搭配比例，比较物质的密度要说比重。"}, {"text": "我买了一只配比。", "explanation": "这里应该用〈种〉。配比是抽象的搭配关系，“只”用于成对之物中的一个或某些动物。"}, {"text": "两人配比得很默契。", "explanation": "这里应该用〈配合〉。配比指按量把东西放在一起，两人协作要说配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种饮料有一把新的配比。", "corrected_sentence": "这种饮料有一种新的配比。", "error_description": "量词错误：“配比”应配“种”，应说“一种新的配比”；“把”用于有柄的器具，不能修饰抽象的配比。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份汤的配比们很讲究。", "corrected_sentence": "这份汤的配比很讲究。", "error_description": "“配比”是抽象名词，不能加“们”表示复数，应说“这份汤的配比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
