INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体所占空间的大小。", "primary_collocate": null, "pronunciation": "tǐ jī", "ipa": "tʰi˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "气体受热后会膨胀，体积随之增大，压强也随之上升。", "target_word": "体积", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "同样质量的两种物质，密度不同，体积也就不同。", "target_word": "体积", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个箱子的体积很大，一个人搬不动。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变成冰以后，体积会变大。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱体积小，适合放在厨房里。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请算一算这个盒子的体积。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买行李箱以前，要先看它的体积。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头的体积虽然小，但是很重。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子体积一样，颜色不同。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球越吹，体积越大。", "target_word": "体积", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体积比", "label": "复合"}, {"form": "體積", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体所占空间的大小，可计量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：体积 tǐjī 指物体所占空间的大小。"}, {"text": "地基", "is_correct": false, "explanation": "dì（第四声）与 tǐ（第三声）声母与声调都不同，意思是地基。"}, {"text": "梯级", "is_correct": false, "explanation": "tī（第一声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是梯级。"}, {"text": "提及", "is_correct": false, "explanation": "tí（第二声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是提到。"}, {"text": "体系", "is_correct": false, "explanation": "xì（第四声）与 jī（第一声）声母不同（x 与 j），声调也不同，意思是体系。"}], "explanations": {"体积": "正确：体积 tǐjī 指物体所占空间的大小。", "地基": "dì（第四声）与 tǐ（第三声）声母与声调都不同，意思是地基。", "梯级": "tī（第一声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是梯级。", "提及": "tí（第二声）与 tǐ（第三声）声调不同，jí（第二声）与 jī（第一声）声调也不同，意思是提到。", "体系": "xì（第四声）与 jī（第一声）声母不同（x 与 j），声调也不同，意思是体系。"}, "sentence_index": null, "correct_answer": "体积"}, "level_3": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：“体积”指物体所占空间的大小，气体膨胀后占的空间变大，所以说体积随之增大。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会因为气体受热膨胀而增大。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄只会增长，不能说随气体受热而增大。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不会因为气体膨胀而变大。"}], "explanations": {"体积": "正确：“体积”指物体所占空间的大小，气体膨胀后占的空间变大，所以说体积随之增大。", "颜色": "语义：颜色不会因为气体受热膨胀而增大。", "年龄": "搭配：年龄只会增长，不能说随气体受热而增大。", "味道": "语义：味道不会因为气体膨胀而变大。"}, "sentence_index": 0, "correct_answer": "体积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的体积有十公斤。", "explanation": "这里应该用〈重量〉。体积说的是物体占的空间，用立方米、升等单位；有多少公斤是重量，不能说体积。"}, {"text": "这块地的体积有三百平方米。", "explanation": "这里应该用〈面积〉。平方米量的是平面的大小，地的大小要用面积；体积是立体空间，要用立方米。"}, {"text": "这件事的体积很大，我们没办法处理。", "explanation": "这里应该用〈规模〉。体积只说物体占的空间，不能用来形容事情的大小，事情的大小要说规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体积", "is_correct": true, "explanation": "正确：买行李箱前要看它的大小，应该用“体积”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”说冷热高低，买行李箱时不用看它的温度，与句意不合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：行李箱不会发出声音，买之前看不出它的声音大小。"}, {"text": "姓名", "is_correct": false, "explanation": "语义：行李箱没有姓名，买之前不会去看它的姓名。"}], "explanations": {"体积": "正确：买行李箱前要看它的大小，应该用“体积”。", "温度": "语义：“温度”说冷热高低，买行李箱时不用看它的温度，与句意不合。", "声音": "语义：行李箱不会发出声音，买之前看不出它的声音大小。", "姓名": "语义：行李箱没有姓名，买之前不会去看它的姓名。"}, "sentence_index": 6, "correct_answer": "体积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的体积很高，连树荫下都很热。", "explanation": "这里应该用〈温度〉。温度有高低，体积只说物体占的空间大小，不能用“高”来说它。"}, {"text": "这首歌的体积很大，邻居都听见了。", "explanation": "这里应该用〈音量〉。声音的强弱要说音量，体积是物体占的空间，不能用来形容声音。"}, {"text": "这辆车的体积很快，一眨眼就到了。", "explanation": "这里应该用〈速度〉。快慢说的是速度，体积只指空间大小，不能用来描述车跑得快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视体积的很大，放在客厅里正好。", "corrected_sentence": "这台电视体积很大，放在客厅里正好。", "error_description": "错误：“体积”后多加了“的”，“体积的很大”结构不通，应为“体积很大”，“体积”后直接接“很大”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子的体积的不大，适合放在小房间里。", "corrected_sentence": "这张桌子的体积不大，适合放在小房间里。", "error_description": "错误：“体积”后多加了“的”，“体积的不大”结构不通，应为“这张桌子的体积不大”，“体积”后直接接“不大”，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
