INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "碳氮比，简称C/N比，指有机物中碳元素与氮元素的质量比值，常用于衡量土壤或堆肥的养分平衡。", "primary_collocate": null, "pronunciation": "tàn dàn bǐ", "ipa": "tʰan⁵¹ tan⁵¹ pi²¹⁴", "syllable_count": 3, "sentences": [{"text": "理想的堆肥配比约为25:1，此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "碳氮比", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "构建该系统的技术逻辑并不复杂，但需建立在对碳氮比、通气性与微生物群落动态平衡的深刻理解之上。", "target_word": "碳氮比", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "堆肥时，碳氮比太高，分解就会变慢。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民先测一下土壤的碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "落叶的碳氮比高，鸡粪的碳氮比低。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，堆肥的碳氮比最好在25到30之间。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加入木屑可以提高碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碳氮比失衡时，堆肥会发臭。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们加了青草来降低碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验报告里写了每种材料的碳氮比。", "target_word": "碳氮比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "C/N比", "label": "简称"}], "register": "科技", "sense_fingerprint": "有机物中碳与氮的质量比值，用来衡量土壤或堆肥的养分平衡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碳氮比", "is_correct": true, "explanation": "正确：“此碳氮比”指碳和氮的比值，能促进嗜温菌群的演替，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能促进嗜温菌群的演替，也不能表示碳氮配比。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说高低、涨跌，不能与“促进……演替”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能促进微生物演替，也不能指碳氮的比值。"}], "explanations": {"碳氮比": "正确：“此碳氮比”指碳和氮的比值，能促进嗜温菌群的演替，符合句意。", "颜色": "语义：颜色不能促进嗜温菌群的演替，也不能表示碳氮配比。", "价格": "搭配：“价格”一般说高低、涨跌，不能与“促进……演替”搭配。", "味道": "语义：味道不能促进微生物演替，也不能指碳氮的比值。"}, "sentence_index": 0, "correct_answer": "碳氮比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋肥料的碳氮比有十公斤。", "explanation": "这里应该用〈重量〉。公斤是重量单位，碳氮比是比值，不能用公斤来算。"}, {"text": "堆肥的碳氮比升到六十度。", "explanation": "这里应该用〈温度〉。升到几度说的是温度，碳氮比是比值，不会“升到”几度。"}, {"text": "土壤的碳氮比偏酸。", "explanation": "这里应该用〈酸碱度〉。偏酸、偏碱说的是酸碱度，碳氮比是比值，不能用酸碱来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碳氮比", "is_correct": true, "explanation": "正确：加入木屑可以提高的是碳氮比，这是一个比值，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“提高”不能与“年龄”搭配，年龄只会增长。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：说长度变大要用“加长”，不说“提高长度”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：木屑不能让工资提高，这个句子说的是堆肥的配比。"}], "explanations": {"碳氮比": "正确：加入木屑可以提高的是碳氮比，这是一个比值，符合句意。", "年龄": "搭配：“提高”不能与“年龄”搭配，年龄只会增长。", "长度": "搭配：说长度变大要用“加长”，不说“提高长度”。", "工资": "语义：木屑不能让工资提高，这个句子说的是堆肥的配比。"}, "sentence_index": 6, "correct_answer": "碳氮比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的碳氮比很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳说的是颜色，碳氮比是比值，不能用来形容鲜艳。"}, {"text": "这辆车的碳氮比很快。", "explanation": "这里应该用〈速度〉。快慢说的是速度，碳氮比是比值，车跑得快不能用它来说。"}, {"text": "这个孩子的碳氮比有五岁。", "explanation": "这里应该用〈年龄〉。岁数说的是年龄，碳氮比是比值，不能用岁数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堆落叶碳氮比了很高，腐烂得很慢。", "corrected_sentence": "这堆落叶碳氮比很高，腐烂得很慢。", "error_description": "错误：“碳氮比了很高”，“了”放错了位置。正确：“碳氮比很高”，“碳氮比”后直接接“很高”，中间不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批肥料碳氮比的合适，可以直接用。", "corrected_sentence": "这批肥料碳氮比合适，可以直接用。", "error_description": "错误：“碳氮比的合适”，“的”放错了位置。正确：“这批肥料碳氮比合适”，“碳氮比”后直接接谓语“合适”，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
