INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11499, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "特别爱好，对某事物有浓厚的兴趣和强烈的欲望。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂʐ̩˥˩", "syllable_count": 1, "sentences": [{"text": "这位学者嗜古成癖，常年埋首故纸堆，对考据之学近乎痴迷。", "target_word": "嗜", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在消费主义盛行的当下，不少年轻人嗜网购成瘾，以购物纾解压力，却也因此陷入财务困境。", "target_word": "嗜", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "爷爷嗜茶，每天早上都要喝一杯。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嗜酒如命，家人都很担心。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小嗜甜，一天要吃好几块糖。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老作家嗜书，家里到处都是书。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四川人嗜辣，每顿饭都要放辣椒。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嗜烟成瘾，怎么劝也戒不掉。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人嗜茶，还专门写了很多茶书。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥嗜咖啡，一天要喝三杯。", "target_word": "嗜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗜好", "label": "复合"}, {"form": "嗜睡", "label": "复合"}], "register": "书面", "sense_fingerprint": "特别爱好某物并带到沉迷程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11499, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嗜", "is_correct": true, "explanation": "嗜（第四声）表示特别爱好，是正确答案。"}, {"text": "四", "is_correct": false, "explanation": "sì（第四声）与 shì 声母不同（s 与 sh），意思是数字四。"}, {"text": "食", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是吃、食物。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shì 声调不同，意思是诗。"}, {"text": "始", "is_correct": false, "explanation": "shǐ（第三声）与 shì 声调不同，意思是开始。"}], "explanations": {"嗜": "嗜（第四声）表示特别爱好，是正确答案。", "四": "sì（第四声）与 shì 声母不同（s 与 sh），意思是数字四。", "食": "shí（第二声）与 shì 声调不同，意思是吃、食物。", "诗": "shī（第一声）与 shì 声调不同，意思是诗。", "始": "shǐ（第三声）与 shì 声调不同，意思是开始。"}, "sentence_index": null, "correct_answer": "嗜"}, "level_3": {"options": [{"text": "嗜", "is_correct": true, "explanation": "正确。“嗜古成癖”表示特别爱好古代事物，与“常年埋首故纸堆”的描述相符。"}, {"text": "恶", "is_correct": false, "explanation": "语义：“恶”表示厌恶，“恶古成癖”不成搭配，且与“近乎痴迷”的语义相反。"}, {"text": "忌", "is_correct": false, "explanation": "搭配：“忌”表示回避，“忌古成癖”不成词；与“近乎痴迷”的语义矛盾。"}, {"text": "怕", "is_correct": false, "explanation": "搭配：“怕”后接的是害怕的对象，“怕古成癖”不成立，且与“近乎痴迷”矛盾。"}], "explanations": {"嗜": "正确。“嗜古成癖”表示特别爱好古代事物，与“常年埋首故纸堆”的描述相符。", "恶": "语义：“恶”表示厌恶，“恶古成癖”不成搭配，且与“近乎痴迷”的语义相反。", "忌": "搭配：“忌”表示回避，“忌古成癖”不成词；与“近乎痴迷”的语义矛盾。", "怕": "搭配：“怕”后接的是害怕的对象，“怕古成癖”不成立，且与“近乎痴迷”矛盾。"}, "sentence_index": 0, "correct_answer": "嗜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嗜了一封信，然后就出门了。", "explanation": "这里应该用〈写〉。“嗜”表示特别喜爱，不能表示“写信”这种具体动作。"}, {"text": "他嗜了一口水，然后就走了。", "explanation": "“嗜”只表示爱好，不能表示“喝一口”这类具体动作，这里应该用〈喝〉。"}, {"text": "这项工作他嗜了一年才完成。", "explanation": "这里应该用〈耗〉。“耗”表示花费时间，“嗜”没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11499, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嗜", "is_correct": true, "explanation": "嗜（第四声）表示特别爱好，是正确答案。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是数字十。"}, {"text": "狮", "is_correct": false, "explanation": "shī（第一声）与 shì 声调不同，意思是狮子。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shì 声调不同，意思是让、使得。"}, {"text": "寺", "is_correct": false, "explanation": "sì（第四声）与 shì 声母不同（s 与 sh），意思是寺庙。"}], "explanations": {"嗜": "嗜（第四声）表示特别爱好，是正确答案。", "十": "shí（第二声）与 shì 声调不同，意思是数字十。", "狮": "shī（第一声）与 shì 声调不同，意思是狮子。", "使": "shǐ（第三声）与 shì 声调不同，意思是让、使得。", "寺": "sì（第四声）与 shì 声母不同（s 与 sh），意思是寺庙。"}, "sentence_index": null, "correct_answer": "嗜"}, "level_3": {"options": [{"text": "嗜", "is_correct": true, "explanation": "“四川人嗜辣”表示四川人特别爱吃辣，与“每顿饭都要放辣椒”一致。"}, {"text": "拒", "is_correct": false, "explanation": "搭配：“拒”后接的是请求、建议等，不说“拒辣”；且与“每顿饭都要放辣椒”矛盾。"}, {"text": "弃", "is_correct": false, "explanation": "搭配：“弃”多接“弃权”“弃医”等，不说“弃辣”，且与“每顿饭都要放辣椒”矛盾。"}, {"text": "畏", "is_correct": false, "explanation": "语域：“畏”是文言色彩很重的词，与口语化的描述不符，且与“每顿饭都要放辣椒”矛盾。"}], "explanations": {"嗜": "“四川人嗜辣”表示四川人特别爱吃辣，与“每顿饭都要放辣椒”一致。", "拒": "搭配：“拒”后接的是请求、建议等，不说“拒辣”；且与“每顿饭都要放辣椒”矛盾。", "弃": "搭配：“弃”多接“弃权”“弃医”等，不说“弃辣”，且与“每顿饭都要放辣椒”矛盾。", "畏": "语域：“畏”是文言色彩很重的词，与口语化的描述不符，且与“每顿饭都要放辣椒”矛盾。"}, "sentence_index": 6, "correct_answer": "嗜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哥哥很嗜妹妹，每天都陪她玩。", "explanation": "这里应该用〈喜欢〉。“嗜”的对象应是事物或活动，不能指人，表示对人的喜爱不能用“嗜”。"}, {"text": "哥哥嗜了一块蛋糕，然后就去上班了。", "explanation": "这里应该用〈吃〉。“嗜”表示特别喜爱，不能表示“吃掉”这种具体动作。"}, {"text": "哥哥嗜了我一本书，我很高兴。", "explanation": "这里应该用〈送〉。“嗜”没有给人东西的意思，不能带“我”和“一本书”两个宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子读嗜科幻小说，一放学就去图书馆。", "corrected_sentence": "这个孩子嗜读科幻小说，一放学就去图书馆。", "error_description": "错误：“读嗜”；正确：“嗜读”。“嗜”是动词，修饰“读”时要放在“读”之前，不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他嗜不烟，从来不抽。", "corrected_sentence": "他不嗜烟，从来不抽。", "error_description": "错误：“嗜不烟”；正确：“不嗜烟”。否定词“不”应放在“嗜”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能在高温环境中生长繁殖的微生物群体。", "primary_collocate": null, "pronunciation": "shì rè jūn qún", "ipa": "ʂɻ̩˥˩ ɻɤ˥˩ tɕyn˥ tɕʰyn˧˥", "syllable_count": 4, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "嗜热菌群", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "堆肥升温后，嗜热菌群开始大量繁殖。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温泉里的高温环境适合嗜热菌群生长。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌群在六十度的水里也能活着。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆体温度升高后，嗜温菌减少，嗜热菌群多起来。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家从温泉水中找到了嗜热菌群。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌群能把堆肥里的有机物分解掉。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种嗜热菌群只在高温下才能繁殖。", "target_word": "嗜热菌群", "complexity_tier": "T3", "furigana": "shì rè jūn qún", "sentence_source": "generated"}, {"text": "研究人员正在培养一种新的嗜热菌群。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗜热菌群让堆肥的温度保持在六十度左右。", "target_word": "嗜热菌群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗜热菌", "label": "复合"}, {"form": "一种嗜热菌群", "label": "量词"}], "register": "科技", "sense_fingerprint": "能在高温环境中生长繁殖的微生物群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗜热菌群", "is_correct": true, "explanation": "正确：指演替的终点，即能在高温中繁殖的微生物群体，与句中“升至55–65°C”相符。"}, {"text": "嗜温菌群", "is_correct": false, "explanation": "语义：句中“嗜温菌群”已是演替的起点，再作终点则前后相同，无法使堆体升温。"}, {"text": "嗜冷菌群", "is_correct": false, "explanation": "语义：嗜冷菌群适应低温，与“升至55–65°C”的高温目标矛盾。"}, {"text": "杂草群落", "is_correct": false, "explanation": "语义：句中演替的是微生物群体，杂草群落是植物群落，与堆体升温的过程不符。"}], "explanations": {"嗜热菌群": "正确：指演替的终点，即能在高温中繁殖的微生物群体，与句中“升至55–65°C”相符。", "嗜温菌群": "语义：句中“嗜温菌群”已是演替的起点，再作终点则前后相同，无法使堆体升温。", "嗜冷菌群": "语义：嗜冷菌群适应低温，与“升至55–65°C”的高温目标矛盾。", "杂草群落": "语义：句中演替的是微生物群体，杂草群落是植物群落，与堆体升温的过程不符。"}, "sentence_index": 0, "correct_answer": "嗜热菌群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在显微镜下看到一个嗜热菌群正在分裂。", "explanation": "这里说的是单个细胞分裂，应该用〈细胞〉。嗜热菌群指许多微生物的集合，群体不会整体分裂，分裂的是单个细胞。"}, {"text": "这种嗜热菌群只有一个细胞那么大。", "explanation": "这里应该用〈细菌〉。嗜热菌群是许多菌的集合，不能说只有一个细胞那么大。"}, {"text": "培养皿上的嗜热菌群只有几毫米大，一个嗜热菌群由一个细胞分裂而来。", "explanation": "这里应该用〈菌落〉。菌群是多种微生物的集合，由单个细胞分裂形成的是菌落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗜热菌群", "is_correct": true, "explanation": "正确：指能分解堆肥有机物的微生物群体，与句意相符。"}, {"text": "塑料袋", "is_correct": false, "explanation": "语义：塑料袋不是生物，无法分解堆肥中的有机物，句意不通。"}, {"text": "杂草种子", "is_correct": false, "explanation": "语义：杂草种子是植物的繁殖体，不能分解有机物，句意不通。"}, {"text": "温泉", "is_correct": false, "explanation": "搭配：温泉是水体环境，不是能分解有机物的主体，作主语与句中的动作不搭。"}], "explanations": {"嗜热菌群": "正确：指能分解堆肥有机物的微生物群体，与句意相符。", "塑料袋": "语义：塑料袋不是生物，无法分解堆肥中的有机物，句意不通。", "杂草种子": "语义：杂草种子是植物的繁殖体，不能分解有机物，句意不通。", "温泉": "搭配：温泉是水体环境，不是能分解有机物的主体，作主语与句中的动作不搭。"}, "sentence_index": 6, "correct_answer": "嗜热菌群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究人员在培养箱里放了一台嗜热菌群。", "explanation": "这里应该用〈种〉。〈台〉用于机器，不用于微生物群体。"}, {"text": "堆肥表面长着一棵嗜热菌群。", "explanation": "这里应该用〈种〉。〈棵〉用于植物，不能用来计量微生物群体。"}, {"text": "温泉里漂着一条嗜热菌群。", "explanation": "这里应该用〈种〉。〈条〉用于细长的东西，不能用来计量嗜热菌群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里培养着一只嗜热菌群。", "corrected_sentence": "实验室里培养着一种嗜热菌群。", "error_description": "量词错误：“只”用于动物，嗜热菌群应使用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池塘边的土里藏着一条嗜热菌群。", "corrected_sentence": "池塘边的土里藏着一种嗜热菌群。", "error_description": "量词错误：“条”用于细长的东西，嗜热菌群应使用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
