INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指生物群落中一个群落被另一个群落取代的过程。", "primary_collocate": null, "pronunciation": "yǎn tì", "ipa": "jɛn˨˩˦ tʰi˥˩", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "演替", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "火灾之后，这片森林慢慢开始了演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地经过多年演替，变成了小树林。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群落演替需要几十年甚至上百年。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水变浅后，湖边的植物发生了演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员记录了这片荒地的演替过程。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演替让裸露的岩石上慢慢长出了植物。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥升温时，微生物群落也在发生演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弃耕的农田里，杂草的演替很快。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变化会影响森林的演替方向。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群落演替", "label": "复合"}, {"form": "次生演替", "label": "复合"}], "register": "科技", "sense_fingerprint": "生物群落中一个群落被另一个群落取代的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演替", "is_correct": true, "explanation": "正确：指一个群落被另一个群落取代的过程，与句中“嗜温菌群向嗜热菌群的”相符。"}, {"text": "降温", "is_correct": false, "explanation": "语义：句中要求堆体升至55–65°C，“降温”方向相反，不能描述嗜温到嗜热的转变。"}, {"text": "灭活", "is_correct": false, "explanation": "搭配：“灭活”的对象是病原体，不能用于菌群之间的更替。"}, {"text": "火灾", "is_correct": false, "explanation": "语义：火灾是突发的灾害，不是菌群逐步更替的过程，句意不通。"}], "explanations": {"演替": "正确：指一个群落被另一个群落取代的过程，与句中“嗜温菌群向嗜热菌群的”相符。", "降温": "语义：句中要求堆体升至55–65°C，“降温”方向相反，不能描述嗜温到嗜热的转变。", "灭活": "搭配：“灭活”的对象是病原体，不能用于菌群之间的更替。", "火灾": "语义：火灾是突发的灾害，不是菌群逐步更替的过程，句意不通。"}, "sentence_index": 0, "correct_answer": "演替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的旧零件已经全部演替成新的了。", "explanation": "这里应该用〈替换〉。演替专指生物群落的更替，机器零件的更换应用〈替换〉。"}, {"text": "汉字的字形经过了长期演替。", "explanation": "这里应该用〈演变〉。演替指生物群落被另一个群落取代，文字字形的变化应用〈演变〉。"}, {"text": "这款手机的型号每年都在演替。", "explanation": "这里应该用〈换代〉。演替指生物群落的取代，产品型号的更新换代应用〈换代〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演替", "is_correct": true, "explanation": "正确：指群落的逐步更替，岩石上慢慢长出植物正是演替的结果。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪是剪去植物，与“慢慢长出了植物”的结果相反。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐使植物减少，与“长出了植物”不符。"}, {"text": "翻耕", "is_correct": false, "explanation": "搭配：翻耕针对耕地的土壤，不能对裸露的岩石进行。"}], "explanations": {"演替": "正确：指群落的逐步更替，岩石上慢慢长出植物正是演替的结果。", "修剪": "语义：修剪是剪去植物，与“慢慢长出了植物”的结果相反。", "砍伐": "语义：砍伐使植物减少，与“长出了植物”不符。", "翻耕": "搭配：翻耕针对耕地的土壤，不能对裸露的岩石进行。"}, "sentence_index": 6, "correct_answer": "演替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "值班人员每周演替一次。", "explanation": "这里应该用〈轮换〉。演替只用于生物群落的更替，人员的轮班应用〈轮换〉。"}, {"text": "这个软件的版本已经演替了，换成了新版本。", "explanation": "这里应该用〈更新〉。演替指生物群落的取代，软件版本的升级应用〈更新〉。"}, {"text": "这台旧洗衣机今天演替了，换成了新的。", "explanation": "这里应该用〈换新〉。演替指生物群落的取代，家电的更换应用〈换新〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草地在几十年里慢慢被演替了。", "corrected_sentence": "这片草地在几十年里慢慢演替了。", "error_description": "句式错误：“演替”是不及物动词，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年这块地发生过演替。", "corrected_sentence": "明年这块地发生演替。", "error_description": "时态错误：“过”表示已经发生的经历，与将来的“明年”矛盾，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
