INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指堆积起来的物体，通常是由许多相同或不同的东西聚集形成的立体形状。", "primary_collocate": null, "pronunciation": "duī tǐ", "ipa": "twei˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "堆体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "堆体里的温度很高，用手摸能感觉到热。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用翻堆机把堆体翻了一遍。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆体太干时，要往里面加一些水。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保温，农民在堆体上盖了一层草。", "target_word": "堆体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个堆体长五米，高两米。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "堆体中心的温度比外层高很多。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "堆体内部缺少空气，会发出臭味。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个堆体需要两个月才能完全腐熟。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们每天记录堆体的温度。", "target_word": "堆体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "堆体温度", "label": "复合"}], "register": "书面", "sense_fingerprint": "堆积而成的立体物体，多指堆肥等的整个堆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆体", "is_correct": true, "explanation": "正确：指堆积的物料整体，能被加热到55–65°C，是句中“使……升至”的主语。"}, {"text": "菌群", "is_correct": false, "explanation": "语义：“菌群”指微生物的集合，不能作“升至55–65°C”的被加热对象，句中要加热的是堆里的物料。"}, {"text": "病原体", "is_correct": false, "explanation": "语义：病原体是句中要被“灭活”的对象，不能作升温的主语。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：“湿度”以百分比计，不说升至摄氏度。"}], "explanations": {"堆体": "正确：指堆积的物料整体，能被加热到55–65°C，是句中“使……升至”的主语。", "菌群": "语义：“菌群”指微生物的集合，不能作“升至55–65°C”的被加热对象，句中要加热的是堆里的物料。", "病原体": "语义：病原体是句中要被“灭活”的对象，不能作升温的主语。", "湿度": "搭配：“湿度”以百分比计，不说升至摄氏度。"}, "sentence_index": 0, "correct_answer": "堆体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家后院有一只堆体，是用落叶堆成的。", "explanation": "这里应该用〈个〉。“只”用于动物，或成对东西中的一个，不用于堆体。"}, {"text": "他那结实的堆体让人羡慕。", "explanation": "这里应该用〈身体〉。“堆体”指堆积起来的物料，形容人的躯体要用“身体”。"}, {"text": "这个堆体有三十个成员。", "explanation": "这里应该用〈团体〉。“堆体”指堆起来的物料，不指由人组成的团体，说“有三十个成员”要用“团体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆体", "is_correct": true, "explanation": "正确：指堆积的物料，句中的“中心”“外层”指它的内外部位。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩是抽象的评价，没有“中心”与“外层”的温度可言，句意不通。"}, {"text": "配比", "is_correct": false, "explanation": "语义：“配比”是比例，不是有温度的实体，不能说中心的温度。"}, {"text": "雨量", "is_correct": false, "explanation": "搭配：“雨量”以毫米计降水，不用来说中心的温度。"}], "explanations": {"堆体": "正确：指堆积的物料，句中的“中心”“外层”指它的内外部位。", "成绩": "语义：成绩是抽象的评价，没有“中心”与“外层”的温度可言，句意不通。", "配比": "语义：“配比”是比例，不是有温度的实体，不能说中心的温度。", "雨量": "搭配：“雨量”以毫米计降水，不用来说中心的温度。"}, "sentence_index": 6, "correct_answer": "堆体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块堆体在比赛中拿了金牌。", "explanation": "这里应该用〈运动员〉。“堆体”指堆起来的物料，不能参加比赛，拿金牌的应是运动员。"}, {"text": "这个箱子的堆体会唱歌。", "explanation": "语义：“堆体”指堆起来的物料，没有唱歌的能力，句意不通。"}, {"text": "这次旅行让我获得了难忘的堆体。", "explanation": "这里应该用〈体验〉。“堆体”指堆起来的物料，不指亲身经历的感受，说旅行中的感受要用“体验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在院角堆起一片堆体，用来发酵落叶。", "corrected_sentence": "工人在院角堆起一个堆体，用来发酵落叶。", "error_description": "量词错误：“堆体”应用“个”。“片”用于平面、薄的东西，不能说“一片堆体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民被堆体翻了一遍，让它更均匀。", "corrected_sentence": "农民把堆体翻了一遍，让它更均匀。", "error_description": "句式错误：“堆体”是“翻”的对象，应用“把”字句引出，应说“农民把堆体翻了一遍”。改用“被”会把堆体说成动作的施事，句意颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降至", "is_correct": true, "explanation": "正确：与“升至”相反，指数值由高向低降到某一数。"}, {"text": "达到", "is_correct": false, "explanation": "语义：“达到”表示到了某一程度，与“升至”同向，不是反义词。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”表示不变，与“升至”没有反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示数量上升，与“升至”同向，不是反义词。"}], "correct_answer": "降至", "explanations": {"降至": "正确：与“升至”相反，指数值由高向低降到某一数。", "达到": "语义：“达到”表示到了某一程度，与“升至”同向，不是反义词。", "保持": "语义：“保持”表示不变，与“升至”没有反义关系。", "增加": "语义：“增加”表示数量上升，与“升至”同向，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降至", "is_correct": true, "explanation": "正确：与“升至”相反，指数值由高向低降到某一数。"}, {"text": "维持", "is_correct": false, "explanation": "语义：“维持”指保持原状，不表示数值变化，与“升至”不是反义词。"}, {"text": "停留", "is_correct": false, "explanation": "语义：“停留”指暂时不动，与“升至”没有反义关系。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指不再进行，与“升至”没有反义关系。"}], "correct_answer": "降至", "explanations": {"降至": "正确：与“升至”相反，指数值由高向低降到某一数。", "维持": "语义：“维持”指保持原状，不表示数值变化，与“升至”不是反义词。", "停留": "语义：“停留”指暂时不动，与“升至”没有反义关系。", "停止": "语义：“停止”指不再进行，与“升至”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从较低的位置、等级或数量上升到较高的位置、等级或数量。", "primary_collocate": null, "pronunciation": "shēng zhì", "ipa": "ʂɤŋ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "升至", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中午气温升至三十五度，大家都不想出门。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水温升至一百度时，水就开始沸腾。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加热后，炉内温度在十分钟内升至五百度。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的销量从一万件升至三万件。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的职位从经理升至总经理。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人的体温升至三十九度，医生很担心。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水一夜之间升至警戒线，村民已经转移了。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价升至每平方米五万元，年轻人买不起。", "target_word": "升至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室内温度升至二十五度后，空调自动停了。", "target_word": "升至", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升至了", "label": "体标"}], "register": "书面", "sense_fingerprint": "数量、温度、等级等上升到某一水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：“升至”意为上升到某个数值或等级。"}, {"text": "升职", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，“升职”意思是提升职务。"}, {"text": "生吃", "is_correct": false, "explanation": "zh 与 ch 声母不同，“生吃”意思是不煮就吃。"}, {"text": "生事", "is_correct": false, "explanation": "zh 与 sh 声母不同，“生事”意思是找麻烦。"}, {"text": "神志", "is_correct": false, "explanation": "shēng 与 shén 韵尾不同（ng 与 n），“神志”意思是意识、心智。"}], "explanations": {"升至": "正确：“升至”意为上升到某个数值或等级。", "升职": "zhì（第四声）与 zhí（第二声）声调不同，“升职”意思是提升职务。", "生吃": "zh 与 ch 声母不同，“生吃”意思是不煮就吃。", "生事": "zh 与 sh 声母不同，“生事”意思是找麻烦。", "神志": "shēng 与 shén 韵尾不同（ng 与 n），“神志”意思是意识、心智。"}, "sentence_index": null, "correct_answer": "升至"}, "level_3": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：表示温度从低到高上升到所说的数值。"}, {"text": "降至", "is_correct": false, "explanation": "语义：“降至”指下降，与句中为了灭菌而升温的意思相反。"}, {"text": "升值", "is_correct": false, "explanation": "搭配：“升值”用于价值，温度不说升值。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指变冷，与句中要加热到高温的目的相反。"}], "explanations": {"升至": "正确：表示温度从低到高上升到所说的数值。", "降至": "语义：“降至”指下降，与句中为了灭菌而升温的意思相反。", "升值": "搭配：“升值”用于价值，温度不说升值。", "冷却": "语义：“冷却”指变冷，与句中要加热到高温的目的相反。"}, "sentence_index": 0, "correct_answer": "升至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的存款从一千元升至五百元。", "explanation": "这里应该用〈降至〉。“升至”表示数值上升，存款减少要用“降至”。"}, {"text": "他的排名从门口升至厨房。", "explanation": "语义：“升至”后接数值或等级，不接地点，“排名”也不能从门口移到厨房，句意不通。"}, {"text": "会议升至下午。", "explanation": "这里应该用〈推迟到〉。“升至”表示数量或等级的上升，不用于时间的推后，会议改到下午要说“推迟到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：“升至”意为上升到某个数值或等级。"}, {"text": "圣旨", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，zhì 与 zhǐ 声调也不同，“圣旨”意思是皇帝的命令。"}, {"text": "升势", "is_correct": false, "explanation": "zh 与 sh 声母不同，“升势”意思是上升的趋势。"}, {"text": "生纸", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“生纸”意思是未加工的纸。"}, {"text": "省志", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，“省志”意思是一省的地方志。"}], "explanations": {"升至": "正确：“升至”意为上升到某个数值或等级。", "圣旨": "shēng（第一声）与 shèng（第四声）声调不同，zhì 与 zhǐ 声调也不同，“圣旨”意思是皇帝的命令。", "升势": "zh 与 sh 声母不同，“升势”意思是上升的趋势。", "生纸": "zhì（第四声）与 zhǐ（第三声）声调不同，“生纸”意思是未加工的纸。", "省志": "shēng（第一声）与 shěng（第三声）声调不同，“省志”意思是一省的地方志。"}, "sentence_index": null, "correct_answer": "升至"}, "level_3": {"options": [{"text": "升至", "is_correct": true, "explanation": "正确：表示体温从低到高上升到三十九度。"}, {"text": "降温", "is_correct": false, "explanation": "配价：“降温”是动宾结构，后面不接“至”引出的数值作补语。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：“倒退”指向后退，体温不会倒退三十九度。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体变成液体，体温不会熔化。"}], "explanations": {"升至": "正确：表示体温从低到高上升到三十九度。", "降温": "配价：“降温”是动宾结构，后面不接“至”引出的数值作补语。", "倒退": "语义：“倒退”指向后退，体温不会倒退三十九度。", "熔化": "语义：“熔化”指固体变成液体，体温不会熔化。"}, "sentence_index": 6, "correct_answer": "升至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "室内温度升至了十分钟。", "explanation": "这里应该用〈持续〉。“升至”后面接数值，表示时间长短要用“持续”。"}, {"text": "飞机终于升至北京。", "explanation": "这里应该用〈抵达〉。“升至”的对象是数值或等级，不能是地名。"}, {"text": "飞机从高空升至地面。", "explanation": "这里应该用〈降落〉。“升至”表示向上，从高空到地面是向下，要说“降至”或“降落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油温升至一百八十个时，就可以下锅了。", "corrected_sentence": "油温升至一百八十度时，就可以下锅了。", "error_description": "量词错误：“升至”后面的温度应用“度”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油价升至每升八个后，大家都少开车了。", "corrected_sentence": "油价升至每升八元后，大家都少开车了。", "error_description": "量词错误：“每升”的价格应用“元”，不用“个”，应说“每升八元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
