INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使微生物或病毒失去活性，不再具有感染或致病能力。", "primary_collocate": null, "pronunciation": "miè huó", "ipa": "mjɛ˥˩ xwo˧˥", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体。", "target_word": "灭活", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "高温能灭活堆体里的病菌。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂先把病毒灭活，再制成疫苗。", "target_word": "灭活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线可以灭活空气中的病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加热到六十度，就能灭活这种细菌。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院用特殊的设备灭活污水里的病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家成功灭活了这种新病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灭活后的病毒不会让人生病。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种消毒水能在五分钟内灭活病毒。", "target_word": "灭活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室需要先灭活样本里的病原体，才能安全检测。", "target_word": "灭活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭活了", "label": "体标"}, {"form": "灭活过", "label": "体标"}, {"form": "灭活疫苗", "label": "复合"}], "register": "书面", "sense_fingerprint": "使病毒、病菌失去活性和致病能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖是数量增多，与“有效”去除病原体的语境相反。"}, {"text": "灭活", "is_correct": true, "explanation": "正确。灭活指使病原体失去活性，与“有效”和“病原体”搭配。"}, {"text": "传播", "is_correct": false, "explanation": "语义：传播是扩散，与“有效”、堆体升温杀灭病原的语境相反。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：吸收多用于营养、能量，不能与病原体、杂草种子搭配。"}], "explanations": {"繁殖": "语义：繁殖是数量增多，与“有效”去除病原体的语境相反。", "灭活": "正确。灭活指使病原体失去活性，与“有效”和“病原体”搭配。", "传播": "语义：传播是扩散，与“有效”、堆体升温杀灭病原的语境相反。", "吸收": "搭配：吸收多用于营养、能量，不能与病原体、杂草种子搭配。"}, "sentence_index": 0, "correct_answer": "灭活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紫外线可以灭活空气中的异味。", "explanation": "这里应该用〈消除〉。灭活只用于使微生物或病毒失去活性，异味不是微生物，应用消除。"}, {"text": "警察用电棍灭活了那个歹徒。", "explanation": "这里应该用〈制服〉。灭活不用于人，制服歹徒应用制服。"}, {"text": "消防员用了两个小时才把这场大火灭活。", "explanation": "这里应该用〈灭火〉。灭活只用于微生物或病毒，扑灭大火应用灭火。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸收", "is_correct": false, "explanation": "搭配：吸收多用于营养、知识，不能用于病毒。"}, {"text": "灭活", "is_correct": true, "explanation": "正确。灭活指使病毒失去活性，与“成功”和“新病毒”搭配。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎是对人或客人的礼貌接待，与病毒的语境不相容。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：消化用于食物，不能用于病毒。"}], "explanations": {"吸收": "搭配：吸收多用于营养、知识，不能用于病毒。", "灭活": "正确。灭活指使病毒失去活性，与“成功”和“新病毒”搭配。", "欢迎": "语义：欢迎是对人或客人的礼貌接待，与病毒的语境不相容。", "消化": "搭配：消化用于食物，不能用于病毒。"}, "sentence_index": 6, "correct_answer": "灭活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室需要先灭活样本里的杂质，才能安全检测。", "explanation": "这里应该用〈清理〉。灭活只用于微生物或病毒，去除杂质应用清理。"}, {"text": "地震灭活了整个小镇。", "explanation": "这里应该用〈毁灭〉。灭活只用于微生物或病毒，地震摧毁小镇应用毁灭。"}, {"text": "风把蜡烛灭活了。", "explanation": "这里应该用〈吹灭〉。灭活不用于火焰，风吹熄蜡烛应用吹灭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "紫外线可以空气中的病毒灭活。", "corrected_sentence": "紫外线可以把空气中的病毒灭活。", "error_description": "错误：“灭活”的宾语“空气中的病毒”前缺少“把”，直接放在动词前不通。正确：“可以把空气中的病毒灭活”，用“把”字句引出宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员成功了灭活这批新病毒。", "corrected_sentence": "研究人员成功灭活这批新病毒。", "error_description": "错误：「了」插在动词「灭活」之前，写成「成功了灭活」，不通。正确：「成功灭活这批新病毒」，「灭活」前不加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
