INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能引起人或动物生病的微小生物。", "primary_collocate": null, "pronunciation": "bìng yuán tǐ", "ipa": "piŋ⁵¹ ɥɛn³⁵ tʰi²¹⁴", "syllable_count": 3, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "病原体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "病原体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "病原体会让人和动物生病。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在血液里找到了病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温可以杀死很多病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手能减少病原体传播。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病原体通过空气传播。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里要小心处理病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥升温后，病原体会死掉。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究新的病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病原體", "label": "繁体"}], "register": "科技", "sense_fingerprint": "能引起人或动物生病的微小生物，如细菌、病毒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体是能使人或动物生病的微生物，可以被灭活。"}, {"text": "养分", "is_correct": false, "explanation": "语义：养分是营养物质，不是微生物，不能被灭活。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不是生物，不会被灭活。"}, {"text": "铁锅", "is_correct": false, "explanation": "语义：铁锅不是生物，不能被灭活。"}], "explanations": {"病原体": "正确。病原体是能使人或动物生病的微生物，可以被灭活。", "养分": "语义：养分是营养物质，不是微生物，不能被灭活。", "氧气": "语义：氧气是气体，不是生物，不会被灭活。", "铁锅": "语义：铁锅不是生物，不能被灭活。"}, "sentence_index": 0, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑感染了病原体。", "explanation": "这里应该用〈病毒〉。病原体指能使人或动物生病的微生物，不能指电脑中的程序。"}, {"text": "我在显微镜下看见了一条病原体。", "explanation": "这里应该用量词〈种〉或〈个〉。“条”用于细长的东西，病原体不说“一条”。"}, {"text": "这种病原体可以用来做酸奶。", "explanation": "这里应该用〈细菌〉。病原体专指致病的微生物，做酸奶的细菌是有益的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体是致病的微生物，可以通过空气传播。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固态物体，不会通过空气传播。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“传播”多用于疾病、消息、知识，不说水果通过空气传播。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是实体，不会通过空气传播。"}], "explanations": {"病原体": "正确。病原体是致病的微生物，可以通过空气传播。", "冰块": "语义：冰块是固态物体，不会通过空气传播。", "水果": "搭配：“传播”多用于疾病、消息、知识，不说水果通过空气传播。", "颜色": "语义：颜色不是实体，不会通过空气传播。"}, "sentence_index": 6, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面团发酵要靠病原体。", "explanation": "这里应该用〈酵母〉。面团发酵靠的是酵母等微生物，病原体指致病的东西，不能用于发酵。"}, {"text": "妈妈在伤口上涂了病原体来消炎。", "explanation": "这里应该用〈抗生素〉。消炎要靠抗生素等药物，病原体会引起感染，不能用来消炎。"}, {"text": "妈妈用病原体给菜地浇水。", "explanation": "这里应该用〈水〉。浇水要用水，病原体是致病的微生物，不能用来浇地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只病原体会通过飞沫传播。", "corrected_sentence": "这种病原体会通过飞沫传播。", "error_description": "量词错误：病原体前应用量词“种”，不说“这只病原体”。“只”多用于动物或成对、个体的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多病原体们会传播疾病。", "corrected_sentence": "很多病原体会传播疾病。", "error_description": "“们”一般只附在指人的词后，病原体不能加“们”表示复数，应直接说“很多病原体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
