INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指生长在农田、花园等地方，妨碍作物或花卉生长的野生草本植物。", "primary_collocate": null, "pronunciation": "zá cǎo", "ipa": "tsa³⁵ tsʰɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "理想配比约为1:2（体积比），此碳氮比可促进嗜温菌群向嗜热菌群的演替，使堆体在数日内升至55–65°C，有效灭活病原体与杂草种子。", "target_word": "杂草", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "杂草", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "花园里长满了杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地里拔杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂草会抢走庄稼的水和养分。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨多，杂草长得很快。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜地要常常除杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥前先把杂草堆在一起。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂草种子能在土里活好几年。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在院子里清理杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雜草", "label": "繁体"}, {"form": "一片杂草", "label": "量词"}], "register": "中性", "sense_fingerprint": "农田、花园里妨碍作物或花卉生长的野生草本植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杂草", "is_correct": true, "explanation": "正确。杂草种子指杂草的种子，是需要被灭活的对象。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是植物，没有种子。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是植物，没有种子。"}, {"text": "宝石", "is_correct": false, "explanation": "搭配：“种子”前多为植物名，不说宝石种子。"}], "explanations": {"杂草": "正确。杂草种子指杂草的种子，是需要被灭活的对象。", "手机": "语义：手机不是植物，没有种子。", "玩具": "语义：玩具不是植物，没有种子。", "宝石": "搭配：“种子”前多为植物名，不说宝石种子。"}, "sentence_index": 0, "correct_answer": "杂草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里种杂草。", "explanation": "这里应该用〈庄稼〉。杂草是妨碍作物生长的野草，不会有人特意种植。"}, {"text": "他在地里看见了一头杂草。", "explanation": "这里应该用量词〈片〉或〈株〉。“头”用于牲畜，杂草可说“一片杂草”或“一株杂草”。"}, {"text": "我们在院子里种了很多杂草。", "explanation": "这里应该用〈花〉。杂草不是人有意种植的植物，不能说种杂草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂草", "is_correct": true, "explanation": "正确。除杂草指清除地里妨碍作物生长的野草。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单不是植物，不能用“除”去掉。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不长在菜地里，也不需要被清除，句意不通。"}, {"text": "小孩", "is_correct": false, "explanation": "配价：“除”的宾语多为杂草、害虫等物，不能是人。"}], "explanations": {"杂草": "正确。除杂草指清除地里妨碍作物生长的野草。", "账单": "语义：账单不是植物，不能用“除”去掉。", "钢琴": "语义：钢琴不长在菜地里，也不需要被清除，句意不通。", "小孩": "配价：“除”的宾语多为杂草、害虫等物，不能是人。"}, "sentence_index": 6, "correct_answer": "杂草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花店里卖各种杂草。", "explanation": "这里应该用〈鲜花〉。杂草是妨碍作物生长的野草，不能当作花卉出售。"}, {"text": "他买了一份杂草送给朋友。", "explanation": "这里应该用〈礼物〉。杂草通常没有观赏价值，不能当作礼物送人。"}, {"text": "妈妈去超市买了一袋杂草，用来给手机充电。", "explanation": "这里应该用〈电池〉。给手机充电要用电池或充电器，杂草不能用来充电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田边长着一颗杂草。", "corrected_sentence": "田边长着一丛杂草。", "error_description": "量词错误：杂草成丛生长，应用量词“丛”。“颗”用于粒状的小东西，不能用于杂草。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶在院子里清理一只杂草。", "corrected_sentence": "奶奶在院子里清理一片杂草。", "error_description": "量词错误：“只”多用于动物或成对、个体的事物，杂草成片生长，不能说“一只杂草”，应用量词“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "反义：忽视与注意相对，表示不予重视，与“注意到病人脸色”的语义相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动脑子想问题，与注意没有反义关系。"}, {"text": "发现", "is_correct": false, "explanation": "发现与注意是近义关系，不是反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，与注意没有语义上的对立关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "反义：忽视与注意相对，表示不予重视，与“注意到病人脸色”的语义相反。", "思考": "思考是动脑子想问题，与注意没有反义关系。", "发现": "发现与注意是近义关系，不是反义关系。", "游泳": "游泳是一种运动，与注意没有语义上的对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "反义：忽视与注意相对，表示不予理会，与“注意到我在看手机”的语义相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是一种活动，与注意没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是一种动作，与注意没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，与注意没有反义关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "反义：忽视与注意相对，表示不予理会，与“注意到我在看手机”的语义相反。", "唱歌": "唱歌是一种活动，与注意没有反义关系。", "写字": "写字是一种动作，与注意没有反义关系。", "跑步": "跑步是一种运动，与注意没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把精力集中观察，认识事物的特点或变化。", "primary_collocate": null, "pronunciation": "zhù yì", "ipa": "ʈʂu˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "你注意到他今天的变化了吗？", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我注意过天上的云是怎么慢慢变化的。", "target_word": "注意", "complexity_tier": "T3", "furigana": "wǒ zhù yì guò tiān shàng de yún shì zěn me màn màn biàn huà de.", "sentence_source": "generated"}, {"text": "小李注意着路边的花，慢慢地走。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生注意到病人的脸色不好。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有注意到门口站着一个人。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师注意到小明最近很安静。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她注意观察天气的变化。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有注意过猫是怎么走路的？", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这才注意到，窗外下雪了。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈注意到我一直在看手机。", "target_word": "注意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注意了", "label": "体标"}, {"form": "注意过", "label": "体标"}, {"form": "注意着", "label": "体标"}], "register": "中性", "sense_fingerprint": "留心观察而发现事物的特点或变化（注意到）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "注意", "is_correct": true, "explanation": "正确答案，与听到的读音一致，意思是留心观察。"}, {"text": "主义", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是“主义”。"}, {"text": "竹椅", "is_correct": false, "explanation": "两个音节的声调都不同，意思是“竹子做的椅子”。"}, {"text": "逐一", "is_correct": false, "explanation": "两个音节的声调都不同，意思是“一个接一个”。"}, {"text": "句意", "is_correct": false, "explanation": "j 与 zh 声母不同，意思是“句子的意思”。"}], "explanations": {"注意": "正确答案，与听到的读音一致，意思是留心观察。", "主义": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是“主义”。", "竹椅": "两个音节的声调都不同，意思是“竹子做的椅子”。", "逐一": "两个音节的声调都不同，意思是“一个接一个”。", "句意": "j 与 zh 声母不同，意思是“句子的意思”。"}, "sentence_index": null, "correct_answer": "注意"}, "level_3": {"options": [{"text": "注意", "is_correct": true, "explanation": "“注意到”表示留心察觉，符合“变化”这一察觉对象的语境。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：忘记直接带宾语，后面不能接补语“到”，且与询问是否察觉变化的语境相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略表示不予理会，与问句询问是否察觉变化的语义相反。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：赞美的对象是人或作品，不能用于“变化”这类现象，也不能接“到”。"}], "explanations": {"注意": "“注意到”表示留心察觉，符合“变化”这一察觉对象的语境。", "忘记": "配价：忘记直接带宾语，后面不能接补语“到”，且与询问是否察觉变化的语境相反。", "忽略": "语义：忽略表示不予理会，与问句询问是否察觉变化的语义相反。", "赞美": "搭配：赞美的对象是人或作品，不能用于“变化”这类现象，也不能接“到”。"}, "sentence_index": 0, "correct_answer": "注意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我注意明天去北京，所以已经订了票。", "explanation": "这里应该用〈打算〉。注意指留心观察、察觉变化，不表示计划，表示打算要用“打算”。"}, {"text": "我们在电影院注意了一场电影。", "explanation": "这里应该用〈看〉或〈观看〉。注意侧重留心特点或变化，整场电影的观赏应说“看”或“观看”。"}, {"text": "老师注意了我的请假，让我下午就回家。", "explanation": "这里应该用〈批准〉。注意只表示留心，不表示同意请求，准假应说“批准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注意", "is_correct": true, "explanation": "“注意观察”表示留心地观察，与后面的动词搭配。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视表示不予重视，与后面的“观察”语义矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃表示不再坚持下去，与“注意观察”的留心之意相反，句意不合。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：讨论的对象是问题或话题，不能直接接动词“观察”作宾语。"}], "explanations": {"注意": "“注意观察”表示留心地观察，与后面的动词搭配。", "忽视": "语义：忽视表示不予重视，与后面的“观察”语义矛盾。", "放弃": "语义：放弃表示不再坚持下去，与“注意观察”的留心之意相反，句意不合。", "讨论": "搭配：讨论的对象是问题或话题，不能直接接动词“观察”作宾语。"}, "sentence_index": 6, "correct_answer": "注意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈注意了我一眼，就走开了。", "explanation": "这里应该用〈看〉。注意侧重心里留心，不指视线接触的动作，看一眼应说“看”。"}, {"text": "妈妈这个月注意了三千元房租，手头很紧。", "explanation": "这里应该用〈交〉。注意表示留心，不表示付款，交房租应说“交”。"}, {"text": "妈妈把注意放进了我的书包里。", "explanation": "注意是抽象的留心，不能像物品一样放进书包，这里误把它当成了实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才没注意见窗外的雨。", "corrected_sentence": "我刚才没注意到窗外的雨。", "error_description": "错误：结果补语“见”不能接在“注意”后。正确：应说“注意到”，“到”作结果补语，写作“没注意到窗外的雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈注意了到我的变化。", "corrected_sentence": "妈妈注意到了我的变化。", "error_description": "错误：“了”插在了“注意”和“到”之间。正确：“了”应放在“注意到”之后，写作“注意到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "植物", "is_correct": false, "explanation": "植物与动物性没有反义关系，只是不同类的生物。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与动物性没有语义上的对立关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空是自然景物，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "植物": "植物与动物性没有反义关系，只是不同类的生物。", "桌子": "桌子是家具，与动物性没有语义上的对立关系。", "天空": "天空是自然景物，与动物性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "房屋", "is_correct": false, "explanation": "房屋是建筑物，与动物性没有反义关系。"}, {"text": "大海", "is_correct": false, "explanation": "大海是自然景物，与动物性没有语义上的对立关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包是日常用品，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "房屋": "房屋是建筑物，与动物性没有反义关系。", "大海": "大海是自然景物，与动物性没有语义上的对立关系。", "书包": "书包是日常用品，与动物性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人身上保留的、与动物相似的原始本能和生理需求。", "primary_collocate": null, "pronunciation": "dòng wù xìng", "ipa": "tʊŋ˥˩ u˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他一闻到饭菜的香味，身体里的动物性就压不住了，连平时最讲规矩的人也抢着先吃。", "target_word": "动物性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "人既有动物性，也有理性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饿了要吃饭，这是人的动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气的时候，动物性就出来了。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人不能只靠动物性生活。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉和喝水都是人的动物性需要。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他控制不住自己的动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人要管好自己的动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在危险面前，人的动物性会让他想跑。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物性是人身上最早的本能。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動物性", "label": "繁体"}, {"form": "动物性蛋白", "label": "复合"}], "register": "书面", "sense_fingerprint": "人身上保留的与动物相似的原始本能和生理需求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指人身上与动物相似的本能，与“一闻到香味就压不住”的语境相合。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不存在于身体里，与“压不住”的语境不合。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不能在身体里被压住，句意不合。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是身体里需要压住的东西，句意不合。"}], "explanations": {"动物性": "动物性指人身上与动物相似的本能，与“一闻到香味就压不住”的语境相合。", "词典": "语义：词典是工具书，不存在于身体里，与“压不住”的语境不合。", "花园": "语义：花园是一个地方，不能在身体里被压住，句意不合。", "音乐": "语义：音乐不是身体里需要压住的东西，句意不合。"}, "sentence_index": 0, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把动物性放在书架上。", "explanation": "这里应该用〈本能〉或〈欲望〉。动物性是抽象的本能，不能像物品一样放在书架上，这里误把它当成了实物。"}, {"text": "他的动物性这次考了第一名。", "explanation": "这里应该用〈成绩〉。动物性指人身上的本能，不指考试名次，谈名次应说“成绩”。"}, {"text": "他的动物性很温和。", "explanation": "这里应该用〈性格〉。动物性指本能，不能用来形容人的温和性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指本能冲动，符合“控制不住”的语境。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不是可以被控制住的冲动，与句子语义不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是需要控制的冲动，与句子语义不合。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“控制”不能支配“形状”这类外貌特征。"}], "explanations": {"动物性": "动物性指本能冲动，符合“控制不住”的语境。", "数学": "语义：数学不是可以被控制住的冲动，与句子语义不合。", "窗户": "语义：窗户不是需要控制的冲动，与句子语义不合。", "形状": "搭配：“控制”不能支配“形状”这类外貌特征。"}, "sentence_index": 6, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的动物性很沉稳。", "explanation": "这里应该用〈气质〉。动物性指身体本能，不能用来形容沉稳的气质。"}, {"text": "这个人的动物性很高尚。", "explanation": "这里应该用〈品德〉。动物性不指道德品质，不能说“高尚”。"}, {"text": "这篇文章的动物性很独特。", "explanation": "这里应该用〈风格〉。动物性指本能，不指文章的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是人动物性。", "corrected_sentence": "这是人的动物性。", "error_description": "错误：修饰名词“动物性”时省略了“的”。正确：应说“人的动物性”，名词修饰语后要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人都有一只动物性。", "corrected_sentence": "人都有一种动物性。", "error_description": "量词错误：“只”用于动物或成对的物件，抽象的“动物性”应用“种”。正确：“人都有一种动物性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
