INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物经过变化或处理后剩下的部分。", "primary_collocate": null, "pronunciation": "cán yú", "ipa": "tsʰan˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "火烧完以后，只剩下一点残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子里的残余倒掉了。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完衣服，水里还有一些残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燃料烧完后，罐子底部还有一些残余。", "target_word": "残余", "complexity_tier": "T3", "furigana": "rán liào shāo wán hòu, guàn zi dǐ bù hái yǒu yì xiē cán yú.", "sentence_source": "generated"}, {"text": "桌上有一些做饭后的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在清理房子里的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧习惯的残余，他还没有完全改掉。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾以后，房子里只有一些残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着炉子里的残余，不说话。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拆除后，旧房子的残余还堆在河边。", "target_word": "残余", "complexity_tier": "T3", "furigana": "chāi chú hòu, jiù fáng zi de cán yú hái duī zài hé biān.", "sentence_source": "generated"}], "morphological_forms": [{"form": "殘餘", "label": "繁体"}, {"form": "残余物", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物经过变化或处理后剩下的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11512, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "残余", "is_correct": true, "explanation": "正确答案。残余（cán yú）指经过变化或处理后剩下的部分。"}, {"text": "蚕育", "is_correct": false, "explanation": "蚕育（cányù）第二个音节声调不同（yù 第四声），意思是养育、培育，与残余无关。"}, {"text": "参与", "is_correct": false, "explanation": "参与（cānyǔ）两个音节的声调都不同，意思是参加，与残余（cán yú）声调不同。"}, {"text": "藏于", "is_correct": false, "explanation": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}], "explanations": {"残余": "正确答案。残余（cán yú）指经过变化或处理后剩下的部分。", "蚕育": "蚕育（cányù）第二个音节声调不同（yù 第四声），意思是养育、培育，与残余无关。", "参与": "参与（cānyǔ）两个音节的声调都不同，意思是参加，与残余（cán yú）声调不同。", "藏于": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}, "sentence_index": null, "correct_answer": "残余"}, "level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指火烧后剩下的部分，与“火烧完以后，只剩下一点”相合。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：“一点”不能计量“人群”，火烧之后也不会剩下人群。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：火烧完以后不会只剩下歌声，“歌声”与火烧的语境不合。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金不会因火烧而剩下，句中语境不合。"}], "explanations": {"残余": "残余指火烧后剩下的部分，与“火烧完以后，只剩下一点”相合。", "人群": "搭配：“一点”不能计量“人群”，火烧之后也不会剩下人群。", "歌声": "语义：火烧完以后不会只剩下歌声，“歌声”与火烧的语境不合。", "奖金": "语义：奖金不会因火烧而剩下，句中语境不合。"}, "sentence_index": 0, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "账户里的残余还有三百元。", "explanation": "这里应该用〈余额〉。残余指事物经过处理后剩下的部分，银行账户里的结余要用余额。"}, {"text": "这个月工资还有残余，我就存起来了。", "explanation": "这里应该用〈剩余〉。残余指经过处理后剩下的部分，工资用完后的余下部分要用剩余。"}, {"text": "秋收以后，农户家里的粮食残余着不少。", "explanation": "这里应该用〈剩〉。残余是名词，不能作动词表示“剩下”，应说“剩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指旧习惯剩下的一部分，与“还没有完全改掉”相合。"}, {"text": "花园", "is_correct": false, "explanation": "语义：旧习惯不是花园，句中说的是没有改掉的习惯，“花园”与语境不合。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“存款”不能用来修饰“习惯”，“旧习惯的存款”不成词组。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：习惯不是瓶子，“还没有完全改掉”也不能说瓶子改掉。"}], "explanations": {"残余": "残余指旧习惯剩下的一部分，与“还没有完全改掉”相合。", "花园": "语义：旧习惯不是花园，句中说的是没有改掉的习惯，“花园”与语境不合。", "存款": "搭配：“存款”不能用来修饰“习惯”，“旧习惯的存款”不成词组。", "瓶子": "语义：习惯不是瓶子，“还没有完全改掉”也不能说瓶子改掉。"}, "sentence_index": 6, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一只残余就是拆下来的旧木板。", "explanation": "量词错误：残余是剩下的东西，不能用动物量词“只”计量，这里应该用“块”或“点”。"}, {"text": "歌声停了，耳边还留着它的残余。", "explanation": "这里应该用〈余音〉。残余指事物经过处理后剩下的部分，声音停止后留在耳边的回响要用余音。"}, {"text": "用二十除以三，商是六，残余是二。", "explanation": "这里应该用〈余数〉。残余指事物经过处理后剩下的部分，除法中除不尽、剩下的数要用余数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只残余都是烧焦的木头。", "corrected_sentence": "这些残余都是烧焦的木头。", "error_description": "量词错误：“只”用于动物或单个物件，不能计量“残余”这种零散的碎片，应改用“这些”。正确：“这些残余”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房间里只剩下一些残余们，别再扫了。", "corrected_sentence": "房间里只剩下一些残余，别再扫了。", "error_description": "后缀错误：“们”只用于指人的名词，残余是物质，不能加“们”，正确的说法是“一些残余”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
