INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11513, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动植物体内所含的油性物质，常温下呈液态或固态，不溶于水，能燃烧。", "primary_collocate": null, "pronunciation": "yóu zhī", "ipa": "joʊ˧˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "动物体内有很多油脂。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物种子里的油脂可以榨成油。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种坚果含有丰富的油脂。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油脂不溶于水，所以水洗不掉。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体会把多余的能量变成油脂储存起来。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肥肉里的油脂特别多。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油脂可以燃烧，也能提供热量。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤表面有一层油脂保护着。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大豆里的油脂含量很高。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吃太多油脂对心脏不好。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层油脂", "label": "量词"}, {"form": "一些油脂", "label": "量词"}], "register": "中性", "sense_fingerprint": "动植物体内的油性物质，不溶于水，可燃烧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11513, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正确答案。油脂（yóu zhī）指动植物体内的油性物质。"}, {"text": "优质", "is_correct": false, "explanation": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。"}, {"text": "油纸", "is_correct": false, "explanation": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。"}, {"text": "有志", "is_correct": false, "explanation": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}], "explanations": {"油脂": "正确答案。油脂（yóu zhī）指动植物体内的油性物质。", "优质": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。", "油纸": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。", "有志": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}, "sentence_index": null, "correct_answer": "油脂"}, "level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂指动植物体内的油性物质，与“动物体内有很多”相合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：动物体内不会有星星，句中语境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：动物体内不会有歌曲，“很多歌曲”与句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色属于外表形貌，不存在于动物体内，“动物体内有很多颜色”说不通。"}], "explanations": {"油脂": "油脂指动植物体内的油性物质，与“动物体内有很多”相合。", "星星": "语义：动物体内不会有星星，句中语境不合。", "歌曲": "语义：动物体内不会有歌曲，“很多歌曲”与句意不合。", "颜色": "体貌：颜色属于外表形貌，不存在于动物体内，“动物体内有很多颜色”说不通。"}, "sentence_index": 0, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车快没油了，我去加满油脂。", "explanation": "这里应该用〈汽油〉。油脂指动植物体内的油性物质，给汽车加油要用汽油。"}, {"text": "我买了一桶油脂，准备刷墙。", "explanation": "这里应该用〈油漆〉。油脂指动植物体内的油性物质，刷墙要用油漆。"}, {"text": "煤油灯里的油脂快用完了。", "explanation": "这里应该用〈煤油〉。煤油灯要烧煤油，句中的油脂是动植物体内的油性物质，与煤油灯的燃料不是一回事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂可以燃烧，也能提供热量，与句中描述相合。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块不能燃烧，也不能提供热量，句中语境不合。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能燃烧，也不能提供热量，与句意不合。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“可以燃烧”要求燃料类的主语，“歌声”不能与之搭配。"}], "explanations": {"油脂": "油脂可以燃烧，也能提供热量，与句中描述相合。", "冰块": "语义：冰块不能燃烧，也不能提供热量，句中语境不合。", "玻璃": "语义：玻璃不能燃烧，也不能提供热量，与句意不合。", "歌声": "搭配：“可以燃烧”要求燃料类的主语，“歌声”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一只油脂，还没用。", "explanation": "量词错误：“只”多用于动物，油脂是物质，应该用“点”或“层”计量。"}, {"text": "我每天都用油脂来写作业。", "explanation": "这里应该用〈铅笔〉。油脂是油性物质，不能用来写字，写作业要用铅笔或钢笔。"}, {"text": "用油脂可以洗掉衣服上的油渍。", "explanation": "这里应该用〈洗衣粉〉。油脂本身是油性物质，会留下油渍，不能用来洗衣服；洗掉衣服上的油渍要用洗衣粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种坚果有很多个油脂。", "corrected_sentence": "这种坚果有很多油脂。", "error_description": "量词错误：“个”不能计量“油脂”这类物质名词，应直接说“很多油脂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鸟的羽毛上有一只油脂，能防水。", "corrected_sentence": "鸟的羽毛上有一层油脂，能防水。", "error_description": "量词错误：油脂是物质，不能用动物量词“只”计量，正确的说法是“一层油脂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
