INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从某个范围或情形中去除。", "primary_collocate": null, "pronunciation": "pái chú", "ipa": "pʰaɪ˧˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "警察已经排除了他的嫌疑。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生排除了这是癌症的可能。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先排除错误的答案吧。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把不对的答案排除。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家排除了地震的危险。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成功，就要排除干扰。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查后，他们排除了机器出故障的原因。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查结果排除了他杀的可能。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想办法排除了所有困难。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先排除不可能的方案，再选最好的。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除了", "label": "体标"}, {"form": "排除过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把可能性、嫌疑、干扰等从范围中去除", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11514, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除（pái chú）是本词，意思是从某个范围或情形中去掉。"}, {"text": "开除", "is_correct": false, "explanation": "开除（kāi chú）与排除（pái chú）声母不同，意思是解雇或除名，不是去掉可能性。"}, {"text": "派出", "is_correct": false, "explanation": "派出（pài chū）与排除（pái chú）声调不同，意思是派遣。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出（pāi chū）与排除（pái chú）声调不同，意思是拍卖得到，如拍出高价。"}], "explanations": {"排除": "排除（pái chú）是本词，意思是从某个范围或情形中去掉。", "开除": "开除（kāi chú）与排除（pái chú）声母不同，意思是解雇或除名，不是去掉可能性。", "派出": "派出（pài chū）与排除（pái chú）声调不同，意思是派遣。", "拍出": "拍出（pāi chū）与排除（pái chú）声调不同，意思是拍卖得到，如拍出高价。"}, "sentence_index": null, "correct_answer": "排除"}, "level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除：嫌疑被去掉，符合句意。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”的对象是消息、情况，不能说“打听嫌疑”。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”用于纪录、沉默、僵局，不能用于嫌疑。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是嫌疑，这句话语义不通。"}], "explanations": {"排除": "排除：嫌疑被去掉，符合句意。", "打听": "搭配：“打听”的对象是消息、情况，不能说“打听嫌疑”。", "打破": "搭配：“打破”用于纪录、沉默、僵局，不能用于嫌疑。", "吃": "语义：“吃”的对象不能是嫌疑，这句话语义不通。"}, "sentence_index": 0, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他排除了我的好意。", "explanation": "这里应该用〈感谢〉。排除表示去掉可能性或干扰，对别人的好意要说感谢，不说排除。"}, {"text": "我排除了他的道歉。", "explanation": "这里应该用〈接受〉。排除针对可能性、嫌疑、干扰等，对别人的道歉要说接受或原谅。"}, {"text": "他排除了那只小猫的呼吸。", "explanation": "排除针对可能性、嫌疑、干扰等，呼吸是生理活动，不能被排除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除：机器故障的原因被逐一去掉，符合句意。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”用于盒子、门等，不能用于原因。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象不能是原因，这句话语义不通。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”指把包裹、零件分开，不能用于原因。"}], "explanations": {"排除": "排除：机器故障的原因被逐一去掉，符合句意。", "打开": "搭配：“打开”用于盒子、门等，不能用于原因。", "喝": "语义：“喝”的对象不能是原因，这句话语义不通。", "拆开": "搭配：“拆开”指把包裹、零件分开，不能用于原因。"}, "sentence_index": 6, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他排除了一个微笑。", "explanation": "排除针对可能性、嫌疑、干扰等，微笑不是可以被排除的对象。"}, {"text": "老师排除了那首诗的韵律。", "explanation": "韵律是作品的性质，不是可以被排除的范围或干扰，此处“排除”不成立。"}, {"text": "孩子排除了那只小鸟的翅膀。", "explanation": "排除针对可能性、嫌疑、干扰等抽象范围，不能用来去掉小鸟的翅膀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把所有不合格的产品排除外。", "corrected_sentence": "我们把所有不合格的产品排除在外。", "error_description": "“排除”后面要接“在外”，说“排除在外”；“排除外”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生不排除了这种可能。", "corrected_sentence": "医生不排除这种可能。", "error_description": "体标错误：“不排除这种可能”是固定说法，句中多加的“了”不合习惯，应去掉。正确：“医生不排除这种可能。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "避免", "is_correct": true, "explanation": "避免与引致意思相反：一个是造成结果，一个是避开结果。"}, {"text": "分享", "is_correct": false, "explanation": "分享与引致没有反义关系，二者意思无关。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行与引致没有反义关系，二者意思无关。"}, {"text": "修改", "is_correct": false, "explanation": "修改与引致没有反义关系，二者意思无关。"}], "correct_answer": "避免", "explanations": {"避免": "避免与引致意思相反：一个是造成结果，一个是避开结果。", "分享": "分享与引致没有反义关系，二者意思无关。", "旅行": "旅行与引致没有反义关系，二者意思无关。", "修改": "修改与引致没有反义关系，二者意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
