INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引起，导致（某种结果）。", "primary_collocate": null, "pronunciation": "yǐn zhì", "ipa": "in˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "须特别注意，动物性残余如肉类、油脂及乳制品应严格排除，因其易引致厌氧发酵，滋生异味与害虫。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "睡眠不足可能引致头痛。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小错误引致了严重的后果。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨引致河水上涨。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟过多会引致多种疾病。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话引致大家的不满。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油太热了，容易引致火灾。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理不好会引致公司亏损。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "误会往往是沟通不够引致的。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变化引致了不少人感冒。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引致了", "label": "体标"}, {"form": "引致过", "label": "体标"}], "register": "书面", "sense_fingerprint": "某原因引起、导致不良结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致（yǐn zhì）是本词，表示引起某种结果。"}, {"text": "印制", "is_correct": false, "explanation": "印制（yìn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是印刷、制作。"}, {"text": "银制", "is_correct": false, "explanation": "银制（yín zhì）与引致（yǐn zhì）第一个音节声调不同，意思是用银制成。"}, {"text": "音质", "is_correct": false, "explanation": "音质（yīn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是声音的质量。"}], "explanations": {"引致": "引致（yǐn zhì）是本词，表示引起某种结果。", "印制": "印制（yìn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是印刷、制作。", "银制": "银制（yín zhì）与引致（yǐn zhì）第一个音节声调不同，意思是用银制成。", "音质": "音质（yīn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是声音的质量。"}, "sentence_index": null, "correct_answer": "引致"}, "level_3": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致：表示引起不良结果，与“易……厌氧发酵”的句意相符。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”用于果实、经验，不能说收获厌氧发酵。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象不能是发酵，这句话语义不通。"}, {"text": "放映", "is_correct": false, "explanation": "语义：“放映”用于电影、幻灯片，不能用于发酵，这句话语义不通。"}], "explanations": {"引致": "引致：表示引起不良结果，与“易……厌氧发酵”的句意相符。", "收获": "搭配：“收获”用于果实、经验，不能说收获厌氧发酵。", "欣赏": "语义：“欣赏”的对象不能是发酵，这句话语义不通。", "放映": "语义：“放映”用于电影、幻灯片，不能用于发酵，这句话语义不通。"}, "sentence_index": 0, "correct_answer": "引致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆引致了一批新书。", "explanation": "这里应该用〈引进〉。引致表示引起某种结果，不用于把新书引进馆内。"}, {"text": "这部电影引致了很多观众。", "explanation": "这里应该用〈吸引〉。引致的对象是结果，不用来描述把人引来。"}, {"text": "他引致了一句名言。", "explanation": "这里应该用〈引用〉。引致表示引起结果，不用于引述别人的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致：表示导致不良结果，火灾是油太热的后果，符合句意。"}, {"text": "扑灭", "is_correct": false, "explanation": "语义：油太热不会让火灾“容易被扑灭”，这句话与句意相反。"}, {"text": "发动", "is_correct": false, "explanation": "搭配：“发动”用于战争、攻势，不能说发动火灾。"}, {"text": "防止", "is_correct": false, "explanation": "语义：“防止”与“油太热”的因果关系相反，这句话不通。"}], "explanations": {"引致": "引致：表示导致不良结果，火灾是油太热的后果，符合句意。", "扑灭": "语义：油太热不会让火灾“容易被扑灭”，这句话与句意相反。", "发动": "搭配：“发动”用于战争、攻势，不能说发动火灾。", "防止": "语义：“防止”与“油太热”的因果关系相反，这句话不通。"}, "sentence_index": 6, "correct_answer": "引致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快引致了客厅。", "explanation": "这里应该用〈打扫〉。引致表示引起某种结果，不用于清理场所。"}, {"text": "老师引致了作业。", "explanation": "这里应该用〈批改〉。引致表示引起某种结果，不用于给作业打分。"}, {"text": "工人引致了电梯。", "explanation": "这里应该用〈修理〉。引致表示引起某种结果，不用于修复设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场暴雨引致了。", "corrected_sentence": "这场暴雨引致了山体滑坡。", "error_description": "宾语缺失：“引致”是及物动词，后面必须带出现的结果，“这场暴雨引致了”不完整；应补为“这场暴雨引致了山体滑坡。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药没容易引致副作用。", "corrected_sentence": "这种药不容易引致副作用。", "error_description": "“容易”前应用否定词“不”，说“不容易引致”；“没”只用于否定已发生或已拥有的事，“没容易”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
