INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指不正常、令人不愉快的气味。", "primary_collocate": null, "pronunciation": "yì wèi", "ipa": "i˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "须特别注意，动物性残余如肉类、油脂及乳制品应严格排除，因其易引致厌氧发酵，滋生异味与害虫。", "target_word": "异味", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冰箱里有一股异味。", "target_word": "异味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间很久没开窗，有异味。", "target_word": "异味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鞋柜里的异味让人不舒服。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾桶放久了会产生异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用活性炭吸走了冰箱的异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水有异味，最好不要喝。", "target_word": "异味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打开窗户，可以去掉房间里的异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服放在柜子里，沾上了异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车里的异味很重，我想开窗。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "異味", "label": "繁体"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "不正常、令人不愉快的气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异味", "is_correct": true, "explanation": "正确。句意是厌氧发酵会滋生异味与害虫。"}, {"text": "光明", "is_correct": false, "explanation": "语义：“滋生”的对象是异味、害虫、细菌之类有害的东西，“光明”不能被滋生。"}, {"text": "财富", "is_correct": false, "explanation": "语义：“财富”不是有害之物，不能与“害虫”并列作为滋生的结果。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“滋生”多用于细菌、害虫、问题等，不能说“滋生信心”。"}], "explanations": {"异味": "正确。句意是厌氧发酵会滋生异味与害虫。", "光明": "语义：“滋生”的对象是异味、害虫、细菌之类有害的东西，“光明”不能被滋生。", "财富": "语义：“财富”不是有害之物，不能与“害虫”并列作为滋生的结果。", "信心": "搭配：“滋生”多用于细菌、害虫、问题等，不能说“滋生信心”。"}, "sentence_index": 0, "correct_answer": "异味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的异味很好。", "explanation": "这里应该用〈味道〉。“异味”指难闻的气味，不能用“很好”形容；好闻的气味应说“味道”或“香味”。"}, {"text": "车里飘来一朵异味，我想开窗。", "explanation": "这里应该用〈股〉。“异味”是一种气味，量词应用“股”；“朵”用于花等。"}, {"text": "这盘菜的异味很诱人。", "explanation": "这里应该用〈香味〉。“诱人”形容好的气味，“异味”指难闻的气味，二者感情色彩相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异味", "is_correct": true, "explanation": "正确。句意是水有难闻的气味，最好不要喝。"}, {"text": "诗意", "is_correct": false, "explanation": "语义：“诗意”不是水的性质，句中要说明的是让人不宜饮用的属性。"}, {"text": "重量", "is_correct": false, "explanation": "语义：水的重量与能否饮用无关，句中要说明的是气味或异常的性质。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“有”后接“脾气”多用于人，水没有脾气，搭配不当。"}], "explanations": {"异味": "正确。句意是水有难闻的气味，最好不要喝。", "诗意": "语义：“诗意”不是水的性质，句中要说明的是让人不宜饮用的属性。", "重量": "语义：水的重量与能否饮用无关，句中要说明的是气味或异常的性质。", "脾气": "搭配：“有”后接“脾气”多用于人，水没有脾气，搭配不当。"}, "sentence_index": 6, "correct_answer": "异味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里响起一阵异味。", "explanation": "这里应该用〈钟声〉。“响起”的对象是声音，异味是气味，应说“飘出”。"}, {"text": "这块布的异味很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，异味是难闻的气味，二者不搭配。"}, {"text": "这杯水的异味很高。", "explanation": "这里应该用〈温度〉。“高”可以形容温度，但不能形容难闻的气味，应说“异味很重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的垃圾桶里有一个异味，该倒了。", "corrected_sentence": "厨房的垃圾桶里有一股异味，该倒了。", "error_description": "量词错误：“异味”是气味，量词应用“股”，不能用通用量词“个”。正确说法是“一股异味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车里飘出一股很异味，我想开窗。", "corrected_sentence": "车里飘出一股异味，我想开窗。", "error_description": "语序错误：程度副词“很”应修饰形容词或心理动词，不能插在名词“异味”前。正确说法是“飘出一股异味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
