INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "害虫指对人类的生活、生产或健康造成危害的昆虫或其他动物。", "primary_collocate": null, "pronunciation": "hài chóng", "ipa": "xaɪ˥˩ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "须特别注意，动物性残余如肉类、油脂及乳制品应严格排除，因其易引致厌氧发酵，滋生异味与害虫。", "target_word": "害虫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "苍蝇是传播疾病的害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民用药水消灭田里的害虫。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种害虫专吃玉米叶子。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚊子也是一种害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "果园里的害虫越来越多。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鸟儿吃掉了树上的害虫，保护了果树。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里没有打扫，容易生出害虫。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓢虫能帮农民吃掉害虫。", "target_word": "害虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "粮食放在潮湿的地方，容易招来害虫。", "target_word": "害虫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害蟲", "label": "繁体"}, {"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "危害人类生活、生产或健康的昆虫或其他动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "正确。“滋生”指害虫、细菌等生物繁殖出现，“异味”与之搭配，应填“害虫”。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会因发酵而滋生异味，句中的“厌氧发酵”和“动物性残余”都与它无关。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是有害之物，“滋生”的对象应是异味、害虫这类有害事物，不能说“滋生蛋糕”。"}, {"text": "铁锅", "is_correct": false, "explanation": "搭配：“滋生”只用于生物繁殖出现的情况，不能说器物滋生异味。"}], "explanations": {"害虫": "正确。“滋生”指害虫、细菌等生物繁殖出现，“异味”与之搭配，应填“害虫”。", "花朵": "语义：花朵不会因发酵而滋生异味，句中的“厌氧发酵”和“动物性残余”都与它无关。", "蛋糕": "语义：蛋糕不是有害之物，“滋生”的对象应是异味、害虫这类有害事物，不能说“滋生蛋糕”。", "铁锅": "搭配：“滋生”只用于生物繁殖出现的情况，不能说器物滋生异味。"}, "sentence_index": 0, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂是害虫，能帮果农给花授粉。", "explanation": "这里应该用〈益虫〉。害虫指危害生产或健康的虫子；蜜蜂帮助授粉，是益虫，不能说害虫。"}, {"text": "这段代码里有害虫，一运行就出错。", "explanation": "这里应该用〈漏洞〉。害虫指对生产或健康有害的昆虫或动物；代码里的错误要说“漏洞”。"}, {"text": "吸烟的害虫很多，大家都应该知道。", "explanation": "这里应该用〈害处〉。害虫指虫子或动物，吸烟的危害不是虫子，要说“害处”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "正确。鸟吃掉的是树上的害虫，吃掉害虫才能保护果树，句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能保护果树，“吃掉了石头，保护了果树”说不通。"}, {"text": "空调", "is_correct": false, "explanation": "配价：“吃”的对象必须是可以吃的东西，“空调”不能被鸟吃。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是生物，与鸟、果树和“保护”的语境无关，句子说不通。"}], "explanations": {"害虫": "正确。鸟吃掉的是树上的害虫，吃掉害虫才能保护果树，句意相符。", "石头": "语义：石头不能保护果树，“吃掉了石头，保护了果树”说不通。", "空调": "配价：“吃”的对象必须是可以吃的东西，“空调”不能被鸟吃。", "玻璃": "语义：玻璃不是生物，与鸟、果树和“保护”的语境无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种害虫会让人拉肚子，吃之前要煮熟。", "explanation": "这里应该用〈细菌〉。拉肚子的病因是细菌，细菌不是虫子，不能说害虫。"}, {"text": "流感害虫会通过飞沫传播，大家要戴口罩。", "explanation": "这里应该用〈病毒〉。流感由病毒引起，病毒不是虫子，不能说“流感害虫”。"}, {"text": "这片田的草是害虫，要用除草剂除掉。", "explanation": "这里应该用〈杂草〉。害虫指对生产或健康有害的昆虫或其他动物，草是植物，不能说害虫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里爬进来一棵害虫。", "corrected_sentence": "院子里爬进来一只害虫。", "error_description": "量词错误：“害虫”应用量词“只”，“棵”只用于树木等植物，不能用来数虫子。正确说法：院子里爬进来一只害虫。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民用药水把把害虫消灭了。", "corrected_sentence": "农民用药水把害虫消灭了。", "error_description": "“把”字重复：“把害虫”前只需一个“把”，多写一个“把”不通。正确说法：农民用药水把害虫消灭了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一刀切", "is_correct": true, "explanation": "正确。“一刀切”指不分地区情况，采用统一办法，与因地制宜的做法相反。"}, {"text": "吃饭", "is_correct": false, "explanation": "与因地制宜无关，不是反义词。"}, {"text": "夸夸其谈", "is_correct": false, "explanation": "与因地制宜无关，指说话浮夸，不是反义词。"}, {"text": "画蛇添足", "is_correct": false, "explanation": "与因地制宜无关，指多此一举，不是反义词。"}], "correct_answer": "一刀切", "explanations": {"一刀切": "正确。“一刀切”指不分地区情况，采用统一办法，与因地制宜的做法相反。", "吃饭": "与因地制宜无关，不是反义词。", "夸夸其谈": "与因地制宜无关，指说话浮夸，不是反义词。", "画蛇添足": "与因地制宜无关，指多此一举，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "千篇一律", "is_correct": true, "explanation": "正确。“千篇一律”指事情都一个样、不分具体情况，与因地制宜的做法相反。"}, {"text": "翻山越岭", "is_correct": false, "explanation": "与因地制宜无关，指越过山岭，不是反义词。"}, {"text": "雪中送炭", "is_correct": false, "explanation": "与因地制宜无关，指在别人急需时给予帮助，不是反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "与因地制宜无关，不是反义词。"}], "correct_answer": "千篇一律", "explanations": {"千篇一律": "正确。“千篇一律”指事情都一个样、不分具体情况，与因地制宜的做法相反。", "翻山越岭": "与因地制宜无关，指越过山岭，不是反义词。", "雪中送炭": "与因地制宜无关，指在别人急需时给予帮助，不是反义词。", "唱歌": "与因地制宜无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据不同地区的实际情况，采取适当的措施来处理问题。", "primary_collocate": null, "pronunciation": "yīn dì zhì yí", "ipa": "in˥ ti˥˩ ʈʂʐ̩˥˩ i˧˥", "syllable_count": 4, "sentences": [{"text": "堆肥容器的选择需因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "种树要因地制宜，山上和河边不一样。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地气候不同，农业要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路和平地不同，修路必须因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方冷，南方热，盖房子要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子缺水，所以种菜要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的学校因地制宜，用石头盖了教室。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老板会因地制宜，不会照搬别人的办法。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到了新城市，做生意也要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙地和泥地不一样，因地制宜才能把花种好。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "按各地实际情况采取合适办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因地制宜", "is_correct": true, "explanation": "正确。“需”后接动词，“因地制宜”指根据具体情况选择，与选择容器相符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：容器的选择不需要翻译，句中说的是按实际情况选择。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：选择容器不是玩耍，与句意不符。"}, {"text": "喝酒", "is_correct": false, "explanation": "搭配：“选择需喝酒”不能搭配，“喝酒”与堆肥容器的选择无关。"}], "explanations": {"因地制宜": "正确。“需”后接动词，“因地制宜”指根据具体情况选择，与选择容器相符。", "翻译": "语义：容器的选择不需要翻译，句中说的是按实际情况选择。", "玩耍": "语义：选择容器不是玩耍，与句意不符。", "喝酒": "搭配：“选择需喝酒”不能搭配，“喝酒”与堆肥容器的选择无关。"}, "sentence_index": 0, "correct_answer": "因地制宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全县学校都用同一份教案，老师们因地制宜，全都一个样。", "explanation": "这里应该用〈千篇一律〉。教案统一、毫无变化，与因地制宜的灵活处理相反，应说“千篇一律”。"}, {"text": "他脾气很好，因地制宜，从不发火。", "explanation": "这里应该用〈心平气和〉。因地制宜指根据实际情况办事，形容性情平和要说“心平气和”。"}, {"text": "全校的菜都一个味道，厨师因地制宜，从不改变。", "explanation": "这里应该用〈千篇一律〉。菜都一个味道、毫无变化，与因地制宜的含义相反，应说“千篇一律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因地制宜", "is_correct": true, "explanation": "正确。山区条件特殊，学校据此就地取材，用石头盖教室，句意相符。"}, {"text": "追求时髦", "is_correct": false, "explanation": "语义：用石头盖教室与追求时髦相矛盾，句中讲的是就地取材。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡与“用石头盖了教室”没有关系，句子说不通。"}, {"text": "熬夜", "is_correct": false, "explanation": "搭配：“熬夜”是人的作息，不能用来概括学校建筑选材的做法。"}], "explanations": {"因地制宜": "正确。山区条件特殊，学校据此就地取材，用石头盖教室，句意相符。", "追求时髦": "语义：用石头盖教室与追求时髦相矛盾，句中讲的是就地取材。", "洗澡": "语义：洗澡与“用石头盖了教室”没有关系，句子说不通。", "熬夜": "搭配：“熬夜”是人的作息，不能用来概括学校建筑选材的做法。"}, "sentence_index": 6, "correct_answer": "因地制宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服是因地制宜做的，全都一个尺码，很不合身。", "explanation": "这里应该用〈一刀切〉。全都一个尺码是不分身材的统一做法，与因地制宜相反，应说“一刀切”。"}, {"text": "医生看病时因地制宜，给所有病人开同一种药。", "explanation": "这里应该用〈一刀切〉。给所有病人开同一种药是不分病情的统一做法，与因地制宜相反，应说“一刀切”。"}, {"text": "他写文章从不考虑读者，只会因地制宜地照搬别人的话。", "explanation": "这里应该用〈生搬硬套〉。因地制宜要求结合实际，“照搬别人的话”是不加变通的套用，应说“生搬硬套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修路很因地制宜，山区和平原的做法不同。", "corrected_sentence": "修路要因地制宜，山区和平原的做法不同。", "error_description": "程度副词“很”不能修饰“因地制宜”（动词性成语）。正确说法：修路要因地制宜，山区和平原的做法不同。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土地不同，只有一个因地制宜，花才能种好。", "corrected_sentence": "土地不同，只有因地制宜，花才能种好。", "error_description": "量词错误：“因地制宜”是动词性成语，不能直接加数量词“一个”。正确说法：土地不同，只有因地制宜，花才能种好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
