INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公寓是一种多层或高层的住宅建筑，通常有多套独立的住房单元。", "primary_collocate": null, "pronunciation": "gōng yù", "ipa": "kʊŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "我家住在一栋十层的公寓里。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座公寓离地铁站很近。", "target_word": "公寓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公寓门口等我。", "target_word": "公寓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座公寓里有二十多套房子。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以租学校旁边的公寓。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座公寓有三十层，电梯很快。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公寓的电梯坏了，我们只好走楼梯。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚搬进新公寓，还没有买沙发。", "target_word": "公寓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座公寓有很多住户，楼下有个小超市。", "target_word": "公寓", "complexity_tier": "T3", "furigana": "zhè zuò gōng yù yǒu hěn duō zhù hù, lóu xià yǒu gè xiǎo chāo shì", "sentence_source": "generated"}, {"text": "我家附近新建了一座公寓，楼层很高。", "target_word": "公寓", "complexity_tier": "T3", "furigana": "wǒ jiā fù jìn xīn jiàn le yí zuò gōng yù, lóu céng hěn gāo", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "公寓楼", "label": "复合"}], "register": "中性", "sense_fingerprint": "多层或高层的住宅楼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确答案。公寓（gōng yù）是多层或高层的住宅楼。"}, {"text": "公路", "is_correct": false, "explanation": "lù 与 yù 声母不同（l／y），意思是公路。"}, {"text": "工具", "is_correct": false, "explanation": "jù 与 yù 声母不同（j／y），意思是工具。"}, {"text": "公务", "is_correct": false, "explanation": "wù 与 yù 声母不同（w／y），意思是公务。"}, {"text": "工序", "is_correct": false, "explanation": "xù 与 yù 声母不同（x／y），意思是工序。"}, {"text": "工余", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是工作之余。"}], "explanations": {"公寓": "正确答案。公寓（gōng yù）是多层或高层的住宅楼。", "公路": "lù 与 yù 声母不同（l／y），意思是公路。", "工具": "jù 与 yù 声母不同（j／y），意思是工具。", "公务": "wù 与 yù 声母不同（w／y），意思是公务。", "工序": "xù 与 yù 声母不同（x／y），意思是工序。", "工余": "yú（第二声）与 yù（第四声）声调不同，意思是工作之余。"}, "sentence_index": null, "correct_answer": "公寓"}, "level_3": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确。公寓是多层住宅楼，可以“住在……里”，且用量词“栋”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习的地方，人不能住在里面。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一栋十层”指楼房，冰箱不用“栋”，也没有楼层。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是购物场所，不能用来居住。"}], "explanations": {"公寓": "正确。公寓是多层住宅楼，可以“住在……里”，且用量词“栋”。", "教室": "语义：教室是学习的地方，人不能住在里面。", "冰箱": "搭配：“一栋十层”指楼房，冰箱不用“栋”，也没有楼层。", "超市": "语义：超市是购物场所，不能用来居住。"}, "sentence_index": 0, "correct_answer": "公寓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公寓有十几栋楼，周围环境很好。", "explanation": "这里应该用〈小区〉。公寓指一栋楼，十几栋楼组成的住宅群要用“小区”。"}, {"text": "这座公寓里住满了病人，每层都有护士。", "explanation": "这里应该用〈医院〉。公寓是供家庭居住的住宅楼，收治病人的地方要用“医院”。"}, {"text": "这座公寓的一楼是阅览室，每层都有很多书架。", "explanation": "这里应该用〈图书馆〉。公寓供人居住，阅览室和书架属于图书馆，不能用“公寓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11522, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确答案。公寓（gōng yù）是多层或高层的住宅楼。"}, {"text": "公墓", "is_correct": false, "explanation": "mù 与 yù 声母不同（m／y），意思是公墓（墓地）。"}, {"text": "公布", "is_correct": false, "explanation": "bù 与 yù 声母不同（b／y），意思是公开发布。"}, {"text": "公余", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是公务之余的空闲时间。"}, {"text": "公益", "is_correct": false, "explanation": "yì 与 yù 韵母不同（i／ü），意思是公共利益。"}], "explanations": {"公寓": "正确答案。公寓（gōng yù）是多层或高层的住宅楼。", "公墓": "mù 与 yù 声母不同（m／y），意思是公墓（墓地）。", "公布": "bù 与 yù 声母不同（b／y），意思是公开发布。", "公余": "yú（第二声）与 yù（第四声）声调不同，意思是公务之余的空闲时间。", "公益": "yì 与 yù 韵母不同（i／ü），意思是公共利益。"}, "sentence_index": null, "correct_answer": "公寓"}, "level_3": {"options": [{"text": "公寓", "is_correct": true, "explanation": "正确。“公寓的电梯”指这栋住宅楼的电梯，搭配自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，没有电梯，不能说“冰箱的电梯”。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：电梯属于楼房设施，“花园的电梯”不搭配。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不可能有电梯，“书包的电梯坏了”说不通。"}], "explanations": {"公寓": "正确。“公寓的电梯”指这栋住宅楼的电梯，搭配自然。", "冰箱": "语义：冰箱是家用电器，没有电梯，不能说“冰箱的电梯”。", "花园": "搭配：电梯属于楼房设施，“花园的电梯”不搭配。", "书包": "语义：书包里不可能有电梯，“书包的电梯坏了”说不通。"}, "sentence_index": 6, "correct_answer": "公寓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公寓有五十层，每层都有很多公司。", "explanation": "这里应该用〈大厦〉。公寓是供人居住的住宅楼，不用来指办公的高楼。"}, {"text": "这座公寓有三十个教室，每天都有人上课。", "explanation": "这里应该用〈学校〉。公寓供居住，不设教室上课，这类场所要用“学校”。"}, {"text": "这座公寓有五条生产线，工人三百多名。", "explanation": "这里应该用〈工厂〉。生产线和工人属于工厂，公寓是住宅，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在一栋老公寓上住了二十年。", "corrected_sentence": "他们在一栋老公寓里住了二十年。", "error_description": "错误形式：“公寓上”；正确形式：“公寓里”。表示住在建筑内部要用方位词“里”，不用“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套公寓有二十层，楼下有一家书店。", "corrected_sentence": "这栋公寓有二十层，楼下有一家书店。", "error_description": "错误形式：“这套公寓”；正确形式：“这栋公寓”。“套”指一户住房的单位，描述整幢楼的层数要用“栋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
