INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11524, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指容器或空间封闭严密，与外界完全隔绝。", "primary_collocate": null, "pronunciation": "mì bì shì", "ipa": "mi˥˩ pi˥˩ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "城市公寓里可以用密闭式堆肥箱处理厨余，即使放在屋里也不会散发异味，红蚯蚓还能把厨余高效降解成肥料。", "target_word": "密闭式", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这个密闭式垃圾桶没有臭味。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密闭式的盒子能让饼干保持干脆。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里放着一个密闭式容器。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个密闭式的瓶子能防止香料变味。", "target_word": "密闭式", "complexity_tier": "T3", "furigana": "zhè ge mì bì shì de píng zi néng fáng zhǐ xiāng liào biàn wèi", "sentence_source": "generated"}, {"text": "买密闭式的罐子，米就不会受潮。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室用密闭式柜子放药品。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种密闭式水箱，虫子进不去。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密闭式房间里空气不好，要开窗。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选了密闭式的堆肥桶，放在阳台上。", "target_word": "密闭式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "封闭严密、与外界隔绝的样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密闭式", "is_correct": true, "explanation": "正确。密闭式指封闭严密、与外界隔绝，适合做封闭的堆肥箱。"}, {"text": "户外式", "is_correct": false, "explanation": "语义：户外式箱子不能放在屋里使用，与“即使放在屋里也不会散发异味”相矛盾。"}, {"text": "冷藏式", "is_correct": false, "explanation": "语义：冷藏会抑制红蚯蚓的活动，与“高效降解”相矛盾。"}, {"text": "敞口式", "is_correct": false, "explanation": "语义：敞口箱放在屋里会散发异味，与“不会散发异味”相矛盾。"}], "explanations": {"密闭式": "正确。密闭式指封闭严密、与外界隔绝，适合做封闭的堆肥箱。", "户外式": "语义：户外式箱子不能放在屋里使用，与“即使放在屋里也不会散发异味”相矛盾。", "冷藏式": "语义：冷藏会抑制红蚯蚓的活动，与“高效降解”相矛盾。", "敞口式": "语义：敞口箱放在屋里会散发异味，与“不会散发异味”相矛盾。"}, "sentence_index": 0, "correct_answer": "密闭式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间咖啡馆的厨房采用密闭式设计，客人能看到厨师。", "explanation": "这里应该用〈敞开式〉。密闭式指严密封闭、与外界隔绝，与“客人能看到厨师”矛盾。"}, {"text": "这间仓库是密闭式的，空气很流通。", "explanation": "这里应该用〈通风式〉。密闭式强调与外界隔绝，不能用来形容空气流通的空间。"}, {"text": "这个密闭式的院子，阳光能直接照进来。", "explanation": "这里应该用〈露天式〉。密闭式的空间与外界隔绝，阳光进不来，与“露天”相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密闭式", "is_correct": true, "explanation": "正确。密闭式柜子封闭严密，适合存放药品。"}, {"text": "游乐式", "is_correct": false, "explanation": "搭配：“游乐式”多修饰游乐设施，不用于修饰“柜子”。"}, {"text": "草地式", "is_correct": false, "explanation": "语义：草地无法用来存放药品，与实验室环境不符。"}, {"text": "海滩式", "is_correct": false, "explanation": "语义：海滩环境与实验室放药品的场景不符。"}], "explanations": {"密闭式": "正确。密闭式柜子封闭严密，适合存放药品。", "游乐式": "搭配：“游乐式”多修饰游乐设施，不用于修饰“柜子”。", "草地式": "语义：草地无法用来存放药品，与实验室环境不符。", "海滩式": "语义：海滩环境与实验室放药品的场景不符。"}, "sentence_index": 6, "correct_answer": "密闭式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间密闭式的房间，四面墙上都开着大窗户。", "explanation": "这里应该用〈开放〉。密闭式指封闭严密、与外界隔绝，四面开窗的房间属于开放式空间，要用“开放”。"}, {"text": "这个密闭式的袋子，袋口一直敞着，灰尘随便进出。", "explanation": "这里应该用〈敞口〉。密闭式的袋子封闭严密，袋口敞着、灰尘随便进出，要用“敞口”。"}, {"text": "这个密闭式的水壶，水从壶嘴里不断地往外流。", "explanation": "这里应该用〈渗漏〉。密闭式的水壶不让水外流，水从壶嘴不断流出，与其矛盾，应该用“渗漏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个罐子很密闭式的，米不容易受潮。", "corrected_sentence": "这个罐子是密闭式的，米不容易受潮。", "error_description": "错误形式：“很密闭式的”；正确形式：“是密闭式的”。“密闭式”是类别性质的词，不能用“很”修饰，作谓语要用“是……的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个铁盒是很密闭式的，饼干不会受潮。", "corrected_sentence": "这个铁盒是密闭式的，饼干不会受潮。", "error_description": "错误形式：“是很密闭式的”；正确形式：“是密闭式的”。“很”是程度副词，不能修饰区别词“密闭式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
