INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蠕虫是身体细长、柔软、没有骨骼的一类动物，通常生活在土壤或水中，如蚯蚓。", "primary_collocate": null, "pronunciation": "rú chóng", "ipa": "ɻu˧˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "城市公寓可采用密闭式蠕虫堆肥箱（vermicomposter），利用红蚯蚓（Eisenia fetida）的肠道微生物高效降解细碎厨余，产出富含植物生长激素的“黑色金子”——腐殖质浓缩液。", "target_word": "蠕虫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蠕虫没有骨头，身体又细又软。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路边的泥土里有很多蠕虫。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫生活在土里或水里，样子细长。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟喜欢吃草地上的蠕虫。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在研究水里的一种蠕虫。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫没有腿，只能慢慢爬。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蠕虫又细又长，颜色是灰色的。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼的时候，他用蠕虫做鱼饵。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫能让土变得松软，对花草有好处。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "蠕蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体细长柔软、无骨骼、生活在土壤或水中的一类动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蠕虫", "is_correct": true, "explanation": "正确：后文“红蚯蚓”和“肠道微生物”说明这种箱子是用蠕虫分解厨余的。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶不能分解厨余，与后文“利用红蚯蚓的肠道微生物降解细碎厨余”矛盾。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能被降解成腐殖质，与“产出……腐殖质浓缩液”的意思矛盾。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "搭配：“堆肥箱”前面通常是堆肥的生物或材料，不说“蚂蚁堆肥箱”。"}], "explanations": {"蠕虫": "正确：后文“红蚯蚓”和“肠道微生物”说明这种箱子是用蠕虫分解厨余的。", "蝴蝶": "语义：蝴蝶不能分解厨余，与后文“利用红蚯蚓的肠道微生物降解细碎厨余”矛盾。", "汽油": "语义：汽油不能被降解成腐殖质，与“产出……腐殖质浓缩液”的意思矛盾。", "蚂蚁": "搭配：“堆肥箱”前面通常是堆肥的生物或材料，不说“蚂蚁堆肥箱”。"}, "sentence_index": 0, "correct_answer": "蠕虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在菜园里挖到一朵蠕虫。", "explanation": "这里应该用〈条〉。“朵”用于花，蠕虫细长，不能用“朵”来数。"}, {"text": "我在池塘里钓到了三头蠕虫。", "explanation": "这里应该用〈条〉。“头”多用于牛、猪等大牲畜，不用于蠕虫。"}, {"text": "草地上爬着一匹蠕虫。", "explanation": "这里应该用〈条〉。“匹”专用于马、骡等动物，蠕虫不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蠕虫", "is_correct": true, "explanation": "正确：“没有腿，只能慢慢爬”正是对蠕虫的描述。"}, {"text": "蜈蚣", "is_correct": false, "explanation": "体貌：蜈蚣身上有许多条腿，与“没有腿”矛盾。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫有四条腿，不可能“没有腿，只能慢慢爬”。"}, {"text": "鸟", "is_correct": false, "explanation": "语义：鸟有腿，还会飞，与“只能慢慢爬”矛盾。"}], "explanations": {"蠕虫": "正确：“没有腿，只能慢慢爬”正是对蠕虫的描述。", "蜈蚣": "体貌：蜈蚣身上有许多条腿，与“没有腿”矛盾。", "猫": "语义：猫有四条腿，不可能“没有腿，只能慢慢爬”。", "鸟": "语义：鸟有腿，还会飞，与“只能慢慢爬”矛盾。"}, "sentence_index": 6, "correct_answer": "蠕虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的草地上，有一块蠕虫。", "explanation": "这里应该用〈条〉。“块”用于成块的东西，蠕虫是细长的，不能用“块”。"}, {"text": "我的孩子捡到一张蠕虫。", "explanation": "这里应该用〈条〉。“张”用于纸、桌子等扁平的东西，蠕虫不能用。"}, {"text": "花园里有一座蠕虫。", "explanation": "这里应该用〈条〉。“座”用于山、桥等大型固定的东西，蠕虫不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在菜园里翻出了一张蠕虫。", "corrected_sentence": "我在菜园里翻出了一条蠕虫。", "error_description": "量词错误：应为“一条蠕虫”。蠕虫细长，应用量词“条”；“张”用于纸、桌子等扁平的东西，不能用于蠕虫。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了三张蠕虫做鱼饵。", "corrected_sentence": "我买了三条蠕虫做鱼饵。", "error_description": "应为“三条蠕虫”。蠕虫细长，量词用“条”；“张”用于纸、桌子等扁平的东西，不能用于蠕虫。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
