INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像鲜血或火焰的颜色。", "primary_collocate": null, "pronunciation": "hóng", "ipa": "xʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他的手受伤了，流出的血很红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子里的火烧得很红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花红得像火一样。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果熟了，从绿变红了。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩的衣服是红的，很好看。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了酒，脸和脖子都很红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，山上的叶子都红了。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红的是辣椒，绿的是青菜。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口很红，可能发炎了。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚出炉的铁块烧得很红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紅", "label": "繁体"}, {"form": "红红", "label": "重叠"}, {"form": "通红", "label": "复合"}], "register": "中性", "sense_fingerprint": "像鲜血或火焰的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：红 hóng 指像鲜血或火焰的颜色。"}, {"text": "烘", "is_correct": false, "explanation": "hōng（第一声）与 hóng（第二声）声调不同，意思是烘烤。"}, {"text": "轰", "is_correct": false, "explanation": "hōng（第一声）与 hóng（第二声）声调不同，意思是轰鸣。"}, {"text": "哄", "is_correct": false, "explanation": "hòng（第四声）与 hóng（第二声）声调不同，意思是起哄。"}, {"text": "横", "is_correct": false, "explanation": "héng 与 hóng 韵母不同（e 与 o），意思是横向。"}], "explanations": {"红": "正确：红 hóng 指像鲜血或火焰的颜色。", "烘": "hōng（第一声）与 hóng（第二声）声调不同，意思是烘烤。", "轰": "hōng（第一声）与 hóng（第二声）声调不同，意思是轰鸣。", "哄": "hòng（第四声）与 hóng（第二声）声调不同，意思是起哄。", "横": "héng 与 hóng 韵母不同（e 与 o），意思是横向。"}, "sentence_index": null, "correct_answer": "红"}, "level_3": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：血是红色的，“很红”描述流出的血。"}, {"text": "绿", "is_correct": false, "explanation": "语义：血不是绿色，与“流出的血”的常识矛盾。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：血不是蓝色，这里描述的是血的颜色，蓝色不符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“血”一般不用“硬”来形容，“血很硬”不符合常理。"}], "explanations": {"红": "正确：血是红色的，“很红”描述流出的血。", "绿": "语义：血不是绿色，与“流出的血”的常识矛盾。", "蓝": "语义：血不是蓝色，这里描述的是血的颜色，蓝色不符。", "硬": "搭配：“血”一般不用“硬”来形容，“血很硬”不符合常理。"}, "sentence_index": 0, "correct_answer": "红"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他的成绩很红，老师都夸他。", "explanation": "这里的“红”指受欢迎、出名，是另一个义项，不能用来说成绩，应该用〈好〉。"}, {"text": "他爷爷的葬礼办得很红，亲戚都来了。", "explanation": "这里的“红”指喜庆（红事即喜事），是另一个义项，用于葬礼不合适，葬礼应说〈白事〉。"}, {"text": "这家公司今年的利润很红，比去年多了一倍。", "explanation": "这里应该用〈高〉。“红”不用来说利润多少；“红利”是另一个词，指分红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：红 hóng 指像鲜血或火焰的颜色。"}, {"text": "猴", "is_correct": false, "explanation": "hóu 与 hóng 韵尾不同（u 与 ng），意思是猴子。"}, {"text": "航", "is_correct": false, "explanation": "háng 与 hóng 韵母不同（a 与 o），意思是航行。"}, {"text": "恒", "is_correct": false, "explanation": "héng 与 hóng 韵母不同（e 与 o），意思是恒久。"}], "explanations": {"红": "正确：红 hóng 指像鲜血或火焰的颜色。", "猴": "hóu 与 hóng 韵尾不同（u 与 ng），意思是猴子。", "航": "háng 与 hóng 韵母不同（a 与 o），意思是航行。", "恒": "héng 与 hóng 韵母不同（e 与 o），意思是恒久。"}, "sentence_index": null, "correct_answer": "红"}, "level_3": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：秋天叶子变红，与“都……了”的变化相符。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：叶子的形状不会因秋天变“圆”，与“红了”的颜色变化不符。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”用于味道，不用来形容叶子。"}, {"text": "空", "is_correct": false, "explanation": "搭配：叶子不说“空了”，与“叶子都……了”的变色描述不符。"}], "explanations": {"红": "正确：秋天叶子变红，与“都……了”的变化相符。", "圆": "体貌：叶子的形状不会因秋天变“圆”，与“红了”的颜色变化不符。", "咸": "搭配：“咸”用于味道，不用来形容叶子。", "空": "搭配：叶子不说“空了”，与“叶子都……了”的变色描述不符。"}, "sentence_index": 6, "correct_answer": "红"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个沙发的价格很红，卖得特别好。", "explanation": "这里的“红”指受欢迎（另一义项），用于价格不对，价格应该用〈高〉。"}, {"text": "这个苹果很红，像红军一样勇敢。", "explanation": "这里的“红”指革命（红军）义项，与颜色无关，用于形容苹果的勇敢不合理。"}, {"text": "这锅粥很红，小心烫嘴。", "explanation": "这里应该用〈烫〉或〈热〉。“红”只用于烧得发光发红的东西（如烧红的铁），粥不会呈现这种红色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵花比那朵很红。", "corrected_sentence": "这朵花比那朵更红。", "error_description": "比较句中不能用“很”，应为“比那朵更红”。“很”表示程度，不能与“比”字句搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那块烤肉烤红红的，很香。", "corrected_sentence": "那块烤肉烤得红红的，很香。", "error_description": "应为“烤得红红的”。“红红的”作结果补语时要用“得”连接，“烤红红的”少了“得”，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
