INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蚯蚓是环节动物，身体细长柔软，生活在土壤中，能疏松土壤，对植物生长有益。", "primary_collocate": null, "pronunciation": "qiū yǐn", "ipa": "tɕʰjoʊ˥ jɪn˨˩˦", "syllable_count": 2, "sentences": [{"text": "园丁在堆肥箱里放了一些蚯蚓，让它们分解厨余。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓住在土里，身体细长又柔软。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上会有很多蚯蚓。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓能让土变松，花草长得更好。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在地上找蚯蚓吃。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园里挖到了一条蚯蚓。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓没有骨头，爬得很慢。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民喜欢土里有蚯蚓，因为土会更松。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用蚯蚓当鱼饵去钓鱼。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓是对植物有益的环节动物。", "target_word": "蚯蚓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "生活在土壤中、能疏松土壤的细长柔软的环节动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蚯蚓", "is_correct": true, "explanation": "正确：蚯蚓能分解厨余，园丁把它们放进堆肥箱。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶是靠翅膀飞行的成虫，不是蠕虫，无法在堆肥箱里降解厨余。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是吸血的害虫，不能分解厨余。"}, {"text": "蝗虫", "is_correct": false, "explanation": "语义：蝗虫吃的是活的植物，不能分解厨余。"}], "explanations": {"蚯蚓": "正确：蚯蚓能分解厨余，园丁把它们放进堆肥箱。", "蝴蝶": "语义：蝴蝶是靠翅膀飞行的成虫，不是蠕虫，无法在堆肥箱里降解厨余。", "蚊子": "语义：蚊子是吸血的害虫，不能分解厨余。", "蝗虫": "语义：蝗虫吃的是活的植物，不能分解厨余。"}, "sentence_index": 0, "correct_answer": "蚯蚓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在花园里挖到了一朵蚯蚓。", "explanation": "这里应该用〈条〉。“朵”用于花，蚯蚓身体细长，不能用“朵”来数。"}, {"text": "他游泳时，腿上叮了一条蚯蚓。", "explanation": "这里应该用〈蚂蟥〉。蚯蚓生活在土里，不叮咬人；叮在腿上吸血的是蚂蟥。"}, {"text": "孩子在草地上跑，突然飞起一条蚯蚓。", "explanation": "这里应该用〈蝴蝶〉。蚯蚓没有翅膀，不会飞；会飞的是蝴蝶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蚯蚓", "is_correct": true, "explanation": "正确：蚯蚓没有骨头，靠身体伸缩慢慢爬行，与句中描述相符。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象身体庞大、骨骼粗壮，与句中“没有骨头”不符。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟有骨骼，而且会飞，与“没有骨头，爬得很慢”矛盾。"}, {"text": "猴子", "is_correct": false, "explanation": "语义：猴子有骨骼，善于攀爬而非慢慢爬行，与“没有骨头，爬得很慢”矛盾。"}], "explanations": {"蚯蚓": "正确：蚯蚓没有骨头，靠身体伸缩慢慢爬行，与句中描述相符。", "大象": "体貌：大象身体庞大、骨骼粗壮，与句中“没有骨头”不符。", "小鸟": "语义：小鸟有骨骼，而且会飞，与“没有骨头，爬得很慢”矛盾。", "猴子": "语义：猴子有骨骼，善于攀爬而非慢慢爬行，与“没有骨头，爬得很慢”矛盾。"}, "sentence_index": 6, "correct_answer": "蚯蚓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蚯蚓身上有很多条腿，爬得很快。", "explanation": "这里应该用〈蜈蚣〉。蚯蚓没有腿，靠身体伸缩爬行；有很多条腿、爬得快的是蜈蚣。"}, {"text": "蚯蚓吐丝结茧，过几周就变成了蛾。", "explanation": "这里应该用〈蚕〉。吐丝结茧、再变成蛾的是蚕，蚯蚓不会吐丝结茧。"}, {"text": "蚯蚓背着硬壳，爬得很慢。", "explanation": "这里应该用〈蜗牛〉。蚯蚓身体软，没有硬壳；背着硬壳慢慢爬的是蜗牛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在雨后的院子里捡到了一朵蚯蚓。", "corrected_sentence": "妹妹在雨后的院子里捡到了一条蚯蚓。", "error_description": "量词错误：蚯蚓身体细长，应用量词“条”，不能用“朵”（“朵”用于花）。正确说法是“一条蚯蚓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨后，蚯蚓从土里爬来出了。", "corrected_sentence": "雨后，蚯蚓从土里爬出来了。", "error_description": "趋向补语语序错误：“爬出来”是固定顺序，“爬来出”不通顺。正确说法是“爬出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人或动物体内消化管道的总称，从胃的幽门到肛门，负责吸收营养和排出废物。", "primary_collocate": null, "pronunciation": "cháng dào", "ipa": "ʈʂʰɑŋ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "城市公寓可采用密闭式蠕虫堆肥箱（vermicomposter），利用红蚯蚓（Eisenia fetida）的肠道微生物高效降解细碎厨余，产出富含植物生长激素的“黑色金子”——腐殖质浓缩液。", "target_word": "肠道", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生说我的肠道有点发炎。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃蔬菜对肠道很好。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物先经过胃，再进入肠道。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他肠道不舒服，一直拉肚子。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶里的细菌能帮助肠道消化。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药主要在肠道里被吸收。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做肠道检查前，不能吃东西。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓的肠道又细又长。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肠道里住着很多有益的细菌。", "target_word": "肠道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腸道", "label": "繁体"}, {"form": "肠道菌群", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物体内从胃到肛门的消化管道总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肠道", "is_correct": true, "explanation": "正确：句中指的是红蚯蚓消化道内的微生物，“肠道微生物”是常见搭配。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液不是消化管道，与蚯蚓体内降解厨余的微生物无关。"}, {"text": "声带", "is_correct": false, "explanation": "搭配：“微生物”前常接“肠道、土壤”等环境，“声带微生物”搭配不当，也与厨余降解无关。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车与蚯蚓的消化过程无关，不能降解细碎厨余。"}], "explanations": {"肠道": "正确：句中指的是红蚯蚓消化道内的微生物，“肠道微生物”是常见搭配。", "血液": "语义：血液不是消化管道，与蚯蚓体内降解厨余的微生物无关。", "声带": "搭配：“微生物”前常接“肠道、土壤”等环境，“声带微生物”搭配不当，也与厨余降解无关。", "汽车": "语义：汽车与蚯蚓的消化过程无关，不能降解细碎厨余。"}, "sentence_index": 0, "correct_answer": "肠道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说我的一只肠道发炎了。", "explanation": "这里应该用〈段〉。肠道是长管子，量词用“段”，不用“只”。"}, {"text": "肠道能帮助呼吸，把氧气送进血液。", "explanation": "这里应该用〈肺〉。把氧气送进血液、帮助呼吸的是肺；肠道是消化管，不参与呼吸。"}, {"text": "肠道负责把食物送进胃里，让胃来消化。", "explanation": "这里应该用〈食道〉。食物经食道进入胃；肠道位于胃之后，不负责把食物送进胃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肠道", "is_correct": true, "explanation": "正确：药物主要在消化道（肠道）里被吸收，与句子相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：药物不会在冰箱里被吸收，人体吸收药物的处所是消化道。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场不是人体器官，药物不会在操场里被吸收。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“被吸收”的处所须是能吸收药物的人体器官，“钱包里”不能与之搭配。"}], "explanations": {"肠道": "正确：药物主要在消化道（肠道）里被吸收，与句子相符。", "冰箱": "语义：药物不会在冰箱里被吸收，人体吸收药物的处所是消化道。", "操场": "语义：操场不是人体器官，药物不会在操场里被吸收。", "钱包": "搭配：“被吸收”的处所须是能吸收药物的人体器官，“钱包里”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "肠道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肠道负责过滤血液，排出尿液。", "explanation": "这里应该用〈肾〉。过滤血液、形成尿液的是肾；肠道负责消化吸收，不过滤血液。"}, {"text": "肠道里储存着胆汁，帮助消化脂肪。", "explanation": "这里应该用〈胆囊〉。胆汁储存在胆囊里，经导管流入肠道；肠道本身不储存胆汁。"}, {"text": "肠道推动血液流动，让血液循环全身。", "explanation": "这里应该用〈心脏〉。推动血液循环的是心脏；肠道负责消化吸收，不推动血液。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说他的一棵肠道发炎了。", "corrected_sentence": "医生说他的一段肠道发炎了。", "error_description": "量词错误：应为“一段肠道”。肠道是管状器官，应用量词“段”；“棵”用于树木，不能用于肠道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃坏东西以后，肠道很疼得厉害。", "corrected_sentence": "吃坏东西以后，肠道疼得厉害。", "error_description": "程度重复：“很”与“得厉害”都表示程度，不能同时使用。应为“疼得厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
