INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11531, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "细小而零碎。", "primary_collocate": null, "pronunciation": "xì suì", "ipa": "ɕi˥˩ sueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "厨房的垃圾桶里有很多细碎的厨余。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把青菜切得很细碎。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上传来细碎的脚步声。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶间漏下细碎的阳光。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上落满了细碎的纸片。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外飘着细碎的雨点。", "target_word": "细碎", "complexity_tier": "T3", "furigana": "chuāng wài piāo zhe xì suì de yǔ diǎn.", "sentence_source": "generated"}, {"text": "妈妈把生姜剁得很细碎，放进了锅里。", "target_word": "细碎", "complexity_tier": "T3", "furigana": "mā ma bǎ shēng jiāng duò de hěn xì suì, fàng jìn le guō lǐ.", "sentence_source": "generated"}, {"text": "他把饼干捏成细碎的渣，撒在窗台上。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们细碎的笑声从院子里传来。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，细碎的花瓣飘了下来。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "細碎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容东西或声音细小而零碎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细碎", "is_correct": true, "explanation": "细碎：修饰“厨余”，指切碎或分解成细小零碎的食物残渣，符合句意。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能透光，不能用来修饰厨余。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”说颜色，厨余不能用它来形容。"}, {"text": "庄严", "is_correct": false, "explanation": "语域：“庄严”是书面、庄重的褒义形容，与“厨余”这类日常废弃物不搭。"}], "explanations": {"细碎": "细碎：修饰“厨余”，指切碎或分解成细小零碎的食物残渣，符合句意。", "透明": "搭配：“透明”形容物体能透光，不能用来修饰厨余。", "雪白": "搭配：“雪白”说颜色，厨余不能用它来形容。", "庄严": "语域：“庄严”是书面、庄重的褒义形容，与“厨余”这类日常废弃物不搭。"}, "sentence_index": 0, "correct_answer": "细碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小蚂蚁很细碎。", "explanation": "这里应该用〈细小〉。细碎指东西零散地成为许多小块，形容单个小东西要用细小。"}, {"text": "这座大山很细碎。", "explanation": "这里应该用〈雄伟〉。细碎指零散的细小东西，形容整座大山的气势要用雄伟。"}, {"text": "我站在大海边，显得很细碎。", "explanation": "这里应该用〈渺小〉。细碎形容零散的细小东西，形容人在广阔环境中的微不足道要用渺小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细碎", "is_correct": true, "explanation": "细碎：修饰“剁”的结果，说明生姜被剁成细小碎末，符合句意。"}, {"text": "光滑", "is_correct": false, "explanation": "语义：生姜被剁后不可能光滑，“光滑”与剁碎的结果相反。"}, {"text": "完整", "is_correct": false, "explanation": "语义：“完整”指没有缺损，剁过的生姜已不再完整，与句意矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或天空等透明的东西，不能用来形容生姜。"}], "explanations": {"细碎": "细碎：修饰“剁”的结果，说明生姜被剁成细小碎末，符合句意。", "光滑": "语义：生姜被剁后不可能光滑，“光滑”与剁碎的结果相反。", "完整": "语义：“完整”指没有缺损，剁过的生姜已不再完整，与句意矛盾。", "清澈": "搭配：“清澈”形容水或天空等透明的东西，不能用来形容生姜。"}, "sentence_index": 6, "correct_answer": "细碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件玉器的做工很细碎。", "explanation": "这里应该用〈精细〉。细碎指零散的细小东西，形容做工精致要用精细。"}, {"text": "雷声很细碎。", "explanation": "这里应该用〈轰鸣〉。细碎形容细小断续的声音，雷声是洪亮的轰鸣，要用轰鸣描写。"}, {"text": "她的皮肤很细碎。", "explanation": "这里应该用〈细腻〉。细碎指零散细小的东西，形容皮肤光滑、质地柔和要用细腻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟细碎的啄着地上的谷粒。", "corrected_sentence": "小鸟细碎地啄着地上的谷粒。", "error_description": "错误形式「细碎的啄」，正确形式「细碎地啄」。修饰动词“啄”的状语要用「地」，「的」用于名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她细碎的挪动着脚步。", "corrected_sentence": "她细碎地挪动着脚步。", "error_description": "错误形式「细碎的挪动」，正确形式「细碎地挪动」。修饰动词“挪动”的状语要用「地」，「的」用于名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
