INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由脑垂体分泌的一种激素，能促进身体生长和发育。", "primary_collocate": null, "pronunciation": "shēng zhǎng jī sù", "ipa": "ʂɤŋ˥ ʈʂɑŋ˨˩˦ tɕi˥ su˥˩", "syllable_count": 4, "sentences": [{"text": "他的身材一直偏矮，医生给他开了生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个孩子缺少生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生长激素由脑垂体分泌。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上睡得好，身体会分泌更多生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天打一针生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生长激素能帮助孩子长高。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动可以促进生长激素的分泌。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果显示他的生长激素偏低。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生长激素对骨骼发育很重要。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些运动员非法使用生长激素。", "target_word": "生长激素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生長激素", "label": "繁体"}], "register": "书面", "sense_fingerprint": "脑垂体分泌、促进生长发育的激素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生长激素", "is_correct": true, "explanation": "生长激素：脑垂体分泌的激素，用于治疗生长激素缺乏引起的身材矮小，符合句意。"}, {"text": "退烧药", "is_correct": false, "explanation": "语义：退烧药用于退热，与身材矮小无关。"}, {"text": "抗生素", "is_correct": false, "explanation": "语义：抗生素用于抗菌消炎，与身材矮小无关。"}, {"text": "止痛药", "is_correct": false, "explanation": "语义：止痛药用于缓解疼痛，与身材矮小无关。"}], "explanations": {"生长激素": "生长激素：脑垂体分泌的激素，用于治疗生长激素缺乏引起的身材矮小，符合句意。", "退烧药": "语义：退烧药用于退热，与身材矮小无关。", "抗生素": "语义：抗生素用于抗菌消炎，与身材矮小无关。", "止痛药": "语义：止痛药用于缓解疼痛，与身材矮小无关。"}, "sentence_index": 0, "correct_answer": "生长激素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天打一只生长激素。", "explanation": "这里应该用〈针〉。「只」用于动物等，注射药剂要用〈针〉。"}, {"text": "孩子的生长激素很快。", "explanation": "这里应该用〈生长发育〉。生长激素是一种物质，不能用“快”来形容；描述身体长大的过程要用生长发育。"}, {"text": "他每天注射一颗生长激素。", "explanation": "这里应该用〈针〉。「颗」用于颗粒状的东西，注射剂要用〈针〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生长激素", "is_correct": true, "explanation": "生长激素：作“分泌”的对象，指脑垂体分泌的、促进生长的物质，符合句意。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：“睡眠”是一种生理状态，不是可以被分泌的物质，与句意不符。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液是循环在血管中的体液，不属于分泌物，与句意不符。"}, {"text": "维生素", "is_correct": false, "explanation": "搭配：“分泌”通常搭配腺体产生的激素、汗液等，不与维生素搭配。"}], "explanations": {"生长激素": "生长激素：作“分泌”的对象，指脑垂体分泌的、促进生长的物质，符合句意。", "睡眠": "语义：“睡眠”是一种生理状态，不是可以被分泌的物质，与句意不符。", "血液": "语义：血液是循环在血管中的体液，不属于分泌物，与句意不符。", "维生素": "搭配：“分泌”通常搭配腺体产生的激素、汗液等，不与维生素搭配。"}, "sentence_index": 6, "correct_answer": "生长激素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天打一滴生长激素。", "explanation": "这里应该用〈针〉。「滴」用于液体的滴，注射药剂要用〈针〉。"}, {"text": "他每天注射一把生长激素。", "explanation": "这里应该用〈针〉。「把」用于有柄的器具，计量注射剂要用〈针〉。"}, {"text": "他买了一张生长激素。", "explanation": "这里应该用〈支〉。「张」用于平面的东西，不能用来计量药剂，药剂要用「支」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生让她每天打一只生长激素。", "corrected_sentence": "医生让她每天打一针生长激素。", "error_description": "错误形式「一只生长激素」，正确形式「一针生长激素」。「只」用于动物等，注射药剂要用「针」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每周打一张生长激素。", "corrected_sentence": "他每周打一针生长激素。", "error_description": "错误形式「一张生长激素」，正确形式「一针生长激素」。「张」用于平面的东西，注射药剂要用「针」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
