INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指黄金，一种贵重金属，常用于制造首饰和货币。", "primary_collocate": null, "pronunciation": "jīn zi", "ipa": "tɕin˥ tsɿ", "syllable_count": 2, "sentences": [{"text": "这个戒指是用金子做的。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把金子放在小盒子里。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金子很重，我一只手拿不动。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候人们用金子当钱买东西。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金子在阳光下看起来很亮。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块小金子送给妻子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的金子比别家便宜。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有人想找到金子。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金子不会生锈，所以很值钱。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的耳环是金子做的，不是银的。", "target_word": "金子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块金子", "label": "量词"}, {"form": "一堆金子", "label": "量词"}], "register": "口语", "sense_fingerprint": "黄金，贵重金属，用于首饰和货币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11534, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子（jīn zi）指黄金。"}, {"text": "镜子", "is_correct": false, "explanation": "jīn（第一声）与 jìng（第四声）韵尾不同（n／ng），声调也不同，意思是镜子。"}, {"text": "亲子", "is_correct": false, "explanation": "jīn 与 qīn 声母不同（j／q），意思是亲子，即父母与子女。"}, {"text": "金字", "is_correct": false, "explanation": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。"}, {"text": "金纸", "is_correct": false, "explanation": "第二音节声母与声调不同（zi 与 zhǐ，z／zh），意思是烧纸用的金色纸。"}], "explanations": {"金子": "正确：金子（jīn zi）指黄金。", "镜子": "jīn（第一声）与 jìng（第四声）韵尾不同（n／ng），声调也不同，意思是镜子。", "亲子": "jīn 与 qīn 声母不同（j／q），意思是亲子，即父母与子女。", "金字": "第二音节声调不同（zi 轻声与 zì 第四声），意思是金色的字，如金字招牌。", "金纸": "第二音节声母与声调不同（zi 与 zhǐ，z／zh），意思是烧纸用的金色纸。"}, "sentence_index": null, "correct_answer": "金子"}, "level_3": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子是可以用来做戒指的贵金属，符合“用……做的”。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，不能用来做戒指。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“用……做的”要求具体的材料，“时间”是抽象概念，不能作为制作戒指的材料。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是制作首饰的材料。"}], "explanations": {"金子": "正确：金子是可以用来做戒指的贵金属，符合“用……做的”。", "面粉": "语义：面粉是食材，不能用来做戒指。", "时间": "搭配：“用……做的”要求具体的材料，“时间”是抽象概念，不能作为制作戒指的材料。", "冰箱": "语义：冰箱是家用电器，不是制作首饰的材料。"}, "sentence_index": 0, "correct_answer": "金子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁是一种很常见的金子。", "explanation": "这里应该用〈金属〉。金子专指黄金这一种金属，说“一种很常见的……”这类泛指时要用〈金属〉。"}, {"text": "夕阳把天空染得很金子。", "explanation": "这里应该用〈金色〉。金子是金属，描写颜色要用〈金色〉，不能说“染得很金子”。"}, {"text": "他买了一只金子。", "explanation": "这里应该用〈块〉。金子是块状材料，量词用〈块〉；〈只〉用于动物或成对的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11534, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：金子（jīn zi）指黄金。"}, {"text": "今次", "is_correct": false, "explanation": "第二音节声母不同（z／c，zi 与 cì），意思是这一次。"}, {"text": "金丝", "is_correct": false, "explanation": "第二音节声母不同（z／s，zi 与 sī），意思是金色的细丝，如金丝眼镜。"}, {"text": "金质", "is_correct": false, "explanation": "第二音节声母与声调不同（z／zh，zi 与 zhì），意思是金质，如金质奖章。"}], "explanations": {"金子": "正确：金子（jīn zi）指黄金。", "今次": "第二音节声母不同（z／c，zi 与 cì），意思是这一次。", "金丝": "第二音节声母不同（z／s，zi 与 sī），意思是金色的细丝，如金丝眼镜。", "金质": "第二音节声母与声调不同（z／zh，zi 与 zhì），意思是金质，如金质奖章。"}, "sentence_index": null, "correct_answer": "金子"}, "level_3": {"options": [{"text": "金子", "is_correct": true, "explanation": "正确：“卖的金子”比别家便宜，金子是可以出售的商品。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是商品，不能买卖，也谈不上“比别家便宜”。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光无法出售，不能说“卖的阳光”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“卖的……比别家便宜”要求可售商品，“名字”不能用来出售，也没有价格。"}], "explanations": {"金子": "正确：“卖的金子”比别家便宜，金子是可以出售的商品。", "天空": "语义：天空不是商品，不能买卖，也谈不上“比别家便宜”。", "阳光": "语义：阳光无法出售，不能说“卖的阳光”。", "名字": "搭配：“卖的……比别家便宜”要求可售商品，“名字”不能用来出售，也没有价格。"}, "sentence_index": 6, "correct_answer": "金子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在奥运会上赢得了一块金子。", "explanation": "这里应该用〈金牌〉。比赛的奖牌要说“金牌”，金子是贵金属，不指奖牌。"}, {"text": "他们度过了一段金子时代。", "explanation": "这里应该用〈黄金〉。固定说法是“黄金时代”，不说“金子时代”。"}, {"text": "他刚买了一台金子。", "explanation": "这里应该用〈块〉。金子是块状材料，〈台〉用于机器，不能用于金子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一只金子。", "corrected_sentence": "她买了一块金子。", "error_description": "错误：“只”用于动物或成对的物件，金子是块状材料，量词应用“块”。正确说法为“她买了一块金子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的耳环是把金子做的。", "corrected_sentence": "她的耳环是用金子做的。", "error_description": "错误：“用”引出做成物品的材料，应说“用金子做”，不能用“把”替代。正确说法为“她的耳环是用金子做的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
