INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "腐殖质是土壤中有机物经微生物分解形成的暗色胶体物质，能改善土壤结构、保水保肥并提供养分。", "primary_collocate": null, "pronunciation": "fǔ zhí zhì", "ipa": "fu˨˩˦ ʈʂɨ˧˥ ʈʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "城市公寓可采用密闭式蠕虫堆肥箱（vermicomposter），利用红蚯蚓（Eisenia fetida）的肠道微生物高效降解细碎厨余，产出富含植物生长激素的“黑色金子”——腐殖质浓缩液。", "target_word": "腐殖质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "腐殖质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其本质在于将有机物质通过微生物的代谢作用，转化为富含腐殖质的稳定有机肥，从而实现食物残渣的闭环再生。", "target_word": "腐殖质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林的土壤里有很多腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "腐殖质能让土壤保持水分。", "target_word": "腐殖质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "落叶腐烂以后，会变成黑色的腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在菜地里加了腐殖质，菜长得更好。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种土壤含有丰富的腐殖质，颜色很深。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把堆好的落叶翻一翻，就能得到腐殖质。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水把山坡上的腐殖质冲走了。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层腐殖质", "label": "量词（层）"}, {"form": "腐殖质层", "label": "复合"}], "register": "书面", "sense_fingerprint": "土壤中有机物被微生物分解后形成的暗色物质，能保水保肥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐殖质", "is_correct": true, "explanation": "正确答案。腐殖质是有机物分解后形成的物质，可以浓缩成“浓缩液”。"}, {"text": "厨余", "is_correct": false, "explanation": "语义：“厨余”是待降解的原料，不是降解后的产物，与“浓缩液”不合。"}, {"text": "沼气", "is_correct": false, "explanation": "语义：“沼气”是气体，不能形成“浓缩液”。"}, {"text": "蚯蚓", "is_correct": false, "explanation": "搭配：“蚯蚓”是参与降解的生物，不能用作“浓缩液”的名称。"}], "explanations": {"腐殖质": "正确答案。腐殖质是有机物分解后形成的物质，可以浓缩成“浓缩液”。", "厨余": "语义：“厨余”是待降解的原料，不是降解后的产物，与“浓缩液”不合。", "沼气": "语义：“沼气”是气体，不能形成“浓缩液”。", "蚯蚓": "搭配：“蚯蚓”是参与降解的生物，不能用作“浓缩液”的名称。"}, "sentence_index": 0, "correct_answer": "腐殖质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把腐殖质挂在墙上，当成一幅画来欣赏。", "explanation": "这里应该用〈画〉。挂在墙上供人欣赏的是画，腐殖质是土壤中的物质，不能当画。"}, {"text": "他每天晚上都读腐殖质。", "explanation": "这里应该用〈书〉。读的对象是书、报纸等，腐殖质是土壤中的物质，不能阅读。"}, {"text": "他每天都吃腐殖质。", "explanation": "腐殖质是土壤中的物质，不能作食物，“吃”的搭配不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐殖质", "is_correct": true, "explanation": "正确答案。腐殖质是土壤肥力的来源，加入后菜能长得更好。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是肥料，加入菜地不能使菜长得更好。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能使菜长得更好，与句意不合。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水不是肥料，对菜的生长没有作用，与句意不合。"}], "explanations": {"腐殖质": "正确答案。腐殖质是土壤肥力的来源，加入后菜能长得更好。", "汽油": "语义：汽油是燃料，不是肥料，加入菜地不能使菜长得更好。", "垃圾": "语义：垃圾不能使菜长得更好，与句意不合。", "香水": "语义：香水不是肥料，对菜的生长没有作用，与句意不合。"}, "sentence_index": 6, "correct_answer": "腐殖质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些腐殖质很快就会发芽。", "explanation": "这里应该用〈种子〉。腐殖质是物质，不会发芽，发芽只用于种子。"}, {"text": "腐殖质在土里扎了根。", "explanation": "这里应该用〈树苗〉。腐殖质是物质，不会扎根，“扎根”只用于植物。"}, {"text": "腐殖质在土里爬来爬去。", "explanation": "这里应该用〈蚯蚓〉。腐殖质是物质，不能爬，“爬”只用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "园丁往花盆里加了一条腐殖质。", "corrected_sentence": "园丁往花盆里加了一袋腐殖质。", "error_description": "错误形式“一条腐殖质”，正确形式“一袋腐殖质”。“条”用于细长的物体，腐殖质应用“袋”“层”“堆”等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民在地里翻了着一层腐殖质。", "corrected_sentence": "农民在地里翻着一层腐殖质。", "error_description": "错误：“了”与“着”不能同时用在同一动词后。表示持续状态只用“着”，应为“翻着一层腐殖质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
