INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "将物质中的水分去掉或减少后得到的浓度较高的液体形态。", "primary_collocate": null, "pronunciation": "nóng suō yè", "ipa": "noŋ˧˥ suɔ˥ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "厂家把橙汁熬浓，做成了浓缩液。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶果汁浓缩液要加水喝。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把牛奶里的水去掉，做成浓缩液。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓缩液的味道比普通的果汁浓。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种浓缩液要稀释后使用。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在汤里加了一勺浓缩液。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂每天生产两吨浓缩液。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓缩液放进冰箱可以保存很久。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把浓缩液和水按一比十混合。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这管浓缩液太浓了，先少用一点。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶浓缩液", "label": "量词"}, {"form": "一管浓缩液", "label": "量词"}], "register": "中性", "sense_fingerprint": "去掉或减少水分后得到的高浓度液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浓缩液", "is_correct": true, "explanation": "正确：把橙汁熬浓后得到的正是浓缩液。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不能通过把橙汁熬浓得到。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是电器部件，不是由橙汁加工出来的。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是把橙汁熬浓后做成的。"}], "explanations": {"浓缩液": "正确：把橙汁熬浓后得到的正是浓缩液。", "氧气": "语义：氧气是气体，不能通过把橙汁熬浓得到。", "电池": "语义：电池是电器部件，不是由橙汁加工出来的。", "石头": "语义：石头不是把橙汁熬浓后做成的。"}, "sentence_index": 0, "correct_answer": "浓缩液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶买了一颗浓缩液。", "explanation": "这里应该用〈瓶〉。〈颗〉用于粒状或圆形的小东西，浓缩液是液体，应用〈瓶〉或〈管〉。"}, {"text": "他买了一块浓缩液。", "explanation": "这里应该用〈瓶〉。浓缩液是液体，量词用〈瓶〉或〈管〉，不用〈块〉。"}, {"text": "他在桌子上放了一朵浓缩液。", "explanation": "这里应该用〈瓶〉。〈朵〉用于花、云等，浓缩液是液体，应用〈瓶〉或〈管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浓缩液", "is_correct": true, "explanation": "正确：工厂可以每天生产以吨计的浓缩液。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“吨”是计量质量的量词，“时间”不能用吨计量，也不能被生产。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是工厂生产的产品。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情，不能由工厂批量生产。"}], "explanations": {"浓缩液": "正确：工厂可以每天生产以吨计的浓缩液。", "时间": "搭配：“吨”是计量质量的量词，“时间”不能用吨计量，也不能被生产。", "名字": "语义：名字不是工厂生产的产品。", "微笑": "语义：微笑是表情，不能由工厂批量生产。"}, "sentence_index": 6, "correct_answer": "浓缩液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈买了一台浓缩液。", "explanation": "这里应该用〈瓶〉。〈台〉用于机器，浓缩液是液体，应用〈瓶〉或〈管〉计量。"}, {"text": "爸爸在厨房里放了一张浓缩液。", "explanation": "这里应该用〈瓶〉。〈张〉用于纸张、桌子等平面的东西，浓缩液是液体，应用〈瓶〉或〈管〉。"}, {"text": "他把一座浓缩液倒进了杯子里。", "explanation": "这里应该用〈瓶〉。〈座〉用于山、楼、桥等大型固定物，浓缩液是液体，应用〈瓶〉或〈管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一块浓缩液。", "corrected_sentence": "妈妈买了一瓶浓缩液。", "error_description": "错误：浓缩液是液体，量词应用“瓶”（或“管”），“块”用于块状物。正确说法为“妈妈买了一瓶浓缩液”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一浓缩液和水混合了。", "corrected_sentence": "他把一瓶浓缩液和水混合了。", "error_description": "错误：浓缩液是液体，量词要用“瓶”或“管”，不能省略量词直接说“一浓缩液”。正确说法为“他把一瓶浓缩液和水混合了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "「失去」与「拥有」相反，指不再拥有某物。"}, {"text": "思考", "is_correct": false, "explanation": "「思考」是心理活动，与「拥有」没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行」指出外游览，与「拥有」没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "「跳舞」指身体动作，与「拥有」没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "「失去」与「拥有」相反，指不再拥有某物。", "思考": "「思考」是心理活动，与「拥有」没有反义关系。", "旅行": "「旅行」指出外游览，与「拥有」没有反义关系。", "跳舞": "「跳舞」指身体动作，与「拥有」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "「失去」与「拥有」相反，指不再拥有某物。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」是体育运动，与「拥有」没有反义关系。"}, {"text": "咳嗽", "is_correct": false, "explanation": "「咳嗽」指身体的症状，与「拥有」没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "「画画」指绘画活动，与「拥有」没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "「失去」与「拥有」相反，指不再拥有某物。", "游泳": "「游泳」是体育运动，与「拥有」没有反义关系。", "咳嗽": "「咳嗽」指身体的症状，与「拥有」没有反义关系。", "画画": "「画画」指绘画活动，与「拥有」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "领有，具有。", "primary_collocate": null, "pronunciation": "yōng yǒu", "ipa": "yʊŋ˥ iou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家拥有丰富的资源。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有一个幸福的家庭。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拥有三家公司。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校拥有很好的老师。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市拥有一千多年的历史。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人拥有很多机会。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拥有过一辆红色的汽车。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司拥有自己的工厂。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有一双漂亮的眼睛。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们拥有着同样的梦想。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥有了", "label": "体标"}, {"form": "拥有着", "label": "体标"}, {"form": "拥有过", "label": "体标"}], "register": "中性", "sense_fingerprint": "领有、具有（资源、财富、条件等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拥有", "is_correct": true, "explanation": "拥有（yōng yǒu）：领有、具有，即本词条的读音与意思。"}, {"text": "应有", "is_correct": false, "explanation": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」，不是领有。"}, {"text": "公有", "is_correct": false, "explanation": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有、归国家或集体所有。"}, {"text": "空有", "is_correct": false, "explanation": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}], "explanations": {"拥有": "拥有（yōng yǒu）：领有、具有，即本词条的读音与意思。", "应有": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」，不是领有。", "公有": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有、归国家或集体所有。", "空有": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}, "sentence_index": null, "correct_answer": "拥有"}, "level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「拥有」表示领有，「丰富的资源」可以被国家领有，句子通顺。"}, {"text": "生产", "is_correct": false, "explanation": "语义：资源是天然存在的，不是被生产出来的，不能说「生产丰富的资源」。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：「缺乏」表示没有，与后面的「丰富」相矛盾。"}, {"text": "打造", "is_correct": false, "explanation": "搭配：「打造」多接品牌、平台等，不能说「打造丰富的资源」。"}], "explanations": {"拥有": "「拥有」表示领有，「丰富的资源」可以被国家领有，句子通顺。", "生产": "语义：资源是天然存在的，不是被生产出来的，不能说「生产丰富的资源」。", "缺乏": "语义：「缺乏」表示没有，与后面的「丰富」相矛盾。", "打造": "搭配：「打造」多接品牌、平台等，不能说「打造丰富的资源」。"}, "sentence_index": 0, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天拥有了一场考试。", "explanation": "这里应该用〈参加〉。考试是活动，「拥有」表示领有，不能说「拥有一场考试」，应说「参加考试」。"}, {"text": "这里拥有了一件大事。", "explanation": "这里应该用〈发生〉。事件是发生的，「拥有」表示领有，不能说「拥有一件大事」，应说「发生了一件大事」。"}, {"text": "市政府拥有了一场音乐会。", "explanation": "这里应该用〈举行〉。音乐会是活动，「拥有」表示领有，不能说「拥有一场音乐会」，应说「举行一场音乐会」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「拥有过」表示曾经领有，「一辆红色的汽车」可以被领有，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能接汽车作宾语，「吃过一辆红色的汽车」不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能接汽车作宾语，「唱过一辆红色的汽车」不成立。"}, {"text": "具备", "is_correct": false, "explanation": "搭配：「具备」多用于能力、条件等抽象事物，不说「具备一辆汽车」。"}], "explanations": {"拥有": "「拥有过」表示曾经领有，「一辆红色的汽车」可以被领有，句子通顺。", "吃": "搭配：「吃」不能接汽车作宾语，「吃过一辆红色的汽车」不成立。", "唱": "搭配：「唱」不能接汽车作宾语，「唱过一辆红色的汽车」不成立。", "具备": "搭配：「具备」多用于能力、条件等抽象事物，不说「具备一辆汽车」。"}, "sentence_index": 6, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民拥有这项政策。", "explanation": "这里应该用〈拥护〉。拥有表示领有，对政策表示支持要用「拥护」。"}, {"text": "他们拥有了激烈的讨论。", "explanation": "这里应该用〈进行〉。讨论是一种活动，不能被领有，应说「进行激烈的讨论」。"}, {"text": "学校拥有了一场精彩的比赛。", "explanation": "这里应该用〈举办〉。比赛是活动，「拥有」只用于可以被领有的事物，应说「举办一场精彩的比赛」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学很拥有一座图书馆。", "corrected_sentence": "这所大学拥有一座图书馆。", "error_description": "错误在于「拥有」前多加了程度副词「很」。「很」只能修饰形容词或心理动词，不能直接修饰动词「拥有」，正确说法是「这所大学拥有一座图书馆」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛屿拥有一只美丽的海滩。", "corrected_sentence": "这座岛屿拥有一个美丽的海滩。", "error_description": "错误在于量词。「海滩」是场所，应用量词「个」，「只」多用于动物、船只等，不能修饰「海滩」。正确说法是「这座岛屿拥有一个美丽的海滩」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
