INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11539, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示适合、恰当；也用于表示应该（多用于否定或疑问）。", "primary_collocate": null, "pronunciation": "yí", "ipa": "i˧˥", "syllable_count": 1, "sentences": [{"text": "堆肥容器的选择需因地制宜。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "有院子的人宜建一个分层式堆肥仓。", "target_word": "宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，老人不宜出门。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚吃完饭，不宜马上跑步。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花宜种在阳光充足的地方。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天天亮得早，宜早起锻炼。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人不宜吃太咸的东西。", "target_word": "宜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事宜早不宜迟。", "target_word": "宜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉前不宜喝浓茶，会影响睡眠。", "target_word": "宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚了，还是不宜给他打电话吗？", "target_word": "宜", "complexity_tier": "T3", "furigana": "zhè me wǎn le, hái shi bù yí gěi tā dǎ diàn huà ma?", "sentence_source": "generated"}], "morphological_forms": [{"form": "不宜", "label": "否定式"}, {"form": "适宜", "label": "复合词"}, {"form": "合宜", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "宜：情态动词，表示适合、应该做某事，多用于否定「不宜」，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宜", "is_correct": true, "explanation": "宜（yí）：适合、恰当，或应该做，即本词条的读音与意思。"}, {"text": "一", "is_correct": false, "explanation": "一（yī，第一声）与宜（yí，第二声）声调不同，意思是数字「一」。"}, {"text": "以", "is_correct": false, "explanation": "以（yǐ，第三声）与宜（yí，第二声）声调不同，意思是「用」或「把……作为」。"}, {"text": "离", "is_correct": false, "explanation": "离（lí）与宜（yí）声母不同：l 与 y，意思是离开、距离。"}, {"text": "泥", "is_correct": false, "explanation": "泥（ní）与宜（yí）声母不同：n 与 y，意思是泥土。"}], "explanations": {"宜": "宜（yí）：适合、恰当，或应该做，即本词条的读音与意思。", "一": "一（yī，第一声）与宜（yí，第二声）声调不同，意思是数字「一」。", "以": "以（yǐ，第三声）与宜（yí，第二声）声调不同，意思是「用」或「把……作为」。", "离": "离（lí）与宜（yí）声母不同：l 与 y，意思是离开、距离。", "泥": "泥（ní）与宜（yí）声母不同：n 与 y，意思是泥土。"}, "sentence_index": null, "correct_answer": "宜"}, "level_3": {"options": [{"text": "宜", "is_correct": true, "explanation": "「因地制宜」是固定成语，「宜」是正确的成语用字。"}, {"text": "应", "is_correct": false, "explanation": "搭配：「因地制」后固定接「宜」，不能说「因地制应」。"}, {"text": "该", "is_correct": false, "explanation": "搭配：「因地制」后固定接「宜」，「因地制该」不成立。"}, {"text": "可", "is_correct": false, "explanation": "搭配：“因地制”后固定接“宜”，“因地制可”不成立。"}], "explanations": {"宜": "「因地制宜」是固定成语，「宜」是正确的成语用字。", "应": "搭配：「因地制」后固定接「宜」，不能说「因地制应」。", "该": "搭配：「因地制」后固定接「宜」，「因地制该」不成立。", "可": "搭配：“因地制”后固定接“宜”，“因地制可”不成立。"}, "sentence_index": 0, "correct_answer": "宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天宜下雨。", "explanation": "这里应该用〈可能〉。「宜」表示适合或应该，推测会不会下雨要用「可能」，不能用「宜」。"}, {"text": "天宜黑了。", "explanation": "这里应该用〈快要〉。“宜”表示适合或应该，表示即将发生要用“快要”，不能用“宜”。"}, {"text": "他宜生病。", "explanation": "这里应该用〈容易〉。“宜”表示适合或应该，说某人容易生病要用“容易”，不能用“宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宜", "is_correct": true, "explanation": "宜（yí）：适合、恰当，或应该做，即本词条的读音与意思。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī，第一声）与宜（yí，第二声）声调不同，意思是衣服。"}, {"text": "已", "is_correct": false, "explanation": "已（yǐ，第三声）与宜（yí，第二声）声调不同，意思是「已经」。"}, {"text": "鼻", "is_correct": false, "explanation": "鼻（bí）与宜（yí）声母不同：b 与 y，意思是鼻子。"}, {"text": "医", "is_correct": false, "explanation": "医（yī，第一声）与宜（yí，第二声）声调不同，意思是医生、医治。"}], "explanations": {"宜": "宜（yí）：适合、恰当，或应该做，即本词条的读音与意思。", "衣": "衣（yī，第一声）与宜（yí，第二声）声调不同，意思是衣服。", "已": "已（yǐ，第三声）与宜（yí，第二声）声调不同，意思是「已经」。", "鼻": "鼻（bí）与宜（yí）声母不同：b 与 y，意思是鼻子。", "医": "医（yī，第一声）与宜（yí，第二声）声调不同，意思是医生、医治。"}, "sentence_index": null, "correct_answer": "宜"}, "level_3": {"options": [{"text": "宜", "is_correct": true, "explanation": "「不宜吃」表示不适合吃，符合医嘱的意思，句子通顺。"}, {"text": "乐", "is_correct": false, "explanation": "语义：“不乐吃”表示心情不快地吃，与医嘱“不适合吃”的意思不同。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“不曾吃”表示从未吃过，陈述的是事实，与医嘱“不适合吃”的意思不同。"}, {"text": "易", "is_correct": false, "explanation": "语义：「不易」表示不容易做到，与「不适合吃」的意思不同。"}], "explanations": {"宜": "「不宜吃」表示不适合吃，符合医嘱的意思，句子通顺。", "乐": "语义：“不乐吃”表示心情不快地吃，与医嘱“不适合吃”的意思不同。", "曾": "语义：“不曾吃”表示从未吃过，陈述的是事实，与医嘱“不适合吃”的意思不同。", "易": "语义：「不易」表示不容易做到，与「不适合吃」的意思不同。"}, "sentence_index": 6, "correct_answer": "宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生宜看见远处的山。", "explanation": "这里应该用〈能〉。「宜」表示适合或应该，表示能不能看见要用「能」，不能用「宜」。"}, {"text": "老人宜感冒。", "explanation": "这里应该用〈容易〉。「宜」表示适合或应该，说某人容易生病要用「容易」，不能用「宜」。"}, {"text": "这台电脑宜坏。", "explanation": "这里应该用〈容易〉。「宜」表示适合或应该，说电脑容易出故障要用「容易」，不能用「宜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气很宜去爬山。", "corrected_sentence": "今天天气不宜去爬山。", "error_description": "错误在于「宜」前多加了程度副词「很」。「宜」是情态动词，否定时用「不宜」，不能用「很」修饰。正确说法是「今天天气不宜去爬山」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个时候宜不出门。", "corrected_sentence": "这个时候不宜出门。", "error_description": "错误在于语序。固定的否定形式是「不宜」，「宜不」的语序不成立。正确说法是「这个时候不宜出门」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
