INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "储存粮食等物资的地方或设施。", "primary_collocate": null, "pronunciation": "cāng", "ipa": "tsʰɑŋ˥", "syllable_count": 1, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "仓", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "仓里堆满了刚收的稻谷。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天，农民把新米装进仓里。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只老鼠钻进仓里偷吃粮食。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个仓很大，能放五万斤小麦。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开仓门，里面全是玉米。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在仓前排队，等着领粮食。", "target_word": "仓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，大家赶紧把粮食搬进仓。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓里很干燥，粮食不会发霉。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里新盖了一个仓，用来存玉米。", "target_word": "仓", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮仓", "label": "复合词"}, {"form": "仓库", "label": "复合词"}, {"form": "仓储", "label": "复合词"}, {"form": "倉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "仓：名词，储存粮食等物资的场所或设施，如粮仓、仓库", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仓", "is_correct": true, "explanation": "仓（cāng）：储存粮食等物资的地方或设施，即本词条的读音与意思。"}, {"text": "藏", "is_correct": false, "explanation": "藏（cáng，第二声）与仓（cāng，第一声）声调不同，意思是隐藏。"}, {"text": "餐", "is_correct": false, "explanation": "餐（cān）与仓（cāng）韵母不同：an 与 ang，意思是饭食。"}, {"text": "脏", "is_correct": false, "explanation": "脏（zāng）与仓（cāng）声母不同：z 与 c，意思是不干净。"}, {"text": "昌", "is_correct": false, "explanation": "昌（chāng）与仓（cāng）声母不同：ch 与 c，意思是兴盛。"}], "explanations": {"仓": "仓（cāng）：储存粮食等物资的地方或设施，即本词条的读音与意思。", "藏": "藏（cáng，第二声）与仓（cāng，第一声）声调不同，意思是隐藏。", "餐": "餐（cān）与仓（cāng）韵母不同：an 与 ang，意思是饭食。", "脏": "脏（zāng）与仓（cāng）声母不同：z 与 c，意思是不干净。", "昌": "昌（chāng）与仓（cāng）声母不同：ch 与 c，意思是兴盛。"}, "sentence_index": null, "correct_answer": "仓"}, "level_3": {"options": [{"text": "仓", "is_correct": true, "explanation": "「堆肥仓」指用来分层堆放、发酵堆肥的设施，符合上下文中的分层、连续处理。"}, {"text": "船", "is_correct": false, "explanation": "语义：堆肥是分解有机物的设施，船与堆肥无关，「堆肥船」讲不通。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不是堆肥的容器，「堆肥鞋」讲不通。"}, {"text": "花", "is_correct": false, "explanation": "搭配：「堆肥」后接的是设施名词，「花」不能作为堆肥的设施。"}], "explanations": {"仓": "「堆肥仓」指用来分层堆放、发酵堆肥的设施，符合上下文中的分层、连续处理。", "船": "语义：堆肥是分解有机物的设施，船与堆肥无关，「堆肥船」讲不通。", "鞋": "语义：鞋不是堆肥的容器，「堆肥鞋」讲不通。", "花": "搭配：「堆肥」后接的是设施名词，「花」不能作为堆肥的设施。"}, "sentence_index": 0, "correct_answer": "仓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去仓买衣服。", "explanation": "这里应该用〈商店〉。仓是储存物资的场所，不做买卖，买衣服应去商店。"}, {"text": "农民盖了一条粮仓。", "explanation": "这里应该用〈座〉。仓是建筑，量词应用「座」，「条」用于细长的东西。"}, {"text": "仓里坐满了学生。", "explanation": "这里应该用〈教室〉。「仓」是储存粮食等物资的场所，学生应坐在「教室」里，不能坐在粮仓里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仓", "is_correct": true, "explanation": "「在仓前排队，等着领粮食」指在粮仓前排队领粮，句子通顺。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是可以排队领取粮食的场所，「在书前排队领粮食」讲不通。"}, {"text": "树", "is_correct": false, "explanation": "搭配：「在……前排队」要接场所或设施，「树」不能作为排队领粮的地点。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不是排队领粮的地点，「在灯前排队领粮食」讲不通。"}], "explanations": {"仓": "「在仓前排队，等着领粮食」指在粮仓前排队领粮，句子通顺。", "书": "语义：书不是可以排队领取粮食的场所，「在书前排队领粮食」讲不通。", "树": "搭配：「在……前排队」要接场所或设施，「树」不能作为排队领粮的地点。", "灯": "语义：灯不是排队领粮的地点，「在灯前排队领粮食」讲不通。"}, "sentence_index": 6, "correct_answer": "仓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去仓取钱。", "explanation": "这里应该用〈银行〉。仓存放物资，不用来存取钱款，取钱应去银行。"}, {"text": "我们在仓里吃晚饭。", "explanation": "这里应该用〈餐厅〉。「仓」指储存粮食等物资的场所，不是吃饭的地方，吃饭应去〈餐厅〉。"}, {"text": "他在仓里给病人看病。", "explanation": "这里应该用〈医院〉。「仓」指储存物资的场所，不是看病的地方，看病应去〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条仓很大。", "corrected_sentence": "那座仓很大。", "error_description": "错误在于量词。仓是建筑，应用量词「座」，「条」用于细长的东西。正确说法是「那座仓很大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把仓很大，能放很多粮食。", "corrected_sentence": "这个仓很大，能放很多粮食。", "error_description": "错误在于量词。「把」用于有柄的物品，仓是建筑，应用量词「个」或「座」。正确说法是「这个仓很大，能放很多粮食」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
