INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使分开，不让接触或联系。", "primary_collocate": null, "pronunciation": "gé lí", "ipa": "kɤ˧˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "隔离", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生让他在家隔离七天。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院把病人隔离在单独的房间里。", "target_word": "隔离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室把病毒样本隔离保存。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士把发烧的病人隔离起来。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们需要隔离十四天才能出门。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养鸡场要把生病的鸡隔离。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校隔离了生病的学生。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感冒的孩子要和其他人隔离。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪封路，山村与外界隔离了。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔离了", "label": "完成体"}, {"form": "隔离过", "label": "经历体"}, {"form": "自我隔离", "label": "复合词"}, {"form": "隔离区", "label": "复合词"}, {"form": "隔离病房", "label": "复合词"}], "register": "中性", "sense_fingerprint": "隔离：动词，使人或事物分开，不让接触或联系，如隔离病人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隔离", "is_correct": true, "explanation": "正确：物理隔离指用实体手段把各阶段分开，与“分层式”“不同发酵阶段”相合。"}, {"text": "混合", "is_correct": false, "explanation": "语义：混合会打乱各发酵阶段，与“分层”和“连续处理”相悖。"}, {"text": "压缩", "is_correct": false, "explanation": "搭配：“物理”后接“压缩”指改变体积，与“实现阶段划分”搭配不当。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：清洗与分层发酵、划分阶段无关，句子意思说不通。"}], "explanations": {"隔离": "正确：物理隔离指用实体手段把各阶段分开，与“分层式”“不同发酵阶段”相合。", "混合": "语义：混合会打乱各发酵阶段，与“分层”和“连续处理”相悖。", "压缩": "搭配：“物理”后接“压缩”指改变体积，与“实现阶段划分”搭配不当。", "清洗": "语义：清洗与分层发酵、划分阶段无关，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "隔离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他隔离了家乡去北京工作。", "explanation": "这里应该用〈离开〉。隔离是为防止接触而强行分开，不用于一个人自愿离开家乡。"}, {"text": "他把蛋糕隔离成八块。", "explanation": "这里应该用〈分割〉。隔离强调不让接触，不表示切成几块。"}, {"text": "妈妈隔离我们一起玩。", "explanation": "这里应该用〈陪伴〉。隔离是把人分开，与“一起玩”的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隔离", "is_correct": true, "explanation": "正确：生病的鸡要与其他鸡分开，养鸡场要把它隔离。"}, {"text": "放飞", "is_correct": false, "explanation": "语义：放飞是让动物飞走，与“生病的鸡”需要处理的情境相反。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象一般是人，不说“表扬鸡”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的宾语是场地等，不说“打扫鸡”。"}], "explanations": {"隔离": "正确：生病的鸡要与其他鸡分开，养鸡场要把它隔离。", "放飞": "语义：放飞是让动物飞走，与“生病的鸡”需要处理的情境相反。", "表扬": "搭配：“表扬”的对象一般是人，不说“表扬鸡”。", "打扫": "搭配：“打扫”的宾语是场地等，不说“打扫鸡”。"}, "sentence_index": 6, "correct_answer": "隔离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一座桥把两个村子隔离起来。", "explanation": "这里应该用〈连接〉。隔离是使分开、不让接触，与桥的作用相反。"}, {"text": "他把牛奶隔离喝了。", "explanation": "这里应该用〈喝〉。隔离是使分开、不让接触，不能用来形容喝东西。"}, {"text": "两国领导人进行了隔离。", "explanation": "这里应该用〈沟通〉。隔离是使分开，不用于两国之间的交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士把孩子隔离另一间屋子里。", "corrected_sentence": "护士把孩子隔离在另一间屋子里。", "error_description": "错误：“隔离另一间屋子里”缺少介词。正确：“隔离在另一间屋子里”。“把”字句中，“隔离”后需用介词引出处所，常用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些病人还没隔离了。", "corrected_sentence": "这些病人还没隔离。", "error_description": "错误：“还没隔离了”。正确：“还没隔离”。“没”表示尚未发生的动作，动词后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“连续”无关：“粗糙”形容表面不光滑，不涉及是否中断。"}, {"text": "轻松", "is_correct": false, "explanation": "与“连续”无关：“轻松”形容不费力或心情舒畅，不是“连续”的反义。"}, {"text": "清楚", "is_correct": false, "explanation": "与“连续”无关：“清楚”形容清晰明白，不表示有无中断。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "粗糙": "与“连续”无关：“粗糙”形容表面不光滑，不涉及是否中断。", "轻松": "与“连续”无关：“轻松”形容不费力或心情舒畅，不是“连续”的反义。", "清楚": "与“连续”无关：“清楚”形容清晰明白，不表示有无中断。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "锋利", "is_correct": false, "explanation": "与“连续”无关：“锋利”形容刀刃等尖锐，不涉及是否中断。"}, {"text": "平淡", "is_correct": false, "explanation": "与“连续”无关：“平淡”形容没有起伏或特色，不是“连续”的反义。"}, {"text": "清脆", "is_correct": false, "explanation": "与“连续”无关：“清脆”形容声音清亮悦耳，不表示有无中断。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "锋利": "与“连续”无关：“锋利”形容刀刃等尖锐，不涉及是否中断。", "平淡": "与“连续”无关：“平淡”形容没有起伏或特色，不是“连续”的反义。", "清脆": "与“连续”无关：“清脆”形容声音清亮悦耳，不表示有无中断。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物一个接一个地连接起来，没有中断。", "primary_collocate": null, "pronunciation": "lián xù", "ipa": "ljɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "连续", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这几天连续下雨，路上很湿。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连续三年都是班里第一名。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司连续五个月卖得很好。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我连续工作了八个小时，很累。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个连续的过程，不能停。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "连续三天的大雪，让城市很安静。", "target_word": "连续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她连续两次考试都得了满分。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，他连续进了三个球。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "连续几晚没睡好，他今天没有精神。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "连续性", "label": "复合"}, {"form": "连续剧", "label": "复合"}, {"form": "連續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物一个接一个、中间没有中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续处理”指各阶段依次、不间断地进行，与分层隔离、分阶段投入的做法一致。"}, {"text": "瞬时", "is_correct": false, "explanation": "语义：“瞬时”指极短时间内完成，与需要持续数周的发酵阶段相冲突。"}, {"text": "偶发", "is_correct": false, "explanation": "搭配：“偶发”多修饰事件，不能修饰“处理”。"}, {"text": "突发", "is_correct": false, "explanation": "搭配：“突发”修饰事件或状况，“突发处理”不通，也与有计划的分阶段处理矛盾。"}], "explanations": {"连续": "“连续处理”指各阶段依次、不间断地进行，与分层隔离、分阶段投入的做法一致。", "瞬时": "语义：“瞬时”指极短时间内完成，与需要持续数周的发酵阶段相冲突。", "偶发": "搭配：“偶发”多修饰事件，不能修饰“处理”。", "突发": "搭配：“突发”修饰事件或状况，“突发处理”不通，也与有计划的分阶段处理矛盾。"}, "sentence_index": 0, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥把两岸连续起来了。", "explanation": "这里应该用〈连接〉。连续只表示一个接一个、中间不中断，不能表示把两个地方接在一起。"}, {"text": "这两段管子连续在一起，水才能流过去。", "explanation": "这里应该用〈相连〉。连续表示接连不断、中间不中断，不能表示两段管子接在一起；物体相接要用〈相连〉。"}, {"text": "两场比赛之间连续了一个月，大家都在等。", "explanation": "这里应该用〈间隔〉。连续表示中间不停顿，两场比赛之间隔了一个月应说间隔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续三天”修饰“大雪”，说明大雪一连下了三天，中间没有间断。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”指分散、稀少，不能描述一连三天的大雪。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指时间很短，与“三天”的时长相矛盾。"}, {"text": "猛烈", "is_correct": false, "explanation": "搭配：“猛烈”修饰强度，不能修饰表示时段的“三天”。"}], "explanations": {"连续": "“连续三天”修饰“大雪”，说明大雪一连下了三天，中间没有间断。", "零星": "语义：“零星”指分散、稀少，不能描述一连三天的大雪。", "短暂": "语义：“短暂”指时间很短，与“三天”的时长相矛盾。", "猛烈": "搭配：“猛烈”修饰强度，不能修饰表示时段的“三天”。"}, "sentence_index": 6, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他连续去了一次北京，印象很深。", "explanation": "这里应该用〈偶尔〉。连续要求同一动作一次接一次地反复出现，只去一次不能说连续；偶然去一次要用〈偶尔〉。"}, {"text": "她的心情很连续，大家都看得出来。", "explanation": "这里应该用〈稳定〉。连续表示一个接一个、中间不中断，不能用来形容心情的平稳；心情平稳要用〈稳定〉。"}, {"text": "这两件事之间隔了三年，却连续得很，大家都很关心。", "explanation": "这里应该用〈相隔〉。连续表示中间不中断，两件事隔了三年就不能说连续；说明时间上的间隔应用〈相隔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这周连续了下雨，我们没法出门。", "corrected_sentence": "这周连续下雨，我们没法出门。", "error_description": "体标错误：“连续”作状语修饰“下雨”，不能直接加体标“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场连续三个小时地大雨，让路面都积了水。", "corrected_sentence": "这场连续三个小时的大雨，让路面都积了水。", "error_description": "错误在“的”与“地”：“连续三个小时”修饰名词“大雨”，应用“的”；写成“地”是把修饰语当成了状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上层", "is_correct": true, "explanation": "上层与底层相对，指社会中地位较高的阶层。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家指从事写作的人，与底层没有反义关系。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是售书的场所，与底层没有反义关系。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学体裁，与底层没有反义关系。"}], "correct_answer": "上层", "explanations": {"上层": "上层与底层相对，指社会中地位较高的阶层。", "作家": "语义：作家指从事写作的人，与底层没有反义关系。", "书店": "语义：书店是售书的场所，与底层没有反义关系。", "小说": "语义：小说是文学体裁，与底层没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上层", "is_correct": true, "explanation": "上层与底层相对，指社会中地位较高的阶层。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是遮挡窗户的织物，与底层没有反义关系。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用的器物，与底层没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，与底层没有反义关系。"}], "correct_answer": "上层", "explanations": {"上层": "上层与底层相对，指社会中地位较高的阶层。", "窗帘": "语义：窗帘是遮挡窗户的织物，与底层没有反义关系。", "乐器": "语义：乐器是演奏用的器物，与底层没有反义关系。", "天气": "语义：天气指气象状况，与底层没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指社会中最低的层次，常指贫困或地位低下的群体。", "primary_collocate": null, "pronunciation": "dǐ céng", "ipa": "ti˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这项政策的初衷，是让社会底层群体也能分享经济增长的成果。", "target_word": "底层", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他出生在社会底层，家里很穷。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层的工人每天工作十个小时。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是底层人民的生活。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从底层一步一步做到了经理。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层员工的工资一直不高。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很了解底层老百姓的苦。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司里，底层的人说话没人听。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一辈子生活在社会底层。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家常常写底层小人物的故事。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "底層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社会中地位最低、生活贫困的阶层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层：dǐ céng，指社会中地位最低、生活贫困的群体或阶层。"}, {"text": "地层", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。"}, {"text": "低层", "is_correct": false, "explanation": "dī（第一声）与 dǐ（第三声）声调不同，意思是较低的层次。"}, {"text": "里层", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}], "explanations": {"底层": "底层：dǐ céng，指社会中地位最低、生活贫困的群体或阶层。", "地层": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。", "低层": "dī（第一声）与 dǐ（第三声）声调不同，意思是较低的层次。", "里层": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}, "sentence_index": null, "correct_answer": "底层"}, "level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指社会中地位低、生活贫困的群体，与“社会……群体”的语境相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的场所，不能指社会中的群体。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能指社会中的群体。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不指人群，不能修饰“群体”。"}], "explanations": {"底层": "底层指社会中地位低、生活贫困的群体，与“社会……群体”的语境相符。", "花园": "语义：花园是种植花草的场所，不能指社会中的群体。", "月亮": "语义：月亮是天体，不能指社会中的群体。", "天气": "搭配：“天气”不指人群，不能修饰“群体”。"}, "sentence_index": 0, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是社会的底层，很有地位。", "explanation": "这里应该用〈精英〉。精英指地位高的人；底层指地位低下的群体，与“很有地位”矛盾。"}, {"text": "这位底层富豪每年捐款很多。", "explanation": "这里应该用〈有钱人〉。有钱人指财富多的人；底层指地位低下、生活贫困的群体，与能年年大额捐款的身份矛盾。"}, {"text": "这家公司的底层制定了新的规定。", "explanation": "这里应该用〈管理层〉。管理层负责制定规定；底层指地位低的群体，不负责制定规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指社会中地位低的群体，与“老百姓的苦”相合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，不能修饰“老百姓”指人群。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节指时间段，不指人群，句意说不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“老百姓”前的修饰语要指人群或社会阶层，“闹钟”不能修饰“老百姓”。"}], "explanations": {"底层": "底层指社会中地位低的群体，与“老百姓的苦”相合。", "海洋": "语义：海洋是地理事物，不能修饰“老百姓”指人群。", "季节": "语义：季节指时间段，不指人群，句意说不通。", "闹钟": "搭配：“老百姓”前的修饰语要指人群或社会阶层，“闹钟”不能修饰“老百姓”。"}, "sentence_index": 6, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议由底层主持。", "explanation": "这里应该用〈校长〉。校长负责主持会议；底层指地位低的群体，不能主持会议。"}, {"text": "他是公司的底层，负责制定战略。", "explanation": "这里应该用〈高层〉。高层指地位高、负责决策的人；底层指地位低的群体，不能指负责决策的人。"}, {"text": "社会的底层价值是公平。", "explanation": "这里应该用〈核心〉。核心指事物最重要的部分，可说“核心价值”；底层指地位低的群体，不能修饰“价值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直生活在社会底层着。", "corrected_sentence": "他一直生活在社会底层。", "error_description": "助词位置错：“着”要紧跟动词，不能放在名词“底层”后面，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经过帮助底层的人。", "corrected_sentence": "他曾经帮助底层的人。", "error_description": "“过”位置错：“过”只能紧跟动词，“曾经过帮助”不成立，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
