INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某一特定的地域范围，例如一个城市里的不同部分或某个区域。", "primary_collocate": null, "pronunciation": "qū", "ipa": "tɕʰy˥", "syllable_count": 1, "sentences": [{"text": "这座城市划分出了六个区，每个都有自己的特点。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在城东的那个区。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区有很多公园。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校所在的区交通很方便。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的那个区离地铁很近。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区的房子比别的区贵。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们区的图书馆周末也开门。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区的孩子都在同一所学校上学。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有十六个区。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区晚上很安静。", "target_word": "区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地区", "label": "复合"}, {"form": "區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市中划分出来的行政或地域范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11549, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "区", "is_correct": true, "explanation": "区读 qū（第一声），指城市中划分出的地域范围。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是前往。"}, {"text": "取", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是拿取。"}, {"text": "居", "is_correct": false, "explanation": "jū 与 qū 声母不同（j 与 q），意思是居住。"}, {"text": "秋", "is_correct": false, "explanation": "qiū 比 qū 多一个 i 介音，意思是秋天。"}], "explanations": {"区": "区读 qū（第一声），指城市中划分出的地域范围。", "去": "qù（第四声）与 qū（第一声）声调不同，意思是前往。", "取": "qǔ（第三声）与 qū（第一声）声调不同，意思是拿取。", "居": "jū 与 qū 声母不同（j 与 q），意思是居住。", "秋": "qiū 比 qū 多一个 i 介音，意思是秋天。"}, "sentence_index": null, "correct_answer": "区"}, "level_3": {"options": [{"text": "区", "is_correct": true, "explanation": "“区”指城市划分出的地域单位，与“划分出六个区”的语境相符。"}, {"text": "花", "is_correct": false, "explanation": "语义：花是植物，不是城市划分出的地域单位，句意说不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是植物，不能作为城市划分出的地域单位。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书是出版物，不能与“划分出”搭配指地域。"}], "explanations": {"区": "“区”指城市划分出的地域单位，与“划分出六个区”的语境相符。", "花": "语义：花是植物，不是城市划分出的地域单位，句意说不通。", "树": "语义：树是植物，不能作为城市划分出的地域单位。", "书": "搭配：书是出版物，不能与“划分出”搭配指地域。"}, "sentence_index": 0, "correct_answer": "区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最擅长的区是数学。", "explanation": "这里的“区”被用成了学科领域的意思。区指城市中划分出的地域范围，不指擅长的学科，这里应说〈领域〉。"}, {"text": "北京是一个很大的区。", "explanation": "这里应该用〈城市〉。区指城市内划分出的一部分，不能用来指整个城市。"}, {"text": "他是我们公司的区，负责销售。", "explanation": "这里的“区”被用成了公司内部门的意思。区指地域范围，不指公司里的部门，这里应说〈部门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11549, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "区", "is_correct": true, "explanation": "区读 qū（第一声），指城市中划分出的地域范围。"}, {"text": "娶", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是娶妻。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是趣味。"}, {"text": "需", "is_correct": false, "explanation": "xū 与 qū 声母不同（x 与 q），意思是需要。"}, {"text": "出", "is_correct": false, "explanation": "chū 与 qū 声母不同（ch 与 q），意思是出去。"}], "explanations": {"区": "区读 qū（第一声），指城市中划分出的地域范围。", "娶": "qǔ（第三声）与 qū（第一声）声调不同，意思是娶妻。", "趣": "qù（第四声）与 qū（第一声）声调不同，意思是趣味。", "需": "xū 与 qū 声母不同（x 与 q），意思是需要。", "出": "chū 与 qū 声母不同（ch 与 q），意思是出去。"}, "sentence_index": null, "correct_answer": "区"}, "level_3": {"options": [{"text": "区", "is_correct": true, "explanation": "区指城市中划分出的地域，“我们区的图书馆”指所在地域的图书馆，符合语境。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭是食物，不能作为图书馆所在的范围。"}, {"text": "组", "is_correct": false, "explanation": "搭配：组指小组或班组，“我们组的图书馆”不指一个地域范围，与语境不搭。"}, {"text": "段", "is_correct": false, "explanation": "语义：段指一段路或一段时间，不指可以设立图书馆的地域。"}], "explanations": {"区": "区指城市中划分出的地域，“我们区的图书馆”指所在地域的图书馆，符合语境。", "饭": "语义：饭是食物，不能作为图书馆所在的范围。", "组": "搭配：组指小组或班组，“我们组的图书馆”不指一个地域范围，与语境不搭。", "段": "语义：段指一段路或一段时间，不指可以设立图书馆的地域。"}, "sentence_index": 6, "correct_answer": "区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个区很高，像一栋楼。", "explanation": "这里的“区”被用成了建筑物的意思。区指地域范围，不指建筑物，这里应说〈大楼〉。"}, {"text": "这个区是一位老师，每天教我们英语。", "explanation": "这里的“区”被当成了人使用。区是城市中的地域范围，不能充当人或担任职业。"}, {"text": "这个区是我们今天要学的第三课。", "explanation": "这里的“区”被用成了课本单元的意思。区指地域范围，不是课本里的划分单位，这里应说〈单元〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那把区的公园很多。", "corrected_sentence": "那个区的公园很多。", "error_description": "“那把区”中量词用错：区应搭配量词“个”，“把”用于有柄的器具，不能计量区域。正确形式为“那个区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个里区有很多公园。", "corrected_sentence": "这个区里有很多公园。", "error_description": "“里区”语序错误：方位词“里”应放在处所名词之后，应说“区里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
