INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指处于上下或前后之间的那一层或等级。", "primary_collocate": null, "pronunciation": "zhōng céng", "ipa": "ʈʂʊŋ˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "中层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在公司做中层，工作很忙。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的中层都很年轻。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中层的同事每天要开很多会。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板和中层一起讨论了新计划。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小职员升到了中层。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中层既要听老板的，也要管好下面的人。", "target_word": "中层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次公司给中层加了工资。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想当高层，只想做中层。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的中层经理下周要出差。", "target_word": "中层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中层干部", "label": "复合"}, {"form": "中層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上下之间的那一层或等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中层", "is_correct": true, "explanation": "“中层”指三层之中间的一层，与“底层”“顶层”的层次相对应。"}, {"text": "基层", "is_correct": false, "explanation": "语义：“基层”指最下面的一层，与前文“底层”同指一处，中层不能同时是最下层。"}, {"text": "表层", "is_correct": false, "explanation": "语义：“表层”指最外面的一层，与句中已有的“顶层”重复，层次也对不上。"}, {"text": "中期", "is_correct": false, "explanation": "搭配：“中期”指时间阶段，不能与“熟化过渡带”这样的空间层次搭配。"}], "explanations": {"中层": "“中层”指三层之中间的一层，与“底层”“顶层”的层次相对应。", "基层": "语义：“基层”指最下面的一层，与前文“底层”同指一处，中层不能同时是最下层。", "表层": "语义：“表层”指最外面的一层，与句中已有的“顶层”重复，层次也对不上。", "中期": "搭配：“中期”指时间阶段，不能与“熟化过渡带”这样的空间层次搭配。"}, "sentence_index": 0, "correct_answer": "中层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的中层写得很精彩，我最喜欢。", "explanation": "这里应该用〈中段〉。中层指层级，不指书的中间部分；表示作品中间的部分要用〈中段〉。"}, {"text": "工程进入中层，大家都很忙。", "explanation": "这里应该用〈中期〉。中层指层级，不表示时间阶段；表示工程进展到哪个阶段要用〈中期〉。"}, {"text": "这是一家中层企业，员工有五百人。", "explanation": "这里应该用〈中型〉。中层指层级，不用来描述企业规模；描述规模要用〈中型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中层", "is_correct": true, "explanation": "“中层”指处在中间层级的管理人员，既要向上听命，又要向下管理，与句意相符。"}, {"text": "实习生", "is_correct": false, "explanation": "语义：实习生一般不负责管理下面的人，与“管好下面的人”矛盾。"}, {"text": "股东", "is_correct": false, "explanation": "语义：股东是出资人，不是要“听老板的”的人，与句意矛盾。"}, {"text": "客户", "is_correct": false, "explanation": "语义：客户是购买产品或服务的一方，不在公司内部的上下级关系中，句意不通。"}], "explanations": {"中层": "“中层”指处在中间层级的管理人员，既要向上听命，又要向下管理，与句意相符。", "实习生": "语义：实习生一般不负责管理下面的人，与“管好下面的人”矛盾。", "股东": "语义：股东是出资人，不是要“听老板的”的人，与句意矛盾。", "客户": "语义：客户是购买产品或服务的一方，不在公司内部的上下级关系中，句意不通。"}, "sentence_index": 6, "correct_answer": "中层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在中层读书，成绩一直很好。", "explanation": "这里应该用〈中学〉。中层指层级或中间的那一层，不指学校阶段；表示初中、高中这一阶段要用〈中学〉。"}, {"text": "这家饭店的服务属于中层，客人都很满意。", "explanation": "这里应该用〈中等〉。中层指层级或中间的那一层，不用来评价服务水平；表示水平一般要用〈中等〉。"}, {"text": "这个城市的中层地区交通很方便。", "explanation": "这里应该用〈中部〉。中层指层级或中间的那一层，不指地理位置；表示地区位于中部要用〈中部〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们公司的一只中层，负责销售。", "corrected_sentence": "他是我们公司的一个中层，负责销售。", "error_description": "量词错误：“中层”指人时，量词应用“个”，“只”专用于动物等，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中层地员工每天都很忙。", "corrected_sentence": "中层的员工每天都很忙。", "error_description": "错误在“的”与“地”：“中层”修饰名词“员工”，应用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
