INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过加热或其他方式使物质成熟或达到适合使用的状态。", "primary_collocate": null, "pronunciation": "shú huà", "ipa": "ʂu˧˥ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "熟化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "堆肥要放几个月才能熟化。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种奶酪需要熟化半年。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团要熟化一会儿，才好做面包。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地要一年才能熟化。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把原料放在仓里熟化三天。", "target_word": "熟化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥熟化以后，可以拿去种花。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批有机肥还在棚里熟化，暂时不能用。", "target_word": "熟化", "complexity_tier": "T3", "furigana": "shú huà", "sentence_source": "generated"}, {"text": "新开的田地要先熟化，再种菜。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度太低，肥料熟化得很慢。", "target_word": "熟化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟化了", "label": "体标"}, {"form": "熟化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "物质经过处理变得成熟、可以使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：熟化（shú huà），指通过加热或其他方式使物质成熟或达到适合使用的状态。"}, {"text": "俗话", "is_correct": false, "explanation": "sú 与 shú 声母不同（s / sh），俗话指流传已久的通俗谚语。"}, {"text": "书画", "is_correct": false, "explanation": "shū（第一声）与 shú（第二声）声调不同，书画指书法和绘画。"}, {"text": "实话", "is_correct": false, "explanation": "shí 与 shú 韵母不同（i / u），实话指真实的话。"}, {"text": "赎回", "is_correct": false, "explanation": "第二个音节 huí（第二声）与 huà（第四声）韵母和声调都不同，赎回指用钱换回抵押的东西。"}], "explanations": {"熟化": "正确：熟化（shú huà），指通过加热或其他方式使物质成熟或达到适合使用的状态。", "俗话": "sú 与 shú 声母不同（s / sh），俗话指流传已久的通俗谚语。", "书画": "shū（第一声）与 shú（第二声）声调不同，书画指书法和绘画。", "实话": "shí 与 shú 韵母不同（i / u），实话指真实的话。", "赎回": "第二个音节 huí（第二声）与 huà（第四声）韵母和声调都不同，赎回指用钱换回抵押的东西。"}, "sentence_index": null, "correct_answer": "熟化"}, "level_3": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：“熟化”修饰“过渡带”，表示中层是经发酵处理逐渐成熟的过渡区。"}, {"text": "翻耕", "is_correct": false, "explanation": "语义：“翻耕”指翻动耕地，与堆肥仓内的分层过渡区不搭，句意不通。"}, {"text": "投入", "is_correct": false, "explanation": "语义：“投入新料”是顶层的做法，中层并不是投料的地方。"}, {"text": "加热", "is_correct": false, "explanation": "搭配：“加热”针对物体，不能修饰“过渡带”这样的地带。"}], "explanations": {"熟化": "正确：“熟化”修饰“过渡带”，表示中层是经发酵处理逐渐成熟的过渡区。", "翻耕": "语义：“翻耕”指翻动耕地，与堆肥仓内的分层过渡区不搭，句意不通。", "投入": "语义：“投入新料”是顶层的做法，中层并不是投料的地方。", "加热": "搭配：“加热”针对物体，不能修饰“过渡带”这样的地带。"}, "sentence_index": 0, "correct_answer": "熟化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些香蕉过几天才会熟化。", "explanation": "这里应该用〈成熟〉。熟化指经加工使物质达到可用状态，香蕉自然变熟应说成熟。"}, {"text": "这棵树要熟化二十年才能长成大树。", "explanation": "这里应该用〈生长〉。熟化用于经人工处理的物质，树木长大要用生长。"}, {"text": "这几年他在工作中熟化得很快。", "explanation": "这里应该用〈成长〉。熟化只用于物质，人在工作中的成长不能说熟化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟化", "is_correct": true, "explanation": "正确：“熟化”作谓语，堆肥经过处理成熟后即可使用，与“以后”呼应。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：倒掉表示丢弃，与后文“拿去种花”矛盾。"}, {"text": "煮沸", "is_correct": false, "explanation": "搭配：“煮沸”针对液体，堆肥是固体，不能说煮沸。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁后堆肥已无法再用于种花。"}], "explanations": {"熟化": "正确：“熟化”作谓语，堆肥经过处理成熟后即可使用，与“以后”呼应。", "倒掉": "语义：倒掉表示丢弃，与后文“拿去种花”矛盾。", "煮沸": "搭配：“煮沸”针对液体，堆肥是固体，不能说煮沸。", "烧毁": "语义：烧毁后堆肥已无法再用于种花。"}, "sentence_index": 6, "correct_answer": "熟化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这头牛已经熟化了。", "explanation": "熟化用于经加工使物质可用的过程，牛的成长不能说熟化。"}, {"text": "这只小猫三个月就熟化了。", "explanation": "熟化的对象是经处理的物质，不能用来描述小猫的成长。"}, {"text": "我的哥哥在大学里熟化了很多。", "explanation": "熟化只指使物质变得可用的过程，不用于描述人在大学里的成长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批有机肥需要熟化了两个月才能用。", "corrected_sentence": "这批有机肥需要熟化两个月才能用。", "error_description": "时态错误：“需要……才能”句中“熟化”后不加“了”，应说“需要熟化两个月才能用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些粪肥很慢慢熟化了。", "corrected_sentence": "这些粪肥慢慢熟化了。", "error_description": "程度副词错误：“慢慢”是状语，前面不能加“很”，应说“慢慢熟化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
