INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两个不同区域之间相互连接或逐渐变化的地带。", "primary_collocate": null, "pronunciation": "guò dù dài", "ipa": "kuo˥˩ tu˥˩ tai˥˩", "syllable_count": 3, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "过渡带", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林和草原之间有一条很宽的过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湿地是水和陆地之间的过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区和平原的过渡带，气候慢慢变暖。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过渡带里的植物，既像山上的，又像平地的。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在海边的过渡带做了很多调查。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的冷水和暖水之间有一层过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和农村之间的过渡带，房子越来越少。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠边上的过渡带，草一年比一年少。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上画出了两种土壤的过渡带。", "target_word": "过渡带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過渡帶", "label": "繁体"}, {"form": "过渡地带", "label": "复合"}], "register": "中性", "sense_fingerprint": "过渡带：两个不同区域之间逐渐变化、相互连接的地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过渡带", "is_correct": true, "explanation": "正确：“过渡带”指中层这一逐渐变化的过渡区域，与“熟化”搭配。"}, {"text": "顶层", "is_correct": false, "explanation": "语义：后文“顶层”已指最上一层，中层不能同时是顶层。"}, {"text": "底部", "is_correct": false, "explanation": "语义：与前文“底层”指同一位置，句意矛盾。"}, {"text": "出口", "is_correct": false, "explanation": "搭配：“熟化”修饰物质或区域，不能修饰“出口”。"}], "explanations": {"过渡带": "正确：“过渡带”指中层这一逐渐变化的过渡区域，与“熟化”搭配。", "顶层": "语义：后文“顶层”已指最上一层，中层不能同时是顶层。", "底部": "语义：与前文“底层”指同一位置，句意矛盾。", "出口": "搭配：“熟化”修饰物质或区域，不能修饰“出口”。"}, "sentence_index": 0, "correct_answer": "过渡带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一年是他从学生到工作者的过渡带。", "explanation": "这里应该用〈过渡期〉。过渡带指两个区域之间的地带，表示一段时间要说过渡期。"}, {"text": "草原与沙漠之间的过渡带毫无渐变，两边像是被一刀切开。", "explanation": "这里应该用〈界线〉。过渡带指逐渐变化的地带，两边一刀切开、毫无渐变的情形应说界线。"}, {"text": "两块布的过渡带很整齐。", "explanation": "这里应该用〈接缝〉。过渡带指逐渐变化的地带，两块布相接的线应说接缝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过渡带", "is_correct": true, "explanation": "正确：“过渡带”指冷水与暖水之间逐渐变化的一层区域，与“一层”搭配。"}, {"text": "地基", "is_correct": false, "explanation": "语义：湖水之间不会有地基，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户的量词是“扇”，不说“一层”。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：湖中的冷水和暖水之间不会铺着地毯。"}], "explanations": {"过渡带": "正确：“过渡带”指冷水与暖水之间逐渐变化的一层区域，与“一层”搭配。", "地基": "语义：湖水之间不会有地基，句意不通。", "窗户": "搭配：窗户的量词是“扇”，不说“一层”。", "地毯": "语义：湖中的冷水和暖水之间不会铺着地毯。"}, "sentence_index": 6, "correct_answer": "过渡带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河是两个县的过渡带。", "explanation": "这里应该用〈分界线〉。河流是界线，不是逐渐变化的地带，不能说过渡带。"}, {"text": "这堵墙是两个房间的过渡带。", "explanation": "这里应该用〈隔断〉。墙是突然分开两个空间，过渡带指渐变的地带。"}, {"text": "这块界碑两边的过渡带没有一点渐变。", "explanation": "这里应该用〈界线〉。过渡带指逐渐变化的地带，两边毫无渐变应说界线，界碑标示的是界线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两种土壤之间有一头明显的过渡带。", "corrected_sentence": "两种土壤之间有一条明显的过渡带。", "error_description": "量词错误：“头”专用于牛、马等大牲畜，不能用来数地带，应用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水和陆地之间有一朵过渡带。", "corrected_sentence": "水和陆地之间有一条过渡带。", "error_description": "量词错误：“朵”多用于花，不能用来数过渡带，应用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
