INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "（名词）建筑物最上面的一层；也比喻事物发展中的最高阶段或级别。", "primary_collocate": null, "pronunciation": "dǐng céng", "ipa": "tiŋ˨˩˦ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "而拥有庭院者则宜构建分层式堆肥仓，通过物理隔离实现不同发酵阶段的连续处理：底层为初级分解区，中层为熟化过渡带，顶层持续投入新料。", "target_word": "顶层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座塔的顶层可以看到全城。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕的顶层放着一颗草莓。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司顶层的领导正在开会。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要进入行业顶层，需要多年努力。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的顶层玩家只有几百人。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的顶层放着旧相机。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金字塔的顶层最小，底层最大。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会顶层的人也会遇到烦恼。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树的顶层叶子最先见到阳光。", "target_word": "顶层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頂層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顶层：最上面的一层，也指最高级别或阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顶层", "is_correct": true, "explanation": "顶层指最上面的一层，与“持续投入新料”的位置对应。"}, {"text": "基层", "is_correct": false, "explanation": "语义：“基层”指最底下的一层，与“底层为初级分解区”的位置重复。"}, {"text": "深层", "is_correct": false, "explanation": "语义：“深层”指较深的一层，与“顶层”的位置相反。"}, {"text": "中心", "is_correct": false, "explanation": "搭配：“中心”指中间位置，与“底层”“中层”并列时不能指顶部。"}], "explanations": {"顶层": "顶层指最上面的一层，与“持续投入新料”的位置对应。", "基层": "语义：“基层”指最底下的一层，与“底层为初级分解区”的位置重复。", "深层": "语义：“深层”指较深的一层，与“顶层”的位置相反。", "中心": "搭配：“中心”指中间位置，与“底层”“中层”并列时不能指顶部。"}, "sentence_index": 0, "correct_answer": "顶层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的顶层写得很有意思。", "explanation": "这里不宜用〈顶层〉。“顶层”指建筑或等级的最上层，书的内容没有这样的层次，应说“最后一章”。"}, {"text": "他的顶层很饿。", "explanation": "这里不宜用〈顶层〉。“顶层”指位置或等级，不能用来描述人的饥饿；说饿应说“他很饿”。"}, {"text": "这个学期的顶层很忙。", "explanation": "这里不宜用〈顶层〉。学期没有上下层次，“顶层”只用于有层级的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顶层", "is_correct": true, "explanation": "顶层指最上面的一层，与“放着旧相机”的书架语境一致。"}, {"text": "地下室", "is_correct": false, "explanation": "搭配：“地下室”是房间，不是书架的一部分。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：“天花板”是房屋的结构，不能作为书架上放东西的一层。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是房间，与书架的分层结构不搭。"}], "explanations": {"顶层": "顶层指最上面的一层，与“放着旧相机”的书架语境一致。", "地下室": "搭配：“地下室”是房间，不是书架的一部分。", "天花板": "语义：“天花板”是房屋的结构，不能作为书架上放东西的一层。", "厨房": "搭配：“厨房”是房间，与书架的分层结构不搭。"}, "sentence_index": 6, "correct_answer": "顶层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的顶层很聪明。", "explanation": "这里不宜用〈顶层〉。电脑没有分层结构，“顶层”不能用来形容聪明与否；说电脑聪明应说“这台电脑很聪明”。"}, {"text": "这块石头的顶层很甜。", "explanation": "这里不宜用〈顶层〉。“顶层”指位置或等级，不能用来描述味道。"}, {"text": "我的顶层很冷。", "explanation": "这里不宜用〈顶层〉。“顶层”指位置或等级，不能用来描述人的冷暖；说冷应说“我很冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座楼的很顶层住着一位老人。", "corrected_sentence": "这座楼的顶层住着一位老人。", "error_description": "错误：“很”修饰了名词“顶层”，“顶层”是名词，不能受程度副词修饰。正确：去掉“很”，应说“这座楼的顶层住着一位老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座楼的一座顶层有一间阁楼。", "corrected_sentence": "这座楼的顶层有一间阁楼。", "error_description": "错误：“顶层”前误加了量词“座”。正确：“顶层”不加量词，应说“这座楼的顶层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
