INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新近出现或爆料的信息或内幕，通常指未被广泛了解的新闻或秘密。", "primary_collocate": null, "pronunciation": "xīn liào", "ipa": "ɕin˥ liɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "记者在采访中无意透露了一个新料，同行都很关注。", "target_word": "新料", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这位明星昨天又爆出了一个新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者手里有一个大新料，明天就发表。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网友都在等这个明星的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我讲了一个公司里的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是有很多娱乐圈的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新料一放出来，全网都炸了。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么新料？快告诉我们吧。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社花了很多钱买这个新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚微博上有人放出了新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "新料：新近爆出、尚未广为人知的新闻或内幕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新料", "is_correct": true, "explanation": "xīn liào，指新近爆出或未广为人知的消息、内幕，即本义。"}, {"text": "金料", "is_correct": false, "explanation": "jīn 与 xīn 声母不同，金料指金的原料，意思不是新近爆出的内幕。"}, {"text": "心量", "is_correct": false, "explanation": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。"}, {"text": "新粮", "is_correct": false, "explanation": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。"}, {"text": "辛劳", "is_correct": false, "explanation": "láo 与 liào 的声调和韵母不同，辛劳指辛苦劳累。"}], "explanations": {"新料": "xīn liào，指新近爆出或未广为人知的消息、内幕，即本义。", "金料": "jīn 与 xīn 声母不同，金料指金的原料，意思不是新近爆出的内幕。", "心量": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。", "新粮": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。", "辛劳": "láo 与 liào 的声调和韵母不同，辛劳指辛苦劳累。"}, "sentence_index": null, "correct_answer": "新料"}, "level_3": {"options": [{"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是绘画用的材料，不能被“透露”，句意不通。"}, {"text": "木料", "is_correct": false, "explanation": "语义：“木料”是木材实物，不能被“透露”。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：“饲料”是喂养牲畜的材料，不能被“透露”。"}, {"text": "新料", "is_correct": true, "explanation": "“新料”指新近爆出或未广为人知的消息，与“无意透露了一个……，同行都很关注”相合。"}], "explanations": {"颜料": "语义：“颜料”是绘画用的材料，不能被“透露”，句意不通。", "木料": "语义：“木料”是木材实物，不能被“透露”。", "饲料": "语义：“饲料”是喂养牲畜的材料，不能被“透露”。", "新料": "“新料”指新近爆出或未广为人知的消息，与“无意透露了一个……，同行都很关注”相合。"}, "sentence_index": 0, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在汤里加了一把新料，香味很浓。", "explanation": "这里应该用〈调料〉。“新料”指新近爆出的消息或内幕，不能用来指做汤的调料。"}, {"text": "这是十年前的新料了。", "explanation": "这里应该用〈旧闻〉。“新料”指刚出现、大家还不了解的消息，不能用来指十年前已经过去的事。"}, {"text": "他把这杯新料一口喝完了。", "explanation": "这里的〈新料〉被误当作饮料。“新料”指新爆出的消息，不能当作可以喝的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧料", "is_correct": false, "explanation": "语义：“旧料”指旧的材料，不能“放出来”就让全网炸开，句意不通。"}, {"text": "石料", "is_correct": false, "explanation": "语义：“石料”是采石得来的材料，不能“放出来”引发全网关注。"}, {"text": "布料", "is_correct": false, "explanation": "语义：“布料”是纺织用的材料，不是能让全网炸开的消息。"}, {"text": "新料", "is_correct": true, "explanation": "“新料”指新近爆出的消息，与“放出来，全网都炸了”的语境相合。"}], "explanations": {"旧料": "语义：“旧料”指旧的材料，不能“放出来”就让全网炸开，句意不通。", "石料": "语义：“石料”是采石得来的材料，不能“放出来”引发全网关注。", "布料": "语义：“布料”是纺织用的材料，不是能让全网炸开的消息。", "新料": "“新料”指新近爆出的消息，与“放出来，全网都炸了”的语境相合。"}, "sentence_index": 6, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把新料放进冰箱里保存。", "explanation": "这里的〈新料〉被误当作可以冷藏的食材。“新料”指新近爆出的消息或内幕，是抽象信息，不能放进冰箱。"}, {"text": "他每天都把新料擦得很干净。", "explanation": "这里的〈新料〉被误当作可以清理的实物。“新料”指新爆出的消息或内幕，是抽象信息，不能当作有形的东西来处理。"}, {"text": "他用新料把门关上了。", "explanation": "这里的〈新料〉被误当作工具或物件。“新料”指新近爆出的内幕，不能用来做工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网上昨晚爆出了一只新料。", "corrected_sentence": "网上昨晚爆出了一个新料。", "error_description": "量词错误：“新料”前应用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。错误为“一只新料”，正确为“一个新料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于爆出了一个的新料。", "corrected_sentence": "他终于爆出了一个新料。", "error_description": "助词错误：“一个”与名词之间不能加“的”，应说“一个新料”，不能说“一个的新料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
