INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将堆积的肥料、粮食等翻动，使其混合均匀或通风。", "primary_collocate": null, "pronunciation": "fān duī", "ipa": "fan˥ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "定期翻堆确保氧气渗透，防止局部厌氧酸化，是维持微生物群落活性的关键操作。", "target_word": "翻堆", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "操作流程中的核心干预在于维持“三要素”协同：湿度应控制在手握成团、轻触即散的程度，相当于50%-60%的含水量；翻堆频率建议每周一次，以引入氧气，抑制厌氧菌滋生；温度则需监测中心区域，理想范围为55°C至65°C，此为嗜热菌群活跃区间，可有效灭杀病原体与杂草种子。", "target_word": "翻堆", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "师傅用铁锹给堆肥翻堆，让空气进去。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粮食堆得太高会发热，要及时翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥发臭了，说明该翻堆了。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们翻堆后，肥料里的温度慢慢降低了。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场用机器翻堆，比人工快得多。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，我们不能翻堆，只好明天再做。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻堆的时候，要把底下的肥料翻到上面来。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每个星期六早上都去菜地翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻堆机", "label": "复合"}], "register": "中性", "sense_fingerprint": "翻动堆积的肥料或粮食，使其均匀、通风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：定期翻动堆料可以让氧气进入，与「确保氧气渗透」相符。"}, {"text": "覆盖", "is_correct": false, "explanation": "语义：覆盖会阻隔空气，与「确保氧气渗透」的目的相反。"}, {"text": "压实", "is_correct": false, "explanation": "语义：压实会使堆料变紧、空隙减少，与「氧气渗透」矛盾。"}, {"text": "灌溉", "is_correct": false, "explanation": "搭配：「灌溉」指向土壤浇水，不能说「灌溉氧气渗透」这类搭配。"}], "explanations": {"翻堆": "正确：定期翻动堆料可以让氧气进入，与「确保氧气渗透」相符。", "覆盖": "语义：覆盖会阻隔空气，与「确保氧气渗透」的目的相反。", "压实": "语义：压实会使堆料变紧、空隙减少，与「氧气渗透」矛盾。", "灌溉": "搭配：「灌溉」指向土壤浇水，不能说「灌溉氧气渗透」这类搭配。"}, "sentence_index": 0, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面糊要用勺子翻堆均匀。", "explanation": "这里应该用〈搅拌〉。翻堆指翻动堆积的肥料、粮食，不用于搅匀面糊。"}, {"text": "湿衣服要挂在阳光下翻堆。", "explanation": "这里应该用〈晾晒〉。衣物晾干要说晾晒，翻堆只用于堆积的肥料或粮食。"}, {"text": "锅里的青菜要用大火翻堆。", "explanation": "这里应该用〈翻炒〉。在锅中翻动食材要说翻炒，翻堆不用于烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：农场用机器翻动堆料，比人工快，符合语境。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：焊接是连接金属的作业，与农场的堆料处理无关。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：「装订」多指书册加工，不用于农场的作业。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：印刷是印制文字图像的工作，与农场的堆料处理不符。"}], "explanations": {"翻堆": "正确：农场用机器翻动堆料，比人工快，符合语境。", "焊接": "语义：焊接是连接金属的作业，与农场的堆料处理无关。", "装订": "搭配：「装订」多指书册加工，不用于农场的作业。", "印刷": "语义：印刷是印制文字图像的工作，与农场的堆料处理不符。"}, "sentence_index": 6, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在床上翻堆，睡得不踏实。", "explanation": "这里应该用〈翻身〉。人在床上转动身体要说翻身，翻堆指翻动堆积的物料。"}, {"text": "这栋老房子要翻堆，换掉漏水的屋顶。", "explanation": "这里应该用〈翻修〉。房屋整修要说翻修，翻堆只用于堆积的物料。"}, {"text": "他翻堆了一本旧杂志，找到了那张照片。", "explanation": "这里应该用〈翻看〉。翻看书刊要说翻看，翻堆不用于翻阅杂志。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们刚翻堆得，肥料很快就热了。", "corrected_sentence": "工人们刚翻堆了，肥料很快就热了。", "error_description": "错误：「翻堆」表示刚完成的动作，「了」应紧跟在「翻堆」之后，不能换成「得」。正确形式：刚翻堆了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器翻堆的很快。", "corrected_sentence": "这台机器翻堆翻得很快。", "error_description": "错误：重复动词后的补语要用「得」，不能用「的」。正确形式：翻堆翻得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
