INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体慢慢地透过物体；比喻一种思想或势力逐渐进入。", "primary_collocate": null, "pronunciation": "shèn tòu", "ipa": "ʂən˥˩ tʰoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "雨水慢慢渗透到土里。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗水渗透了他的衣服。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶坏了，雨水慢慢渗透下来。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的思想会慢慢渗透到孩子心里。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国文化渐渐渗透到我们的生活中。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品正在渗透进小城市。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红酒洒在纸上，很快就渗透了。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络已经渗透到每个家庭。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布不防水，雨水很快就渗透了。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌方的间谍想渗透到我们内部。", "target_word": "渗透", "complexity_tier": "T3", "furigana": "dí fāng de jiàn dié xiǎng shèn tòu dào wǒ men nèi bù", "sentence_source": "generated"}], "morphological_forms": [{"form": "渗透了", "label": "体标"}, {"form": "渗透着", "label": "体标"}, {"form": "渗透过", "label": "体标"}, {"form": "滲透", "label": "繁体"}, {"form": "渗透力", "label": "复合"}], "register": "中性", "sense_fingerprint": "渗透：液体慢慢透过物体；思想、势力逐渐进入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃烧", "is_correct": false, "explanation": "语义：雨水不能燃烧，也不会“燃烧到土里”，句意不通。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”指打碎，雨水不能被粉碎后进入土中。"}, {"text": "碾压", "is_correct": false, "explanation": "搭配：“碾压”指用力压过去，不说雨水“碾压到土里”。"}, {"text": "渗透", "is_correct": true, "explanation": "正确选项“渗透”表示液体慢慢透过物体，与“雨水慢慢……到土里”相合。"}], "explanations": {"燃烧": "语义：雨水不能燃烧，也不会“燃烧到土里”，句意不通。", "粉碎": "语义：“粉碎”指打碎，雨水不能被粉碎后进入土中。", "碾压": "搭配：“碾压”指用力压过去，不说雨水“碾压到土里”。", "渗透": "正确选项“渗透”表示液体慢慢透过物体，与“雨水慢慢……到土里”相合。"}, "sentence_index": 0, "correct_answer": "渗透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨水慢慢渗透进了天空。", "explanation": "“渗透”的处所须是能被液体渗入的物体或领域，天空不能被渗透，这里搭配不当。"}, {"text": "他把书渗透进了包里。", "explanation": "这里应该用〈塞〉。渗透指液体或思想逐渐进入，不能有意把固体塞进去。"}, {"text": "他把钱渗透给了穷人。", "explanation": "这里应该用〈捐〉。渗透不能表示有意给予财物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破碎", "is_correct": false, "explanation": "语义：红酒洒在纸上不会“破碎”，句意不通。"}, {"text": "咀嚼", "is_correct": false, "explanation": "搭配：“咀嚼”的对象是食物，不说红酒被咀嚼。"}, {"text": "闪烁", "is_correct": false, "explanation": "语义：“闪烁”指光亮忽明忽暗，与红酒渗入纸张无关。"}, {"text": "渗透", "is_correct": true, "explanation": "正确选项“渗透”表示液体透过物体，与“红酒洒在纸上，很快就……了”相合。"}], "explanations": {"破碎": "语义：红酒洒在纸上不会“破碎”，句意不通。", "咀嚼": "搭配：“咀嚼”的对象是食物，不说红酒被咀嚼。", "闪烁": "语义：“闪烁”指光亮忽明忽暗，与红酒渗入纸张无关。", "渗透": "正确选项“渗透”表示液体透过物体，与“红酒洒在纸上，很快就……了”相合。"}, "sentence_index": 6, "correct_answer": "渗透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天渗透三次药。", "explanation": "这里应该用〈服〉。渗透表示液体透入或思想、势力进入，不用于吃药。"}, {"text": "老师渗透了全班的作业。", "explanation": "这里应该用〈批改〉。渗透不用于对作业进行处理。"}, {"text": "妈妈慢慢渗透了那只碗。", "explanation": "这里应该用〈洗〉。渗透是液体逐渐透入的意思，不能用于人清洗物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种墨水很快就渗透纸里了。", "corrected_sentence": "这种墨水很快就渗透到纸里了。", "error_description": "介词缺失：“渗透”后接处所时要加“到”或“进”，不能直接说“渗透纸里”，应为“渗透到纸里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水渗透很快。", "corrected_sentence": "雨水渗透得很快。", "error_description": "补语错误：表示程度的补语要用“得”连接，应为“渗透得很快”，不能只说“渗透很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好氧", "is_correct": true, "explanation": "好氧：指需要氧气才能生存的状态，与厌氧意思相反。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥：形容水分少，与厌氧“没有氧气”的状态无关，不是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足，与厌氧无关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：形容声音或环境平静，与厌氧无关系。"}], "correct_answer": "好氧", "explanations": {"好氧": "好氧：指需要氧气才能生存的状态，与厌氧意思相反。", "干燥": "干燥：形容水分少，与厌氧“没有氧气”的状态无关，不是反义词。", "明亮": "明亮：形容光线充足，与厌氧无关系。", "安静": "安静：形容声音或环境平静，与厌氧无关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好氧", "is_correct": true, "explanation": "好氧：指需要氧气才能生存的状态，与厌氧意思相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地，与厌氧无关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙：形容事务多，与厌氧无关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄：形容空间小，与厌氧无关系。"}], "correct_answer": "好氧", "explanations": {"好氧": "好氧：指需要氧气才能生存的状态，与厌氧意思相反。", "柔软": "柔软：形容质地，与厌氧无关系。", "繁忙": "繁忙：形容事务多，与厌氧无关系。", "狭窄": "狭窄：形容空间小，与厌氧无关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有氧气存在或不能有氧气参与的状态。", "primary_collocate": null, "pronunciation": "yàn yǎng", "ipa": "jɛn⁵¹ jɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "翻堆不勤时，堆体深处供氧受限，局部会变得厌氧，并释放出刺激性的臭气，因此堆肥必须定期翻堆通风。", "target_word": "厌氧", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "堆肥太湿太紧，里面很快就会厌氧。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池底没有氧气，那里的环境是厌氧的。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子盖紧以后，里面慢慢变厌氧了。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖底的泥很厚，空气进不去，所以是厌氧的。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种细菌只在厌氧的地方生活。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻堆太少，堆里的空气不够，就会厌氧发臭。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的氧气用完了，下面一层已经厌氧了。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沼气池必须密封，让里面保持厌氧。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土太湿时，根部周围容易厌氧，植物会烂根。", "target_word": "厌氧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厭氧", "label": "繁体"}, {"form": "厌氧菌", "label": "复合"}], "register": "书面", "sense_fingerprint": "厌氧：没有氧气或不需要氧气的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厌氧", "is_correct": true, "explanation": "厌氧（yàn yǎng）：指没有氧气或不需要氧气的状态，即正确答案。"}, {"text": "眼痒", "is_correct": false, "explanation": "眼痒（yǎn yǎng）与厌氧第一个音节声调不同，yǎn（第三声）与 yàn（第四声）只差声调，意思是眼睛发痒。"}, {"text": "艳阳", "is_correct": false, "explanation": "艳阳（yàn yáng）与厌氧第二个音节声调不同，yáng（第二声）与 yǎng（第三声）只差声调，意思是明丽的阳光。"}, {"text": "咽痒", "is_correct": false, "explanation": "咽痒（yān yǎng）与厌氧第一个音节声调不同，yān（第一声）与 yàn（第四声）只差声调，意思是咽喉发痒。"}, {"text": "岩羊", "is_correct": false, "explanation": "岩羊（yán yáng）两个音节的声调都与厌氧不同，指一种野生动物。"}], "explanations": {"厌氧": "厌氧（yàn yǎng）：指没有氧气或不需要氧气的状态，即正确答案。", "眼痒": "眼痒（yǎn yǎng）与厌氧第一个音节声调不同，yǎn（第三声）与 yàn（第四声）只差声调，意思是眼睛发痒。", "艳阳": "艳阳（yàn yáng）与厌氧第二个音节声调不同，yáng（第二声）与 yǎng（第三声）只差声调，意思是明丽的阳光。", "咽痒": "咽痒（yān yǎng）与厌氧第一个音节声调不同，yān（第一声）与 yàn（第四声）只差声调，意思是咽喉发痒。", "岩羊": "岩羊（yán yáng）两个音节的声调都与厌氧不同，指一种野生动物。"}, "sentence_index": null, "correct_answer": "厌氧"}, "level_3": {"options": [{"text": "厌氧", "is_correct": true, "explanation": "厌氧：没有氧气的状态，填入后「局部会变得厌氧」与「供氧受限」的前提一致，并导致臭气，符合语境。"}, {"text": "好氧", "is_correct": false, "explanation": "语义：「好氧」指需要氧气，与「供氧受限」的前提相反，说不通。"}, {"text": "有氧", "is_correct": false, "explanation": "语义：「有氧」说明氧气充足，与「供氧受限」的前提矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥的堆体不会释放刺激性的臭气，与后半句矛盾。"}], "explanations": {"厌氧": "厌氧：没有氧气的状态，填入后「局部会变得厌氧」与「供氧受限」的前提一致，并导致臭气，符合语境。", "好氧": "语义：「好氧」指需要氧气，与「供氧受限」的前提相反，说不通。", "有氧": "语义：「有氧」说明氧气充足，与「供氧受限」的前提矛盾。", "干燥": "语义：干燥的堆体不会释放刺激性的臭气，与后半句矛盾。"}, "sentence_index": 0, "correct_answer": "厌氧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在高原上，人很容易厌氧。", "explanation": "这里应该用〈缺氧〉。厌氧指环境或微生物没有氧气，人在高原上氧气不足要说缺氧。"}, {"text": "煤气泄漏时，屋里的人很快就厌氧了。", "explanation": "这里应该用〈窒息〉。厌氧用于环境或微生物，屋里的人因吸入煤气无法呼吸要说窒息。"}, {"text": "这间地下室很厌氧，住久了很不舒服。", "explanation": "这里应该用〈闷〉。厌氧是专业术语，描述房间不通风要说闷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厌氧", "is_correct": true, "explanation": "厌氧：没有氧气的状态，填入后“就会厌氧发臭”指堆肥缺氧后发臭，符合语境。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”与“发臭”矛盾，堆肥缺氧时才会腐败发臭。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容卫生状态，不与“发臭”这种腐败状态搭配。"}, {"text": "芳香", "is_correct": false, "explanation": "语义：“芳香”与“发臭”意思相反，句子说不通。"}], "explanations": {"厌氧": "厌氧：没有氧气的状态，填入后“就会厌氧发臭”指堆肥缺氧后发臭，符合语境。", "新鲜": "语义：“新鲜”与“发臭”矛盾，堆肥缺氧时才会腐败发臭。", "干净": "搭配：“干净”形容卫生状态，不与“发臭”这种腐败状态搭配。", "芳香": "语义：“芳香”与“发臭”意思相反，句子说不通。"}, "sentence_index": 6, "correct_answer": "厌氧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很厌氧，夏天穿很舒服。", "explanation": "这里应该用〈透气〉。厌氧指环境没有氧气，衣服能不能透气要说透气。"}, {"text": "这条鱼很厌氧，一直在水里游来游去。", "explanation": "这里应该用〈活泼〉。鱼需要氧气才能活，「厌氧」指没有氧气，不能用来形容鱼；形容它爱动应说活泼。"}, {"text": "这个山洞很厌氧，空气一直很清新。", "explanation": "这里应该用〈通风〉。空气流通的山洞要说通风，厌氧指没有氧气的环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些泥土常年被水泡着，底层是厌氧。", "corrected_sentence": "这些泥土常年被水泡着，底层是厌氧的。", "error_description": "漏掉“的”。形容词作“是”的谓语时要说“是……的”，应说“底层是厌氧的”，不能只说“底层是厌氧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层泥很松，空气能透进去，所以没厌氧。", "corrected_sentence": "这层泥很松，空气能透进去，所以不厌氧。", "error_description": "否定词错误：形容词作谓语表示否定要用“不”，不用“没”。应说“不厌氧”，不能说“没厌氧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
