INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使物质变成酸或增加酸性的过程", "primary_collocate": null, "pronunciation": "suān huà", "ipa": "swan⁵⁵ xwa⁵¹", "syllable_count": 2, "sentences": [{"text": "翻堆不勤时，堆体深处供氧受限，有机物分解后酸性物质逐渐积累，局部发生酸化，因此堆肥必须定期翻堆通风。", "target_word": "酸化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "海水里的酸性越来越高，这种酸化会伤害贝类。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤酸化以后，庄稼很难长好。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "suān huà", "sentence_source": "generated"}, {"text": "烧煤放出的气体会造成酸雨和土地酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸化很慢，要过好几年才看得出来。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水的酸化让很多鱼活不下去。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期大量施用化肥，会导致土地酸化。", "target_word": "酸化", "complexity_tier": "T3", "furigana": "suān huà", "sentence_source": "generated"}, {"text": "酸化是水或土慢慢变酸的过程。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少烧煤，可以减缓土地的酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥里的酸化太严重，微生物很难活。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤酸化", "label": "复合"}, {"form": "海洋酸化", "label": "复合"}], "register": "书面", "sense_fingerprint": "酸化：物质变酸或酸性增加的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「发生酸化」指酸性物质积累、物质变酸，与前文「酸性物质逐渐积累」的语境一致。"}, {"text": "绿化", "is_correct": false, "explanation": "搭配：「绿化」指种植植物、美化环境，与堆体内部的酸性积累语境不符。"}, {"text": "液化", "is_correct": false, "explanation": "语义：「液化」指物质变为液体，句中讲的是微生物环境中的酸性变化，意思不合。"}, {"text": "美化", "is_correct": false, "explanation": "语义：「美化」指使环境变美，与堆体内部的酸性变化毫无关系。"}], "explanations": {"酸化": "正确：「发生酸化」指酸性物质积累、物质变酸，与前文「酸性物质逐渐积累」的语境一致。", "绿化": "搭配：「绿化」指种植植物、美化环境，与堆体内部的酸性积累语境不符。", "液化": "语义：「液化」指物质变为液体，句中讲的是微生物环境中的酸性变化，意思不合。", "美化": "语义：「美化」指使环境变美，与堆体内部的酸性变化毫无关系。"}, "sentence_index": 0, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种强酸会酸化金属栏杆。", "explanation": "这里应该用〈腐蚀〉。酸化指使物质变酸或酸性增强，强酸损坏金属应说「腐蚀」。"}, {"text": "岩石经过长年风吹雨打，慢慢酸化了。", "explanation": "这里应该用〈风化〉。岩石破碎分解叫「风化」，「酸化」用于水或土壤等物质变酸，不用于描述岩石。"}, {"text": "农民用石灰酸化了土壤。", "explanation": "这里应该用〈中和〉。石灰是碱性物质，用它处理土壤是为了降低酸性，应说「中和」，不能说「酸化」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「导致土地酸化」指长期施肥使土地变酸，与「长期大量施用化肥」的消极后果一致。"}, {"text": "活化", "is_correct": false, "explanation": "语义：「活化」指激活、增强活力，是积极的变化，与化肥造成的不良后果相反。"}, {"text": "净化", "is_correct": false, "explanation": "语义：「净化」指去除污染、使干净，与化肥造成污染的语境相反。"}, {"text": "同化", "is_correct": false, "explanation": "搭配：「同化」指趋于相同或被吸收，不能说「导致土地同化」，与此句不搭配。"}], "explanations": {"酸化": "正确：「导致土地酸化」指长期施肥使土地变酸，与「长期大量施用化肥」的消极后果一致。", "活化": "语义：「活化」指激活、增强活力，是积极的变化，与化肥造成的不良后果相反。", "净化": "语义：「净化」指去除污染、使干净，与化肥造成污染的语境相反。", "同化": "搭配：「同化」指趋于相同或被吸收，不能说「导致土地同化」，与此句不搭配。"}, "sentence_index": 6, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁在潮湿的空气里会酸化生锈。", "explanation": "这里应该用〈氧化〉。铁生锈是与氧发生的反应，「酸化」指物质变酸，不能用于描述生锈。"}, {"text": "这台机器用久了就会酸化。", "explanation": "这里应该用〈老化〉。机器随使用时间变旧、性能下降叫「老化」，「酸化」指物质变酸。"}, {"text": "这条裙子洗了几次就酸化了。", "explanation": "这里应该用〈褪色〉。衣服颜色变淡叫「褪色」，「酸化」指使物质变酸，不能用于描述衣物颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水的酸化了让很多鱼死了。", "corrected_sentence": "湖水的酸化让很多鱼死了。", "error_description": "「酸化」作名词时后面不能加「了」。「了」只能用于动词「酸化」，这里应删去「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一本很常见的酸化。", "corrected_sentence": "这是一种很常见的酸化。", "error_description": "「酸化」作名词时，量词应用「种」，「本」用于书册，不能用来修饰「酸化」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "惰性", "is_correct": true, "explanation": "惰性：指物质不活泼、不易发生化学反应，与“活性”相对。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与活性没有反义关系，不能与之相对。"}, {"text": "密度", "is_correct": false, "explanation": "语义：密度说的是单位体积的质量，与活性没有反义关系。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：硬度是材料抵抗压入的能力，与化学作用的活性不相对。"}], "correct_answer": "惰性", "explanations": {"惰性": "惰性：指物质不活泼、不易发生化学反应，与“活性”相对。", "温度": "语义：温度与活性没有反义关系，不能与之相对。", "密度": "语义：密度说的是单位体积的质量，与活性没有反义关系。", "硬度": "语义：硬度是材料抵抗压入的能力，与化学作用的活性不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "惰性", "is_correct": true, "explanation": "惰性：指物质不活泼、不易发生化学反应，与“活性”相对。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度说的是快慢，与活性没有反义关系。"}, {"text": "质量", "is_correct": false, "explanation": "语义：质量说的是物体所含物质的多少，与活性没有反义关系。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积说的是物体占的空间，与活性没有反义关系。"}], "correct_answer": "惰性", "explanations": {"惰性": "惰性：指物质不活泼、不易发生化学反应，与“活性”相对。", "速度": "语义：速度说的是快慢，与活性没有反义关系。", "质量": "语义：质量说的是物体所含物质的多少，与活性没有反义关系。", "体积": "语义：体积说的是物体占的空间，与活性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物质或系统具有的能够进行化学反应、生物作用或产生其他变化并维持其功能的特性。", "primary_collocate": null, "pronunciation": "huó xìng", "ipa": "xwo˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "高温会降低酶的活性。", "target_word": "活性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种催化剂的活性很高。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "低温下，这种酶的活性会明显减弱。", "target_word": "活性", "complexity_tier": "T3", "furigana": "dī wēn xià zhè zhǒng méi de huó xìng huì míng xiǎn jiǎn ruò", "sentence_source": "generated"}, {"text": "科学家测量了药物的活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放太久的维生素，活性会慢慢降低。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加热以后，蛋白质失去了活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金属的活性越强，越容易发生化学反应。", "target_word": "活性", "complexity_tier": "T3", "furigana": "jīn shǔ de huó xìng yuè qiáng yuè róng yì fā shēng huà xué fǎn yìng", "sentence_source": "generated"}, {"text": "酸性太强会让这种细菌的活性下降。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷冻可以保持疫苗的活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验表明，这种药物在体内有很强的活性。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "酶活性", "label": "复合"}, {"form": "活性氧", "label": "复合"}], "register": "科技", "sense_fingerprint": "名词：酶、药物、催化剂等物质进行化学或生物作用的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指酶催化化学反应的能力，高温会使它降低，符合句意。"}, {"text": "温度", "is_correct": false, "explanation": "语义：酶的温度与前半句“高温”的意思冲突，句子说不通。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“收入”只说人或机构的钱财，不用于酶。"}, {"text": "薪水", "is_correct": false, "explanation": "搭配：“薪水”指劳动报酬，不能用来说酶。"}], "explanations": {"活性": "活性：指酶催化化学反应的能力，高温会使它降低，符合句意。", "温度": "语义：酶的温度与前半句“高温”的意思冲突，句子说不通。", "收入": "搭配：“收入”只说人或机构的钱财，不用于酶。", "薪水": "搭配：“薪水”指劳动报酬，不能用来说酶。"}, "sentence_index": 0, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的活性很高，运转得很快。", "explanation": "这里应该用〈效率〉。活性指物质进行化学或生物作用的特性，形容机器的工作快慢要用效率。"}, {"text": "这箱药物的活性很轻，搬起来毫不费力。", "explanation": "这里应该用〈重量〉。活性是抽象的特性，不能用“轻”来形容；说物体的轻重要用重量。"}, {"text": "这幅画的活性很鲜艳，一眼就能看见。", "explanation": "这里应该用〈色彩〉。活性指物质进行化学或生物作用的特性，不能用来形容画面的鲜艳程度；说颜色鲜艳要用色彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指金属进行化学反应的能力，与“越容易发生化学反应”一致。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度与化学反应无关，句子的因果关系不通。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“强”一般不修饰重量，这里不能说“重量越强”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格不说强弱，“价格越强”不成立。"}], "explanations": {"活性": "活性：指金属进行化学反应的能力，与“越容易发生化学反应”一致。", "亮度": "语义：亮度与化学反应无关，句子的因果关系不通。", "重量": "搭配：“强”一般不修饰重量，这里不能说“重量越强”。", "价格": "搭配：价格不说强弱，“价格越强”不成立。"}, "sentence_index": 6, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电池的活性很长，能用好几年。", "explanation": "这里应该用〈寿命〉。活性不能用“长”来形容电池的使用期限，说电池能用多久要用寿命。"}, {"text": "这盏灯的活性很强，照得屋子很亮。", "explanation": "这里应该用〈亮度〉。活性说的是物质的化学作用，灯的明暗要用亮度。"}, {"text": "这瓶香水的活性很浓，满屋子都是。", "explanation": "这里应该用〈香气〉。活性指物质的化学或生物作用，不用来形容香味的浓淡；说香味浓要用香气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药物具有一只很强的活性，需要冷藏。", "corrected_sentence": "这种药物具有一种很强的活性，需要冷藏。", "error_description": "量词错误：“活性”的量词应用“种”，“只”只用于动物，不能说“一只活性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种疫苗的活性了很强，需要冷藏。", "corrected_sentence": "这种疫苗的活性很强，需要冷藏。", "error_description": "“了”位置不当。描述性状的“活性很强”中不能插入“了”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
