INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工程学是一门应用科学原理和技术方法来解决实际问题、设计和建造结构、机器、系统或过程的学科。", "primary_collocate": null, "pronunciation": "gōng chéng xué", "ipa": "kʊŋ⁵⁵ ʈʂʰɤŋ³⁵ ɕɥe³⁵", "syllable_count": 3, "sentences": [{"text": "从工程学视角观之，家庭堆肥实为一种低熵循环模型。", "target_word": "工程学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "工程学用科学原理解决实际问题。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学工程学，以后想设计大桥。", "target_word": "工程学", "complexity_tier": "T3", "furigana": "tā zài dàxué xué gōngchéngxué, yǐhòu xiǎng shèjì dàqiáo.", "sentence_source": "generated"}, {"text": "工程学老师带我们参观了一座新桥。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要建一座安全的大楼，必须懂工程学。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学不只是画图，还要考虑成本和安全。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好工程学，需要先学好数学和物理。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用工程学的方法改进了机器。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学让城市里的地铁越来越安全。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读了工程学，现在负责设计新的水系统。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "工程学：应用科学原理解决实际问题、设计建造的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：应用科学原理设计结构、机器的学科，用工程学视角看待堆肥的循环模型，符合语境。"}, {"text": "军事学", "is_correct": false, "explanation": "语义：军事学研究战争与国防，与家庭堆肥的低熵循环无关，「从军事学视角观之」说不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的“从……视角观之”不协调。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是研究结构或系统的学科，「从钢琴视角观之」说不通。"}], "explanations": {"工程学": "工程学：应用科学原理设计结构、机器的学科，用工程学视角看待堆肥的循环模型，符合语境。", "军事学": "语义：军事学研究战争与国防，与家庭堆肥的低熵循环无关，「从军事学视角观之」说不通。", "玩意儿": "语域：“玩意儿”是口语，与书面的“从……视角观之”不协调。", "钢琴": "语义：钢琴是乐器，不是研究结构或系统的学科，「从钢琴视角观之」说不通。"}, "sentence_index": 0, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工程学很大，要用两年才能完成。", "explanation": "这里应该用〈工程〉。工程指具体的建设项目，工程学是学科名称，不能指一项工程。"}, {"text": "他把工程学搬到了阳台上晒太阳。", "explanation": "这里应该用〈教材〉。工程学是学科，不能搬到阳台上；搬的是教材或书。"}, {"text": "他是一名工程学。", "explanation": "这里应该用〈工程师〉。工程学指学科，指人要说工程师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：应用科学原理解决实际问题的学科，填入“学好工程学”符合语境。"}, {"text": "书法", "is_correct": false, "explanation": "语义：学书法与数学和物理的基础无关，不需要先学数学和物理。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：学诗歌不需要先学数学和物理，句子的逻辑说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学”的对象是学科或技能，“空气”不能被“学好”。"}], "explanations": {"工程学": "工程学：应用科学原理解决实际问题的学科，填入“学好工程学”符合语境。", "书法": "语义：学书法与数学和物理的基础无关，不需要先学数学和物理。", "诗歌": "语义：学诗歌不需要先学数学和物理，句子的逻辑说不通。", "空气": "搭配：“学”的对象是学科或技能，“空气”不能被“学好”。"}, "sentence_index": 6, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工程学有三百名工人。", "explanation": "这里应该用〈工厂〉。工程学是学科，不能指拥有工人的单位。"}, {"text": "这门工程学的产品卖得很好。", "explanation": "这里应该用〈公司〉。工程学是学科，不生产也不卖产品；卖产品的是公司或工厂。"}, {"text": "这家工程学下个月要搬到新大楼。", "explanation": "这里应该用〈公司〉。工程学是学科，不能搬家，指单位要说公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她决定明年去大学学一个工程学。", "corrected_sentence": "她决定明年去大学学一门工程学。", "error_description": "量词错误：学科用“门”，不用“个”。应说“一门工程学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很工程学，老师都夸他。", "corrected_sentence": "他很懂工程学，老师都夸他。", "error_description": "「工程学」是名词，不能直接受「很」修饰；应在前面加动词「懂」，说「很懂工程学」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
