INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11566, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "实际上就是；真实情况是。", "primary_collocate": null, "pronunciation": "shí wéi", "ipa": "ʂɻ̩˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "从生态工程学视角观之，家庭堆肥实为一种低熵循环模型。", "target_word": "实为", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这件事看似简单，实为一场误会。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他表面很冷淡，实为一个热心的人。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画看起来很贵，实为一件仿品。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们叫它“蓝宝石”，实为一块普通的玻璃。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座“古城”实为二十年前新建的景区。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说是出差，实为去医院看病。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店名叫“学堂”，实为一家卖茶叶的小店。", "target_word": "实为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次活动名为比赛，实为一次交流。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说是来帮忙，实为添乱。", "target_word": "实为", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "實為", "label": "繁体"}], "register": "书面", "sense_fingerprint": "表面与实际不同，点明真实情况：实际上是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实为", "is_correct": true, "explanation": "实为：实际上就是，引出真实情况，与“家庭堆肥是一种循环模型”的判断一致。"}, {"text": "曾为", "is_correct": false, "explanation": "体貌：“曾为”表示过去的经历，与“从生态工程学视角观之”的现时判断不合。"}, {"text": "将为", "is_correct": false, "explanation": "语义：“将为”表示将来，与现时的判断语境不合。"}, {"text": "沦为", "is_correct": false, "explanation": "语义：“沦为”含贬义，指变坏，与客观判断的语境不合。"}], "explanations": {"实为": "实为：实际上就是，引出真实情况，与“家庭堆肥是一种循环模型”的判断一致。", "曾为": "体貌：“曾为”表示过去的经历，与“从生态工程学视角观之”的现时判断不合。", "将为": "语义：“将为”表示将来，与现时的判断语境不合。", "沦为": "语义：“沦为”含贬义，指变坏，与客观判断的语境不合。"}, "sentence_index": 0, "correct_answer": "实为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哎呀，你实为太坏了！", "explanation": "这里不宜用〈实为〉。实为是书面语，后接的应是判断性的名词成分，不能直接接形容词短语“太坏了”；感叹应说“你真坏”。"}, {"text": "我实为很喜欢吃辣的。", "explanation": "这里应该用〈其实〉。实为表示表面与实际相反，这句只是说明自己的喜好，前后没有反差，应用“其实”。"}, {"text": "我每天六点起床，实为七点吃早饭。", "explanation": "这里应该用〈然后〉。实为表示表面与实际相反，两件日常安排并不对立，只是先后顺序，应说“然后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当作", "is_correct": false, "explanation": "配价：“当作”需要“X当作Y”的结构，这里缺少被当作的对象。"}, {"text": "成了", "is_correct": false, "explanation": "语义：“成了”表示变成，与“说是出差”形成的对比不合。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示转变，不能用来引出“去医院看病”的真实目的。"}, {"text": "实为", "is_correct": true, "explanation": "实为：实际上是，引出与“说是出差”相反的真实情况，与语境一致。"}], "explanations": {"当作": "配价：“当作”需要“X当作Y”的结构，这里缺少被当作的对象。", "成了": "语义：“成了”表示变成，与“说是出差”形成的对比不合。", "变成": "语义：“变成”表示转变，不能用来引出“去医院看病”的真实目的。", "实为": "实为：实际上是，引出与“说是出差”相反的真实情况，与语境一致。"}, "sentence_index": 6, "correct_answer": "实为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说是来帮忙，实为来帮忙的。", "explanation": "这里应该用〈本来〉。实为表示表面与实际相反，前后说的是同一件事，没有反差，应说“本来”，不能用实为。"}, {"text": "他说是来帮忙，实为很能干。", "explanation": "这里不宜用〈实为〉。实为后接的是对真实情况的判断，不能直接接形容词短语“很能干”；应说“其实很能干”。"}, {"text": "他说是来帮忙，实为很高兴。", "explanation": "这里不宜用〈实为〉。实为不能直接接形容词短语“很高兴”，表达真实心情应说“其实很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片看起来很旧，实为实为一件新印的复制品。", "corrected_sentence": "这张照片看起来很旧，实为一件新印的复制品。", "error_description": "“实为”重复：“实为”只用一次，后面直接接真实情况，不能说“实为实为”。正确说法是“这张照片看起来很旧，实为一件新印的复制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说是逛街，实为了去图书馆读书。", "corrected_sentence": "他说是逛街，实为去图书馆读书。", "error_description": "“了”加在“实为”后面：“实为”是固定的连接词，后面直接接真实情况，不能带“了”。正确说法是“他说是逛街，实为去图书馆读书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
