INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机质是指土壤或环境中来自生物体的含碳有机物，是植物营养的重要来源。", "primary_collocate": null, "pronunciation": "yǒu jī zhì", "ipa": "joʊ˨˩˦ tɕi˥ ʈʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "有机质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "有机质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块地里的有机质很多，所以菜长得好。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "落叶烂掉以后会变成有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民给田里加了很多有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤里的有机质是植物的食物。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查土地时，他们先看有机质的含量。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机质少的土地，什么都长不大。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些树叶和草能给土壤带来有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的堆肥里有很多有机质。", "target_word": "有机质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机质含量", "label": "复合词"}, {"form": "土壤有机质", "label": "复合词"}], "register": "科技", "sense_fingerprint": "土壤中来自生物体的含碳有机物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机质", "is_correct": true, "explanation": "正确：「有机质」是生物来源、可在无氧条件下分解的物质，与「填埋」的语境一致。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁在无氧条件下不会像有机物那样分解，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「分解」一般用于有机物，「空气」不能说在无氧条件下「分解」。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是无机材料，不会在无氧条件下分解，「使玻璃分解」说不通。"}], "explanations": {"有机质": "正确：「有机质」是生物来源、可在无氧条件下分解的物质，与「填埋」的语境一致。", "钢铁": "语义：钢铁在无氧条件下不会像有机物那样分解，句意不通。", "空气": "搭配：「分解」一般用于有机物，「空气」不能说在无氧条件下「分解」。", "玻璃": "语义：玻璃是无机材料，不会在无氧条件下分解，「使玻璃分解」说不通。"}, "sentence_index": 0, "correct_answer": "有机质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天生产上百吨有机质。", "explanation": "这里应该用〈钢材〉。有机质是土壤或环境中来自生物体的物质，工厂生产的是钢材，不能说「有机质」。"}, {"text": "这座沙场每天运走几车有机质。", "explanation": "这里应该用〈沙子〉。沙场运走的是沙子，有机质是土壤或环境中的物质，不是沙场的产品。"}, {"text": "这座金矿每年产出几吨有机质。", "explanation": "这里应该用〈黄金〉。金矿产出的是黄金，有机质是土壤或环境中的物质，不能从金矿中产出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机质", "is_correct": true, "explanation": "正确：「有机质的含量」是土壤检测的常见指标，与句意一致。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「温度」一般说「温度高低」，不说「温度的含量」，与此不搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有「含量」，与土壤检测的指标无关。"}, {"text": "口感", "is_correct": false, "explanation": "语义：口感不是土壤检测项目，「口感的含量」说不通。"}], "explanations": {"有机质": "正确：「有机质的含量」是土壤检测的常见指标，与句意一致。", "温度": "搭配：「温度」一般说「温度高低」，不说「温度的含量」，与此不搭配。", "颜色": "语义：颜色没有「含量」，与土壤检测的指标无关。", "口感": "语义：口感不是土壤检测项目，「口感的含量」说不通。"}, "sentence_index": 6, "correct_answer": "有机质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都喝一杯有机质。", "explanation": "这里应该用〈牛奶〉。有机质是土壤或环境中的物质，不能当饮料喝，早上喝的应说牛奶。"}, {"text": "这块透明的玻璃是用有机质做成的。", "explanation": "这里应该用〈沙子〉。玻璃由沙子等无机原料烧制而成，有机质是土壤或环境中的物质，不能用来制玻璃。"}, {"text": "工人用有机质浇筑了地基。", "explanation": "这里应该用〈水泥〉。浇筑地基用水泥，有机质不是建筑材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的有机质含量得很高。", "corrected_sentence": "这块地的有机质含量很高。", "error_description": "「有机质含量」后直接接形容词「很高」作谓语，不用助词「得」。错误：「含量得很高」；正确：「含量很高」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地表面铺了一根有机质。", "corrected_sentence": "这块地表面铺了一层有机质。", "error_description": "「有机质」前应用量词「层」，「根」用于细长的物体，不能用来修饰「有机质」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "作用非常强烈的，尤指对环境影响大的", "primary_collocate": null, "pronunciation": "qiáng xiào", "ipa": "tɕʰjɑŋ˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "强效", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其中，厨余垃圾作为家庭废弃物中占比最高的组成部分，若仅以填埋或焚烧方式处置，不仅占用土地资源，更会产生甲烷等强效温室气体，加剧全球气候危机。", "target_word": "强效", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "甲烷是一种强效温室气体。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效气体会让地球变得更热。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的工厂排出强效污染物，河水变黑了。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强效的化学药剂会伤害土里的小虫。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些强效废气排到空中，对天气影响很大。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了强效除草剂以后，湖里的鱼少了。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不能随便排放强效有害气体。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究怎样减少强效温室气体。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強效", "label": "繁体"}], "register": "书面", "sense_fingerprint": "作用强烈、对环境影响大的（多修饰气体、污染物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强效", "is_correct": true, "explanation": "正确。强效，作用非常强烈。"}, {"text": "强笑", "is_correct": false, "explanation": "声调不同：「qiǎng」（第三声）与「qiáng」（第二声）不同，强笑指勉强地笑。"}, {"text": "长效", "is_correct": false, "explanation": "声母不同：「cháng」的 ch 与「qiáng」的 q 不同，长效指作用持久。"}, {"text": "降效", "is_correct": false, "explanation": "声母和声调都不同：「jiàng」的 j 与 q 不同，第四声与第二声也不同，降效指效率下降。"}, {"text": "轻笑", "is_correct": false, "explanation": "韵母不同：「qīng」与「qiáng」的 -ing／-ang 不同，声调也不同，轻笑指轻轻地笑。"}], "explanations": {"强效": "正确。强效，作用非常强烈。", "强笑": "声调不同：「qiǎng」（第三声）与「qiáng」（第二声）不同，强笑指勉强地笑。", "长效": "声母不同：「cháng」的 ch 与「qiáng」的 q 不同，长效指作用持久。", "降效": "声母和声调都不同：「jiàng」的 j 与 q 不同，第四声与第二声也不同，降效指效率下降。", "轻笑": "韵母不同：「qīng」与「qiáng」的 -ing／-ang 不同，声调也不同，轻笑指轻轻地笑。"}, "sentence_index": null, "correct_answer": "强效"}, "level_3": {"options": [{"text": "无害", "is_correct": false, "explanation": "语义：“无害”与“温室气体”造成危害的语境相矛盾。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“温室气体”，说明甲烷的作用强烈。"}, {"text": "温和", "is_correct": false, "explanation": "搭配：“温和”多形容性质、态度、药性，不用来形容温室气体。"}, {"text": "微弱", "is_correct": false, "explanation": "语义：「微弱」说作用小，与甲烷造成温室效应的语境相矛盾。"}], "explanations": {"无害": "语义：“无害”与“温室气体”造成危害的语境相矛盾。", "强效": "正确。“强效”修饰“温室气体”，说明甲烷的作用强烈。", "温和": "搭配：“温和”多形容性质、态度、药性，不用来形容温室气体。", "微弱": "语义：「微弱」说作用小，与甲烷造成温室效应的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很强效，谁也不敢惹他。", "explanation": "这里应该用〈强硬〉。强效说药物、气体等的作用力，形容人的态度和性格要用强硬。"}, {"text": "她对孩子的爱很强效。", "explanation": "这里应该用〈强烈〉。强效只用于说作用、效力，感情、爱意要说强烈。"}, {"text": "这场洪水造成的破坏很强效。", "explanation": "这里应该用〈严重〉。破坏的程度要说严重，强效说的是作用力强，不修饰破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微弱", "is_correct": false, "explanation": "语义：“微弱”说作用小，与后半句“对天气影响很大”相矛盾。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“废气”，说明排放物的作用强烈。"}, {"text": "轻微", "is_correct": false, "explanation": "搭配：“轻微”多修饰损害、症状，不用来形容废气，而且与“影响很大”矛盾。"}, {"text": "低效", "is_correct": false, "explanation": "语义：“低效”说效率低，不能用来形容废气的作用，与“影响很大”不合。"}], "explanations": {"微弱": "语义：“微弱”说作用小，与后半句“对天气影响很大”相矛盾。", "强效": "正确。“强效”修饰“废气”，说明排放物的作用强烈。", "轻微": "搭配：“轻微”多修饰损害、症状，不用来形容废气，而且与“影响很大”矛盾。", "低效": "语义：“低效”说效率低，不能用来形容废气的作用，与“影响很大”不合。"}, "sentence_index": 6, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的经济很强效。", "explanation": "这里应该用〈强大〉。国家、经济的实力和规模要说强大，强效只修饰作用或效力。"}, {"text": "他的身体很强效，从不生病。", "explanation": "这里应该用〈强壮〉。人的体质健壮要说强壮，强效不用来形容人的身体。"}, {"text": "老师对学生很强效。", "explanation": "这里应该用〈严厉〉。对人的态度要说严厉，强效不能用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汽车尾气里含有一条强效污染物，城市的空气很差。", "corrected_sentence": "汽车尾气里含有一种强效污染物，城市的空气很差。", "error_description": "错误：量词「条」用于细长的事物，污染物应用量词「种」。正确形式：一种强效污染物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民在地里用强效地除草剂，地下水容易受到污染。", "corrected_sentence": "农民在地里用强效除草剂，地下水容易受到污染。", "error_description": "错误：“强效地除草剂”，多加了“地”。强效直接修饰名词，中间不需要“的”或“地”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
