INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "温室是用透明材料建造的房屋，可以控制温度和湿度，用来种植植物。", "primary_collocate": null, "pronunciation": "wēn shì", "ipa": "wən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "为延长番茄的收获期，园区在北侧新建了一批可以调控温湿度的温室，并配备了自动通风与补光系统。", "target_word": "温室", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在寒冬季节，科研人员借助温室内可人工调控的光照与湿度，持续观察热带作物的整个生长周期。", "target_word": "温室", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "冬天，农民在温室里种西红柿。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室里很暖和，花开得很早。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个温室的玻璃很干净。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校后面有一个大温室。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上去温室给花浇水。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室里的温度不能太高。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在温室里看到了很多热带植物。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为外面很冷，所以草莓要种在温室里。", "target_word": "温室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "透明材料建成、可控温湿度、用来种植物的房屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "温室", "is_correct": true, "explanation": "正确答案。温室是用透明材料建造、可以控温控湿、用来种植物的房屋。"}, {"text": "问世", "is_correct": false, "explanation": "wèn（第四声）与 wēn（第一声）声调不同，意思是作品或事物公开出现，不是房屋。"}, {"text": "纹饰", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是器物上的装饰花纹，不是房屋。"}, {"text": "文史", "is_correct": false, "explanation": "wén 与 wēn 声调不同，shǐ 与 shì 声调也不同，意思是文学和历史，不是房屋。"}], "explanations": {"温室": "正确答案。温室是用透明材料建造、可以控温控湿、用来种植物的房屋。", "问世": "wèn（第四声）与 wēn（第一声）声调不同，意思是作品或事物公开出现，不是房屋。", "纹饰": "wén（第二声）与 wēn（第一声）声调不同，意思是器物上的装饰花纹，不是房屋。", "文史": "wén 与 wēn 声调不同，shǐ 与 shì 声调也不同，意思是文学和历史，不是房屋。"}, "sentence_index": null, "correct_answer": "温室"}, "level_3": {"options": [{"text": "温室", "is_correct": true, "explanation": "正确：温室是可人工调控温湿度的种植房屋，与句中「调控温湿度」「番茄」相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不能调控温湿度，也不能用于种植番茄。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不能调控温湿度，与种植无关。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是学生用的桌子，不能调控温湿度，也不能用于种植。"}], "explanations": {"温室": "正确：温室是可人工调控温湿度的种植房屋，与句中「调控温湿度」「番茄」相符。", "银行": "语义：银行是金融机构，不能调控温湿度，也不能用于种植番茄。", "书包": "语义：书包是装书的袋子，不能调控温湿度，与种植无关。", "课桌": "语义：课桌是学生用的桌子，不能调控温湿度，也不能用于种植。"}, "sentence_index": 0, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天我们去温室泡澡，很舒服。", "explanation": "这里应该用〈温泉〉。泡澡要在温泉里，温室是种植植物的房子，不能用来泡澡。"}, {"text": "这个房间的温室很高。", "explanation": "这里应该用〈温度〉。温室指种植植物的透明房屋，不能表示房间冷热的程度；说房间的冷热要用〈温度〉。"}, {"text": "昼夜温室相差很大，早晚要多穿衣服。", "explanation": "这里应该用〈温差〉。温室不能表示昼夜之间的温度变化；说温度相差多少要用〈温差〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不是种花浇水的地方，与「给花浇水」不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，不能在里面给花浇水。"}, {"text": "垃圾箱", "is_correct": false, "explanation": "搭配：「去」后的地点应能给花浇水，「垃圾箱」与此搭配不通。"}, {"text": "温室", "is_correct": true, "explanation": "正确。「去温室给花浇水」指到种植植物的房屋里照料花卉。"}], "explanations": {"银行": "语义：银行是金融机构，不是种花浇水的地方，与「给花浇水」不符。", "冰箱": "语义：冰箱用来冷藏食物，不能在里面给花浇水。", "垃圾箱": "搭配：「去」后的地点应能给花浇水，「垃圾箱」与此搭配不通。", "温室": "正确。「去温室给花浇水」指到种植植物的房屋里照料花卉。"}, "sentence_index": 6, "correct_answer": "温室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草莓要放进温室冷藏，才不会坏。", "explanation": "这里应该用〈冰箱〉。冷藏食物要用冰箱，温室是种植植物的房屋。"}, {"text": "妈妈用温室烤蛋糕。", "explanation": "这里应该用〈烤箱〉。烤箱用来烤食物，温室不能用来烤蛋糕。"}, {"text": "温室上放满了书。", "explanation": "这里应该用〈书架〉。书架用来放书，温室是种植植物的房屋，不能用来放书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在院子里建了一只温室。", "corrected_sentence": "农民在院子里建了一座温室。", "error_description": "量词错误：温室是房屋，应用「座」（或「个」），「只」用于动物等，不能修饰温室。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天，我们在温室上种了不少蔬菜。", "corrected_sentence": "冬天，我们在温室里种了不少蔬菜。", "error_description": "方位词错误：温室是封闭的房屋，应用「里」，「上」用于物体表面，不能说「温室上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
