INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "甲烷是最简单的有机化合物，化学式CH4，是天然气的主要成分，易燃。", "primary_collocate": null, "pronunciation": "jiǎ wán", "ipa": "tɕja˨˩˦ wan˧˥", "syllable_count": 2, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "甲烷", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其中，厨余垃圾作为家庭废弃物中占比最高的组成部分，若仅以填埋或焚烧方式处置，不仅占用土地资源，更会产生甲烷等强效温室气体，加剧全球气候危机。", "target_word": "甲烷", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "甲烷没有颜色，也没有味道。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然气的主要成分是甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲烷很容易着火，要小心。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛的肚子里会产生甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾在地下会慢慢放出甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿井里的甲烷太多，很危险。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的沼气池里有很多甲烷。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲烷是一种会让地球变暖的气体。", "target_word": "甲烷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "化学式CH4、天然气主要成分的最简单有机化合物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甲烷", "is_correct": true, "explanation": "正确。原句指甲烷，化学式 CH₄，是温室气体之一。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气不是温室气体，与后面的化学式 CH₄ 所指的物质不符。"}, {"text": "氢气", "is_correct": false, "explanation": "语义：氢气不是温室气体，与后面的化学式 CH₄ 对不上。"}, {"text": "污水", "is_correct": false, "explanation": "搭配：「温室气体」修饰的是「气体」，「污水」是液体，不能与「气体」搭配。"}], "explanations": {"甲烷": "正确。原句指甲烷，化学式 CH₄，是温室气体之一。", "氧气": "语义：氧气不是温室气体，与后面的化学式 CH₄ 所指的物质不符。", "氢气": "语义：氢气不是温室气体，与后面的化学式 CH₄ 对不上。", "污水": "搭配：「温室气体」修饰的是「气体」，「污水」是液体，不能与「气体」搭配。"}, "sentence_index": 0, "correct_answer": "甲烷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天喝一杯甲烷。", "explanation": "这里应该用〈牛奶〉。甲烷是气体，不能喝，喝的应是牛奶等液体。"}, {"text": "我们每天呼吸的是甲烷。", "explanation": "这里应该用〈氧气〉。人呼吸的是氧气，甲烷是可燃气体，不能用来呼吸。"}, {"text": "我最喜欢吃甲烷。", "explanation": "这里应该用〈糖〉。甲烷是气体，不能吃，喜欢吃的应是糖之类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会从地下放出。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：「放出」的对象应是气体、气味等，「电话」不能搭配。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不会从地下放出。"}, {"text": "甲烷", "is_correct": true, "explanation": "正确。垃圾分解时会在地下慢慢放出甲烷这种气体。"}], "explanations": {"桌子": "语义：桌子是家具，不会从地下放出。", "电话": "搭配：「放出」的对象应是气体、气味等，「电话」不能搭配。", "饼干": "语义：饼干是食品，不会从地下放出。", "甲烷": "正确。垃圾分解时会在地下慢慢放出甲烷这种气体。"}, "sentence_index": 6, "correct_answer": "甲烷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗户是用甲烷做的。", "explanation": "这里应该用〈玻璃〉。甲烷是气体，不能用来做窗户。"}, {"text": "老师用甲烷写字。", "explanation": "这里应该用〈粉笔〉。写字要用粉笔等书写工具，甲烷是气体，不能用来写字。"}, {"text": "下雨了，他撑着甲烷。", "explanation": "这里应该用〈雨伞〉。撑的是雨伞，甲烷是气体，不能用来撑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "矿井里漏出了一只甲烷，工人立刻撤离了。", "corrected_sentence": "矿井里漏出了一股甲烷，工人立刻撤离了。", "error_description": "量词错误：甲烷是气体，应用「股」；「只」用于动物等个体，不能修饰甲烷。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管道里的甲烷漏来出了。", "corrected_sentence": "管道里的甲烷漏出来了。", "error_description": "补语语序错误：「漏出来」是动词加趋向补语的结构，应说「漏出来」，不能说「漏来出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
