INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氧是化学元素，符号O，无色无味的气体，是生命和燃烧必需的物质。", "primary_collocate": null, "pronunciation": "yǎng", "ipa": "jɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "燃烧需要三个条件：可燃物、足够的温度，还有氧。", "target_word": "氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氧是一种没有颜色的气体。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水是由氢和氧组成的。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人每天都要吸进氧。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火没有氧就烧不起来。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "血液把氧送到身体的每个地方。", "target_word": "氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物在白天会放出氧。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金属在潮湿的空气中会与氧反应生锈。", "target_word": "氧", "complexity_tier": "T3", "furigana": "jīnshǔ zài cháoshī de kōngqì zhōng huì yǔ yǎng fǎnyìng shēngxiù", "sentence_source": "generated"}, {"text": "医生让病人吸了一些氧。", "target_word": "氧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一瓶氧。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "氧气", "label": "复合词"}, {"form": "缺氧", "label": "复合词"}, {"form": "液氧", "label": "复合词"}], "register": "科技", "sense_fingerprint": "化学元素O，生命和燃烧必需的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氧", "is_correct": true, "explanation": "氧读 yǎng（第三声），是本题的正确词，指氧元素。"}, {"text": "羊", "is_correct": false, "explanation": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是羊」。"}, {"text": "样", "is_correct": false, "explanation": "「yǎng（第三声）与 yàng（第四声）声调不同，意思是样子、样品」。"}, {"text": "眼", "is_correct": false, "explanation": "「ng 与 n 韵尾不同，yǎn 意思是眼睛」。"}, {"text": "阳", "is_correct": false, "explanation": "「声调不同，yáng 意思是太阳、阳光」。"}], "explanations": {"氧": "氧读 yǎng（第三声），是本题的正确词，指氧元素。", "羊": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是羊」。", "样": "「yǎng（第三声）与 yàng（第四声）声调不同，意思是样子、样品」。", "眼": "「ng 与 n 韵尾不同，yǎn 意思是眼睛」。", "阳": "「声调不同，yáng 意思是太阳、阳光」。"}, "sentence_index": null, "correct_answer": "氧"}, "level_3": {"options": [{"text": "氧", "is_correct": true, "explanation": "正确：燃烧的第三个条件是氧（助燃），句中「还有」引出的正是氧。"}, {"text": "氮", "is_correct": false, "explanation": "语义：氮不能助燃，燃烧并不需要氮。"}, {"text": "水", "is_correct": false, "explanation": "语义：水能灭火，燃烧并不需要水。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐与燃烧无关，不是燃烧的条件。"}], "explanations": {"氧": "正确：燃烧的第三个条件是氧（助燃），句中「还有」引出的正是氧。", "氮": "语义：氮不能助燃，燃烧并不需要氮。", "水": "语义：水能灭火，燃烧并不需要水。", "盐": "语义：盐与燃烧无关，不是燃烧的条件。"}, "sentence_index": 0, "correct_answer": "氧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多新型汽车改用氧做燃料。", "explanation": "这里应该用〈氢〉。氢能燃烧，可以作燃料；氧只能助燃，不能作燃料。"}, {"text": "氧层能挡住太阳的紫外线。", "explanation": "这里应该用〈臭氧〉。能挡紫外线的是臭氧层，“氧层”不是这个词。"}, {"text": "孩子们在公园里玩耍，手里拿着几个充了氧的气球，气球轻轻地飘到了天上。", "explanation": "这里应该用〈氦〉。氧比空气略重，充了氧的气球飘不起来；能飘上天的要充氦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氧", "is_correct": true, "explanation": "氧读 yǎng（第三声），是本题的正确词，指氧元素。"}, {"text": "秧", "is_correct": false, "explanation": "「yǎng（第三声）与 yāng（第一声）声调不同，意思是稻秧」。"}, {"text": "央", "is_correct": false, "explanation": "「声调不同，yāng 意思是中央」。"}, {"text": "洋", "is_correct": false, "explanation": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是海洋」。"}, {"text": "扬", "is_correct": false, "explanation": "「声调不同，yáng 意思是扬起、飞扬」。"}], "explanations": {"氧": "氧读 yǎng（第三声），是本题的正确词，指氧元素。", "秧": "「yǎng（第三声）与 yāng（第一声）声调不同，意思是稻秧」。", "央": "「声调不同，yāng 意思是中央」。", "洋": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是海洋」。", "扬": "「声调不同，yáng 意思是扬起、飞扬」。"}, "sentence_index": null, "correct_answer": "氧"}, "level_3": {"options": [{"text": "氧", "is_correct": true, "explanation": "正确：白天植物通过光合作用释放的是氧。"}, {"text": "氢", "is_correct": false, "explanation": "语义：植物不会在白天向外放出氢，光合作用放出的是氧。"}, {"text": "氮", "is_correct": false, "explanation": "语义：植物不会向外放出氮，句中“放出”的应是氧。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“放出”后接的是气体，糖是固体，植物不向外放出糖。"}], "explanations": {"氧": "正确：白天植物通过光合作用释放的是氧。", "氢": "语义：植物不会在白天向外放出氢，光合作用放出的是氧。", "氮": "语义：植物不会向外放出氮，句中“放出”的应是氧。", "糖": "搭配：“放出”后接的是气体，糖是固体，植物不向外放出糖。"}, "sentence_index": 6, "correct_answer": "氧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一块氧。", "explanation": "这里量词用错。氧是气体，“块”用于固体，应说“一瓶氧”。"}, {"text": "我买了一只氧。", "explanation": "这里量词用错。“只”不用于气体，应说“一瓶氧”。"}, {"text": "我买了一颗氧。", "explanation": "这里量词用错。“颗”用于颗粒状的东西，氧是气体，应说“一瓶氧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病人每天都要氧吸。", "corrected_sentence": "病人每天都要吸氧。", "error_description": "错误：“氧吸”。正确：“吸氧”。“吸氧”是动宾结构，氧要放在“吸”之后，不能前置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林每天都会出放大量的氧。", "corrected_sentence": "这片森林每天都会放出大量的氧。", "error_description": "错误：“出放”。正确：“放出”。补语“出”要紧跟动词“放”，不能放在“放”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "封闭起来保存或停止使用。", "primary_collocate": null, "pronunciation": "fēng cún", "ipa": "fəŋ˥ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "封存", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这批旧文件已经封存十年了。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把过期的合同全部封存起来。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把爷爷写的旧信件封存在木箱里。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院决定封存这台出问题的机器，不再使用。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察封存了现场找到的所有证据。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些档案要封存三十年才能公开。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧厂房里的设备早就封存了，没人用。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆把珍贵的文物封存在恒温库房里。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院下令封存这家公司的账本。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "封存了", "label": "完成体（了）"}, {"form": "封存过", "label": "经历体（过）"}, {"form": "封存着", "label": "持续体（着）"}], "register": "书面", "sense_fingerprint": "封闭起来保存或停止使用（档案、证据、设备等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排放", "is_correct": false, "explanation": "语义：“排放”指向外排出，与“封存”把碳素留在土壤之中的方向相反。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”会把碳素烧掉，与“转化为稳定腐殖质”的语境相矛盾。"}, {"text": "封存", "is_correct": true, "explanation": "封存：封闭保存，使碳素留在土壤基质之中，与“稳定腐殖质”的语境一致。"}, {"text": "销毁", "is_correct": false, "explanation": "搭配：“销毁”的对象多为文件、物品，不说“销毁碳素”。"}], "explanations": {"排放": "语义：“排放”指向外排出，与“封存”把碳素留在土壤之中的方向相反。", "燃烧": "语义：“燃烧”会把碳素烧掉，与“转化为稳定腐殖质”的语境相矛盾。", "封存": "封存：封闭保存，使碳素留在土壤基质之中，与“稳定腐殖质”的语境一致。", "销毁": "搭配：“销毁”的对象多为文件、物品，不说“销毁碳素”。"}, "sentence_index": 0, "correct_answer": "封存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天封存在公司里加班。", "explanation": "这里应该用〈待〉。封存的对象是物品或档案，不能用于人的活动；说人待在某处应说“待”。"}, {"text": "他把小弟弟封存在木箱里。", "explanation": "这里应该用〈关〉。封存指把物品收起来保存，把人关进箱子是“关闭、禁锢”的意思，应说“关”，封存不能用于人。"}, {"text": "这场比赛已经封存了。", "explanation": "这里应该用〈结束〉。封存指把物品收起来保存，比赛是一项活动，已经结束不能说封存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展出", "is_correct": false, "explanation": "语义：“展出”意味着已经公开陈列，与“要封存三十年才能公开”的说法矛盾。"}, {"text": "复印", "is_correct": false, "explanation": "体貌：“复印”是一次完成的动作，不能持续三十年。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是抹去，与“三十年后才能公开”的语境不合。"}, {"text": "封存", "is_correct": true, "explanation": "封存：封闭保存，档案要先被保存三十年，所以才能在之后公开。"}], "explanations": {"展出": "语义：“展出”意味着已经公开陈列，与“要封存三十年才能公开”的说法矛盾。", "复印": "体貌：“复印”是一次完成的动作，不能持续三十年。", "删除": "语义：“删除”是抹去，与“三十年后才能公开”的语境不合。", "封存": "封存：封闭保存，档案要先被保存三十年，所以才能在之后公开。"}, "sentence_index": 6, "correct_answer": "封存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂把原料封存在仓库里，随时可以用。", "explanation": "这里应该用〈储存〉。封存是封起来暂不使用，与“随时可以用”矛盾。"}, {"text": "这瓶牛奶我封存了，等会儿就喝掉。", "explanation": "这里应该用〈饮用〉。封存指收起来暂不使用，牛奶马上要喝，表示饮用应说“饮用”，不能用封存。"}, {"text": "这件衣服我每天都穿，却把它封存在柜子里。", "explanation": "这里应该用〈收〉。封存指封起来暂不使用，衣服每天都穿，只是收进柜子里，应说“收”，不能用封存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这些旧档案把封存在仓库里了。", "corrected_sentence": "我把这些旧档案封存在仓库里了。", "error_description": "“把”字重复：把字句只用一个“把”，“把这些旧档案”后面不能再加“把”。正确说法是“我把这些旧档案封存在仓库里了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院已经把这些账本封存。", "corrected_sentence": "法院已经把这些账本封存了。", "error_description": "“了”漏掉：“把”字句表示已完成时，动词后应加“了”，说“封存了”。正确说法是“法院已经把这些账本封存了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
