INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11579, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "碳，化学元素，符号C，非金属，是构成有机物的重要元素。", "primary_collocate": null, "pronunciation": "tàn sù", "ipa": "tʰan˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "碳素", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "钢里含有少量碳素。", "target_word": "碳素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "植物通过光合作用把碳素固定下来。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "zhí wù tōng guò guāng hé zuò yòng bǎ tàn sù gù dìng xià lái。", "sentence_source": "generated"}, {"text": "碳素是构成有机物的重要元素。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤里的碳素越多，土地越肥。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烧木头的时候，木头里的碳素会变成气体。", "target_word": "碳素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥能把碳素留在土里。", "target_word": "碳素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物吃了食物，就得到了食物里的碳素。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤里碳素的含量很高，所以烧起来很热。", "target_word": "碳素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "碳素是一种非金属元素，符号为C。", "target_word": "碳素", "complexity_tier": "T3", "furigana": "tàn sù shì yì zhǒng fēi jīn shǔ yuán sù，fú hào wéi C。", "sentence_source": "generated"}], "morphological_forms": [{"form": "碳素钢", "label": "复合"}], "register": "书面", "sense_fingerprint": "碳素|化学元素碳，构成有机物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碳素", "is_correct": true, "explanation": "碳素：指被固定进土壤的碳元素，与句意相合。"}, {"text": "甲烷", "is_correct": false, "explanation": "语义：甲烷是句中被释放的温室气体，不能说“封存甲烷于土壤之中”。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是堆肥与填埋的反应条件，不是被封存的物质。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：句中被填埋的是垃圾，堆肥后封存的是转化产物中的碳素，“封存垃圾于土壤基质之中”不合语境。"}], "explanations": {"碳素": "碳素：指被固定进土壤的碳元素，与句意相合。", "甲烷": "语义：甲烷是句中被释放的温室气体，不能说“封存甲烷于土壤之中”。", "氧气": "语义：氧气是堆肥与填埋的反应条件，不是被封存的物质。", "垃圾": "语义：句中被填埋的是垃圾，堆肥后封存的是转化产物中的碳素，“封存垃圾于土壤基质之中”不合语境。"}, "sentence_index": 0, "correct_answer": "碳素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽水里含有大量碳素。", "explanation": "这里应该用〈碳酸〉。汽水中溶解的是碳酸等化合物，“碳素”指单质元素碳，不能这样说。"}, {"text": "他每天早上喝碳素。", "explanation": "这里应该用〈水〉。碳素是化学元素，是固体单质，不能当饮料喝；“碳素”不指可饮用的液体。"}, {"text": "石灰石的主要成分是碳素。", "explanation": "这里应该用〈碳酸钙〉。石灰石的主要成分是化合物碳酸钙，“碳素”只指单质碳元素。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碳素", "is_correct": true, "explanation": "碳素：堆肥所留下的碳元素，与“留在土里”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：堆肥留下的是有机物转化的碳，石头与堆肥的作用无关。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“留在土里”的对象应是堆肥转化来的物质，玻璃不是堆肥会留在土中的东西。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：烟雾是气态且会散去，与“留在土里”相矛盾。"}], "explanations": {"碳素": "碳素：堆肥所留下的碳元素，与“留在土里”相合。", "石头": "语义：堆肥留下的是有机物转化的碳，石头与堆肥的作用无关。", "玻璃": "搭配：“留在土里”的对象应是堆肥转化来的物质，玻璃不是堆肥会留在土中的东西。", "烟雾": "语义：烟雾是气态且会散去，与“留在土里”相矛盾。"}, "sentence_index": 6, "correct_answer": "碳素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做菜时要放碳素，味道才好。", "explanation": "这里应该用〈盐〉。碳素是化学元素，不是调味品，做菜时不用。"}, {"text": "玻璃的主要原料是碳素。", "explanation": "这里应该用〈二氧化硅〉。玻璃的主要原料是二氧化硅，碳素不是玻璃的主要原料。"}, {"text": "这杯茶里加了一块碳素。", "explanation": "这里应该用〈糖〉。碳素是化学元素，不是可以加进茶里的甜味食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "钢里含有一只碳素，正是它让钢比铁更硬。", "corrected_sentence": "钢里含有一种碳素，正是它让钢比铁更硬。", "error_description": "量词错误：“碳素”是物质名词，指物质时用量词“种”，应说“一种碳素”；“一只碳素”误用了指动物或成对器物的“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无烟煤里的碳素们含量很高。", "corrected_sentence": "无烟煤里的碳素含量很高。", "error_description": "错误：“们”只用于指人的复数，“碳素”是物质名词，不能加“们”。“碳素们”不通，应说“碳素含量很高”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
