INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基质指在混合物或结构中起支撑、填充或提供生长环境的基础物质。", "primary_collocate": null, "pronunciation": "jī zhì", "ipa": "tɕi˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "传统填埋使有机质在无氧条件下分解，释放强效温室气体甲烷（CH₄），而好氧堆肥则将其转化为稳定腐殖质，封存碳素于土壤基质之中。", "target_word": "基质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种花适合种在疏松的基质里。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草莓可以种在泥炭基质里。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用椰糠做花盆的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基质太湿，植物的根会烂掉。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无土栽培需要用特殊的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换盆时，要换上新的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珍珠岩能让基质更透气。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水苔是兰花常用的基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋基质里有土和沙子。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤基质", "label": "复合"}, {"form": "栽培基质", "label": "复合"}, {"form": "袋", "label": "量词"}, {"form": "基質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "支撑植物根系、提供生长环境的栽培介质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11581, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指种植时支撑根系、提供生长环境的基础介质。"}, {"text": "极致", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。"}, {"text": "几只", "is_correct": false, "explanation": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。"}, {"text": "寄至", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}], "explanations": {"基质": "正确。基质指种植时支撑根系、提供生长环境的基础介质。", "极致": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。", "几只": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。", "寄至": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。此处指土壤中用于封存碳素的基础介质，与“土壤……之中”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能封存碳素，“土壤价格之中”句意不通。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“土壤色彩”不是常用说法，色彩也不能容纳碳素。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以封存碳素的介质，句意不通。"}], "explanations": {"基质": "正确。此处指土壤中用于封存碳素的基础介质，与“土壤……之中”相符。", "价格": "语义：价格不能封存碳素，“土壤价格之中”句意不通。", "色彩": "搭配：“土壤色彩”不是常用说法，色彩也不能容纳碳素。", "时间": "语义：时间不是可以封存碳素的介质，句意不通。"}, "sentence_index": 0, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把基质垫在头下睡觉。", "explanation": "这里应该用〈枕头〉。基质指种植用的支撑材料，不用来垫头。"}, {"text": "书架上的基质很整齐。", "explanation": "这里应该用〈书〉。基质指种植或支撑用的基础材料，不指书籍。"}, {"text": "我用基质写信。", "explanation": "这里应该用〈纸〉。基质是种植用的支撑材料，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11581, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指种植时支撑根系、提供生长环境的基础介质。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。"}, {"text": "精致", "is_correct": false, "explanation": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。"}, {"text": "鸡只", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}], "explanations": {"基质": "正确。基质指种植时支撑根系、提供生长环境的基础介质。", "资质": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。", "精致": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。", "鸡只": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。换盆时换上的是种植用的基础介质，与“新的”搭配。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：换盆时不换歌曲，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“换上”不能用于天空，天空无法作为可更换的物品。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：换盆与眼镜无关，“换上新的眼镜”在此句中不通。"}], "explanations": {"基质": "正确。换盆时换上的是种植用的基础介质，与“新的”搭配。", "歌曲": "语义：换盆时不换歌曲，句意不通。", "天空": "搭配：“换上”不能用于天空，天空无法作为可更换的物品。", "眼镜": "语义：换盆与眼镜无关，“换上新的眼镜”在此句中不通。"}, "sentence_index": 6, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用基质洗头。", "explanation": "这里应该用〈洗发水〉。基质指种植用的基础材料，不能用来洗头。"}, {"text": "工人用基质修理自行车。", "explanation": "这里应该用〈扳手〉。基质指种植用的基础材料，不能用来修车。"}, {"text": "孩子用基质擦黑板。", "explanation": "这里应该用〈黑板擦〉。基质是种植用的基础材料，不用于擦拭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一只旧基质换掉了。", "corrected_sentence": "我把一袋旧基质换掉了。", "error_description": "量词错误：“基质”应以“袋”计量，不能用“只”（“只”用于动物或单个物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盆花用的基质们很透气。", "corrected_sentence": "这盆花用的基质很透气。", "error_description": "“们”不能加在物质名词“基质”后表示复数，句中应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指有机物质在微生物作用下分解、发酵，变成可被植物吸收的肥料的过程。", "primary_collocate": null, "pronunciation": "fǔ shú", "ipa": "fu˨˩˦ ʂu˧˥", "syllable_count": 2, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "腐熟", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "腐熟", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "树叶要放半年才能腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥腐熟以后，才可以放进花盆。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，肥料腐熟得很慢。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把粪便堆起来，让它慢慢腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有腐熟的肥料会烧坏小苗。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房垃圾腐熟需要很多时间。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加一点水，落叶会腐熟得更快。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腐熟完成后，堆肥变成了黑褐色。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐熟了", "label": "体标"}, {"form": "腐熟过", "label": "体标"}], "register": "书面", "sense_fingerprint": "有机物经微生物分解发酵变成肥料的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复述", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是复述，即把话再说一遍。"}, {"text": "腐熟", "is_correct": true, "explanation": "正确答案。腐熟指有机物在微生物作用下分解、变成可用的肥料。"}, {"text": "腐蚀", "is_correct": false, "explanation": "shí（第二声）与 shú（第二声）韵母不同，意思是腐蚀，指物质被侵蚀损坏。"}, {"text": "服输", "is_correct": false, "explanation": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。"}], "explanations": {"复述": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是复述，即把话再说一遍。", "腐熟": "正确答案。腐熟指有机物在微生物作用下分解、变成可用的肥料。", "腐蚀": "shí（第二声）与 shú（第二声）韵母不同，意思是腐蚀，指物质被侵蚀损坏。", "服输": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。"}, "sentence_index": null, "correct_answer": "腐熟"}, "level_3": {"options": [{"text": "腐熟", "is_correct": true, "explanation": "正确：腐熟指有机物分解成可用的肥料，与「产物被施用于园艺」的语境相符。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印是把文字印在纸上，与有机肥的产物毫无关系，句意不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是被火烧坏，与「施用于家庭园艺、改善土壤」的用途相反。"}, {"text": "漂白", "is_correct": false, "explanation": "搭配：漂白多用于布匹、纸张，不能用来修饰有机肥的产物。"}], "explanations": {"腐熟": "正确：腐熟指有机物分解成可用的肥料，与「产物被施用于园艺」的语境相符。", "打印": "语义：打印是把文字印在纸上，与有机肥的产物毫无关系，句意不通。", "烧毁": "语义：烧毁是被火烧坏，与「施用于家庭园艺、改善土壤」的用途相反。", "漂白": "搭配：漂白多用于布匹、纸张，不能用来修饰有机肥的产物。"}, "sentence_index": 0, "correct_answer": "腐熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面团腐熟以后，才能放进蒸笼里。", "explanation": "这里应该用〈发酵〉。腐熟指有机物分解成肥料，面团变松软要说发酵。"}, {"text": "这筐香蕉放久了，已经腐熟了。", "explanation": "这里应该用〈腐烂〉。腐熟指有机物分解成可用的肥料，水果变坏变烂要说腐烂。"}, {"text": "这块铁板在雨里放了一年，已经腐熟了。", "explanation": "这里应该用〈生锈〉。腐熟指有机物分解成肥料，铁板在雨里变质要说生锈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐熟", "is_correct": true, "explanation": "正确：肥料充分腐熟后才能用，句中「没有腐熟」才会导致烧苗，与句意相符。"}, {"text": "施用", "is_correct": false, "explanation": "语义：施用指已经使用肥料，「没有施用」却「会烧坏小苗」，逻辑不通。"}, {"text": "储存", "is_correct": false, "explanation": "语义：储存只是存放，不会因此烧坏小苗，与句中的因果关系不符。"}, {"text": "加热", "is_correct": false, "explanation": "搭配：「加热」多用于食物、水，不用于描述肥料的状态，且与「没有」连用后句意不通。"}], "explanations": {"腐熟": "正确：肥料充分腐熟后才能用，句中「没有腐熟」才会导致烧苗，与句意相符。", "施用": "语义：施用指已经使用肥料，「没有施用」却「会烧坏小苗」，逻辑不通。", "储存": "语义：储存只是存放，不会因此烧坏小苗，与句中的因果关系不符。", "加热": "搭配：「加热」多用于食物、水，不用于描述肥料的状态，且与「没有」连用后句意不通。"}, "sentence_index": 6, "correct_answer": "腐熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水在通电后腐熟成氢气和氧气。", "explanation": "这里应该用〈分解〉。水分解成氢和氧是化学变化，腐熟只指有机物变成肥料。"}, {"text": "这台电视放进酸液里，慢慢腐熟了。", "explanation": "这里应该用〈腐蚀〉。腐熟指有机物分解成肥料，金属和电器被酸侵蚀要说腐蚀。"}, {"text": "他的脸色腐熟了，看起来很难受。", "explanation": "这里应该用〈发白〉。腐熟指有机物分解成肥料，脸色变苍白要说发白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堆树枝在潮湿的地方腐熟很慢。", "corrected_sentence": "这堆树枝在潮湿的地方腐熟得很慢。", "error_description": "错误形式：腐熟很慢；正确形式：腐熟得很慢。动词后带形容词作补语时，中间要用「得」连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堆枯草慢慢腐熟了成肥料。", "corrected_sentence": "这堆枯草慢慢腐熟成了肥料。", "error_description": "错误形式：腐熟了成；正确形式：腐熟成了。结果补语「成」应紧跟动词「腐熟」，动态助词「了」放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
