INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土壤中由矿物质颗粒和有机物粘结而成的稳定团聚体。", "primary_collocate": null, "pronunciation": "tuán lì jié gòu", "ipa": "tʰwan˧˥ li˥˩ tɕje˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "团粒结构", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "团粒结构", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好的土壤有很好的团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓能帮助土壤形成团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团粒结构好，土壤就能保水。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用有机肥改善土壤的团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙土的团粒结构很差，留不住水。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团粒结构让土壤既透气又保水。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用显微镜讲土壤的团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨太多会破坏田地的团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤团粒结构", "label": "复合"}], "register": "专业", "sense_fingerprint": "团粒结构|名词|土壤稳定团聚体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：土壤没有可以“改善”的噪音，噪音与土壤的结构和性质无关。"}, {"text": "团粒结构", "is_correct": true, "explanation": "正确：“改善土壤”后接“团粒结构”，指土壤中矿物颗粒与有机物粘结成的稳定团聚体。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“改善”一般不与“价格”搭配，土壤也没有价格可以改善。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或事物的外表，此处应指土壤的内部结构，不能说“改善土壤外貌”来提升保水保肥能力。"}], "explanations": {"噪音": "语义：土壤没有可以“改善”的噪音，噪音与土壤的结构和性质无关。", "团粒结构": "正确：“改善土壤”后接“团粒结构”，指土壤中矿物颗粒与有机物粘结成的稳定团聚体。", "价格": "搭配：“改善”一般不与“价格”搭配，土壤也没有价格可以改善。", "外貌": "体貌：“外貌”指人或事物的外表，此处应指土壤的内部结构，不能说“改善土壤外貌”来提升保水保肥能力。"}, "sentence_index": 0, "correct_answer": "团粒结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地的团粒结构很黏，不适合种花。", "explanation": "这里应该用〈土壤质地〉。团粒结构指土壤颗粒团聚形成的结构，描述的是松散与透气的程度；说土壤黏不黏要用“土壤质地”。"}, {"text": "这块地的团粒结构增产了三成。", "explanation": "这里应该用〈产量〉。“增产”说的是作物收成的增加，团粒结构是土壤的结构状态，不能说增产。"}, {"text": "这块地的团粒结构很足，庄稼不用再施肥。", "explanation": "这里应该用〈养分〉。团粒结构只说结构的好坏，说养分充足要用“养分”，不能说“团粒结构很足”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视力", "is_correct": false, "explanation": "语义：沙土没有视力，“视力很差”说的是人或动物的眼睛能力，与沙土无关。"}, {"text": "团粒结构", "is_correct": true, "explanation": "正确：“沙土的团粒结构很差”指沙土中团聚体结构不好，所以留不住水。"}, {"text": "记忆力", "is_correct": false, "explanation": "语义：沙土没有记忆，“记忆力很差”与“留不住水”的说法毫不相干。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”多用于人或动物的性情，一般不用来说沙土的状况。"}], "explanations": {"视力": "语义：沙土没有视力，“视力很差”说的是人或动物的眼睛能力，与沙土无关。", "团粒结构": "正确：“沙土的团粒结构很差”指沙土中团聚体结构不好，所以留不住水。", "记忆力": "语义：沙土没有记忆，“记忆力很差”与“留不住水”的说法毫不相干。", "脾气": "搭配：“脾气”多用于人或动物的性情，一般不用来说沙土的状况。"}, "sentence_index": 6, "correct_answer": "团粒结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在田里施用团粒结构，庄稼很快长大了。", "explanation": "这里应该用〈肥料〉。团粒结构是土壤的结构状态，不能被施用；施用的应是“肥料”。"}, {"text": "春天，山坡上开满了团粒结构。", "explanation": "这里应该用〈野花〉。“开”用于花朵，团粒结构是土壤的结构状态，不会开放；说花开要用“野花”这类词。"}, {"text": "这座城市的团粒结构很发达，街上很热闹。", "explanation": "这里应该用〈工业〉。“发达”可用于工业、交通等，团粒结构是土壤的结构，不能用来形容城市的发展水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "施用腐熟有机肥以后，地里的团粒结构慢慢变了好。", "corrected_sentence": "施用腐熟有机肥以后，地里的团粒结构慢慢变好了。", "error_description": "结果补语“好”应紧跟动词“变”，构成“变好”，“了”放在句末，即“变好了”；“变了好”语序不通，把“了”插在了补语之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水太多的时候，田地的团粒结构们容易被破坏。", "corrected_sentence": "雨水太多的时候，田地的团粒结构容易被破坏。", "error_description": "“团粒结构”指土壤的结构状态，是不可数的名词，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
