INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保持土壤的肥力，使其适合植物生长。", "primary_collocate": null, "pronunciation": "bǎo féi", "ipa": "paʊ̯˨˩˦ feɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "保肥", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "保肥", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种土壤保水又保肥，种菜长得很好。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙土不保肥，一下雨，肥料就流走了。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里加入有机肥，是为了让土壤更好地保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黏土的保肥能力比沙土强。", "target_word": "保肥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地保肥差，要多施一些有机肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农说，种树前先改良土壤，才能保肥保水。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秸秆还田既能保肥，又能减少化肥的使用。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的土壤既能保水，也能保肥，作物才长得好。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保水保肥", "label": "复合"}, {"form": "保肥能力", "label": "复合"}], "register": "书面", "sense_fingerprint": "保持土壤肥力、不让养分流失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确答案。保肥指保持土壤的肥力，使养分不流失。"}, {"text": "保费", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是保险费。"}, {"text": "报废", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）、fèi（第四声）与 féi（第二声）声调不同，意思是报废，即不再使用。"}, {"text": "暴肥", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是短时间内身体迅速长肉，与土壤无关。"}], "explanations": {"保肥": "正确答案。保肥指保持土壤的肥力，使养分不流失。", "保费": "féi（第二声）与 fèi（第四声）声调不同，意思是保险费。", "报废": "bào（第四声）与 bǎo（第三声）、fèi（第四声）与 féi（第二声）声调不同，意思是报废，即不再使用。", "暴肥": "bào（第四声）与 bǎo（第三声）声调不同，意思是短时间内身体迅速长肉，与土壤无关。"}, "sentence_index": null, "correct_answer": "保肥"}, "level_3": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确：保肥指保持土壤养分，与「保水」并列修饰「能力」，句意通顺。"}, {"text": "流失", "is_correct": false, "explanation": "语义：流失指东西漏掉，与「保」的意思相反，和「提升能力」矛盾。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：蒸发指水分散失到空气中，与「保水」相反，句意不通。"}, {"text": "漏水", "is_correct": false, "explanation": "搭配：「漏水」是动宾短语，不能与「保水」并列修饰「能力」。"}], "explanations": {"保肥": "正确：保肥指保持土壤养分，与「保水」并列修饰「能力」，句意通顺。", "流失": "语义：流失指东西漏掉，与「保」的意思相反，和「提升能力」矛盾。", "蒸发": "语义：蒸发指水分散失到空气中，与「保水」相反，句意不通。", "漏水": "搭配：「漏水」是动宾短语，不能与「保水」并列修饰「能力」。"}, "sentence_index": 0, "correct_answer": "保肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件棉衣很保肥，冬天穿着很暖和。", "explanation": "这里应该用〈保温〉。保肥指土壤保持养分，衣服保暖要说保温。"}, {"text": "春天给果树保肥，果子才会长得多。", "explanation": "这里应该用〈施肥〉。保肥是让土壤保持养分，给果树加肥要说施肥。"}, {"text": "妈妈每天给我保肥，我才长得高。", "explanation": "这里应该用〈滋补〉。保肥指土壤保持养分，给人的身体提供营养要说滋补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确：保肥指使土壤保持养分，与后句「要多施有机肥」相呼应。"}, {"text": "育肥", "is_correct": false, "explanation": "搭配：育肥多指给牲畜增肥，不用于说土地。"}, {"text": "保鲜", "is_correct": false, "explanation": "语义：保鲜指使食物保持新鲜，与土地的肥力无关，句意不通。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：喂养是饲养动物，与土地的肥力无关，句意不通。"}], "explanations": {"保肥": "正确：保肥指使土壤保持养分，与后句「要多施有机肥」相呼应。", "育肥": "搭配：育肥多指给牲畜增肥，不用于说土地。", "保鲜": "语义：保鲜指使食物保持新鲜，与土地的肥力无关，句意不通。", "喂养": "语义：喂养是饲养动物，与土地的肥力无关，句意不通。"}, "sentence_index": 6, "correct_answer": "保肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "给玉米保肥，能让根站稳。", "explanation": "这里应该用〈培土〉。保肥是保持土壤养分，让玉米根站稳要说培土。"}, {"text": "这台冰箱很保肥，食物放很久也不坏。", "explanation": "这里应该用〈保鲜〉。保肥只用于土壤和肥料，冰箱保持食物新鲜要说保鲜。"}, {"text": "这头猪吃得很好，很快就保肥了。", "explanation": "这里应该用〈增肥〉。保肥只指保持土壤养分，猪长膘要说增肥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块土层厚的地被保肥，庄稼长得好。", "corrected_sentence": "这块土层厚的地能保肥，庄稼长得好。", "error_description": "错误形式：被保肥；正确形式：能保肥。「保肥」是主动动词，不能直接加「被」；表示能力应用助动词「能」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片新开的荒地保肥很，需要年年加肥。", "corrected_sentence": "这片新开的荒地保肥差，需要年年加肥。", "error_description": "错误形式：保肥很；正确形式：保肥差。说明保肥效果要用补语「差」，「很」不能直接放在「保肥」后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负向", "is_correct": true, "explanation": "负向与正向相对，指消极、不利的趋向，是正确的反义词。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地，与“正向”表示的趋向意义无关，不是反义词。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容清楚，与“正向”的趋向意义无关，不构成反义。"}, {"text": "缓慢", "is_correct": false, "explanation": "缓慢形容速度，不能与“正向”的方向意义对应，不是反义词。"}], "correct_answer": "负向", "explanations": {"负向": "负向与正向相对，指消极、不利的趋向，是正确的反义词。", "坚硬": "坚硬形容质地，与“正向”表示的趋向意义无关，不是反义词。", "清晰": "清晰形容清楚，与“正向”的趋向意义无关，不构成反义。", "缓慢": "缓慢形容速度，不能与“正向”的方向意义对应，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
