INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指积极、健康的趋向或方向。", "primary_collocate": null, "pronunciation": "zhèng xiàng", "ipa": "ʈʂəŋ˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "正向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "多运动对健康有正向影响。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的成绩形成了正向反馈。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政策对经济发展产生了正向影响。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的发展出现了正向的变化。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师能给学生正向的引导。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人的支持会产生正向的力量。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种游戏对孩子没有正向作用。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合作带来了正向的结果。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格下降给销量带来了正向作用。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正向反馈", "label": "复合"}], "register": "书面", "sense_fingerprint": "正向：积极、健康的趋向或方向，多作定语，如正向反馈、正向影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向 zhèng xiàng 指积极、健康的趋向，是正确答案。"}, {"text": "成像", "is_correct": false, "explanation": "成像 chéng xiàng 与 zhèng xiàng 声母 zh 与 ch 不同，意思是形成影像。"}, {"text": "正弦", "is_correct": false, "explanation": "正弦 zhèng xián 与 zhèng xiàng 韵母 ang 与 an 不同，是数学术语，意思是正弦函数。"}, {"text": "正线", "is_correct": false, "explanation": "正线 zhèng xiàn 与 zhèng xiàng 韵母 ang 与 an 不同，意思是主要的线路。"}, {"text": "真香", "is_correct": false, "explanation": "真香 zhēn xiāng 第一个音节韵母 en 与 eng 不同，第二个音节声调也不同，意思是很香。"}], "explanations": {"正向": "正向 zhèng xiàng 指积极、健康的趋向，是正确答案。", "成像": "成像 chéng xiàng 与 zhèng xiàng 声母 zh 与 ch 不同，意思是形成影像。", "正弦": "正弦 zhèng xián 与 zhèng xiàng 韵母 ang 与 an 不同，是数学术语，意思是正弦函数。", "正线": "正线 zhèng xiàn 与 zhèng xiàng 韵母 ang 与 an 不同，意思是主要的线路。", "真香": "真香 zhēn xiāng 第一个音节韵母 en 与 eng 不同，第二个音节声调也不同，意思是很香。"}, "sentence_index": null, "correct_answer": "正向"}, "level_3": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向指积极、健康的趋向，与“改善”“提升”“重建”的积极效果一致。"}, {"text": "有害", "is_correct": false, "explanation": "语义：“有害”与“改善土壤”“提升能力”的积极效果相反。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质地，不能修饰“反馈回路”这样的抽象结构。"}, {"text": "空洞", "is_correct": false, "explanation": "搭配：“空洞”多形容言语或内容，与“反馈回路”的功能不搭。"}], "explanations": {"正向": "正向指积极、健康的趋向，与“改善”“提升”“重建”的积极效果一致。", "有害": "语义：“有害”与“改善土壤”“提升能力”的积极效果相反。", "粗糙": "搭配：“粗糙”形容表面质地，不能修饰“反馈回路”这样的抽象结构。", "空洞": "搭配：“空洞”多形容言语或内容，与“反馈回路”的功能不搭。"}, "sentence_index": 0, "correct_answer": "正向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张椅子很正向。", "explanation": "这里不宜用〈正向〉。“正向”指积极、健康的趋向，不能用来形容椅子；说椅子端正应说“端正”。"}, {"text": "这套软件是正向的。", "explanation": "这里应该用〈正版〉。正向指积极、健康的方向，不指授权是否合法；说软件来源合法应说“正版”。"}, {"text": "这个政策使经济发展正向。", "explanation": "这里应该用〈促进〉。“正向”不能单独作“使……”的谓语，应说“促进经济发展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向 zhèng xiàng 指积极、健康的趋向，是正确答案。"}, {"text": "争相", "is_correct": false, "explanation": "争相 zhēng xiāng 的两个音节声调都与 zhèng xiàng 不同，意思是争着。"}, {"text": "真相", "is_correct": false, "explanation": "真相 zhēn xiàng 第一个音节韵母 en 与 eng 不同，声调也不同，意思是事情的实际情况。"}, {"text": "正香", "is_correct": false, "explanation": "正香 zhèng xiāng 只有第二个音节声调不同，意思是香得正好（口语）。"}], "explanations": {"正向": "正向 zhèng xiàng 指积极、健康的趋向，是正确答案。", "争相": "争相 zhēng xiāng 的两个音节声调都与 zhèng xiàng 不同，意思是争着。", "真相": "真相 zhēn xiàng 第一个音节韵母 en 与 eng 不同，声调也不同，意思是事情的实际情况。", "正香": "正香 zhèng xiāng 只有第二个音节声调不同，意思是香得正好（口语）。"}, "sentence_index": null, "correct_answer": "正向"}, "level_3": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向指积极的趋向或作用，与“支持”产生积极力量的语境一致。"}, {"text": "消沉", "is_correct": false, "explanation": "语义：“消沉”指情绪低落，与“家人的支持”带来的积极作用相反。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”描述温度或态度，不用来修饰“力量”。"}, {"text": "有毒", "is_correct": false, "explanation": "搭配：“有毒”多修饰物质，与“力量”不搭。"}], "explanations": {"正向": "正向指积极的趋向或作用，与“支持”产生积极力量的语境一致。", "消沉": "语义：“消沉”指情绪低落，与“家人的支持”带来的积极作用相反。", "冰冷": "搭配：“冰冷”描述温度或态度，不用来修饰“力量”。", "有毒": "搭配：“有毒”多修饰物质，与“力量”不搭。"}, "sentence_index": 6, "correct_answer": "正向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "价格下降给销量带来了正向的伤害。", "explanation": "这里不能用〈正向〉。正向表示积极、健康，不能修饰“伤害”这类消极的结果；消极的作用应说〈负面〉。"}, {"text": "价格下降给销量带来了正向的数字。", "explanation": "这里应该用〈作用〉。“正向”修饰“作用”“影响”这类有效果含义的词，不修饰“数字”。"}, {"text": "汽车正向后退了一米。", "explanation": "这里应该用〈倒〉。正向指积极或向前的方向，不能描述后退这种相反的运动；车向后开应说“倒车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的税收办法对消费有正向地作用。", "corrected_sentence": "新的税收办法对消费有正向作用。", "error_description": "错误：“地”不能接在“正向”后修饰名词性的“作用”，“地”只用于修饰动词。正确：“有正向作用”，“正向”直接修饰名词，中间不加助词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项改革对学生成长有正向得作用。", "corrected_sentence": "这项改革对学生成长有正向的作用。", "error_description": "错误：“正向”作定语，应接结构助词“的”，不能用“得”。正确：应说“正向的作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将信息、意见或结果等传递回来。", "primary_collocate": null, "pronunciation": "fǎn kuì", "ipa": "fan˨˩˦ kʰweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，还让传感器采集的土壤数据能够定期反馈给管理系统，用以校正施肥方案。", "target_word": "反馈", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，并把每一步的执行结果反馈给决策模块，据此调整目标函数。", "target_word": "反馈", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "请你把试用后的意见反馈给我们。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人对菜的味道有什么看法，可以向店里反馈。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师及时反馈了作业的结果。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的问题已经反馈到学校了。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周都向经理反馈工作的进展。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户反馈说，这个软件有点慢。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现错误，请马上反馈给我们。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院会把检查结果反馈给病人。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反馈了", "label": "体标"}, {"form": "反馈过", "label": "体标"}, {"form": "反馈意见", "label": "复合"}], "register": "书面", "sense_fingerprint": "把信息、意见或结果传回给来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“定期反馈给管理系统”指把采集的数据传回给系统，与“用以校正施肥方案”的用途相符。"}, {"text": "断开", "is_correct": false, "explanation": "语义：“断开”是切断，与“定期……给管理系统”的数据传递相反。"}, {"text": "抑制", "is_correct": false, "explanation": "搭配：“抑制”是压制，不能与“数据”和“给管理系统”构成传递，句子不通。"}, {"text": "游离", "is_correct": false, "explanation": "配价：“游离”是不及物动词，不能带“数据”作宾语，句子不成立。"}], "explanations": {"反馈": "正确。“定期反馈给管理系统”指把采集的数据传回给系统，与“用以校正施肥方案”的用途相符。", "断开": "语义：“断开”是切断，与“定期……给管理系统”的数据传递相反。", "抑制": "搭配：“抑制”是压制，不能与“数据”和“给管理系统”构成传递，句子不通。", "游离": "配价：“游离”是不及物动词，不能带“数据”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借来的书我已经反馈给图书馆了。", "explanation": "这里应该用〈归还〉。反馈只用于信息、意见或结果，书是实物，要说归还或还。"}, {"text": "这首老歌反馈了我很多童年回忆。", "explanation": "这里应该用〈勾起〉。反馈是把信息传回给来源，不能表示勾起回忆或感受，这里应说勾起或带来。"}, {"text": "学校把开学的时间反馈给了学生。", "explanation": "这里应该用〈通知〉。反馈是把信息传回给信息的来源，学校是发布方，不能说反馈给学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“反馈工作的进展”指把工作情况传回给上级，与“每周都”的定期汇报相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求或意见，不能带“进展”作宾语。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽，与“每周都向经理”的正常汇报语境不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“每周都”定期汇报的语境相冲突，句子读不通。"}], "explanations": {"反馈": "正确。“反馈工作的进展”指把工作情况传回给上级，与“每周都”的定期汇报相符。", "拒绝": "搭配：“拒绝”的对象是请求或意见，不能带“进展”作宾语。", "嘲笑": "语义：“嘲笑”是讥讽，与“每周都向经理”的正常汇报语境不符。", "忘记": "语义：“忘记”与“每周都”定期汇报的语境相冲突，句子读不通。"}, "sentence_index": 6, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班以后反馈了家。", "explanation": "这里应该用〈返回〉。反馈不能以地点作宾语，回家要说返回或回到。"}, {"text": "他很感动，一直想反馈老师的恩情。", "explanation": "这里应该用〈回馈〉。反馈的宾语是信息、意见或结果，恩情要说回馈或回报。"}, {"text": "我每天早上反馈了一杯牛奶。", "explanation": "这里应该用〈喝〉。反馈的宾语是信息、意见或结果，牛奶是饮品，要说喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把使用后的感受反馈我们。", "corrected_sentence": "请把使用后的感受反馈给我们。", "error_description": "错误：“反馈”后漏了“给”，应说“反馈给我们”。“反馈”要用“给”引出接收的人，不能直接接人称代词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把问题反馈了给客服。", "corrected_sentence": "我把问题反馈给了客服。", "error_description": "错误：“了”放错了位置。“反馈”后先接“给”，再接“了”，应说“反馈给了客服”，不能把“了”插在“给”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
