INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电流或信号从起点出发，经过一个系统或设备后返回起点的闭合路径。", "primary_collocate": null, "pronunciation": "huí lù", "ipa": "xweɪ˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "当此腐熟产物被施用于家庭园艺系统时，不仅改善土壤团粒结构，提升保水保肥能力，更重建了植物—微生物—有机质之间的正向反馈回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，通过多层级反馈回路调整目标函数。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "信号经过这个回路，又回到了起点。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个回路让系统自己调整速度。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师发现回路里的信号太弱了。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个控制回路是闭合的。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息在回路中不断循环。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回路断开了，系统就停止工作。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个反馈回路让他越学越快。", "target_word": "回路", "complexity_tier": "T3", "furigana": "huí lù", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "反馈回路", "label": "复合"}, {"form": "闭合回路", "label": "复合"}], "register": "书面语", "sense_fingerprint": "信号或信息经系统后回到起点的闭合路径，引申为反馈循环", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f3bb72-e6b9-4d54-bc89-55e59a88509c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。回路指闭合的电流或信号路径。"}, {"text": "回炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是重新熔化或返工。"}, {"text": "回流", "is_correct": false, "explanation": "liú 比 lù 多一个 i 音，且声调不同，意思是向相反方向流动。"}, {"text": "回礼", "is_correct": false, "explanation": "lǐ 与 lù 的韵母和声调都不同，意思是还礼或回赠的礼物。"}, {"text": "贿赂", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是用财物收买。"}], "explanations": {"回路": "正确。回路指闭合的电流或信号路径。", "回炉": "lú（第二声）与 lù（第四声）声调不同，意思是重新熔化或返工。", "回流": "liú 比 lù 多一个 i 音，且声调不同，意思是向相反方向流动。", "回礼": "lǐ 与 lù 的韵母和声调都不同，意思是还礼或回赠的礼物。", "贿赂": "huì（第四声）与 huí（第二声）声调不同，意思是用财物收买。"}, "sentence_index": null, "correct_answer": "回路"}, "level_3": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。句中指正向反馈回路，即植物、微生物与有机质之间闭合的反馈关系。"}, {"text": "细胞", "is_correct": false, "explanation": "语义：细胞是生物的基本结构单位，不能指“之间”的反馈关系，句意不通。"}, {"text": "路子", "is_correct": false, "explanation": "语域：“路子”是口语，与本句的书面语风格不符，也不能指反馈关系。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象现象，不能作为植物与微生物之间的反馈关系。"}], "explanations": {"回路": "正确。句中指正向反馈回路，即植物、微生物与有机质之间闭合的反馈关系。", "细胞": "语义：细胞是生物的基本结构单位，不能指“之间”的反馈关系，句意不通。", "路子": "语域：“路子”是口语，与本句的书面语风格不符，也不能指反馈关系。", "天气": "语义：天气是气象现象，不能作为植物与微生物之间的反馈关系。"}, "sentence_index": 0, "correct_answer": "回路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条回路通往市中心。", "explanation": "这里应该用〈线路〉。回路是闭合的电流或信号路径，不能指通往某地的路线。"}, {"text": "我们从这个回路走进了大楼。", "explanation": "这里应该用〈通道〉。回路是闭合的系统路径，不是人可以穿行的通道。"}, {"text": "工人接好了一头回路。", "explanation": "这里应该用〈条〉或〈个〉。〈头〉用于牛、羊等牲畜，不能用来计量回路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
